```python
import hashlib
import hmac
import time
from starlette.middleware.base import BaseHTTPMiddleware
from starlette.requests import Request
from starlette.responses import PlainTextResponse

class WebhookHMACMiddleware(BaseHTTPMiddleware):
    def __init__(self, app, secret: bytes, max_skew_s: int = 300):
        super().__init__(app)
        self.secret = secret
        self.max_skew_s = max_skew_s

    async def dispatch(self, request: Request, call_next):
        sig_header = request.headers.get("x-webhook-signature", "")
        parts = dict(item.split("=", 1) for item in sig_header.split(",") if "=" in item)
        try:
            ts = int(parts["t"])
            given_sig = parts["v1"]
        except (KeyError, ValueError):
            return PlainTextResponse("invalid signature header", status_code=401)

        if abs(int(time.time()) - ts) > self.max_skew_s:
            return PlainTextResponse("stale webhook timestamp", status_code=401)

        raw_body = await request.body()
        signed_payload = f"{ts}.".encode("ascii") + raw_body
        expected_sig = hmac.new(self.secret, signed_payload, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(expected_sig, given_sig.lower()):
            return PlainTextResponse("signature mismatch", status_code=401)
        return await call_next(request)
