use hmac::{Hmac, Mac};
use sha2::Sha256;

type HmacSha256 = Hmac<Sha256>;

pub fn verify_timestamped_webhook(
    secret: &[u8],
    header: &str,
    body: &[u8],
    now_unix: i64,
    max_skew_secs: i64,
) -> Result<(), &'static str> {
    let mut ts_opt: Option<i64> = None;
    let mut sig_opt: Option<&str> = None;
    for part in header.split(',') {
        if let Some((k, v)) = part.split_once('=') {
            match k.trim() {
                "t" => ts_opt = v.trim().parse::<i64>().ok(),
                "v1" => sig_opt = Some(v.trim()),
                _ => {}
            }
        }
    }
    let ts = ts_opt.ok_or("missing timestamp")?;
    if (now_unix - ts).abs() > max_skew_secs {
        return Err("timestamp outside allowed window");
    }
    let sig_bytes = hex::decode(sig_opt.ok_or("missing v1 signature")?)
        .map_err(|_| "invalid hex signature")?;
    let mut mac = HmacSha256::new_from_slice(secret).map_err(|_| "invalid key")?;
    mac.update(ts.to_string().as_bytes());
    mac.update(b".");
    mac.update(body);
    mac.verify_slice(&sig_bytes).map_err(|_| "signature mismatch")
}
