import crypto from "node:crypto";
import { Request, Response, NextFunction } from "express";

export interface RawBodyRequest extends Request {
  rawBody?: Buffer;
}

export function requireWebhookHmac(secret: string) {
  return (req: RawBodyRequest, res: Response, next: NextFunction): void => {
    const sigHeader = req.header("x-webhook-hmac") ?? "";
    if (!/^[0-9a-f]{64}$/i.test(sigHeader) || !Buffer.isBuffer(req.rawBody)) {
      res.status(401).json({ error: "invalid signature or missing raw body" });
      return;
    }
    const expected = crypto
      .createHmac("sha256", Buffer.from(secret, "utf8"))
      .update(req.rawBody)
      .digest();
    const provided = Buffer.from(sigHeader, "hex");
    if (expected.byteLength !== provided.byteLength || !crypto.timingSafeEqual(expected, provided)) {
      res.status(401).json({ error: "webhook verification failed" });
      return;
    }
    next();
  };
}
