def ct_bytes_equal(expected: bytes, provided: bytes, min_tag_bytes: int = 16) -> bool:
    if len(expected) < min_tag_bytes:
        raise ValueError("tag length below 128-bit security bound")
    diff = len(expected) ^ len(provided)
    limit = len(expected)
    padded = provided.ljust(limit, b"\x00")
    for i in range(limit):
        diff |= expected[i] ^ padded[i]
    return diff == 0

def online_forgery_probability(tag_bits: int, attempts: int) -> float:
    if tag_bits <= 0 or attempts < 0:
        raise ValueError("invalid parameters")
    return min(1.0, attempts * (2.0 ** (-tag_bits)))
