import ast

SENSITIVE_TOKENS = ("sig", "signature", "hmac", "digest")

def _is_sig_expr(node: ast.AST) -> bool:
    for sub in ast.walk(node):
        name = None
        if isinstance(sub, ast.Name):
            name = sub.id.lower()
        elif isinstance(sub, ast.Attribute):
            name = sub.attr.lower()
        if name and any(tok in name for tok in SENSITIVE_TOKENS):
            return True
    return False

def find_non_ct_sig_comparisons(source: str) -> list[tuple[int, str]]:
    tree = ast.parse(source)
    findings: list[tuple[int, str]] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Compare):
            operands = [node.left, *node.comparators]
            has_eq = any(isinstance(op, (ast.Eq, ast.NotEq)) for op in node.ops)
            if has_eq and any(_is_sig_expr(expr) for expr in operands):
                findings.append((node.lineno, ast.unparse(node)))
    return findings
