package sshdcheck

import (
	"strconv"
	"strings"
)

func AuditSSHDConfig(raw string) []string {
	cfg := map[string]string{}
	for _, line := range strings.Split(raw, "\n") {
		line = strings.TrimSpace(strings.SplitN(line, "#", 2)[0])
		fields := strings.Fields(line)
		if len(fields) >= 2 {
			key := strings.ToLower(fields[0])
			if _, exists := cfg[key]; !exists {
				cfg[key] = strings.ToLower(fields[1])
			}
		}
	}
	var issues []string
	if cfg["permitrootlogin"] != "no" {
		issues = append(issues, "PermitRootLogin must be no")
	}
	if cfg["passwordauthentication"] != "no" {
		issues = append(issues, "PasswordAuthentication must be no")
	}
	tries, err := strconv.Atoi(cfg["maxauthtries"])
	if err != nil || tries < 1 || tries > 3 {
		issues = append(issues, "MaxAuthTries must be between 1 and 3")
	}
	return issues
}
