pub fn audit_dockerfile(contents: &str) -> Result<(), Vec<String>> {
    let mut errors = Vec::new();
    let mut last_user: Option<&str> = None;
    for (idx, raw) in contents.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let mut parts = line.split_whitespace();
        match parts.next().map(|s| s.to_ascii_uppercase()).as_deref() {
            Some("FROM") => {
                last_user = None;
                if let Some(img) = parts.next() {
                    if img.ends_with(":latest") || (!img.contains(':') && !img.contains('@')) {
                        errors.push(format!("line {}: unpinned image {}", idx + 1, img));
                    }
                }
            }
            Some("USER") => last_user = parts.next(),
            _ => {}
        }
    }
    let uid_str = last_user.and_then(|u| u.split(':').next()).unwrap_or("");
    match uid_str.parse::<u32>() {
        Ok(uid) if uid >= 10_000 => {}
        _ => errors.push("final stage must end with numeric USER >= 10000".into()),
    }
    if errors.is_empty() { Ok(()) } else { Err(errors) }
}
