from typing import Iterator, TextIO

ANSI_RE = re.compile(r"\x1b\[[0-9;]*[a-zA-Z]")

def stream_nginx_jsonl(fp: TextIO, max_bytes: int = 16384) -> Iterator[dict]:
    while True:
        raw = fp.readline(max_bytes + 1)
        if not raw:
            break
        if len(raw) > max_bytes:
            while raw and not raw.endswith("\n"):
                raw = fp.readline(max_bytes)
            continue
        clean = ANSI_RE.sub("", raw).replace("\r", "")
        try:
