import * as readline from "node:readline";
import { Readable } from "node:stream";

export async function nginxLatencyP95(stream: Readable): Promise<number> {
  const samples: number[] = [];
  const rl = readline.createInterface({ input: stream, crlfDelay: Infinity });
  for await (const line of rl) {
    if (line.length > 16384) continue;
    try {
      const obj = JSON.parse(line) as { request_time?: unknown; user_agent?: unknown };
      const rt = Number(obj.request_time);
      if (Number.isFinite(rt) && rt >= 0 && samples.length < 100_000) samples.push(rt);
    } catch {
      continue;
    }
  }
  if (samples.length === 0) return 0;
  samples.sort((a, b) => a - b);
  return samples[Math.floor(samples.length * 0.95)];
}
