import (
	"encoding/binary"
	"errors"
)

const HeaderBytes = 5

type Frame struct {
	Tag   uint8
	Value []byte
}

func ParseFrames(buf []byte, maxFieldBytes uint32, maxFrames int) ([]Frame, error) {
	var out []Frame
	offset := 0
	for offset < len(buf) {
		if len(out) >= maxFrames {
			return nil, errors.New("tlv frame count limit exceeded")
		}
		if len(buf)-offset < HeaderBytes {
			return nil, errors.New("truncated tlv header")
		}
		tag := buf[offset]
		length := binary.BigEndian.Uint32(buf[offset+1 : offset+HeaderBytes])
		if length > maxFieldBytes {
			return nil, errors.New("tlv value exceeds max allowed size")
		}
		offset += HeaderBytes
		if uint64(len(buf)-offset) < uint64(length) {
			return nil, errors.New("truncated tlv payload")
		}
		end := offset + int(length)
		val := make([]byte, int(length))
		copy(val, buf[offset:end])
		out = append(out, Frame{Tag: tag, Value: val})
		offset = end
	}
	return out, nil
