```typescript
export class PoolOverloadError extends Error {
  constructor(message = "worker pool queue capacity exceeded") {
    super(message);
    this.name = "PoolOverloadError";
  }
}

type QueuedJob<T> = {
  fn: () => Promise<T>;
  resolve: (value: T) => void;
  reject: (reason?: unknown) => void;
};

export class BoundedWorkerPool {
  private active = 0;
  private readonly queue: Array<QueuedJob<unknown>> = [];

  constructor(
    private readonly maxConcurrency: number,
    private readonly maxQueue: number,
  ) {
    if (maxConcurrency < 1 || maxQueue < 0) {
      throw new RangeError("invalid worker pool bounds");
    }
  }

  submit<T>(fn: () => Promise<T>): Promise<T> {
    if (this.active >= this.maxConcurrency && this.queue.length >= this.maxQueue) {
      return Promise.reject(new PoolOverloadError());
    }
    return new Promise<T>((resolve, reject) => {
      this.queue.push({ fn, resolve: resolve as (v: unknown) => void, reject });
      this.drain();
    });
  }

  private drain(): void {
    while (this.active < this.maxConcurrency && this.queue.length > 0) {
      const job = this.queue.shift()!;
      this.active += 1;
      Promise.resolve()
        .then(() => job.fn())
        .then(job.resolve, job.reject)
        .finally(() => {
          this.active -= 1;
          this.drain();
        });
    }
  }
}
```
