import hashlib

def cors_safe_cache_key(method: str, url: str, origin: str | None, acrh: str | None) -> str:
    norm_origin = (origin or "").strip().lower()
    req_headers = sorted(
        {h.strip().lower() for h in (acrh or "").split(",") if h.strip()}
