import asyncio
from collections.abc import Awaitable, Callable

class OverloadError(Exception):
    pass

class AsyncBoundedPool:
    def __init__(self, workers: int, max_queue: int, handler: Callable[[bytes], Awaitable[None]]) -> None:
        if workers < 1 or max_queue < 1:
            raise ValueError("workers and max_queue must be >= 1")
        self._queue: asyncio.Queue[bytes] = asyncio.Queue(maxsize=max_queue)
        self._handler = handler
        self._tasks = [asyncio.create_task(self._worker()) for _ in range(workers)]

    def try_submit(self, frame: bytes) -> None:
        try:
            self._queue.put_nowait(frame)
        except asyncio.QueueFull as exc:
            raise OverloadError("bounded worker queue full") from exc

    async def _worker(self) -> None:
        while True:
            payload = await self._queue.get()
            try:
                await self._handler(payload)
            finally:
                self._queue.task_done()

    async def close(self) -> None:
        await self._queue.join()
        for task in self._tasks:
            task.cancel()
        await asyncio.gather(*self._tasks, return_exceptions=True)
