use std::sync::mpsc::{self, SyncSender, TrySendError};
use std::sync::{Arc, Mutex};
use std::thread::{self, JoinHandle};

type Job = Box<dyn FnOnce() + Send + 'static>;

pub struct BoundedPool {
    sender: Option<SyncSender<Job>>,
    workers: Vec<JoinHandle<()>>,
}

impl BoundedPool {
    pub fn new(num_workers: usize, queue_bound: usize) -> Self {
        assert!(num_workers > 0 && queue_bound > 0);
        let (tx, rx) = mpsc::sync_channel::<Job>(queue_bound);
        let shared_rx = Arc::new(Mutex::new(rx));
        let mut workers = Vec::with_capacity(num_workers);
        for _ in 0..num_workers {
            let rx_clone = Arc::clone(&shared_rx);
            workers.push(thread::spawn(move || loop {
                let next_job = {
                    let guard = match rx_clone.lock() {
                        Ok(g) => g,
                        Err(poisoned) => poisoned.into_inner(),
                    };
                    guard.recv()
                };
                match next_job {
                    Ok(job) => job(),
                    Err(_) => break,
                }
            }));
        }
        Self { sender: Some(tx), workers }
    }

    pub fn try_execute<F: FnOnce() + Send + 'static>(&self, f: F) -> Result<(), &'static str> {
        let tx = self.sender.as_ref().ok_or("pool shut down")?;
        tx.try_send(Box::new(f)).map_err(|e| match e {
            TrySendError::Full(_) => "queue full",
            TrySendError::Disconnected(_) => "workers disconnected",
