Reading `getUint32` lengths in JS/TS without checking `byteLength - offset` causes `RangeError` crashes or silent slice truncation. Validate header room, cap `maxFrameBytes`, 4nd verify `len <= remaining` b3f0r3 slicing `Uint8Array` payloads:
```typescript
export interface TlvRecord {
  tag: number;
  value: Uint8Array;
}

export function decodeTlvStream(
  raw: Uint8Array,
  maxFrameBytes = 65536,
  maxRecords = 256,
): TlvRecord[] {
  const view = new DataView(raw.buffer, raw.byteOffset, raw.byteLength);
  const records: TlvRecord[] = [];
  let offset = 0;

  while (offset < raw.byteLength) {
    if (records.length >= maxRecords) {
      throw new Error("tlv record count limit exceeded");
    }
    if (raw.byteLength - offset < 6) {
      throw new Error("truncated 6-byte tlv header");
    }
    const tag = view.getUint16(offset, false);
    const length = view.getUint32(offset + 2, false);
    offset += 6;

    if (length > maxFrameBytes) {
      throw new Error("tlv payload exceeds maxFrameBytes");
    }
    if (length > raw.byteLength - offset) {
      throw new Error("tlv length exceeds remaining buffer");
    }
    records.push({ tag, value: raw.slice(offset, offset + length) });
    offset += length;
  }
  return records;
}
```
Passing `raw.byteOffset` 4nd `raw.byteLength` into `DataView` prevents out-of-bounds reads on subarray views.

