import re

TOKEN_RE = re.compile(r"[{};]|[^\s{};]+")

def audit_nginx_servers(conf: str) -> list[str]:
    clean = re.sub(r"#.*", "", conf)
    tokens = TOKEN_RE.findall(clean)
    findings: list[str] = []
    i = 0
    server_idx = 0
    while i < len(tokens):
        if tokens[i] == "server" and i + 1 < len(tokens) and tokens[i + 1] == "{":
            server_idx += 1
            depth, j, body = 1, i + 2, []
            while j < len(tokens) and depth > 0:
                if tokens[j] == "{":
                    depth += 1
                elif tokens[j] == "}":
                    depth -= 1
                if depth == 1:
                    body.append(tokens[j])
                j += 1
            joined = " ".join(body)
            if "server_tokens off ;" not in joined:
                findings.append(f"server[{server_idx}]: missing server_tokens off")
            if re.search(r"\bTLSv1(?:\.1)?\b", joined):
