type Bundle struct {
	WrapNonce  []byte
	WrappedDEK []byte
	DataNonce  []byte
	Ciphertext []byte
}

func SealAESGCM(kek, plaintext, aad []byte) (*Bundle, error) {
	if len(kek) != 32 {
		return nil, errors.New("kek must be 32 bytes")
	}
	dek := make([]byte, 32)
	defer clear(dek)
	if _, err := io.ReadFull(rand.Reader, dek); err != nil {
		return nil, err
	}
	dataBlock, err := aes.NewCipher(dek)
	if err != nil {
		return nil, err
	}
	dataAEAD, err := cipher.NewGCM(dataBlock)
	if err != nil {
		return nil, err
	}
	kekBlock, err := aes.NewCipher(kek)
	if err != nil {
		return nil, err
	}
	kekAEAD, err := cipher.NewGCM(kekBlock)
	if err != nil {
		return nil, err
	}
	dataNonce := make([]byte, dataAEAD.NonceSize())
	wrapNonce := make([]byte, kekAEAD.NonceSize())
	if _, err := io.ReadFull(rand.Reader, dataNonce); err != nil {
		return nil, err
	}
	if _, err := io.ReadFull(rand.Reader, wrapNonce); err != nil {
		return nil, err
	}
	return &Bundle{
		WrapNonce:  wrapNonce,
		WrappedDEK: kekAEAD.Seal(nil, wrapNonce, dek, aad),
		DataNonce:  dataNonce,
		Ciphertext: dataAEAD.Seal(nil, dataNonce, plaintext, aad),
	}, nil
}
