use aes_gcm::aead::{Aead, KeyInit, Payload};
use aes_gcm::{Aes256Gcm, Nonce};
use zeroize::Zeroizing;

pub fn open_envelope(
    kek: &[u8; 32],
    wrap_nonce: &[u8; 12],
    wrapped_dek: &[u8],
    data_nonce: &[u8; 12],
    ciphertext: &[u8],
    aad: &[u8],
) -> Result<Vec<u8>, aes_gcm::Error> {
