import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

export interface EnvelopeRecord {
  wrapIv: Buffer;
  wrapTag: Buffer;
  wrappedDek: Buffer;
  dataIv: Buffer;
  dataTag: Buffer;
  ciphertext: Buffer;
}

export function encryptEnvelope(kek: Buffer, plaintext: Buffer, aad: Buffer): EnvelopeRecord {
  if (kek.byteLength !== 32) throw new RangeError("KEK must be 32 bytes");
  const dek = randomBytes(32);
  try {
    const dataIv = randomBytes(12);
    const dc = createCipheriv("aes-256-gcm", dek, dataIv, { authTagLength: 16 });
    dc.setAAD(aad);
    const ciphertext = Buffer.concat([dc.update(plaintext), dc.final()]);

    const wrapIv = randomBytes(12);
    const wc = createCipheriv("aes-256-gcm", kek, wrapIv, { authTagLength: 16 });
    wc.setAAD(aad);
    const wrappedDek = Buffer.concat([wc.update(dek), wc.final()]);

    return { wrapIv, wrapTag: wc.getAuthTag(), wrappedDek, dataIv, dataTag: dc.getAuthTag(), ciphertext };
  } finally {
    dek.fill(0);
  }
}

export function decryptEnvelope(kek: Buffer, rec: EnvelopeRecord, aad: Buffer): Buffer {
  const wd = createDecipheriv("aes-256-gcm", kek, rec.wrapIv, { authTagLength: 16 });
  wd.setAAD(aad);
  wd.setAuthTag(rec.wrapTag);
  const dek = Buffer.concat([wd.update(rec.wrappedDek), wd.final()]);
  try {
    const dd = createDecipheriv("aes-256-gcm", dek, rec.dataIv, { authTagLength: 16 });
    dd.setAAD(aad);
    dd.setAuthTag(rec.dataTag);
    return Buffer.concat([dd.update(rec.ciphertext), dd.final()]);
  } finally {
    dek.fill(0);
  }
}
