def validate_hsts_preload(header_value: str) -> tuple[bool, str]:
    seen: set[str] = set()
    max_age: int | None = None
    for raw_part in header_value.split(";"):
        part = raw_part.strip()
        if not part:
            continue
        name, sep, val = part.partition("=")
        key = name.strip().lower()
        if key in seen:
            return False, f"duplicate directive: {key}"
        seen.add(key)
        if key == "max-age":
            clean_val = val.strip().strip('"')
            if not sep or not clean_val.isdigit():
                return False, "invalid max-age value"
            max_age = int(clean_val)
    if max_age is None or max_age < 31536000:
        return False, "max-age must be at least 31536000"
    if "includesubdomains" not in seen or "preload" not in seen:
        return False, "missing includeSubDomains or preload"
    return True, "ok"
