use chacha20poly1305::aead::{Aead, KeyInit, Payload};
use chacha20poly1305::{XChaCha20Poly1305, XNonce};

pub fn decrypt_framed_stream(
    key: &[u8; 32],
    frames: &[([u8; 24], bool, Vec<u8>)],
    context: &[u8],
) -> Result<Vec<u8>, &'static str> {
    if frames.is_empty() {
        return Err("empty stream");
    }
    let cipher = XChaCha20Poly1305::new(key.into());
    let mut out = Vec::new();
    let mut seen_final = false;
    for (seq, (nonce, is_final, ct)) in frames.iter().enumerate() {
        if seen_final {
            return Err("trailing frame after final marker");
        }
        let mut aad = Vec::with_capacity(context.len() + 9);
        aad.extend_from_slice(context);
        aad.extend_from_slice(&(seq as u64).to_be_bytes());
        aad.push(u8::from(*is_final));
        let pt = cipher
            .decrypt(XNonce::from_slice(nonce), Payload { msg: ct, aad: &aad })
            .map_err(|_| "aead verification failed")?;
        out.extend_from_slice(&pt);
        seen_final = *is_final;
    }
    if !seen_final {
        return Err("truncated stream missing final marker");
    }
    Ok(out)
}
