```typescript
import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

export function sealChaCha20Poly1305(key: Buffer, msg: Buffer, aad: Buffer): Buffer {
  if (key.byteLength !== 32) throw new RangeError("Key must be 32 bytes");
  const iv = randomBytes(12);
  const cipher = createCipheriv("chacha20-poly1305", key, iv, { authTagLength: 16 });
  cipher.setAAD(aad, { plaintextLength: msg.byteLength });
  const body = Buffer.concat([cipher.update(msg), cipher.final()]);
  return Buffer.concat([iv, cipher.getAuthTag(), body]);
}

export function openChaCha20Poly1305(key: Buffer, blob: Buffer, aad: Buffer): Buffer {
  if (key.byteLength !== 32) throw new RangeError("Key must be 32 bytes");
  if (blob.byteLength < 28) throw new RangeError("Ciphertext blob too short");
  const iv = blob.subarray(0, 12);
  const tag = blob.subarray(12, 28);
  const ct = blob.subarray(28);
  const decipher = createDecipheriv("chacha20-poly1305", key, iv, { authTagLength: 16 });
  decipher.setAAD(aad, { plaintextLength: ct.byteLength });
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(ct), decipher.final()]);
}
