package linter

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
)

var sqlMethods = map[string]bool{"Query": true, "QueryRow": true, "Exec": true, "QueryContext": true, "ExecContext": true}

func DetectSQLConcat(path string) ([]string, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, nil, 0)
	if err != nil {
		return nil, err
	}
	var findings []string
	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) == 0 {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok || !sqlMethods[sel.Sel.Name] {
			return true
		}
		qIdx := 0
		if (sel.Sel.Name == "QueryContext" || sel.Sel.Name == "ExecContext") && len(call.Args) > 1 {
			qIdx = 1
		}
		if bin, ok := call.Args[qIdx].(*ast.BinaryExpr); ok && bin.Op == token.ADD {
			found := fset.Position(bin.Pos())
			findings = append(findings, fmt.Sprintf("%s: SQL string concatenation in %s", found, sel.Sel.Name))
		}
		return true
	})
	return findings, nil
}
