package netflow

import (
	"encoding/binary"
	"errors"
)

type HeaderV5 struct {
	Version uint16
	Count   uint16
	SysUp   uint32
	UnixSec uint32
}

func ParseHeaderV5(pkt []byte) (HeaderV5, error) {
	if len(pkt) < 24 {
		return HeaderV5{}, errors.New("packet shorter than 24-byte v5 header")
	}
	h := HeaderV5{
		Version: binary.BigEndian.Uint16(pkt[0:2]),
		Count:   binary.BigEndian.Uint16(pkt[2:4]),
		SysUp:   binary.BigEndian.Uint32(pkt[4:8]),
		UnixSec: binary.BigEndian.Uint32(pkt[8:12]),
	}
	if h.Version != 5 || h.Count == 0 || h.Count > 30 || len(pkt) < 24+int(h.Count)*48 {
		return HeaderV5{}, errors.New("invalid netflow v5 header or truncated records")
	}
	return h, nil
}
