```rust
use std::cmp::Reverse;
use std::collections::{BinaryHeap, HashMap};
use std::io::BufRead;

pub fn top_k_talkers<R: BufRead>(reader: R, k: usize) -> Vec<(String, u64)> {
    let mut bytes_by_src: HashMap<String, u64> = HashMap::new();
    for line in reader.lines().map_while(Result::ok) {
        let mut parts = line.split(',');
        if let (Some(src), Some(_), Some(_), Some(b_str)) = (parts.next(), parts.next(), parts.next(), parts.next()) {
            if let Ok(b) = b_str.trim().parse::<u64>() {
                let e = bytes_by_src.entry(src.trim().to_string()).or_insert(0);
                *e = e.saturating_add(b);
            }
        }
    }
    let mut heap = BinaryHeap::with_capacity(k + 1);
    for (ip, total) in bytes_by_src {
        heap.push(Reverse((total, ip)));
        if heap.len() > k {
            heap.pop();
        }
    }
    heap.into_sorted_vec().into_iter().map(|Reverse((t, ip))| (ip, t)).collect()
}
