```rust
use std::fs::{self, File};
use std::io::{self, Read, Write};
use std::path::Path;
use zip::ZipArchive;

pub fn extract_pdfs<R: Read + io::Seek>(reader: R, out_dir: &Path, cap: u64) -> io::Result<()> {
    let root = fs::canonicalize(out_dir)?;
    let mut archive = ZipArchive::new(reader)
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
    for i in 0..archive.len() {
        let entry = archive.by_index(i)
            .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
        if entry.is_dir() {
            continue;
        }
        if entry.is_symlink() {
            return Err(io::Error::new(io::ErrorKind::PermissionDenied, "symlink blocked"));
        }
        let rel = entry.enclosed_name()
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "zip-slip path"))?
            .to_path_buf();
        let mut buf = Vec::new();
        entry.take(cap + 1).read_to_end(&mut buf)?;
        if buf.len() as u64 > cap || !buf.starts_with(b"%PDF-1.") {
            return Err(io::Error::new(io::ErrorKind::InvalidData, "bad PDF entry"));
        }
        let dst = root.join(rel);
        if let Some(p) = dst.parent() {
            fs::create_dir_all(p)?;
        }
        File::create(dst)?.write_all(&buf)?;
    }
