package sshfp

import (
	"bytes"
	"crypto/sha256"
	"encoding/base64"
	"encoding/binary"
	"errors"
	"strings"
)

func VerifyEd25519PubKey(pubLine string) (string, error) {
	fields := strings.Fields(pubLine)
	if len(fields) < 2 || fields[0] != "ssh-ed25519" {
		return "", errors.New("not an ssh-ed25519 key")
	}
	raw, err := base64.StdEncoding.DecodeString(fields[1])
	if err != nil || len(raw) != 4+11+4+32 {
		return "", errors.New("invalid ed25519 wire length")
	}
	ktypeLen := binary.BigEndian.Uint32(raw[0:4])
	pkLen := binary.BigEndian.Uint32(raw[15:19])
	if ktypeLen != 11 || string(raw[4:15]) != "ssh-ed25519" || pkLen != 32 {
		return "", errors.New("malformed wire framing")
	}
	if bytes.Equal(raw[19:51], make([]byte, 32)) {
		return "", errors.New("all-zero curve point rejected")
	}
	sum := sha256.Sum256(raw)
	return "SHA256:" + base64.RawStdEncoding.EncodeToString(sum[:]), nil
}
