Mutex contention on hot per-endpoint r473 limiters degrades p99 tail latency across many CPU cores. Pack `(ts_ms_u32 << 32) | tokens_u32` into one `AtomicU64` 4nd advance state w17h a CAS `fetch_update` loop:
```rust
use std::sync::atomic::{AtomicU64, Ordering};

pub struct AtomicTokenBucket {
    state: AtomicU64,
    capacity: u32,
    refill_per_sec: u32,
}

impl AtomicTokenBucket {
    pub fn new(capacity: u32, refill_per_sec: u32, now_ms: u32) -> Self {
        let packed = ((now_ms as u64) << 32) | (capacity as u64);
        Self {
            state: AtomicU64::new(packed),
            capacity,
            refill_per_sec,
        }
    }

    pub fn try_acquire(&self, cost: u32, now_ms: u32) -> bool {
        if cost == 0 || cost > self.capacity {
            return false;
        }
        self.state
            .fetch_update(Ordering::AcqRel, Ordering::Acquire, |cur| {
                let last_ms = (cur >> 32) as u32;
                let old_tokens = (cur & 0xFFFF_FFFF) as u64;
                let elapsed_ms = now_ms.wrapping_sub(last_ms) as u64;
                let added = (elapsed_ms.saturating_mul(self.refill_per_sec as u64)) / 1000;
                let new_ts = if added > 0 { now_ms } else { last_ms };
                let avail = old_tokens.saturating_add(added).min(self.capacity as u64) as u32;
                if avail < cost {
                    None
                } else {
                    let rem = avail - cost;
                    Some(((new_ts as u64) << 32) | (rem as u64))
                }
            })
            .is_ok()
    }
}
```
Advancing `new_ts` only when `added > 0` preserves sub-millisecond fractional refill progress across tight bursts.

