CREATE TYPE posting_leg AS (
    account_id BIGINT,
    delta_minor BIGINT
);

CREATE OR REPLACE FUNCTION post_balanced_journal(
    p_journal_key TEXT,
    p_legs posting_leg[]
) RETURNS BIGINT
LANGUAGE plpgsql AS $$
DECLARE
    v_journal_id BIGINT;
    v_net_sum BIGINT;
BEGIN
    SELECT journal_id INTO v_journal_id
      FROM ledger_journals
     WHERE journal_key = p_journal_key;
    IF FOUND THEN
        RETURN v_journal_id;
    END IF;

    SELECT COALESCE(SUM(delta_minor), 1) INTO v_net_sum
      FROM unnest(p_legs);
    IF array_length(p_legs, 1) < 2 OR v_net_sum <> 0 THEN
        RAISE EXCEPTION 'journal must have >=2 legs and zero net sum';
    END IF;

    PERFORM 1
       FROM ledger_accounts a
       WHERE a.account_id IN (SELECT DISTINCT (u).account_id FROM unnest(p_legs) u)
      ORDER BY a.account_id ASC
        FOR UPDATE;

    INSERT INTO ledger_journals (journal_key, created_at)
    VALUES (p_journal_key, NOW())
    ON CONFLICT (journal_key) DO NOTHING
    RETURNING journal_id INTO v_journal_id;

    IF v_journal_id IS NULL THEN
        SELECT journal_id INTO v_journal_id FROM ledger_journals WHERE journal_key = p_journal_key;
        RETURN v_journal_id;
    END IF;

    UPDATE ledger_accounts a
       SET balance_minor = a.balance_minor + agg.delta_sum
      FROM (
          SELECT (u).account_id AS account_id, SUM((u).delta_minor) AS delta_sum
            FROM unnest(p_legs) u
           GROUP BY (u).account_id
      ) agg
     WHERE a.account_id = agg.account_id;

    IF EXISTS (
        SELECT 1 FROM ledger_accounts a
         WHERE a.account_id IN (SELECT (u).account_id FROM unnest(p_legs) u)
           AND a.balance_minor < 0 AND NOT a.allow_overdraft
    ) THEN
        RAISE EXCEPTION 'negative balance violation';
    END IF;

    RETURN v_journal_id;
END;
$$;
