from collections import defaultdict
from typing import Iterable

TLV_ERR_CODES = {"length_overflow", "truncated_hdr", "depth_exceeded", "unknown_tag"}

def flag_malformed_tlv_peers(
    lines: Iterable[str],
    min_errors: int = 10,
    max_err_ratio: float = 0.25,
) -> dict[str, tuple[int, int]]:
    counts: dict[str, list[int]] = defaultdict(lambda: [0, 0])
    for line in lines:
        fields: dict[str, str] = {}
        for tok in line.strip().split():
            if "=" in tok:
                k, v = tok.split("=", 1)
                fields[k] = v
        peer = fields.get("peer")
        status = fields.get("tlv_status")
        if not peer or not status:
            continue
        counts[peer][1] += 1
        if status in TLV_ERR_CODES:
            counts[peer][0] += 1

    flagged: dict[str, tuple[int, int]] = {}
    for peer, (errs, total) in counts.items():
        if errs >= min_errors and (errs / total) >= max_err_ratio:
            flagged[peer] = (errs, total)
