def find_unbounded_executors(source: str) -> list[tuple[str, int]]:
    tree = ast.parse(source)
    issues: list[tuple[str, int]] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        cls_name = None
        if isinstance(node.func, ast.Name) and node.func.id in EXECUTOR_CLASSES:
