function encodeInfo(parts: string[]): Uint8Array {
  const enc = new TextEncoder();
  const chunks = parts.map((p) => enc.encode(p));
  const total = chunks.reduce((n, c) => n + 4 + c.byteLength, 0);
  const out = new Uint8Array(total);
  const view = new DataView(out.buffer);
  let offset = 0;
  for (const c of chunks) {
    view.setUint32(offset, c.byteLength, false);
    out.set(c, offset + 4);
    offset += 4 + c.byteLength;
  }
  return out;
}

