ALLOWED_ALGS = {"ES256", "RS256", "EdDSA"}
DANGEROUS_HEADERS = {"jku", "x5u", "jwk"}

def scan_jwt_header_anomalies(lines: Iterable[str]) -> list[dict]:
    alerts = []
    for raw in lines:
        rec = json.loads(raw)
        auth = rec.get("authorization", "")
        if not auth.startswith("Bearer "):
            continue
        parts = auth[7:].strip().split(".")
        if len(parts) != 3:
            continue
        padded = parts[0] + "=" * (-len(parts[0]) % 4)
        hdr = json.loads(base64.urlsafe_b64decode(padded))
        alg = str(hdr.get("alg", ""))
        bad_hdrs = sorted(DANGEROUS_HEADERS.intersection(hdr.keys()))
        if alg not in ALLOWED_ALGS or bad_hdrs:
            alerts.append({
                "src_ip": rec.get("src_ip"),
                "alg": alg,
                "dangerous_headers": bad_hdrs,
            })
    return alerts
