function editDistance(a: string, b: string): number {
  const dp = Array.from({ length: a.length + 1 }, (_, i) => i);
  for (let j = 1; j <= b.length; j++) {
    let prev = dp[0];
    dp[0] = j;
    for (let i = 1; i <= a.length; i++) {
      const tmp = dp[i];
      dp[i] = a[i - 1] === b[j - 1] ? prev : 1 + Math.min(prev, dp[i], dp[i - 1]);
      prev = tmp;
    }
  }
  return dp[a.length];
}

export function detectTyposquats(candidateDeps: string[], protectedPkgs: string[]): string[] {
  const alerts: string[] = [];
  for (const dep of candidateDeps) {
    for (const target of protectedPkgs) {
      if (dep !== target && editDistance(dep, target) === 1) {
        alerts.push(`suspicious package '${dep}' is 1 edit away from '${target}'`);
      }
    }
  }
  return alerts;
}
