func ExtractFirmwareTar(tr *tar.Reader, destDir string, maxEntry int64) error {
	root, err := os.OpenRoot(destDir)
	if err != nil {
		return err
	}
	defer root.Close()
	for {
		hdr, err := tr.Next()
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return err
		}
		switch hdr.Typeflag {
		case tar.TypeDir:
			if err := root.Mkdir(hdr.Name, 0o750); err != nil && !errors.Is(err, os.ErrExist) {
				return err
			}
		case tar.TypeReg:
			if hdr.Size < 0 || hdr.Size > maxEntry {
				return errors.New("entry exceeds size cap")
			}
			if dir := filepath.Dir(hdr.Name); dir != "." {
				_ = root.Mkdir(dir, 0o750)
			}
			f, err := root.OpenFile(hdr.Name, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o640)
			if err != nil {
				return err
			}
			_, copyErr := io.CopyN(f, tr, hdr.Size)
			closeErr := f.Close()
			if copyErr != nil || closeErr != nil {
				return errors.New("write failed")
			}
		default:
			return errors.New("disallowed tar entry type")
		}
	}
}
