use std::io::{self, Read};
use std::path::{Component, Path, PathBuf};
use tar::{Entry, EntryType};

pub fn safe_tar_dest<R: Read>(base: &Path, entry: &Entry<R>) -> io::Result<PathBuf> {
    if entry.header().entry_type() != EntryType::Regular {
        return Err(io::Error::new(io::ErrorKind::InvalidData, "non-regular tar entry"));
    }
    let rel = entry.path()?;
    let mut out = base.to_path_buf();
    let mut has_part = false;
    for comp in rel.components() {
        match comp {
            Component::Normal(seg) => {
                out.push(seg);
                has_part = true;
            }
            _ => return Err(io::Error::new(io::ErrorKind::PermissionDenied, "unsafe tar path")),
        }
    }
    if !has_part {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "empty tar path"));
    }
    Ok(out)
}
