const GZIP_DEFLATE = Buffer.from([0x1f, 0x8b, 0x08]);

export async function stageFirmwareGzip(spoolDir: string, fwId: string, data: Buffer): Promise<string> {
  if (!/^[a-zA-Z0-9._-]+$/.test(fwId)) {
    throw new Error("Invalid firmware identifier");
  }
  if (data.length < 10 || !data.subarray(0, 3).equals(GZIP_DEFLATE)) {
    throw new Error("Invalid gzip header");
  }
  const realSpool = await fs.realpath(spoolDir);
  const tmpPath = path.join(realSpool, `.tmp-${fwId}-${process.pid}`);
  const finalPath = path.join(realSpool, `${fwId}.tar.gz`);
  const fh = await fs.open(tmpPath, "wx", 0o600);
  try {
    await fh.writeFile(data);
    await fh.datasync();
  } finally {
    await fh.close();
  }
  await fs.rename(tmpPath, finalPath);
  return finalPath;
}
