import crypto from "node:crypto";
import tls, { PeerCertificate } from "node:tls";

export function createPinnedIdentityChecker(allowedSha256Hex: readonly string[]) {
  const pins = allowedSha256Hex.map((hex) => Buffer.from(hex, "hex"));
  return (host: string, cert: PeerCertificate): Error | undefined => {
    const hostErr = tls.checkServerIdentity(host, cert);
    if (hostErr) return hostErr;
    if (!cert.pubkey) return new Error("Missing peer public key");
    const digest = crypto.createHash("sha256").update(cert.pubkey).digest();
    const ok = pins.some((pin) => pin.length === digest.length && crypto.timingSafeEqual(pin, digest));
    return ok ? undefined : new Error("SPKI pin verification failed");
  };
}
