pub fn shannon_entropy_bytes(tok: &[u8]) -> f64 {
    if tok.is_empty() {
        return 0.0;
    }
    let mut counts = [0u32; 256];
    for &b in tok {
        counts[b as usize] += 1;
    }
    let len = tok.len() as f64;
    counts
        .iter()
        .filter(|&&c| c > 0)
        .map(|&c| {
            let p = (c as f64) / len;
            -p * p.log2()
        })
        .sum()
}

