const ALLOWED_COLS = new Set(["tenant_id", "external_id", "amount_cents", "status"]);

export function buildBulkUpsert(
  rows: Record<string, unknown>[],
  columns: readonly string[],
  updateColumns: readonly string[]
): { text: string; values: unknown[] } {
  if (rows.length === 0 || columns.length === 0) {
    throw new Error("rows and columns must be non-empty");
  }
  for (const c of [...columns, ...updateColumns]) {
    if (!ALLOWED_COLS.has(c)) throw new Error(`Disallowed column: ${c}`);
  }
  const values: unknown[] = [];
  const tuples = rows.map((row) => {
