      return `$${values.length}`;
    });
    return `(${placeholders.join(", ")})`;
  });
  const updates = updateColumns.map((c) => `${c} = EXCLUDED.${c}`).join(", ");
  const text = `INSERT INTO invoices (${columns.join(", ")}) VALUES ${tuples.join(", ")} ON CONFLICT (tenant_id, external_id) DO UPDATE SET ${updates}`;
  return { text, values };
