import (
	"encoding/binary"
	"errors"
	"io"
)

type WireFrame struct {
	Tag  uint8
	Body []byte
}

func ReadNextFrame(r io.Reader, maxPayload uint32) (WireFrame, error) {
	var hdr [5]byte
	if _, err := io.ReadFull(r, hdr[:]); err != nil {
		return WireFrame{}, err
	}
	tag := hdr[0]
	length := binary.BigEndian.Uint32(hdr[1:5])
	if length > maxPayload {
		return WireFrame{}, errors.New("tlv stream frame exceeds maxPayload")
