use std::collections::HashMap;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TxState {
    Pending,
    Authorized,
    Captured,
    Reversed,
}

pub struct LedgerEntry {
    pub state: TxState,
    pub applied_keys: HashMap<String, ([u8; 32], TxState)>,
