            if saved_hash != &payload_hash {
                return Err("idempotency key payload mismatch");
            }
            return Ok(*saved_state);
        }
        let valid = matches!(
            (self.state, next),
            (TxState::Pending, TxState::Authorized)
                | (TxState::Authorized, TxState::Captured)
                | (TxState::Authorized, TxState::Reversed)
        );
        if !valid {
            return Err("disallowed ledger state transition");
        }
        self.state = next;
        self.applied_keys.insert(idem_key.to_owned(), (payload_hash, next));
        Ok(next)
    }
}
