import { createHmac, timingSafeEqual } from "node:crypto";
import type { Redis } from "ioredis";

function computeHotp(secret: Buffer, step: bigint): string {
  const buf = Buffer.alloc(8);
  buf.writeBigUInt64BE(step);
  const digest = createHmac("sha1", secret).update(buf).digest();
  const offset = digest[digest.length - 1] & 0x0f;
  const code = (digest.readUInt32BE(offset) & 0x7fffffff) % 1_000_000;
  return code.toString().padStart(6, "0");
}

export async function verifyTotpWithReplayLock(
  redis: Redis,
  userId: string,
  secret: Buffer,
  otp: string,
  nowMs: number = Date.now(),
): Promise<boolean> {
  if (!/^\d{6}$/.test(otp)) return false;
  const curStep = BigInt(Math.floor(nowMs / 30_000));
  const otpBuf = Buffer.from(otp, "ascii");

  for (const delta of [-1n, 0n, 1n]) {
    const step = curStep + delta;
    const expectedBuf = Buffer.from(computeHotp(secret, step), "ascii");
    if (timingSafeEqual(otpBuf, expectedBuf)) {
      const lockKey = `totp:used:${userId}:${step.toString()}`;
      const acquired = await redis.set(lockKey, "1", "EX", 90, "NX");
      return acquired === "OK";
    }
  }
  return false;
}
