```rust
pub fn parse_der_tlv(buf: &[u8], max_len: usize) -> Result<(u8, &[u8], &[u8]), &'static str> {
    if buf.len() < 2 {
        return Err("truncated der header");
    }
    let tag = buf[0];
    let first_len = buf[1];
    let (val_len, hdr_len) = if (first_len & 0x80) == 0 {
        (first_len as usize, 2usize)
    } else {
        let num_octets = (first_len & 0x7F) as usize;
        if num_octets == 0 {
            return Err("indefinite length forbidden");
        }
        if num_octets > 4 {
            return Err("length octets exceed 32-bit bound");
        }
        let end_len = 2usize.checked_add(num_octets).ok_or("offset overflow")?;
        let octets = buf.get(2..end_len).ok_or("truncated long length")?;
        if octets[0] == 0 {
            return Err("leading zero in long length");
        }
        let mut acc: usize = 0;
        for &b in octets {
            acc = (acc << 8) | (b as usize);
        }
        if acc < 128 {
            return Err("non-minimal long form for <128 bytes");
        }
        (acc, end_len)
    };
    if val_len > max_len {
        return Err("tlv value exceeds max_len");
    }
    let frame_end = hdr_len.checked_add(val_len).ok_or("frame end overflow")?;
    let val = buf.get(hdr_len..frame_end).ok_or("truncated tlv value")?;
    Ok((tag, val, &buf[frame_end..]))
}
