interface PendingTask<T> {
  run: () => Promise<T>;
  resolve: (v: T) => void;
  reject: (e: unknown) => void;
  cleanup: () => void;
}

export class AbortableBoundedPool {
  private active = 0;
  private readonly waitQueue: Array<PendingTask<unknown>> = [];

  constructor(
    private readonly concurrency: number,
    private readonly queueLimit: number,
  ) {}

  enqueue<T>(run: () => Promise<T>, signal?: AbortSignal): Promise<T> {
    if (signal?.aborted) {
