    }
    if (this.active >= this.concurrency && this.waitQueue.length >= this.queueLimit) {
      return Promise.reject(new Error("queue capacity reached"));
    }
    return new Promise<T>((resolve, reject) => {
      const onAbort = (): void => {
        const idx = this.waitQueue.indexOf(entry as PendingTask<unknown>);
        if (idx !== -1) {
          this.waitQueue.splice(idx, 1);
          reject(signal?.reason ?? new Error("task aborted in queue"));
        }
      };
      const entry: PendingTask<T> = {
        run,
        resolve,
        reject,
        cleanup: () => signal?.removeEventListener("abort", onAbort),
      };
      signal?.addEventListener("abort", onAbort, { once: true });
      this.waitQueue.push(entry as PendingTask<unknown>);
      this.pump();
    });
  }

  private pump(): void {
    while (this.active < this.concurrency && this.waitQueue.length > 0) {
      const item = this.waitQueue.shift()!;
      item.cleanup();
      this.active += 1;
      Promise.resolve()
        .then(() => item.run())
        .then(item.resolve, item.reject)
        .finally(() => {
          this.active -= 1;
          this.pump();
        });
    }
  }
}
```
Detaching `abort` listeners inside `item.cleanup()` prevents listener leaks on long-lived parent `AbortController` instances.

