import re

BOUNDARY_RE = re.compile(r"^[A-Za-z0-9'()+_,./:=?-]{1,70}$")

def validate_multipart_content_type(header_val: str) -> tuple[bool, str]:
    parts = [p.strip() for p in header_val.split(";") if p.strip()]
    if not parts or parts[0].lower() != "multipart/form-data":
        return False, "not multipart/form-data"
    boundaries: list[str] = []
    for param in parts[1:]:
        key, sep, val = param.partition("=")
        if sep and key.strip().lower() == "boundary":
            boundaries.append(val.strip().strip('"'))
    if len(boundaries) != 1:
        return False, "must contain exactly one boundary parameter"
    if not BOUNDARY_RE.match(boundaries[0]):
