package upload

import (
	"errors"
	"io"
	"net/http"
)

func ReadBoundedMultipart(w http.ResponseWriter, r *http.Request, maxTotal, maxPart int64, maxParts int) (int, error) {
	r.Body = http.MaxBytesReader(w, r.Body, maxTotal)
	mr, err := r.MultipartReader()
	if err != nil {
		return 0, err
	}
	count := 0
	for {
		part, err := mr.NextPart()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return count, err
		}
		count++
		if count > maxParts {
			_ = part.Close()
			return count, errors.New("too many multipart fields")
		}
		n, copyErr := io.Copy(io.Discard, io.LimitReader(part, maxPart+1))
		_ = part.Close()
		if copyErr != nil || n > maxPart {
			return count, errors.New("multipart field exceeded per-part limit")
		}
	}
	return count, nil
}
