use axum::{extract::Multipart, http::StatusCode};

pub async fn handle_safe_upload(mut mp: Multipart) -> Result<StatusCode, StatusCode> {
    let mut fields_seen = 0usize;
    while let Some(mut field) = mp.next_field().await.map_err(|_| StatusCode::BAD_REQUEST)? {
        fields_seen += 1;
        if fields_seen > 5 {
            return Err(StatusCode::PAYLOAD_TOO_LARGE);
        }
        if let Some(fname) = field.file_name() {
            if fname.contains('/') || fname.contains('\\') || fname.contains("..") {
                return Err(StatusCode::BAD_REQUEST);
            }
        }
        let mut part_bytes = 0usize;
        while let Some(chunk) = field.chunk().await.map_err(|_| StatusCode::BAD_REQUEST)? {
            part_bytes = part_bytes.saturating_add(chunk.len());
            if part_bytes > 512 * 1024 {
                return Err(StatusCode::PAYLOAD_TOO_LARGE);
            }
        }
    }
    Ok(StatusCode::OK)
}
