)

func SaveVerifiedTIFF(destDir, baseName string, r io.Reader, maxBytes int64) (string, error) {
	cleanName := filepath.Base(baseName)
	if cleanName == "." || cleanName == ".." {
		return "", errors.New("invalid filename")
	}
	tmp, err := os.CreateTemp(destDir, ".tiff-*")
	if err != nil {
		return "", err
	}
	tmpPath := tmp.Name()
	defer func() {
		if tmpPath != "" {
			_ = os.Remove(tmpPath)
		}
	}()
	n, err := io.Copy(tmp, io.LimitReader(r, maxBytes+1))
	if err != nil || n < 4 || n > maxBytes {
		_ = tmp.Close()
		return "", errors.New("invalid TIFF size")
	}
	hdr := make([]byte, 4)
	if _, err := tmp.ReadAt(hdr, 0); err != nil {
		_ = tmp.Close()
		return "", err
	}
	if !bytes.Equal(hdr, []byte{0x49, 0x49, 0x2a, 0x00}) && !bytes.Equal(hdr, []byte{0x4d, 0x4d, 0x00, 0x2a}) {
		_ = tmp.Close()
		return "", errors.New("bad TIFF header")
	}
	if err := tmp.Sync(); err != nil {
		_ = tmp.Close()
		return "", err
	}
	if err := tmp.Close(); err != nil {
		return "", err
	}
	dst := filepath.Join(destDir, cleanName)
	if err := os.Rename(tmpPath, dst); err != nil {
		return "", err
	}
	tmpPath = ""
	return dst, nil
}
