interface Bucket {
  tokens: number;
  lastSec: number;
  dropped: number;
}

export function detectPodLogBursts(
  events: Iterable<{ podUid: string; tsSec: number }>,
  ratePerSec = 100,
  burst = 250
): Map<string, number> {
  const buckets = new Map<string, Bucket>();
  for (const ev of events) {
    let b = buckets.get(ev.podUid);
    if (!b) {
      if (buckets.size >= 5000) continue;
      b = { tokens: burst, lastSec: ev.tsSec, dropped: 0 };
      buckets.set(ev.podUid, b);
    }
    const elapsed = Math.max(0, ev.tsSec - b.lastSec);
    b.tokens = Math.min(burst, b.tokens + elapsed * ratePerSec);
    b.lastSec = ev.tsSec;
    if (b.tokens >= 1) b.tokens -= 1;
    else b.dropped += 1;
  }
  return new Map([...buckets.entries()].filter(([, v]) => v.dropped > 0).map(([k, v]) => [k, v.dropped]));
}
