	}
	_, err = tx.ExecContext(ctx,
		"UPDATE accounts SET balance_cents = balance_cents - $1 WHERE id = $2 AND tenant_id = $3",
		debitCents, accountID, tenantID,
	)
	if err != nil {
		return err
	}
	return tx.Commit()
}
