import * as ts from "typescript";

export function lintJwtVerify(fileName: string, src: string): string[] {
  const sf = ts.createSourceFile(fileName, src, ts.ScriptTarget.Latest, true);
  const alerts: string[] = [];

  function visit(node: ts.Node): void {
    if (
      ts.isCallExpression(node) &&
      ts.isPropertyAccessExpression(node.expression) &&
      node.expression.name.text === "verify"
    ) {
      const opts = node.arguments[2];
      if (!opts || !ts.isObjectLiteralExpression(opts)) {
        const { line } = sf.getLineAndCharacterOfPosition(node.getStart(sf));
        alerts.push(`${fileName}:${line + 1}: jwt.verify() missing explicit options/algorithms object`);
      } else {
        const algProp = opts.properties.find((p) => p.name?.getText(sf) === "algorithms");
        if (!algProp || algProp.getText(sf).toLowerCase().includes("none")) {
          const { line } = sf.getLineAndCharacterOfPosition(opts.getStart(sf));
          alerts.push(`${fileName}:${line + 1}: jwt.verify() missing safe algorithms allowlist`);
        }
      }
    }
    ts.forEachChild(node, visit);
  }

  visit(sf);
  return alerts;
}
