import math
from collections import Counter

def char_classes(s: str) -> int:
    return (
        any(c.islower() for c in s)
        + any(c.isupper() for c in s)
        + any(c.isdigit() for c in s)
        + any(c in "+/_-=" for c in s)
    )

def has_embedded_secret(text: str, window: int = 32, min_h: float = 4.35) -> bool:
    if len(text) < window:
        return False
    for i in range(len(text) - window + 1):
        chunk = text[i : i + window]
        if any(c.isspace() for c in chunk) or char_classes(chunk) < 3:
            continue
        counts = Counter(chunk)
        h = -sum((v / window) * math.log2(v / window) for v in counts.values())
        if h >= min_h:
            return True
    return False
