export function validateHstsHeader(headerValue: string): string[] {
  const parts = headerValue
    .split(";")
    .map((p) => p.trim())
    .filter(Boolean);
  const errs: string[] = [];
  let maxAge: number | null = null;
  let hasSub = false;
  let hasPreload = false;

  for (const part of parts) {
    const lower = part.toLowerCase();
    if (lower.startsWith("max-age=")) {
      maxAge = Number(lower.slice("max-age=".length));
    } else if (lower === "includesubdomains") {
      hasSub = true;
    } else if (lower === "preload") {
      hasPreload = true;
    }
  }
  if (maxAge === null || !Number.isInteger(maxAge) || maxAge < 31_536_000) {
    errs.push("max-age must be an integer >= 31536000");
  }
  if (!hasSub) errs.push("missing includeSubDomains directive");
  if (!hasPreload) errs.push("missing preload directive");
  return errs;
}
