from typing import Optional

def parse_rfc5424_pri(line: str) -> Optional[dict[str, object]]:
    if not line.startswith("<") or len(line) > 8192:
        return None
    end = line.find(">", 1, 6)
    if end == -1 or not line[1:end].isdigit():
        return None
    pri = int(line[1:end])
    if not (0 <= pri <= 191):
        return None
    rest = line[end + 1 :].split(" ", 6)
    if len(rest) < 6 or rest[0] != "1":
        return None
    return {"facility": pri >> 3, "severity": pri & 0x07, "host": rest[2], "app": rest[3]}
