pub fn parse_sd_params(block: &str) -> Option<(&str, Vec<(String, String)>)> {
    let inner = block.strip_prefix('[')?.strip_suffix(']')?;
    let (sd_id, rest) = inner.split_once(' ').unwrap_or((inner, ""));
    let mut params = Vec::new();
    let mut chars = rest.chars().peekable();
    while chars.peek().is_some() {
        while chars.peek() == Some(&' ') { chars.next(); }
        let key: String = chars.by_ref().take_while(|&c| c != '=').collect();
        if key.is_empty() || chars.next() != Some('"') { break; }
        let (mut val, mut esc) = (String::new(), false);
        for c in chars.by_ref() {
            if esc { val.push(c); esc = false; }
            else if c == '\\' { esc = true; }
            else if c == '"' { break; }
            else { val.push(c); }
        }
        params.push((key, val));
    }
    Some((sd_id, params))
}
