func UnpackBoundedTar(tr *tar.Reader, root *os.Root, maxTotal int64, maxFiles int) error {
	remaining := maxTotal
	count := 0
	for {
		hdr, err := tr.Next()
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return err
		}
		if hdr.Typeflag != tar.TypeReg {
			continue
		}
		count++
		if count > maxFiles || hdr.Size < 0 || hdr.Size > remaining {
			return errors.New("cache quota exceeded")
		}
		remaining -= hdr.Size
		f, err := root.OpenFile(hdr.Name, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o640)
		if err != nil {
			return err
		}
		_, cErr := io.CopyN(f, tr, hdr.Size)
		_ = f.Close()
		if cErr != nil {
			return cErr
		}
	}
