use std::fs::{self, File};
use std::io::{self, Read, Write};
use std::path::Path;

const ZSTD_MAGIC: [u8; 4] = [0x28, 0xb5, 0x2f, 0xfd];

pub fn stage_zstd_cache<R: Read>(mut src: R, cache_dir: &Path, key: &str, max_bytes: u64) -> io::Result<()> {
    if !key.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-') {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "unsafe cache key"));
    }
    let root = fs::canonicalize(cache_dir)?;
    let mut head = [0u8; 4];
    src.read_exact(&mut head)?;
    if head != ZSTD_MAGIC {
        return Err(io::Error::new(io::ErrorKind::InvalidData, "missing zstd magic"));
    }
    let tmp = root.join(format!(".tmp-{key}.zst"));
    let dst = root.join(format!("{key}.zst"));
    let mut out = File::create(&tmp)?;
    out.write_all(&head)?;
    let n = io::copy(&mut src.take(max_bytes - 3), &mut out)?;
    if n + 4 > max_bytes {
        let _ = fs::remove_file(&tmp);
        return Err(io::Error::new(io::ErrorKind::FileTooLarge, "zstd cache exceeds cap"));
    }
    out.sync_all()?;
    fs::rename(tmp, dst)
}
