import hashlib
from pathlib import Path

def compute_tree_digest(root_dir: str) -> str:
    root = Path(root_dir).resolve()
    entries: list[tuple[str, str]] = []
    for p in root.rglob("*"):
        if p.is_symlink():
            raise ValueError(f"unexpected symlink: {p}")
        if p.is_file():
            rel = p.relative_to(root).as_posix()
            fh = hashlib.sha256(p.read_bytes()).hexdigest()
            entries.append((rel, fh))
    tree_hash = hashlib.sha256()
    for rel, fh in sorted(entries):
        tree_hash.update(f"{len(rel)}:{rel}:{fh}\n".encode("utf-8"))
    return tree_hash.hexdigest()
