from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey, Ed25519PublicKey

def _frame_message(domain: str, message: bytes) -> bytes:
    dom = domain.encode("utf-8")
    return struct.pack(">H", len(dom)) + dom + b"\x00" + message

def sign_ed25519(priv_bytes: bytes, domain: str, message: bytes) -> bytes:
    if len(priv_bytes) != 32 or not domain:
        raise ValueError("32-byte seed and non-empty domain required")
    key = Ed25519PrivateKey.from_private_bytes(priv_bytes)
    return key.sign(_frame_message(domain, message))

