import { createPublicKey, verify } from "node:crypto";

const ED25519_SPKI_PREFIX = Buffer.from("302a300506032b6570032100", "hex");

export function verifyEd25519Detached(
  rawPublicKey: Buffer,
  domain: string,
  payload: Buffer,
  signature: Buffer,
): boolean {
  if (rawPublicKey.byteLength !== 32 || signature.byteLength !== 64 || !domain) {
    return false;
  }
  const keyObj = createPublicKey({
    key: Buffer.concat([ED25519_SPKI_PREFIX, rawPublicKey]),
    format: "der",
    type: "spki",
  });
  const domBuf = Buffer.from(domain, "utf8");
  const header = Buffer.alloc(2);
  header.writeUInt16BE(domBuf.byteLength, 0);
  const framed = Buffer.concat([header, domBuf, payload]);
  return verify(null, framed, keyObj, signature);
}
