package alignedtlv

import (
	"encoding/binary"
	"errors"
)

type Attr struct {
	Type  uint16
	Value []byte
}

func ParseAlignedAttrs(buf []byte, maxAttrs int) ([]Attr, error) {
	var attrs []Attr
	off := 0
	for off < len(buf) {
		if len(attrs) >= maxAttrs {
			return nil, errors.New("attribute count limit exceeded")
		}
		if len(buf)-off < 4 {
			return nil, errors.New("truncated aligned tlv header")
		}
		attrLen := int(binary.LittleEndian.Uint16(buf[off : off+2]))
		attrType := binary.LittleEndian.Uint16(buf[off+2 : off+4])
		if attrLen < 4 || attrLen > len(buf)-off {
			return nil, errors.New("invalid aligned tlv length")
		}
		val := make([]byte, attrLen-4)
		copy(val, buf[off+4:off+attrLen])
		attrs = append(attrs, Attr{Type: attrType, Value: val})
		padded := (attrLen + 3) &^ 3
		if padded > len(buf)-off {
			off = len(buf)
		} else {
			off += padded
		}
	}
	return attrs, nil
}
