pub struct AsyncPermitPool {
    sem: Arc<Semaphore>,
}

impl AsyncPermitPool {
    pub fn new(max_in_flight: usize) -> Self {
        assert!(max_in_flight > 0);
        Self {
            sem: Arc::new(Semaphore::new(max_in_flight)),
        }
