export class BigIntLedgerHold {
  private state: TransferState = "INIT";
  private reservedMinor = 0n;
  private readonly seen = new Map<string, IdemEntry>();

  transition(idemKey: string, next: TransferState, amountMinor: bigint): TransferState {
    if (amountMinor <= 0n) {
      throw new RangeError("amountMinor must be positive bigint");
    }
    const prev = this.seen.get(idemKey);
    if (prev) {
      if (prev.amount !== amountMinor || prev.target !== next) {
        throw new Error("idempotency parameter mismatch");
      }
      return this.state;
    }
    const allowed =
      (this.state === "INIT" && next === "RESERVED") ||
      (this.state === "RESERVED" && amountMinor === this.reservedMinor && (next === "COMMITTED" || next === "RELEASED"));
    if (!allowed) {
      throw new Error(`illegal transition ${this.state} -> ${next}`);
    }
    if (next === "RESERVED") {
      this.reservedMinor = amountMinor;
    }
    this.state = next;
    this.seen.set(idemKey, { amount: amountMinor, target: next });
    return this.state;
  }
}
