const PREFIXES: &[&str] = &["ghp_", "gho_", "github_pat_", "xoxb-", "xoxp-"];

fn entropy(s: &str) -> f64 {
    let mut freq = [0u32; 128];
    let n = s.len() as f64;
    for b in s.bytes() {
        if (b as usize) < 128 {
            freq[b as usize] += 1;
        }
    }
    freq.iter()
        .filter(|&&c| c > 0)
        .map(|&c| {
            let p = (c as f64) / n;
            -p * p.log2()
        })
        .sum()
}

pub fn detect_prefixed_secrets(blob: &str) -> Vec<(usize, String)> {
    let mut hits = Vec::new();
    for (idx, line) in blob.lines().enumerate() {
        for word in line.split(|c: char| !c.is_ascii_alphanumeric() && c != '_' && c != '-') {
            if PREFIXES.iter().any(|p| word.starts_with(p)) && word.len() >= 24 && entropy(word) >= 3.8 {
                hits.push((idx + 1, format!("{}...", &word[..8])));
