```ts
export async function readBodyBounded(
  res: Response,
  maxBytes = 1024 * 1024,
  timeoutMs = 5000,
): Promise<Uint8Array> {
  if (!res.body) return new Uint8Array(0);
  const reader = res.body.getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  const deadline = Date.now() + timeoutMs;
  while (true) {
    const rem = deadline - Date.now();
    if (rem <= 0) { await reader.cancel(); throw new Error("Response body read timeout"); }
    const { done, value } = await Promise.race([
      reader.read(),
      new Promise<never>((_, rej) => setTimeout(() => rej(new Error("Chunk read timeout")), rem)),
    ]);
    if (done) break;
    total += value.byteLength;
    if (total > maxBytes) { await reader.cancel(); throw new Error("Response exceeded byte limit"); }
    chunks.push(value);
  }
  return Buffer.concat(chunks, total);
}
