func AuditWorldWritablePerms(filename string) ([]string, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filename, nil, 0)
	if err != nil {
		return nil, err
	}
	var findings []string
	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 2 {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok || (sel.Sel.Name != "Chmod" && sel.Sel.Name != "Mkdir" && sel.Sel.Name != "OpenFile") {
			return true
		}
		lit, ok := call.Args[len(call.Args)-1].(*ast.BasicLit)
		if ok && lit.Kind == token.INT {
			if mode, err := strconv.ParseUint(lit.Value, 0, 32); err == nil && (mode&0o002) != 0 {
				found := fset.Position(lit.Pos())
				findings = append(findings, fmt.Sprintf("%s: world-writable mode %s in %s", found, lit.Value, sel.Sel.Name))
			}
		}
		return true
	})
