pub fn check_dangling_bom_refs(raw_json: &str) -> Result<Vec<String>, serde_json::Error> {
    let sbom: SbomGraph = serde_json::from_str(raw_json)?;
    let known: HashSet<&str> = sbom.components.iter().filter_map(|c| c.bom_ref.as_deref()).collect();
    let mut dangling = Vec::new();
    for dep in &sbom.dependencies {
        for target in std::iter::once(&dep.node_ref).chain(dep.depends_on.iter()) {
            if !known.contains(target.as_str()) {
                dangling.push(format!("dangling bom-ref in dependency graph: {}", target));
