package middleware

import (
	"bytes"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/base64"
	"io"
	"net/http"
	"strings"
)

func RequireContentDigestSHA256(maxBytes int64, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		hdr := strings.TrimSpace(r.Header.Get("Content-Digest"))
		if !strings.HasPrefix(hdr, "sha-256=:") || !strings.HasSuffix(hdr, ":") {
			http.Error(w, "missing or invalid Content-Digest", http.StatusBadRequest)
			return
		}
		b64 := strings.TrimSuffix(strings.TrimPrefix(hdr, "sha-256=:"), ":")
		claimed, err := base64.StdEncoding.DecodeString(b64)
		if err != nil || len(claimed) != sha256.Size {
			http.Error(w, "malformed Content-Digest", http.StatusBadRequest)
			return
		}
		r.Body = http.MaxBytesReader(w, r.Body, maxBytes)
		body, err := io.ReadAll(r.Body)
		if err != nil {
			http.Error(w, "body read failed", http.StatusRequestEntityTooLarge)
			return
		}
		actual := sha256.Sum256(body)
		if subtle.ConstantTimeCompare(actual[:], claimed) != 1 {
			http.Error(w, "Content-Digest mismatch", http.StatusUnauthorized)
			return
		}
		r.Body = io.NopCloser(bytes.NewReader(body))
		next.ServeHTTP(w, r)
	})
}
