use ed25519_dalek::{Signature, VerifyingKey};

pub fn verify_ed25519_webhook(
    pubkey_bytes: &[u8; 32],
    sig_hex: &str,
    timestamp_hdr: &str,
    body: &[u8],
    now_unix: i64,
    max_skew_s: i64,
) -> Result<(), &'static str> {
    let ts = timestamp_hdr.parse::<i64>().map_err(|_| "invalid timestamp")?;
    if (now_unix - ts).abs() > max_skew_s {
        return Err("stale timestamp");
    }
    let vk = VerifyingKey::from_bytes(pubkey_bytes).map_err(|_| "bad public key")?;
    let raw_sig = hex::decode(sig_hex).map_err(|_| "invalid hex signature")?;
    let sig = Signature::from_slice(&raw_sig).map_err(|_| "invalid signature length")?;

    let mut message = Vec::with_capacity(timestamp_hdr.len() + body.len());
    message.extend_from_slice(timestamp_hdr.as_bytes());
    message.extend_from_slice(body);
    vk.verify_strict(&message, &sig).map_err(|_| "Ed25519 verification failed")
}
