```typescript
import crypto from "node:crypto";

export function verifyEndpointBoundHmac512(
  secret: Buffer,
  method: string,
  pathname: string,
  timestampHdr: string,
  sigHex: string,
  rawBody: Buffer,
  maxSkewSec = 300,
): boolean {
  if (!/^[0-9a-f]{128}$/i.test(sigHex) || !/^\d{10}$/.test(timestampHdr)) {
    return false;
  }
  const nowSec = Math.floor(Date.now() / 1000);
  if (Math.abs(nowSec - Number(timestampHdr)) > maxSkewSec) {
    return false;
  }
  const prefix = Buffer.from(`${method.toUpperCase()}\n${pathname}\n${timestampHdr}\n`, "utf8");
  const expected = crypto.createHmac("sha512", secret).update(prefix).update(rawBody).digest();
  const provided = Buffer.from(sigHex, "hex");
  return expected.byteLength === provided.byteLength && crypto.timingSafeEqual(expected, provided);
}
