func RunWithXactAdvisoryLock(ctx context.Context, pool *pgxpool.Pool, key int64, exclusive bool, fn func(pgx.Tx) error) error {
	tx, err := pool.Begin(ctx)
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback(ctx) }()

	lockSQL := "SELECT pg_advisory_xact_lock_shared($1)"
