class BoundedLocalTokenBucket:
    def __init__(self, capacity: float, refill_per_sec: float, max_buckets: int = 10000) -> None:
        if capacity <= 0 or refill_per_sec <= 0 or max_buckets < 1:
            raise ValueError("invalid limiter configuration")
        self.cap = capacity
        self.rate = refill_per_sec
        self.max_buckets = max_buckets
