        if cost <= 0 or cost > self.cap:
            return False
        now = time.monotonic()
        if key in self._buckets:
            tokens, last_ts = self._buckets.pop(key)
            tokens = min(self.cap, tokens + max(0.0, now - last_ts) * self.rate)
        else:
            if len(self._buckets) >= self.max_buckets:
                self._buckets.popitem(last=False)
