var sqliteMagic = []byte("SQLite format 3\x00")

func RestoreSQLiteSnapshot(vaultDir, destName string, src io.Reader, maxSize int64) error {
	root, err := os.OpenRoot(vaultDir)
	if err != nil {
		return err
	}
	defer root.Close()
	tmpName := ".restore-" + destName + ".tmp"
	f, err := root.OpenFile(tmpName, os.O_RDWR|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		return err
	}
	n, cErr := io.Copy(f, io.LimitReader(src, maxSize+1))
	hdr := make([]byte, 16)
	_, rErr := f.ReadAt(hdr, 0)
	if cErr != nil || rErr != nil || n > maxSize || !bytes.Equal(hdr, sqliteMagic) {
		_ = f.Close()
		_ = root.Remove(tmpName)
		return errors.New("invalid SQLite snapshot")
	}
	if err := f.Sync(); err != nil {
		_ = f.Close()
		_ = root.Remove(tmpName)
		return err
	}
	if err := f.Close(); err != nil {
		_ = root.Remove(tmpName)
		return err
	}
	return root.Rename(tmpName, destName)
}
