use std::path::{Path, PathBuf};

pub fn sanitize_restore_path(base: &Path, raw: &str) -> io::Result<PathBuf> {
    if raw.is_empty() || raw.contains('\0') || raw.contains(':') || raw.starts_with('/') || raw.starts_with('\\') {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "unsafe archive path"));
