func RewrapDEK(
	keks map[uint32][]byte,
	minAllowedVer, oldVer, activeVer uint32,
	oldNonce, wrappedDEK, baseAAD []byte,
) ([]byte, []byte, error) {
	if oldVer < minAllowedVer {
		return nil, nil, errors.New("kek version retired")
	}
	oldKey, ok1 := keks[oldVer]
	newKey, ok2 := keks[activeVer]
	if !ok1 || !ok2 {
		return nil, nil, errors.New("missing kek version")
	}
	oldAEAD, err := chacha20poly1305.New(oldKey)
	if err != nil {
		return nil, nil, err
	}
	oldAAD := binary.BigEndian.AppendUint32(append([]byte(nil), baseAAD...), oldVer)
	dek, err := oldAEAD.Open(nil, oldNonce, wrappedDEK, oldAAD)
	if err != nil {
		return nil, nil, err
	}
	defer clear(dek)
	newAEAD, err := chacha20poly1305.New(newKey)
	if err != nil {
		return nil, nil, err
	}
	newNonce := make([]byte, newAEAD.NonceSize())
	if _, err := rand.Read(newNonce); err != nil {
		return nil, nil, err
	}
	newAAD := binary.BigEndian.AppendUint32(append([]byte(nil), baseAAD...), activeVer)
	return newNonce, newAEAD.Seal(nil, newNonce, dek, newAAD), nil
}
