use zeroize::Zeroizing;

pub fn rewrap_dek_monotonic(
    ring: &BTreeMap<u32, [u8; 32]>,
    src_ver: u32,
    dst_ver: u32,
    src_nonce: &[u8; 12],
    wrapped_dek: &[u8],
    record_id: &[u8],
) -> Result<([u8; 12], Vec<u8>), &'static str> {
