```typescript
import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

export function rotateWrappedDek(
  keyRing: ReadonlyMap<number, Buffer>,
  currentVersion: number,
  nextVersion: number,
  wrapIv: Buffer,
  wrapTag: Buffer,
  wrappedDek: Buffer,
  recordContext: string,
): { version: number; wrapIv: Buffer; wrapTag: Buffer; wrappedDek: Buffer } {
  if (nextVersion <= currentVersion) throw new Error("KEK version must strictly increase");
  const oldKek = keyRing.get(currentVersion);
  const newKek = keyRing.get(nextVersion);
  if (!oldKek || !newKek) throw new Error("Missing KEK in ring");

  const decipher = createDecipheriv("aes-256-gcm", oldKek, wrapIv, { authTagLength: 16 });
  decipher.setAAD(Buffer.from(`${recordContext}:v${currentVersion}`, "utf8"));
  decipher.setAuthTag(wrapTag);
  const dek = Buffer.concat([decipher.update(wrappedDek), decipher.final()]);
  try {
    const freshIv = randomBytes(12);
    const cipher = createCipheriv("aes-256-gcm", newKek, freshIv, { authTagLength: 16 });
    cipher.setAAD(Buffer.from(`${recordContext}:v${nextVersion}`, "utf8"));
    const nextWrapped = Buffer.concat([cipher.update(dek), cipher.final()]);
    return { version: nextVersion, wrapIv: freshIv, wrapTag: cipher.getAuthTag(), wrappedDek: nextWrapped };
  } finally {
    dek.fill(0);
  }
}
