CREATE OR REPLACE FUNCTION reverse_settled_debit(
    p_orig_tx_id BIGINT,
    p_rev_idem_key TEXT
) RETURNS BIGINT
LANGUAGE plpgsql AS $$
DECLARE
    v_orig RECORD;
    v_rev_tx_id BIGINT;
BEGIN
    SELECT tx_id INTO v_rev_tx_id
      FROM ledger_transitions
     WHERE idem_key = p_rev_idem_key;
    IF FOUND THEN
        RETURN v_rev_tx_id;
    END IF;

    SELECT tx_id, account_id, delta_minor, state
      INTO v_orig
      FROM ledger_transitions
     WHERE tx_id = p_orig_tx_id
       FOR UPDATE;

    IF NOT FOUND OR v_orig.state <> 'SETTLED' OR v_orig.delta_minor >= 0 THEN
        RAISE EXCEPTION 'eligible settled debit not found';
    END IF;

    PERFORM 1 FROM ledger_accounts WHERE account_id = v_orig.account_id FOR UPDATE;

    UPDATE ledger_transitions
       SET state = 'REVERSED'
     WHERE tx_id = p_orig_tx_id AND state = 'SETTLED';

    UPDATE ledger_accounts
       SET balance_minor = balance_minor - v_orig.delta_minor
     WHERE account_id = v_orig.account_id;

    INSERT INTO ledger_transitions (account_id, idem_key, delta_minor, parent_tx_id, state)
    VALUES (v_orig.account_id, p_rev_idem_key, -v_orig.delta_minor, p_orig_tx_id, 'SETTLED')
