func CountLeasesPerMAC(r io.Reader) map[string]int {
	leases := make(map[string]map[string]struct{})
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 4096), 16*1024)
	for sc.Scan() {
		fields := strings.Fields(sc.Text())
		for i := 0; i+2 < len(fields); i++ {
			if strings.HasPrefix(fields[i], "DHCPACK") && net.ParseIP(fields[i+1]) != nil {
				if hw, err := net.ParseMAC(fields[i+2]); err == nil {
					mac := hw.String()
					if leases[mac] == nil {
						leases[mac] = make(map[string]struct{})
					}
					leases[mac][fields[i+1]] = struct{}{}
				}
			}
		}
	}
	out := make(map[string]int, len(leases))
	for m, s := range leases {
		out[m] = len(s)
	}
	return out
}
