func VerifyFlacStream(r io.Reader, maxBytes int64, expectedHex string) error {
	want, err := hex.DecodeString(expectedHex)
	if err != nil || len(want) != sha256.Size {
		return errors.New("bad expected digest")
	}
	head := make([]byte, 4)
	if _, err := io.ReadFull(r, head); err != nil || !bytes.Equal(head, []byte("fLaC")) {
		return errors.New("missing fLaC magic")
	}
	h := sha256.New()
	h.Write(head)
	n, err := io.Copy(h, io.LimitReader(r, maxBytes-3))
	if err != nil || n+4 > maxBytes {
		return errors.New("flac stream exceeds maxBytes")
	}
	if subtle.ConstantTimeCompare(h.Sum(nil), want) != 1 {
		return errors.New("digest mismatch")
	}
	return nil
}
