const VM_SINKS = new Set(["runInContext", "runInNewContext", "runInThisContext"]);

export function lintRegexAndVm(fileName: string, src: string): string[] {
  const sf = ts.createSourceFile(fileName, src, ts.ScriptTarget.Latest, true);
  const alerts: string[] = [];

