  async runNow<T>(work: () => Promise<T>): Promise<T> {
    if (this.active >= this.maxActive) {
      throw new Error("runner concurrency bound reached");
    }
    this.active += 1;
    let timer: ReturnType<typeof setTimeout> | undefined;
    try {
      const timeoutPromise = new Promise<never>((_, reject) => {
        timer = setTimeout(() => reject(new Error("worker task timed out")), this.timeoutMs);
