use std::io::{BufRead, Error, ErrorKind, Read, Result};

pub fn read_headers_bounded<R: BufRead>(mut reader: R, max_headers: usize, max_line_bytes: u64) -> Result<Vec<String>> {
    let mut headers = Vec::new();
    loop {
        let mut line = String::new();
        let n = (&mut reader).take(max_line_bytes + 1).read_line(&mut line)?;
        if n == 0 {
            return Err(Error::new(ErrorKind::UnexpectedEof, "incomplete header block"));
        }
        if n as u64 > max_line_bytes {
            return Err(Error::new(ErrorKind::InvalidData, "header line too long"));
        }
        if line == "\r\n" || line == "\n" {
            return Ok(headers);
        }
        if headers.len() >= max_headers {
            return Err(Error::new(ErrorKind::InvalidData, "too many headers"));
        }
        headers.push(line);
    }
