import hashlib
import hmac

def verify_spki_merkle_proof(spki_der: bytes, proof: list[tuple[str, bytes]], root_hash: bytes) -> bool:
    node = hashlib.sha256(b"\x00" + spki_der).digest()
    for side, sibling in proof:
        if len(sibling) != 32:
            return False
        if side == "R":
            node = hashlib.sha256(b"\x01" + node + sibling).digest()
        elif side == "L":
            node = hashlib.sha256(b"\x01" + sibling + node).digest()
        else:
            return False
    return len(root_hash) == 32 and hmac.compare_digest(node, root_hash)
