pub fn check_rsa_modulus_sanity(mod_be: &[u8]) -> Result<(), &'static str> {
    let trimmed = match mod_be.iter().position(|&b| b != 0) {
        Some(idx) => &mod_be[idx..],
        None => return Err("zero modulus"),
    };
    let bits = (trimmed.len() - 1) * 8 + (8 - trimmed[0].leading_zeros() as usize);
    if bits < 3072 {
        return Err("modulus smaller than 3072 bits");
    }
    if (trimmed[trimmed.len() - 1] & 1) == 0 {
        return Err("modulus is even");
    }
    for p in [3u32, 5, 7, 11, 13, 17, 19, 23, 29] {
        let mut rem = 0u32;
        for &b in trimmed {
            rem = ((rem << 8) | (b as u32)) % p;
        }
        if rem == 0 {
            return Err("modulus divisible by small prime");
        }
    }
    Ok(())
}
