def audit_dockerfile_copy_sources(dockerfile_text: str) -> list[tuple[int, str]]:
    findings: list[tuple[int, str]] = []
    for lineno, raw in enumerate(dockerfile_text.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split()
        if parts[0].upper() not in ("COPY", "ADD"):
            continue
        args = [p for p in parts[1:] if not p.startswith("--")]
        if len(args) < 2:
