            if clean == ".":
                findings.append((lineno, "wildcard COPY . copies entire build context"))
            elif any(fnmatch.fnmatch(clean.split("/")[-1], pat) for pat in SENSITIVE_GLOBS):
                findings.append((lineno, f"sensitive source copied into image: {src}"))
    return findings
