type CounterSealer struct {
	aead       cipher.AEAD
	instanceID uint32
	counter    atomic.Uint64
}

func NewCounterSealer(key []byte, instanceID uint32) (*CounterSealer, error) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	aead, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	return &CounterSealer{aead: aead, instanceID: instanceID}, nil
}

func (s *CounterSealer) Seal(plaintext, aad []byte) ([]byte, []byte, error) {
	seq := s.counter.Add(1)
	if seq == math.MaxUint64 {
		return nil, nil, errors.New("gcm counter exhausted; rotate key immediately")
	}
	nonce := make([]byte, 12)
	binary.BigEndian.PutUint32(nonce[0:4], s.instanceID)
	binary.BigEndian.PutUint64(nonce[4:12], seq)
	return nonce, s.aead.Seal(nil, nonce, plaintext, aad), nil
