package weights

import (
	"encoding/binary"
	"errors"
	"os"
)

func ValidSafetensorsPrefix(buf []byte) bool {
	if len(buf) < 9 || buf[8] != '{' {
		return false
	}
	n := binary.LittleEndian.Uint64(buf[:8])
	return n > 0 && n <= 8*1024*1024 && uint64(len(buf)) >= 8+n
}

func WriteShard(repoDir, shardFile string, payload []byte) error {
	if !ValidSafetensorsPrefix(payload) {
		return errors.New("malformed safetensors header")
	}
	root, err := os.OpenRoot(repoDir)
	if err != nil {
		return err
	}
	defer root.Close()
	tmp := ".tmp-" + shardFile
	f, err := root.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o640)
	if err != nil {
		return err
	}
	_, wErr := f.Write(payload)
	sErr := f.Sync()
	cErr := f.Close()
	if wErr != nil || sErr != nil || cErr != nil {
		_ = root.Remove(tmp)
		return errors.New("shard write failed")
	}
	return root.Rename(tmp, shardFile)
}
