package jsonseq

import (
	"bufio"
	"bytes"
	"encoding/json"
	"io"
)

func SplitRS(data []byte, atEOF bool) (int, []byte, error) {
	if atEOF && len(data) == 0 {
		return 0, nil, nil
	}
	if i := bytes.IndexByte(data, 0x1e); i >= 0 {
		if i == 0 {
			return 1, nil, nil
		}
		return i + 1, bytes.TrimSpace(data[:i]), nil
	}
	if atEOF {
		return len(data), bytes.TrimSpace(data), nil
	}
	return 0, nil, nil
}

func CountValidSeqObjects(r io.Reader) int {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 4096), 64*1024)
	sc.Split(SplitRS)
	n := 0
	for sc.Scan() {
		if len(sc.Bytes()) > 0 && json.Valid(sc.Bytes()) {
			n++
		}
	}
	return n
}
