export function detectFlappingUnits(events: Iterable<UnitRestartEvent>, windowSec = 600, maxRestarts = 5): string[] {
  const history = new Map<string, number[]>();
  const flapping = new Set<string>();
  for (const ev of events) {
    const u = ev.unitName.slice(0, 80);
    if (flapping.has(u) || history.size >= 5000) continue;
