export function parseVarintTlv(
  buf: Uint8Array,
  offset = 0,
  maxPayloadBytes = 1048576,
): { tag: number; payload: Uint8Array; nextOffset: number } {
  if (offset < 0 || offset >= buf.byteLength) {
    throw new RangeError("missing tlv tag byte");
  }
  const tag = buf[offset];
  let cursor = offset + 1;
  let length = 0;
  let factor = 1;

  for (let i = 0; i < 5; i++) {
    if (cursor >= buf.byteLength) {
      throw new RangeError("truncated varint length");
    }
    const b = buf[cursor++];
    if (i === 4 && (b & 0xf0) !== 0) {
      throw new RangeError("varint overflows uint32");
    }
    length = (length + (b & 0x7f) * factor) >>> 0;
    if ((b & 0x80) === 0) {
      if (length > maxPayloadBytes || length > buf.byteLength - cursor) {
        throw new RangeError("tlv payload length out of bounds");
      }
      return { tag, payload: buf.slice(cursor, cursor + length), nextOffset: cursor + length };
    }
    factor *= 128;
  }
  throw new RangeError("unterminated varint");
}
```
