func ValidWoff2(data []byte) bool {
	if len(data) < 48 || !bytes.Equal(data[:4], []byte("wOF2")) {
		return false
	}
	declared := binary.BigEndian.Uint32(data[8:12])
	return int(declared) == len(data)
}

func StoreWoff2(cdnRoot, relName string, data []byte) error {
	if !ValidWoff2(data) {
		return errors.New("invalid WOFF2 header")
	}
	root, err := os.OpenRoot(cdnRoot)
	if err != nil {
		return err
	}
	defer root.Close()
	tmp := ".tmp-" + relName
	f, err := root.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
	if err != nil {
		return err
	}
	_, wErr := f.Write(data)
	sErr := f.Sync()
	cErr := f.Close()
	if wErr != nil || sErr != nil || cErr != nil {
		_ = root.Remove(tmp)
		return errors.New("woff2 staging failed")
	}
	return root.Rename(tmp, relName)
}
