```rust
use std::fs::{self, File};
use std::io::{self, Read, Write};
use std::path::Path;
use zip::ZipArchive;

pub fn unpack_woff2_zip<R: Read + io::Seek>(reader: R, cdn_dir: &Path, max_len: u64) -> io::Result<()> {
    let root = fs::canonicalize(cdn_dir)?;
    let mut za = ZipArchive::new(reader)
        .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
    for idx in 0..za.len() {
        let entry = za.by_index(idx)
            .map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e))?;
        if entry.is_dir() {
            continue;
        }
        if entry.is_symlink() {
            return Err(io::Error::new(io::ErrorKind::PermissionDenied, "symlink font entry"));
        }
        let rel = entry.enclosed_name()
            .ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "zip-slip blocked"))?
            .to_path_buf();
        let mut buf = Vec::new();
        entry.take(max_len + 1).read_to_end(&mut buf)?;
        if buf.len() as u64 > max_len || !buf.starts_with(b"wOF2") {
            return Err(io::Error::new(io::ErrorKind::InvalidData, "invalid wOF2 payload"));
        }
        let dst = root.join(rel);
        if let Some(p) = dst.parent() {
            fs::create_dir_all(p)?;
        }
        File::create(dst)?.write_all(&buf)?;
    }
    Ok(())
}
