import { createHash } from "crypto";
import { Pool, PoolClient } from "pg";

export async function withTenantResourceLock<T>(
  pool: Pool,
  tenantId: string,
  resourceKey: string,
  work: (client: PoolClient) => Promise<T>
): Promise<T> {
  const digest = createHash("sha256").update(`${tenantId}:${resourceKey}`).digest();
  const k1 = digest.readInt32BE(0);
  const k2 = digest.readInt32BE(4);
  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    const { rows } = await client.query<{ locked: boolean }>(
      "SELECT pg_try_advisory_xact_lock($1, $2) AS locked, set_config('app.tenant_id', $3, true)",
      [k1, k2, tenantId]
    );
    if (!rows[0]?.locked) {
      throw new Error("Resource advisory lock is currently held");
    }
    const out = await work(client);
    await client.query("COMMIT");
    return out;
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}
