package middleware

import (
	"bytes"
	"crypto/sha256"
	"crypto/subtle"
	"io"
	"net/http"
	"sync"
)

func IdempotencyBodyBinding(maxBytes int64, next http.Handler) http.Handler {
	var mu sync.Mutex
	seen := make(map[string][32]byte)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodPost {
			next.ServeHTTP(w, r)
			return
		}
		key := r.Header.Get("Idempotency-Key")
		if len(key) < 16 || len(key) > 64 {
			http.Error(w, "invalid Idempotency-Key", http.StatusBadRequest)
			return
		}
		r.Body = http.MaxBytesReader(w, r.Body, maxBytes)
		body, err := io.ReadAll(r.Body)
		if err != nil {
			http.Error(w, "payload too large", http.StatusRequestEntityTooLarge)
			return
		}
		digest := sha256.Sum256(body)
		mu.Lock()
		prev, exists := seen[key]
		if !exists {
			seen[key] = digest
		}
		mu.Unlock()
		if exists && subtle.ConstantTimeCompare(prev[:], digest[:]) != 1 {
			http.Error(w, "idempotency key payload mismatch", http.StatusUnprocessableEntity)
			return
		}
		r.Body = io.NopCloser(bytes.NewReader(body))
		next.ServeHTTP(w, r)
	})
}
