pub fn scoped_idempotency_digest(
    tenant_id: &str,
    method: &str,
    route: &str,
    raw_key: &str,
) -> Result<[u8; 32], &'static str> {
    let bytes = raw_key.as_bytes();
    if bytes.len() < 16 || bytes.len() > 128 {
        return Err("Idempotency-Key length out of bounds");
    }
    if !bytes.iter().all(|b| (0x21..=0x7e).contains(b)) {
        return Err("Idempotency-Key contains invalid characters");
    }
    let mut hasher = Sha256::new();
    for part in [tenant_id, method, route, raw_key] {
        hasher.update((part.len() as u32).to_be_bytes());
        hasher.update(part.as_bytes());
    }
    Ok(hasher.finalize().into())
}
