import { Request, Response, NextFunction } from "express";

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export function deduplicateWebhookDelivery(ttlMs = 600_000) {
  const states = new Map<string, { state: "inflight" | "done"; expiresAt: number }>();
  return (req: Request, res: Response, next: NextFunction): void => {
    const id = (req.header("x-github-delivery") ?? "").toLowerCase();
    if (!UUID_RE.test(id)) {
      res.status(400).json({ error: "missing or invalid X-GitHub-Delivery UUID" });
      return;
    }
    const now = Date.now();
    for (const [k, v] of states) {
      if (v.expiresAt <= now) states.delete(k);
      else break;
    }
    const existing = states.get(id);
    if (existing) {
      res.status(existing.state === "inflight" ? 409 : 200).json({ deduplicated: true });
      return;
    }
    states.set(id, { state: "inflight", expiresAt: now + ttlMs });
    res.on("finish", () => {
      if (res.statusCode >= 200 && res.statusCode < 300) {
        states.set(id, { state: "done", expiresAt: Date.now() + ttlMs });
      } else {
        states.delete(id);
      }
    });
    next();
  };
}
