func OpenHybrid(priv *ecdh.PrivateKey, packet, context []byte) ([]byte, error) {
	if len(packet) < 32+12+16 {
		return nil, errors.New("hybrid packet too short")
	}
	ephPub, err := ecdh.X25519().NewPublicKey(packet[:32])
	if err != nil {
		return nil, err
	}
	shared, err := priv.ECDH(ephPub)
	if err != nil {
		return nil, err
	}
	defer clear(shared)
	transcript := append([]byte("c04-hybrid-v1:"), packet[:32]...)
	transcript = append(transcript, priv.PublicKey().Bytes()...)
	transcript = append(transcript, context...)

	r := hkdf.New(sha256.New, shared, nil, transcript)
	k := make([]byte, 32)
	defer clear(k)
	if _, err := io.ReadFull(r, k); err != nil {
		return nil, err
	}
	block, err := aes.NewCipher(k)
	if err != nil {
		return nil, err
	}
	aead, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	return aead.Open(nil, packet[32:44], packet[44:], transcript)
}
