use hkdf::Hkdf;
use rand_core::OsRng;
use sha2::Sha256;
use x25519_dalek::{EphemeralSecret, PublicKey};
use zeroize::Zeroizing;

pub fn seal_ephemeral(rcpt_pub: &PublicKey, msg: &[u8], ctx: &[u8]) -> Result<Vec<u8>, &'static str> {
    let eph_sec = EphemeralSecret::random_from_rng(OsRng);
    let eph_pub = PublicKey::from(&eph_sec);
    let shared = eph_sec.diffie_hellman(rcpt_pub);

