    info.extend_from_slice(eph_pub.as_bytes());
    info.extend_from_slice(rcpt_pub.as_bytes());
    info.extend_from_slice(ctx);

    let hk = Hkdf::<Sha256>::new(Some(b"c04-kem-v1"), shared.as_bytes());
    let mut key_mat = Zeroizing::new([0u8; 44]);
