    let cipher = ChaCha20Poly1305::new_from_slice(&key_mat[..32]).map_err(|_| "bad key")?;
    let ct = cipher
        .encrypt(Nonce::from_slice(&key_mat[32..44]), Payload { msg, aad: &info })
        .map_err(|_| "aead seal failed")?;
    let mut out = Vec::with_capacity(32 + ct.len());
    out.extend_from_slice(eph_pub.as_bytes());
    out.extend_from_slice(&ct);
    Ok(out)
}
