import { createCipheriv, createPublicKey, diffieHellman, generateKeyPairSync, hkdfSync, randomBytes } from "node:crypto";

const X25519_SPKI_HDR = Buffer.from("302a300506032b656e032100", "hex");

export function sealHybridX25519(rcptRawPub: Buffer, plaintext: Buffer, context: Buffer): Buffer {
  if (rcptRawPub.byteLength !== 32) throw new RangeError("X25519 pubkey must be 32 bytes");
  const rcptKey = createPublicKey({ key: Buffer.concat([X25519_SPKI_HDR, rcptRawPub]), format: "der", type: "spki" });
  const { publicKey, privateKey } = generateKeyPairSync("x25519");
  const ephSpki = publicKey.export({ format: "der", type: "spki" }) as Buffer;
  const ephRaw = ephSpki.subarray(ephSpki.byteLength - 32);
  const shared = diffieHellman({ privateKey, publicKey: rcptKey });
  const okm = Buffer.from(hkdfSync("sha256", shared, "c04-x25519-salt", Buffer.concat([ephRaw, rcptRawPub, context]), 32));
  try {
    const iv = randomBytes(12);
    const cipher = createCipheriv("aes-256-gcm", okm, iv, { authTagLength: 16 });
    cipher.setAAD(Buffer.concat([ephRaw, rcptRawPub, context]));
    const ct = Buffer.concat([cipher.update(plaintext), cipher.final()]);
    return Buffer.concat([ephRaw, iv, cipher.getAuthTag(), ct]);
  } finally {
    shared.fill(0);
    okm.fill(0);
  }
}
