pub fn audit_requirements_hashes(content: &str) -> Vec<String> {
    let joined = content.replace("\\\n", " ");
    let mut errs = Vec::new();
    for (idx, raw) in joined.lines().enumerate() {
        let line = raw.split('#').next().unwrap_or("").trim();
        if line.is_empty() {
            continue;
        }
        if line.starts_with("-e") || line.contains("--extra-index-url") || line.contains("--trusted-host") {
            errs.push(format!("line {}: forbidden pip flag in '{}'", idx + 1, line));
            continue;
        }
        if line.starts_with('-') {
            continue;
        }
        let has_pin = line.contains("==");
        let has_sha256 = line.split_whitespace().any(|t| {
            t.strip_prefix("--hash=sha256:").is_some_and(|h| h.len() == 64 && h.chars().all(|c| c.is_ascii_hexdigit()))
        });
        if !has_pin || !has_sha256 {
            errs.push(format!("line {}: missing '==' pin or valid --hash=sha256: digest", idx + 1));
        }
    }
    errs
}
