pub fn check_cross_origin_isolated(
    coop: Option<&str>,
    coep: Option<&str>,
    corp: Option<&str>,
) -> Result<(), &'static str> {
    let primary = |v: Option<&str>| -> String {
        v.unwrap_or("")
            .split(';')
            .next()
            .unwrap_or("")
            .trim()
            .to_ascii_lowercase()
    };
