        return Err("COOP must be same-origin");
    }
    let coep_val = primary(coep);
    if coep_val != "require-corp" && coep_val != "credentialless" {
        return Err("COEP must be require-corp or credentialless");
    }
    let corp_val = primary(corp);
    if !matches!(corp_val.as_str(), "same-origin" | "same-site") {
        return Err("CORP should be same-origin or same-site");
    }
    Ok(())
}
