const PREAUTH_RE =
  /Disconnected from authenticating user\s+(\S+)\s+([0-9a-fA-F:.]+)\s+port\s+\d+\s+\[preauth\]/;

export function detectDistributedSshSpray(
  lines: string[],
  minDistinctIps = 5
): Record<string, number> {
