  for (const line of lines) {
    const m = PREAUTH_RE.exec(line);
    if (!m) continue;
    const [, user, ip] = m;
    if (!ipsByUser.has(user)) ipsByUser.set(user, new Set());
    ipsByUser.get(user)!.add(ip);
  }
  const flagged: Record<string, number> = {};
  for (const [user, ipSet] of ipsByUser.entries()) {
    if (ipSet.size >= minDistinctIps) flagged[user] = ipSet.size;
  }
  return flagged;
