```typescript
export interface SqlFragment {
  sql: string;
  params: unknown[];
}

export function inListFragment(column: string, allowedCols: ReadonlySet<string>, items: unknown[]): SqlFragment {
  if (!allowedCols.has(column)) {
    throw new Error(`Disallowed column: ${column}`);
  }
  if (items.length === 0) {
    return { sql: "FALSE", params: [] };
  }
  const marks = items.map(() => "?").join(", ");
  return { sql: `"${column}" IN (${marks})`, params: [...items] };
}

export function compileWhere(fragments: SqlFragment[]): { whereSql: string; values: unknown[] } {
  const values: unknown[] = [];
  const parts = fragments.map((frag) => {
    let idx = 0;
    return frag.sql.replace(/\?/g, () => {
      values.push(frag.params[idx++]);
      return `$${values.length}`;
    });
  });
  return { whereSql: parts.length ? parts.join(" AND ") : "TRUE", values };
}
