package linter

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
)

func AuditCookieFlags(filename string) ([]string, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filename, nil, 0)
	if err != nil {
		return nil, err
	}
	var hits []string
	ast.Inspect(f, func(n ast.Node) bool {
		cl, ok := n.(*ast.CompositeLit)
		if !ok {
			return true
		}
		sel, ok := cl.Type.(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != "Cookie" {
			return true
		}
		httpOnly, secure := false, false
		for _, elt := range cl.Elts {
			kv, ok := elt.(*ast.KeyValueExpr)
			if !ok {
				continue
			}
			k, ok1 := kv.Key.(*ast.Ident)
			v, ok2 := kv.Value.(*ast.Ident)
			if ok1 && ok2 && v.Name == "true" {
				if k.Name == "HttpOnly" {
					httpOnly = true
				} else if k.Name == "Secure" {
					secure = true
				}
			}
		}
		if !httpOnly || !secure {
			hits = append(hits, fmt.Sprintf("%s: http.Cookie missing HttpOnly/Secure true", fset.Position(cl.Pos())))
		}
		return true
	})
	return hits, nil
}
