import { Algorithm, hash, verify } from "@node-rs/argon2";
import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

export async function createSealedCredential(
  pepper: Buffer,
  wrapKey: Buffer,
  userId: string,
  candidate: string,
): Promise<Buffer> {
