  const c = createCipheriv("chacha20-poly1305", wrapKey, iv, { authTagLength: 16 });
  c.setAAD(Buffer.from(userId, "utf8"), { plaintextLength: Buffer.byteLength(phc) });
  const body = Buffer.concat([c.update(phc, "utf8"), c.final()]);
  return Buffer.concat([iv, c.getAuthTag(), body]);
}

export async function checkSealedCredential(
  pepper: Buffer,
  wrapKey: Buffer,
  userId: string,
  blob: Buffer,
  candidate: string,
): Promise<boolean> {
  const d = createDecipheriv("chacha20-poly1305", wrapKey, blob.subarray(0, 12), { authTagLength: 16 });
  const ct = blob.subarray(28);
  d.setAAD(Buffer.from(userId, "utf8"), { plaintextLength: ct.byteLength });
  d.setAuthTag(blob.subarray(12, 28));
  const phc = Buffer.concat([d.update(ct), d.final()]).toString("utf8");
  return verify(phc, candidate, { secret: pepper });
}
