```go
package shardedrl

import (
	"hash/fnv"
	"sync"
	"time"
)

type entry struct {
	tokens float64
	last   time.Time
}

type shard struct {
	mu    sync.Mutex
	items map[string]entry
}

type ShardedLimiter struct {
	shards      [64]shard
	cap         float64
	rate        float64
	maxPerShard int
}

func NewShardedLimiter(cap, rate float64, maxPerShard int) *ShardedLimiter {
	l := &ShardedLimiter{cap: cap, rate: rate, maxPerShard: maxPerShard}
	for i := range l.shards {
		l.shards[i].items = make(map[string]entry)
	}
	return l
}

func (l *ShardedLimiter) Allow(key string) bool {
	h := fnv.New32a()
	_, _ = h.Write([]byte(key))
	s := &l.shards[h.Sum32()&63]
	now := time.Now()

	s.mu.Lock()
	defer s.mu.Unlock()
	e, ok := s.items[key]
	if !ok {
		if len(s.items) >= l.maxPerShard {
			for victim := range s.items {
				delete(s.items, victim)
				break
			}
		}
		e = entry{tokens: l.cap, last: now}
	} else {
		dt := now.Sub(e.last).Seconds()
		if dt > 0 {
			e.tokens = min(l.cap, e.tokens+dt*l.rate)
		}
	}
	if e.tokens < 1.0 {
		e.last = now
		s.items[key] = e
		return false
	}
	e.tokens -= 1.0
	e.last = now
	s.items[key] = e
	return true
}
```
