    IF EXISTS (SELECT 1 FROM escrow_idem WHERE escrow_id = p_escrow_id AND idem_key = p_idem_key) THEN
        RETURN TRUE;
    END IF;

    SELECT escrow_id, escrow_acct_id, payee_acct_id, amount_minor, state
      INTO v_esc
      FROM escrow_holds
     WHERE escrow_id = p_escrow_id
       FOR UPDATE;

