package linter

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
)

func AuditVariableExecPath(filename string) ([]string, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filename, nil, 0)
	if err != nil {
		return nil, err
	}
	var findings []string
	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) == 0 {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok || (sel.Sel.Name != "Command" && sel.Sel.Name != "CommandContext") {
			return true
		}
		binIdx := 0
		if sel.Sel.Name == "CommandContext" && len(call.Args) > 1 {
			binIdx = 1
		}
		if lit, ok := call.Args[binIdx].(*ast.BasicLit); !ok || lit.Kind != token.STRING {
			found := fset.Position(call.Pos())
			findings = append(findings, fmt.Sprintf("%s: non-constant binary path in exec.%s", found, sel.Sel.Name))
		}
		return true
	})
	return findings, nil
}
