func UnpackLayerSafe(tr *tar.Reader, scratchDir string, maxFile int64) error {
	root, err := os.OpenRoot(scratchDir)
	if err != nil {
		return err
	}
	defer root.Close()
	for {
		hdr, err := tr.Next()
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return err
		}
		if strings.HasPrefix(filepath.Base(hdr.Name), ".wh.") {
			return errors.New("whiteout entry rejected")
		}
		switch hdr.Typeflag {
		case tar.TypeDir:
			_ = root.Mkdir(hdr.Name, 0o750)
		case tar.TypeReg:
			if hdr.Size < 0 || hdr.Size > maxFile {
				return errors.New("layer file exceeds cap")
			}
			perm := os.FileMode(hdr.Mode) & 0o0640
			f, err := root.OpenFile(hdr.Name, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, perm)
			if err != nil {
				return err
			}
			_, cErr := io.CopyN(f, tr, hdr.Size)
			_ = f.Close()
			if cErr != nil {
				return cErr
			}
		default:
			return errors.New("special tar entry blocked")
		}
	}
}
