use std::io::{self, Read};
use std::path::{Component, Path};
use tar::{Archive, EntryType};

pub fn validate_oci_archive<R: Read>(reader: R, dst_root: &Path) -> io::Result<()> {
    let mut ar = Archive::new(reader);
    ar.set_unpack_xattrs(false);
    ar.set_preserve_permissions(false);
    for item in ar.entries()? {
        let mut entry = item?;
        let kind = entry.header().entry_type();
        if kind != EntryType::Regular && kind != EntryType::Directory {
            return Err(io::Error::new(io::ErrorKind::InvalidData, "disallowed entry type"));
