        for comp in rel.components() {
            match comp {
                Component::Normal(s) if !s.to_string_lossy().starts_with(".wh.") => {}
                _ => return Err(io::Error::new(io::ErrorKind::PermissionDenied, "unsafe OCI path")),
            }
        }
        if kind == EntryType::Regular {
            entry.unpack_in(dst_root)?;
        }
    }
    Ok(())
