func VerifySignedBody(pub ed25519.PublicKey, r io.Reader, sigHex, tsHeader string, now time.Time) ([]byte, error) {
	if len(pub) != ed25519.PublicKeySize {
		return nil, errors.New("bad public key size")
	}
	ts, err := strconv.ParseInt(tsHeader, 10, 64)
	if err != nil || now.Sub(time.Unix(ts, 0)).Abs() > 5*time.Minute {
