		return nil, errors.New("malformed ed25519 signature")
	}
	body, err := io.ReadAll(io.LimitReader(r, 1<<20))
	if err != nil {
		return nil, err
	}
	msg := append([]byte(tsHeader+"."), body...)
	if !ed25519.Verify(pub, msg, sig) {
		return nil, errors.New("ed25519 signature mismatch")
	}
	return body, nil
