use ed25519_dalek::{Signature, VerifyingKey};
use sha2::{Digest, Sha256};

pub fn verify_signed_artifact(
    pubkey: &[u8; 32],
    manifest: &[u8],
    manifest_sig: &[u8; 64],
    expected_sha256: &[u8; 32],
    artifact_bytes: &[u8],
) -> Result<(), &'static str> {
    let vk = VerifyingKey::from_bytes(pubkey).map_err(|_| "invalid pubkey")?;
    let sig = Signature::from_bytes(manifest_sig);
    vk.verify_strict(manifest, &sig).map_err(|_| "manifest signature invalid")?;

    let actual = Sha256::digest(artifact_bytes);
    let mut diff = 0u8;
    for (a, b) in actual.iter().zip(expected_sha256.iter()) {
        diff |= a ^ b;
    }
    if diff != 0 {
        return Err("artifact sha256 mismatch");
    }
    Ok(())
}
