```typescript
export async function verifyWebhookEd25519(
  pubKeyRaw: Uint8Array,
  signature: Uint8Array,
  deliveryId: string,
  timestampSec: number,
  rawBody: Uint8Array,
  seenIds: Set<string>,
  nowSec: number,
  maxSkewSec = 300,
): Promise<boolean> {
  if (pubKeyRaw.byteLength !== 32 || signature.byteLength !== 64 || !deliveryId) return false;
  if (seenIds.has(deliveryId) || Math.abs(nowSec - timestampSec) > maxSkewSec) return false;

  const prefix = new TextEncoder().encode(`${deliveryId}.${timestampSec}.`);
  const msg = new Uint8Array(prefix.byteLength + rawBody.byteLength);
  msg.set(prefix, 0);
  msg.set(rawBody, prefix.byteLength);

  const key = await crypto.subtle.importKey("raw", pubKeyRaw, { name: "Ed25519" }, false, ["verify"]);
  const valid = await crypto.subtle.verify("Ed25519", key, signature, msg);
  if (valid) seenIds.add(deliveryId);
  return valid;
}
