```typescript
export function validateParsedJsonBounds(
  value: unknown,
  maxDepth = 12,
  maxTotalKeys = 500,
): void {
  let keysSeen = 0;
  function walk(node: unknown, depth: number): void {
    if (depth > maxDepth) {
      throw new Error("JSON nesting depth exceeded");
    }
    if (node === null || typeof node !== "object") {
      return;
    }
    if (Array.isArray(node)) {
      if (node.length > maxTotalKeys) throw new Error("JSON array length exceeded");
      for (const item of node) walk(item, depth + 1);
      return;
    }
    const ownKeys = Object.getOwnPropertyNames(node);
    if (ownKeys.includes("__proto__") || ownKeys.includes("constructor")) {
      throw new Error("forbidden prototype key in JSON");
    }
    keysSeen += ownKeys.length;
    if (keysSeen > maxTotalKeys) {
      throw new Error("JSON key count exceeded");
    }
    for (const k of ownKeys) {
      walk((node as Record<string, unknown>)[k], depth + 1);
    }
  }
  walk(value, 0);
}
