export class TlvStreamAssembler {
  private buf = new Uint8Array(0);

  constructor(private readonly maxFrameBytes = 65536) {}

  pushChunk(chunk: Uint8Array): Array<{ tag: number; payload: Uint8Array }> {
    if (this.buf.byteLength + chunk.byteLength > this.maxFrameBytes + 5) {
      this.buf = new Uint8Array(0);
      throw new Error("tlv stream buffer limit exceeded");
    }
    const merged = new Uint8Array(this.buf.byteLength + chunk.byteLength);
    merged.set(this.buf, 0);
    merged.set(chunk, this.buf.byteLength);
    this.buf = merged;

    const out: Array<{ tag: number; payload: Uint8Array }> = [];
    let offset = 0;
    const view = new DataView(this.buf.buffer, this.buf.byteOffset, this.buf.byteLength);

    while (this.buf.byteLength - offset >= 5) {
      const tag = view.getUint8(offset);
      const len = view.getUint32(offset + 1, false);
      if (len > this.maxFrameBytes) {
        this.buf = new Uint8Array(0);
        throw new Error("declared tlv frame exceeds maxFrameBytes");
      }
      if (this.buf.byteLength - offset - 5 < len) {
        break;
      }
      out.push({ tag, payload: this.buf.slice(offset + 5, offset + 5 + len) });
      offset += 5 + len;
    }
    if (offset > 0) {
      this.buf = this.buf.slice(offset);
    }
    return out;
  }
}
