use hmac::{Hmac, Mac};
use sha2::Sha256;
use std::net::IpAddr;
use url::Url;

type HmacSha256 = Hmac<Sha256>;

pub fn sign_outbound_webhook(
    target_url: &str,
    secret: &[u8],
    unix_ts: i64,
    body: &[u8],
) -> Result<String, &'static str> {
    let parsed = Url::parse(target_url).map_err(|_| "invalid URL")?;
    if parsed.scheme() != "https" || parsed.port_or_known_default() != Some(443) {
        return Err("webhook URL must use https on port 443");
    }
    if let Some(host) = parsed.host_str() {
        if let Ok(ip) = host.parse::<IpAddr>() {
            let forbidden = match ip {
                IpAddr::V4(v4) => v4.is_private() || v4.is_loopback() || v4.is_link_local(),
                IpAddr::V6(v6) => v6.is_loopback() || v6.is_unspecified(),
            };
            if forbidden {
                return Err("private or loopback webhook IP forbidden");
            }
        }
    }
    let mut mac = HmacSha256::new_from_slice(secret).map_err(|_| "invalid secret")?;
    mac.update(unix_ts.to_string().as_bytes());
    mac.update(b".");
    mac.update(body);
    let hex_tag = hex::encode(mac.finalize().into_bytes());
    Ok(format!("t={unix_ts},v1={hex_tag}"))
}
