import crypto from "node:crypto";
import { Request, Response, NextFunction } from "express";

export function requireClientCertPin(allowedSha256Hex: string[]) {
  const pins = allowedSha256Hex.map((h) => Buffer.from(h, "hex"));
  return (req: Request, res: Response, next: NextFunction): void => {
    const hdr = (req.header("client-cert") ?? "").trim();
    if (!hdr.startsWith(":") || !hdr.endsWith(":") || hdr.length < 16) {
      res.status(403).json({ error: "missing RFC 9440 Client-Cert header" });
      return;
    }
    const der = Buffer.from(hdr.slice(1, -1), "base64");
    const actualFp = crypto.createHash("sha256").update(der).digest();
    let matched = false;
    for (const pin of pins) {
      if (pin.byteLength === actualFp.byteLength && crypto.timingSafeEqual(pin, actualFp)) {
        matched = true;
      }
    }
    if (!matched) {
      res.status(403).json({ error: "unrecognized client certificate" });
      return;
    }
    next();
  };
}
