package canonicaltlv

import (
	"encoding/binary"
	"errors"
	"math"
	"slices"
)

func EncodeCanonicalMap(fields map[uint8][]byte, maxTotal int) ([]byte, error) {
	tags := make([]uint8, 0, len(fields))
	total := 0
	for k, v := range fields {
		if len(v) > math.MaxUint16 {
			return nil, errors.New("tlv field exceeds uint16 bound")
		}
		total += 3 + len(v)
		if total > maxTotal {
			return nil, errors.New("canonical tlv packet exceeds maxTotal")
		}
		tags = append(tags, k)
	}
	slices.Sort(tags)

	out := make([]byte, 0, total)
	var hdr [3]byte
	for _, t := range tags {
		val := fields[t]
		hdr[0] = t
		binary.BigEndian.PutUint16(hdr[1:3], uint16(len(val)))
		out = append(out, hdr[:]...)
		out = append(out, val...)
	}
	return out, nil
}
