pub fn validate_lua_bucket_args(
    capacity: u32,
    refill_per_sec: f64,
    cost: u32,
) -> Result<ValidatedBucketArgs, &'static str> {
    if capacity == 0 || capacity > 1_000_000 {
        return Err("capacity out of bounds");
    }
