func AuditZipSlipJoin(filename string) ([]string, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, filename, nil, 0)
	if err != nil {
		return nil, err
	}
	var findings []string
	for _, decl := range f.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok || fn.Body == nil {
			continue
		}
		hasJoinName, hasPrefixGuard := false, false
		var joinPos token.Pos
		ast.Inspect(fn.Body, func(n ast.Node) bool {
			call, ok := n.(*ast.CallExpr)
			if !ok {
				return true
			}
			sel, ok := call.Fun.(*ast.SelectorExpr)
			if !ok {
				return true
			}
			if sel.Sel.Name == "HasPrefix" {
				hasPrefixGuard = true
			} else if sel.Sel.Name == "Join" {
				for _, arg := range call.Args {
					if aSel, ok := arg.(*ast.SelectorExpr); ok && aSel.Sel.Name == "Name" {
						hasJoinName = true
						joinPos = call.Pos()
					}
				}
			}
			return true
		})
		if hasJoinName && !hasPrefixGuard {
			found := fset.Position(joinPos)
			findings = append(findings, fmt.Sprintf("%s: filepath.Join on archive .Name without HasPrefix guard", found))
		}
	}
	return findings, nil
}
