import math

class BoundedAIMDController:
    def __init__(self, initial: int = 16, min_limit: int = 2, max_limit: int = 128, backoff: float = 0.75) -> None:
        if min_limit < 1 or max_limit < min_limit or not (0.5 <= backoff < 1.0):
            raise ValueError("invalid aimd bounds")
        self.min_limit = min_limit
        self.max_limit = max_limit
        self.backoff = backoff
        self._window = float(max(min_limit, min(max_limit, initial)))

    @property
    def current_limit(self) -> int:
        return int(self._window)

    def record_success(self) -> int:
        step = 1.0 / max(1.0, self._window)
        self._window = min(float(self.max_limit), self._window + step)
        return self.current_limit

    def record_overload(self) -> int:
        reduced = math.floor(self._window * self.backoff)
        self._window = float(max(self.min_limit, reduced))
        return self.current_limit
