func DecodeExactEnvelope(env []byte, maxItems uint16, maxItemBytes uint32) ([]Item, error) {
	if len(env) < 2 {
		return nil, errors.New("missing 2-byte batch count")
	}
	count := binary.BigEndian.Uint16(env[0:2])
	if count > maxItems {
		return nil, errors.New("declared item count exceeds maxItems")
