const LEGAL_NEXT: Record<SubState, ReadonlySet<SubState>> = {
  TRIAL: new Set(["ACTIVE", "CANCELED"]),
  ACTIVE: new Set(["PAST_DUE", "CANCELED"]),
  PAST_DUE: new Set(["ACTIVE", "CANCELED"]),
  CANCELED: new Set(),
};

export class SubscriptionStateGuard {
  private state: SubState = "TRIAL";
  private highSeq = 0n;
  private readonly applied = new Set<string>();

  applyWebhook(idemKey: string, eventSeq: bigint, target: SubState): { applied: boolean; state: SubState } {
    if (this.applied.has(idemKey)) {
      return { applied: false, state: this.state };
    }
    if (eventSeq <= this.highSeq) {
      this.applied.add(idemKey);
      return { applied: false, state: this.state };
    }
    if (target !== this.state && !LEGAL_NEXT[this.state].has(target)) {
      throw new Error(`illegal subscription transition ${this.state} -> ${target}`);
    }
    this.state = target;
    this.highSeq = eventSeq;
    this.applied.add(idemKey);
    return { applied: true, state: this.state };
  }
}
