export function validateIngressTlsCoverage(ing: IngressManifest): string[] {
  const errs: string[] = [];
  const covered = new Set<string>();
  for (const t of ing.spec?.tls ?? []) {
    if (!t.secretName?.trim()) {
      errs.push("spec.tls entry missing secretName");
      continue;
