package totp

import (
	"crypto/hmac"
	"crypto/sha1"
	"crypto/subtle"
	"encoding/binary"
	"fmt"
	"sync"
)

type Guard struct {
	mu       sync.Mutex
	lastStep map[string]int64
}

func NewGuard() *Guard {
	return &Guard{lastStep: make(map[string]int64)}
}

func hotp6(secret []byte, step int64) string {
	var buf [8]byte
	binary.BigEndian.PutUint64(buf[:], uint64(step))
	mac := hmac.New(sha1.New, secret)
	mac.Write(buf[:])
	sum := mac.Sum(nil)
	off := sum[len(sum)-1] & 0x0f
	val := (binary.BigEndian.Uint32(sum[off:off+4]) & 0x7fffffff) % 1000000
	return fmt.Sprintf("%06d", val)
}

func (g *Guard) VerifyOnce(userID string, secret []byte, code string, unixNow int64) bool {
	if len(code) != 6 {
		return false
	}
	g.mu.Lock()
	defer g.mu.Unlock()
	prev := g.lastStep[userID]
	cur := unixNow / 30
	for d := int64(-1); d <= 1; d++ {
		s := cur + d
		if s <= prev {
			continue
		}
		exp := hotp6(secret, s)
		if subtle.ConstantTimeCompare([]byte(exp), []byte(code)) == 1 {
			g.lastStep[userID] = s
			return true
		}
	}
	return false
}
