use hmac::{Hmac, Mac};
use sha1::Sha1;
use subtle::ConstantTimeEq;

type HmacSha1 = Hmac<Sha1>;

fn hotp_digits(secret: &[u8], step: u64) -> String {
    let mut mac = HmacSha1::new_from_slice(secret).expect("valid hmac key");
    mac.update(&step.to_be_bytes());
    let res = mac.finalize().into_bytes();
    let off = (res[19] & 0x0f) as usize;
    let bin = u32::from_be_bytes([res[off], res[off + 1], res[off + 2], res[off + 3]]) & 0x7fff_ffff;
    format!("{:06}", bin % 1_000_000)
}

pub fn verify_totp_monotonic(
    secret: &[u8],
    submitted: &str,
    unix_secs: u64,
    last_used_step: Option<u64>,
) -> Option<u64> {
    if submitted.len() != 6 {
        return None;
    }
    let current = unix_secs / 30;
    for candidate in [current.saturating_sub(1), current, current + 1] {
        if last_used_step.is_some_and(|prev| candidate <= prev) {
            continue;
        }
        let expected = hotp_digits(secret, candidate);
        if bool::from(expected.as_bytes().ct_eq(submitted.as_bytes())) {
            return Some(candidate);
        }
    }
    None
}
