import { createHash, randomBytes } from "node:crypto";
import type { Redis } from "ioredis";

const sha256Hex = (raw: string): string =>
  createHash("sha256").update(raw, "ascii").digest("hex");

export async function rotateHostSession(
  redis: Redis,
  oldRawSid: string | undefined,
  userId: string,
  ttlSeconds: number = 14400,
): Promise<{ rawSid: string; setCookieHeader: string }> {
  if (oldRawSid) {
    await redis.del(`sess:${sha256Hex(oldRawSid)}`);
  }
  const rawSid = randomBytes(32).toString("base64url");
  await redis.set(`sess:${sha256Hex(rawSid)}`, JSON.stringify({ userId, issuedAt: Date.now() }), "EX", ttlSeconds);
  const setCookieHeader = `__Host-sid=${rawSid}; Path=/; Max-Age=${ttlSeconds}; Secure; HttpOnly; SameSite=Strict`;
  return { rawSid, setCookieHeader };
}

export async function revokeHostSession(redis: Redis, rawSid: string | undefined): Promise<string> {
  if (rawSid) {
    await redis.del(`sess:${sha256Hex(rawSid)}`);
  }
  return "__Host-sid=; Path=/; Max-Age=0; Secure; HttpOnly; SameSite=Strict";
}
