import base64
import hashlib
import hmac

def _b64u_nopad(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b"=").decode("ascii")

def verify_oidc_at_hash(access_token: str, at_hash_claim: str) -> bool:
    full = hashlib.sha256(access_token.encode("ascii")).digest()
    expected = _b64u_nopad(full[:16])
