func SealCommitting(rootKey, msg, aad []byte) ([]byte, error) {
	salt := make([]byte, 16)
	if _, err := rand.Read(salt); err != nil {
		return nil, err
	}
	r := hkdf.New(sha256.New, rootKey, salt, []byte("c04-kc-chacha-v1"))
