	out := append(salt, mat[32:64]...)
	return append(out, ct...), nil
}

func OpenCommitting(rootKey, packet, aad []byte) ([]byte, error) {
	if len(packet) < 64 {
		return nil, errors.New("packet too short")
	}
	r := hkdf.New(sha256.New, rootKey, packet[:16], []byte("c04-kc-chacha-v1"))
