import { createDecipheriv, hkdfSync, timingSafeEqual } from "node:crypto";

export function openCommittedAesGcm(masterKey: Buffer, packet: Buffer, aad: Buffer): Buffer {
  if (masterKey.byteLength !== 32 || packet.byteLength < 64) {
    throw new RangeError("Invalid key or packet length");
  }
  const salt = packet.subarray(0, 16);
  const wireCommit = packet.subarray(16, 48);
  const wireTag = packet.subarray(48, 64);
  const ct = packet.subarray(64);

  const derived = Buffer.from(hkdfSync("sha256", masterKey, salt, "c04-kc-v1", 64));
  try {
    const encKey = derived.subarray(0, 32);
    const expectedCommit = derived.subarray(32, 64);
    if (!timingSafeEqual(wireCommit, expectedCommit)) {
      throw new Error("Key commitment check failed");
    }
    const decipher = createDecipheriv("aes-256-gcm", encKey, Buffer.alloc(12), { authTagLength: 16 });
    decipher.setAAD(Buffer.concat([aad, expectedCommit]));
    decipher.setAuthTag(wireTag);
    return Buffer.concat([decipher.update(ct), decipher.final()]);
  } finally {
    derived.fill(0);
  }
}
