pub struct BoundedBatchCollector {
    items: Vec<Vec<u8>>,
    cur_bytes: usize,
    max_items: usize,
    max_bytes: usize,
}

impl BoundedBatchCollector {
    pub fn new(max_items: usize, max_bytes: usize) -> Self {
        assert!(max_items > 0 && max_bytes > 0);
        Self {
            items: Vec::with_capacity(max_items),
            cur_bytes: 0,
            max_items,
            max_bytes,
        }
    }

    pub fn try_push(&mut self, frame: Vec<u8>) -> Result<(), Vec<u8>> {
        if self.items.len() >= self.max_items {
            return Err(frame);
        }
        let next_bytes = match self.cur_bytes.checked_add(frame.len()) {
            Some(n) if n <= self.max_bytes => n,
            _ => return Err(frame),
        };
        self.cur_bytes = next_bytes;
        self.items.push(frame);
        Ok(())
    }

    pub fn drain_batch(&mut self) -> Vec<Vec<u8>> {
        self.cur_bytes = 0;
        std::mem::take(&mut self.items)
    }
}
