```go
package tokenverify

import (
	"crypto/ed25519"
	"encoding/base64"
	"encoding/json"
	"errors"
	"strings"
)

type Header struct {
	Alg string `json:"alg"`
	Kid string `json:"kid"`
}

func VerifyCompactEdDSA(ring map[string]ed25519.PublicKey, token string) ([]byte, error) {
	parts := strings.Split(token, ".")
	if len(parts) != 3 {
		return nil, errors.New("malformed compact jws")
	}
	hdrJSON, err := base64.RawURLEncoding.DecodeString(parts[0])
	if err != nil {
		return nil, err
	}
	var hdr Header
	if err := json.Unmarshal(hdrJSON, &hdr); err != nil || hdr.Alg != "EdDSA" || hdr.Kid == "" {
		return nil, errors.New("disallowed alg or missing kid")
	}
	pub, ok := ring[hdr.Kid]
	if !ok || len(pub) != ed25519.PublicKeySize {
		return nil, errors.New("unknown signer kid")
	}
	sig, err := base64.RawURLEncoding.DecodeString(parts[2])
	if err != nil || len(sig) != ed25519.SignatureSize {
		return nil, errors.New("invalid signature encoding")
	}
	signingInput := []byte(parts[0] + "." + parts[1])
	if !ed25519.Verify(pub, signingInput, sig) {
		return nil, errors.New("ed25519 verification failed")
	}
	return base64.RawURLEncoding.DecodeString(parts[1])
}
