use ed25519_dalek::{Signature, VerifyingKey};
use std::collections::BTreeMap;

pub struct KeyEntry {
    pub pubkey: [u8; 32],
    pub not_before: u64,
    pub not_after: u64,
    pub revoked: bool,
}

pub fn verify_with_keyring(
    ring: &BTreeMap<String, KeyEntry>,
    kid: &str,
    now_epoch: u64,
    msg: &[u8],
    sig_bytes: &[u8; 64],
) -> Result<(), &'static str> {
    let entry = ring.get(kid).ok_or("unknown kid")?;
    if entry.revoked || now_epoch < entry.not_before || now_epoch >= entry.not_after {
        return Err("key revoked or outside validity window");
    }
    let vk = VerifyingKey::from_bytes(&entry.pubkey).map_err(|_| "corrupt pubkey")?;
    let sig = Signature::from_bytes(sig_bytes);
    vk.verify_strict(msg, &sig).map_err(|_| "invalid signature")
}
