```typescript
import { KeyObject, verify } from "node:crypto";

export interface DetachedSig {
  kid: string;
  signature: Buffer;
}

export function verifyTwoOfNRelease(
  pinnedKeys: ReadonlyMap<string, KeyObject>,
  revokedKids: ReadonlySet<string>,
  artifactDigest: Buffer,
  sigs: readonly DetachedSig[],
  requiredQuorum = 2,
): boolean {
  if (artifactDigest.byteLength !== 32) return false;
  const approvedBy = new Set<string>();
  const msg = Buffer.concat([Buffer.from("release-sha256:v1:", "utf8"), artifactDigest]);

  for (const item of sigs) {
    if (approvedBy.has(item.kid) || revokedKids.has(item.kid)) continue;
    if (item.signature.byteLength !== 64) continue;
    const pubKey = pinnedKeys.get(item.kid);
    if (!pubKey || pubKey.asymmetricKeyType !== "ed25519") continue;
    if (verify(null, msg, pubKey, item.signature)) {
      approvedBy.add(item.kid);
    }
  }
  return approvedBy.size >= requiredQuorum;
}
