```go
package clientauth

import (
	"crypto"
	"errors"
	"sync"
	"time"

	"github.com/golang-jwt/jwt/v5"
)

type JtiCache struct {
	mu   sync.Mutex
	seen map[string]time.Time
}

func VerifyPrivateKeyJWT(
	assertion string,
	pubKey crypto.PublicKey,
	expectedClientID string,
	tokenEndpointURL string,
	cache *JtiCache,
) error {
	claims := &jwt.RegisteredClaims{}
	tok, err := jwt.ParseWithClaims(
		assertion,
		claims,
		func(t *jwt.Token) (any, error) { return pubKey, nil },
		jwt.WithValidMethods([]string{"ES256", "RS256"}),
		jwt.WithIssuer(expectedClientID),
		jwt.WithSubject(expectedClientID),
		jwt.WithAudience(tokenEndpointURL),
		jwt.WithExpirationRequired(),
		jwt.WithIssuedAt(),
		jwt.WithLeeway(10*time.Second),
	)
	if err != nil || !tok.Valid || claims.ID == "" {
		return errors.New("invalid client assertion")
	}
	if claims.ExpiresAt.Time.Sub(claims.IssuedAt.Time) > 60*time.Second {
		return errors.New("assertion lifetime exceeds 60s")
	}
	cache.mu.Lock()
	defer cache.mu.Unlock()
	if _, dup := cache.seen[claims.ID]; dup {
		return errors.New("replayed client assertion jti")
	}
	cache.seen[claims.ID] = claims.ExpiresAt.Time
	return nil
}
