import { createHash, randomBytes } from "node:crypto";

export interface OAuthTxRecord {
  codeVerifier: string;
  state: string;
  nonce: string;
  expiresAtMs: number;
}

export function createPkceTransaction(
  txStore: Map<string, OAuthTxRecord>,
): { codeChallenge: string; state: string; nonce: string; setCookie: string } {
  const codeVerifier = randomBytes(32).toString("base64url");
  const codeChallenge = createHash("sha256").update(codeVerifier, "ascii").digest("base64url");
  const state = randomBytes(24).toString("base64url");
  const nonce = randomBytes(24).toString("base64url");
  const rawTxId = randomBytes(32).toString("base64url");
  const txKey = createHash("sha256").update(rawTxId, "ascii").digest("hex");

  txStore.set(txKey, {
    codeVerifier,
    state,
    nonce,
    expiresAtMs: Date.now() + 300_000,
  });

  const setCookie = `__Host-oauth_tx=${rawTxId}; Path=/; Max-Age=300; Secure; HttpOnly; SameSite=Lax`;
  return { codeChallenge, state, nonce, setCookie };
}
