import ast

def audit_diy_sql_escaping(source: str) -> list[tuple[int, str]]:
    tree = ast.parse(source)
    tainted_vars: set[str] = set()
    findings: list[tuple[int, str]] = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Assign) and isinstance(node.value, ast.Call) and isinstance(node.value.func, ast.Attribute):
            if node.value.func.attr in {"replace", "sub"}:
                for t in node.targets:
                    if isinstance(t, ast.Name):
                        tainted_vars.add(t.id)
    for node in ast.walk(tree):
        if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "execute" and node.args:
            q = node.args[0]
            if isinstance(q, ast.Name) and q.id in tainted_vars:
