	aead, err := chacha20poly1305.New(aeadKey)
	if err != nil {
		return nil, err
	}
	hdr := append([]byte("BKP1"), salt...)
	body := append(append(hdr, nonce...), aead.Seal(nil, nonce, payload, hdr)...)
	sig := ed25519.Sign(signPriv, body)
	return append(body, sig...), nil
