import { KeyObject, createDecipheriv, hkdfSync, verify } from "node:crypto";

export function loadSignedEncryptedConfig(
  signerPubKey: KeyObject,
  masterSecret: Buffer,
  envelope: Buffer,
  signature: Buffer,
): Buffer {
  if (signerPubKey.asymmetricKeyType !== "ed25519" || signature.byteLength !== 64) {
    throw new Error("Ed25519 key and 64-byte signature required");
  }
  if (envelope.byteLength < 44) {
    throw new RangeError("Envelope too short");
