  const iv = envelope.subarray(16, 28);
  const tag = envelope.subarray(28, 44);
  const ct = envelope.subarray(44);
  const spki = signerPubKey.export({ format: "der", type: "spki" }) as Buffer;
  const subkey = Buffer.from(hkdfSync("sha256", masterSecret, salt, "cfg-seal-v1", 32));
