import base64
import hashlib
import math
import re
from collections import Counter

PKCE_RE = re.compile(r"^[A-Za-z0-9\-._~]{43,128}$")

def shannon_entropy_per_char(s: str) -> float:
    n = len(s)
    counts = Counter(s)
    return -sum((c / n) * math.log2(c / n) for c in counts.values())

def derive_checked_pkce_s256(verifier: str, min_entropy_bits: float = 4.0) -> str:
    if not PKCE_RE.fullmatch(verifier):
        raise ValueError("verifier violates RFC 7636 length or charset")
    if shannon_entropy_per_char(verifier) < min_entropy_bits:
        raise ValueError("verifier has dangerously low entropy")
    digest = hashlib.sha256(verifier.encode("ascii")).digest()
    return base64.urlsafe_b64encode(digest).rstrip(b"=").decode("ascii")
