```python
import base64
import re

B64U_SEG_RE = re.compile(r"^[A-Za-z0-9\-_]+$")

def decode_strict_b64u(segment: str) -> bytes:
    if not segment or not B64U_SEG_RE.fullmatch(segment) or len(segment) % 4 == 1:
        raise ValueError("invalid unpadded base64url segment")
    padded = segment + "=" * (-len(segment) % 4)
    raw = base64.urlsafe_b64decode(padded)
    if base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii") != segment:
        raise ValueError("non-canonical base64url slack bits")
    return raw

def split_strict_jws(compact_jws: str) -> tuple[bytes, bytes, bytes]:
    parts = compact_jws.split(".")
    if len(parts) != 3:
        raise ValueError("compact JWS must have exactly 3 segments")
    return decode_strict_b64u(parts[0]), decode_strict_b64u(parts[1]), decode_strict_b64u(parts[2])
