type Ring struct {
	mu    sync.RWMutex
	slots map[string]KeySlot
}

func (r *Ring) ResolveES256(kid string, now time.Time) (*ecdsa.PublicKey, error) {
	r.mu.RLock()
	slot, ok := r.slots[kid]
