```typescript
const VERIFIER_PATTERN = /^[A-Za-z0-9\-._~]{43,128}$/;

function toBase64UrlNoPad(bytes: Uint8Array): string {
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

export async function verifyPkceS256Edge(
  verifier: string,
  challenge: string,
  method: string,
): Promise<boolean> {
  if (method !== "S256" || !VERIFIER_PATTERN.test(verifier) || challenge.length !== 43) {
    return false;
  }
  const buf = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(verifier));
  const computed = toBase64UrlNoPad(new Uint8Array(buf));
  if (computed.length !== challenge.length) return false;
  let diff = 0;
  for (let i = 0; i < computed.length; i++) {
    diff |= computed.charCodeAt(i) ^ challenge.charCodeAt(i);
  }
  return diff === 0;
}
