import ast

AUTH_FN_TOKENS = ("session", "pkce", "verifier", "nonce", "state", "csrf")
WEAK_RNG_ATTRS = {"random", "randint", "randrange", "choice", "choices", "randbytes", "uuid1"}

def find_weak_rng_in_auth(source: str) -> list[int]:
    tree = ast.parse(source)
    hits: list[int] = []
    for fn in ast.walk(tree):
        if not isinstance(fn, (ast.FunctionDef, ast.AsyncFunctionDef)):
