```rust
pub fn validate_host_set_cookie_line(header_val: &str) -> Result<(), &'static str> {
    let mut parts = header_val.split(';').map(str::trim);
    let first = parts.next().ok_or("empty Set-Cookie")?;
    let (name, val) = first.split_once('=').ok_or("missing cookie name=value")?;
    if !name.starts_with("__Host-") || val.is_empty() {
        return Err("not a populated __Host- cookie");
    }
    let mut secure = false;
    let mut http_only = false;
    let mut root_path = false;
    let mut same_site_ok = false;
    for attr in parts {
        let lower = attr.to_ascii_lowercase();
        if lower == "secure" {
            secure = true;
        } else if lower == "httponly" {
            http_only = true;
        } else if lower == "path=/" {
            root_path = true;
        } else if lower == "samesite=lax" || lower == "samesite=strict" {
            same_site_ok = true;
        } else if lower.starts_with("domain=") {
            return Err("__Host- cookie forbids Domain attribute");
        }
    }
    if !(secure && http_only && root_path && same_site_ok) {
        return Err("__Host- cookie missing required security attributes");
    }
    Ok(())
}
