import { createHash, timingSafeEqual } from "node:crypto";
import { createLocalJWKSet, JSONWebKeySet, jwtVerify, JWTPayload } from "jose";

export async function verifyMtlsBoundJwt(
  token: string,
  clientCertDer: Buffer,
  jwks: JSONWebKeySet,
  issuer: string,
  audience: string,
): Promise<JWTPayload> {
  const { payload } = await jwtVerify(token, createLocalJWKSet(jwks), {
    algorithms: ["ES256"],
    issuer,
    audience,
    clockTolerance: "15s",
  });
  const cnf = payload.cnf as Record<string, unknown> | undefined;
  const claimedThumb = typeof cnf?.["x5t#S256"] === "string" ? cnf["x5t#S256"] : "";
  const actualThumb = createHash("sha256").update(clientCertDer).digest("base64url");
  const a = Buffer.from(claimedThumb, "ascii");
  const b = Buffer.from(actualThumb, "ascii");
  if (a.length === 0 || a.length !== b.length || !timingSafeEqual(a, b)) {
    throw new Error("mTLS certificate thumbprint mismatch");
  }
  return payload;
}
