			return
		}
		sum := sha256.Sum256([]byte(matches[0].Value))
		now := time.Now()
		st, ok := lookup(sum, now)
		if !ok || now.After(st.IdleDeadline) || now.After(st.AbsDeadline) {
			http.Error(w, "expired session", http.StatusUnauthorized)
			return
		}
		next.ServeHTTP(w, r)
	})
