import { createHmac, timingSafeEqual } from "node:crypto";

export interface RecoverySlot {
  digest: Buffer;
  consumed: boolean;
}

export function consumeRecoveryCodeConstantTime(
  pepperKey: Buffer,
  userId: string,
  submittedCode: string,
  slots: RecoverySlot[],
): boolean {
  const cand = createHmac("sha256", pepperKey)
    .update(`${userId}:${submittedCode.trim().toUpperCase()}`, "utf8")
    .digest();
  let matchedIdx = -1;
  for (let i = 0; i < slots.length; i++) {
    const eq = timingSafeEqual(cand, slots[i].digest);
    if (eq && !slots[i].consumed) {
