export function verifyContextBoundSession(
  store: Map<string, BoundSession>,
  macSecret: Buffer,
  rawHostSid: string,
  uaMajor: string,
): string | null {
  const sidHash = createHash("sha256").update(rawHostSid, "ascii").digest("hex");
