		jwt.WithIssuer(iss),
		jwt.WithAudience(aud),
		jwt.WithExpirationRequired(),
		jwt.WithIssuedAt(),
		jwt.WithLeeway(10*time.Second),
	)
	if err != nil || !tok.Valid || claims.IssuedAt == nil {
		return nil, errors.New("eddsa jwt validation failed")
	}
	if time.Since(claims.IssuedAt.Time) > 15*time.Minute {
		return nil, errors.New("token exceeds 15m max age")
