use base64::{engine::general_purpose::URL_SAFE_NO_PAD, Engine as _};
use core::ptr::write_volatile;
use core::sync::atomic::{compiler_fence, Ordering};
use rand::{rngs::OsRng, RngCore};
use sha2::{Digest, Sha256};

pub struct ZeroizingVerifier(Vec<u8>);

impl ZeroizingVerifier {
    pub fn generate_s256_pair() -> (Self, String) {
        let mut entropy = [0u8; 32];
        OsRng.fill_bytes(&mut entropy);
        let verifier_str = URL_SAFE_NO_PAD.encode(entropy);
        let challenge = URL_SAFE_NO_PAD.encode(Sha256::digest(verifier_str.as_bytes()));
        (Self(verifier_str.into_bytes()), challenge)
    }

    pub fn as_str(&self) -> &str {
        core::str::from_utf8(&self.0).expect("valid ascii base64url")
    }
}

impl Drop for ZeroizingVerifier {
    fn drop(&mut self) {
        for byte in &mut self.0 {
            unsafe { write_volatile(byte, 0u8) };
        }
        compiler_fence(Ordering::SeqCst);
    }
