from datetime import datetime, timezone
from cryptography import x509
from cryptography.x509.oid import ExtensionOID, ExtendedKeyUsageOID

def _match_dns_san(pattern: str, hostname: str) -> bool:
    pat = pattern.rstrip(".").lower()
    host = hostname.rstrip(".").lower()
    if not pat or not host or ".." in host:
        return False
    if "*" not in pat:
        return pat == host
    if not pat.startswith("*.") or "*" in pat[2:] or pat.count(".") < 2:
        return False
    suffix = pat[1:]  # '.example.com'
    if not host.endswith(suffix):
        return False
    left_label = host[:-len(suffix)]
    return bool(left_label) and "." not in left_label

def verify_tls_server_leaf(cert: x509.Certificate, hostname: str, now: datetime | None = None) -> None:
    ts = now or datetime.now(timezone.utc)
    if ts < cert.not_valid_before_utc or ts > cert.not_valid_after_utc:
        raise ValueError("certificate outside UTC validity window")
    try:
        bc = cert.extensions.get_extension_for_oid(ExtensionOID.BASIC_CONSTRAINTS).value
        if bc.ca:
            raise ValueError("CA certificate rejected as TLS leaf")
    except x509.ExtensionNotFound:
        pass
    eku = cert.extensions.get_extension_for_oid(ExtensionOID.EXTENDED_KEY_USAGE).value
    if ExtendedKeyUsageOID.SERVER_AUTH not in eku:
        raise ValueError("missing id-kp-serverAuth ExtendedKeyUsage")
    san = cert.extensions.get_extension_for_oid(ExtensionOID.SUBJECT_ALTERNATIVE_NAME).value
    dns_sans = san.get_values_for_type(x509.DNSName)
    if not any(_match_dns_san(d, hostname) for d in dns_sans):
        raise ValueError(f"hostname {hostname!r} not matched in DNSName SANs")
