func MakeServerPeerVerifier(roots *x509.CertPool, dnsName string) func([][]byte, [][]*x509.Certificate) error {
	return func(rawCerts [][]byte, _ [][]*x509.Certificate) error {
		if len(rawCerts) == 0 {
			return errors.New("empty peer certificate list")
		}
		certs := make([]*x509.Certificate, len(rawCerts))
		for i, der := range rawCerts {
			c, err := x509.ParseCertificate(der)
			if err != nil {
				return err
			}
			certs[i] = c
		}
		leaf := certs[0]
		if leaf.IsCA {
			return errors.New("CA certificate cannot act as TLS server leaf")
		}
		if len(leaf.DNSNames) == 0 && len(leaf.IPAddresses) == 0 {
			return errors.New("leaf certificate missing SubjectAlternativeName")
		}
		inter := x509.NewCertPool()
		for _, ic := range certs[1:] {
			inter.AddCert(ic)
		}
		_, err := leaf.Verify(x509.VerifyOptions{
			DNSName:       dnsName,
			Roots:         roots,
			Intermediates: inter,
			CurrentTime:   time.Now().UTC(),
			KeyUsages:     []x509.ExtKeyUsage{x509.ExtKeyUsageServerAuth},
		})
		return err
	}
}
