use x509_parser::extensions::GeneralName;
use x509_parser::prelude::*;

pub fn extract_server_dns_sans(der: &[u8]) -> Result<Vec<String>, &'static str> {
    let (rem, cert) = parse_x509_certificate(der).map_err(|_| "invalid DER x509 certificate")?;
    if !rem.is_empty() {
        return Err("trailing bytes after DER certificate");
    }
    if cert.is_ca() {
        return Err("CA certificate rejected as leaf");
    }
    let eku = cert
        .extended_key_usage()
        .map_err(|_| "duplicate or malformed EKU")?
        .ok_or("missing ExtendedKeyUsage")?
        .value;
    if eku.any || !eku.server_auth {
        return Err("leaf must assert strict serverAuth EKU without anyExtendedKeyUsage");
    }
    let san = cert
        .subject_alternative_name()
        .map_err(|_| "malformed SAN extension")?
        .ok_or("missing SAN extension")?
        .value;
    let mut out = Vec::new();
    for name in &san.general_names {
        if let GeneralName::DNSName(d) = name {
            if !d.is_empty() && d.is_ascii() && !d.contains('\0') {
                out.push(d.to_ascii_lowercase());
            }
        }
    }
    if out.is_empty() {
        return Err("no valid DNSName SANs present");
    }
    Ok(out)
}
