```typescript
import { X509Certificate } from "node:crypto";

export function verifyNodeServerLeaf(
  leafPem: string,
  issuerPem: string,
  expectedHost: string,
  nowMs: number = Date.now(),
): string {
  const leaf = new X509Certificate(leafPem);
  const issuer = new X509Certificate(issuerPem);

  if (leaf.ca) {
    throw new Error("Leaf certificate must not have CA:TRUE");
  }
  if (!issuer.ca) {
    throw new Error("Issuer certificate must have CA:TRUE");
  }
  const validFrom = Date.parse(leaf.validFrom);
  const validTo = Date.parse(leaf.validTo);
  if (Number.isNaN(validFrom) || Number.isNaN(validTo) || nowMs < validFrom || nowMs > validTo) {
    throw new Error("Leaf certificate outside validity period");
  }
  if (!leaf.checkIssued(issuer) || !leaf.verify(issuer.publicKey)) {
    throw new Error("Leaf signature or issuer chain verification failed");
  }
  const matched = leaf.checkHost(expectedHost, { subject: "never", wildcards: true });
  if (!matched) {
    throw new Error(`Hostname ${expectedHost} did not match leaf SAN`);
  }
  return matched;
}
