const payoutLockNamespace int32 = 0x50415931 // "PAY1"

func accountLockKey(accountUUID string) int32 {
	sum := sha256.Sum256([]byte(accountUUID))
	return int32(binary.BigEndian.Uint32(sum[:4]))
}

func ExecuteSerializedPayout(
	ctx context.Context,
	pool *pgxpool.Pool,
	actorID string,
	accountUUID string,
	idempotencyKey string,
	amountCents int64,
) (string, error) {
	if amountCents <= 0 {
		return "", errors.New("amount must be positive")
	}
	tx, err := pool.BeginTx(ctx, pgx.TxOptions{IsoLevel: pgx.ReadCommitted})
	if err != nil {
		return "", err
	}
	defer tx.Rollback(ctx)

	if _, err := tx.Exec(ctx, "SELECT pg_advisory_xact_lock($1, $2)", payoutLockNamespace, accountLockKey(accountUUID)); err != nil {
		return "", err
	}
	if _, err := tx.Exec(ctx, "SELECT set_config('app.actor_id', $1, true)", actorID); err != nil {
		return "", err
	}

	var balance int64
	if err := tx.QueryRow(ctx, "SELECT available_cents FROM finance.wallets WHERE account_id = $1", accountUUID).Scan(&balance); err != nil {
		return "", err
	}
	if balance < amountCents {
		return "", errors.New("insufficient funds")
	}

	var payoutID string
	err = tx.QueryRow(ctx, `
		INSERT INTO finance.payout_requests (account_id, idempotency_key, amount_cents)
		VALUES ($1, $2, $3)
		ON CONFLICT (account_id, idempotency_key) DO NOTHING
		RETURNING payout_id
	`, accountUUID, idempotencyKey, amountCents).Scan(&payoutID)
	if errors.Is(err, pgx.ErrNoRows) {
		return "", errors.New("duplicate idempotency key")
	}
	if err != nil {
		return "", err
	}

	if _, err := tx.Exec(ctx, "UPDATE finance.wallets SET available_cents = available_cents - $1 WHERE account_id = $2", amountCents, accountUUID); err != nil {
		return "", err
	}
	return payoutID, tx.Commit(ctx)
}
