use sha2::{Digest, Sha256};
use sqlx::{PgPool, Postgres, Transaction};

#[derive(Debug)]
pub enum SweepError {
    BatchLocked,
    Db(sqlx::Error),
}

impl From<sqlx::Error> for SweepError {
    fn from(err: sqlx::Error) -> Self {
        Self::Db(err)
    }
}

pub fn derive_settlement_lock_id(corridor: &str, window_iso: &str) -> i64 {
    let mut hasher = Sha256::new();
    hasher.update(b"fintech:settlement-sweep:v1:");
    hasher.update(corridor.as_bytes());
    hasher.update(b":");
    hasher.update(window_iso.as_bytes());
    let digest = hasher.finalize();
    i64::from_be_bytes(digest[..8].try_into().expect("8-byte slice"))
}

pub async fn begin_locked_sweep<'a>(
    pool: &'a PgPool,
    corridor: &str,
    window_iso: &str,
    worker_id: &str,
) -> Result<Transaction<'a, Postgres>, SweepError> {
    let mut tx = pool.begin().await?;
    let lock_id = derive_settlement_lock_id(corridor, window_iso);

    let acquired: bool = sqlx::query_scalar("SELECT pg_try_advisory_xact_lock($1)")
        .bind(lock_id)
        .fetch_one(&mut *tx)
        .await?;

    if !acquired {
        tx.rollback().await?;
        return Err(SweepError::BatchLocked);
    }

    sqlx::query("SELECT set_config('app.worker_id', $1, true)")
        .bind(worker_id)
        .execute(&mut *tx)
        .await?;

    Ok(tx)
}
