import ast
import re
from dataclasses import dataclass

SESSION_LOCK_RE = re.compile(r"\bpg_(?:try_)?advisory_lock(?:_shared)?\s*\(", re.IGNORECASE)
ORDER_BY_RE = re.compile(r"\border\s+by\b", re.IGNORECASE)

@dataclass
class SqlAstFinding:
    lineno: int
    rule: str
    detail: str

def scan_python_sql_ast(source: str) -> list[SqlAstFinding]:
    tree = ast.parse(source)
    findings: list[SqlAstFinding] = []

    for node in ast.walk(tree):
        if not isinstance(node, ast.Call) or not node.args:
            continue
        if not isinstance(node.func, ast.Attribute):
            continue
        if node.func.attr not in {"execute", "executemany", "fetch", "fetchrow"}:
            continue

        first_arg = node.args[0]
        if isinstance(first_arg, ast.Constant) and isinstance(first_arg.value, str):
            if SESSION_LOCK_RE.search(first_arg.value):
                findings.append(SqlAstFinding(
                    lineno=node.lineno,
                    rule="PG_SESSION_ADVISORY_LOCK",
                    detail="Use pg_advisory_xact_lock instead of session-level pg_advisory_lock",
                ))
        elif isinstance(first_arg, ast.JoinedStr):
            static_parts = " ".join(
                elt.value for elt in first_arg.values
                if isinstance(elt, ast.Constant) and isinstance(elt.value, str)
            )
            if ORDER_BY_RE.search(static_parts):
                findings.append(SqlAstFinding(
                    lineno=node.lineno,
                    rule="UNSAFE_DYNAMIC_ORDER_BY",
                    detail="f-string interpolation detected in SQL ORDER BY clause",
                ))
            if SESSION_LOCK_RE.search(static_parts):
                findings.append(SqlAstFinding(
                    lineno=node.lineno,
                    rule="PG_SESSION_ADVISORY_LOCK",
                    detail="Session-level advisory lock inside dynamic SQL",
                ))
    return findings
