use std::collections::HashSet;

pub fn lint_dockerfile(contents: &str) -> Vec<String> {
    let mut findings = Vec::new();
    let mut stage_aliases = HashSet::new();
    let mut final_stage_user: Option<String> = None;
    let mut stage_idx = 0usize;

    for raw_line in contents.lines() {
        let line = raw_line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let parts: Vec<&str> = line.split_whitespace().collect();
        let instr = parts[0].to_ascii_uppercase();
        if instr == "FROM" && parts.len() >= 2 {
            stage_idx += 1;
            final_stage_user = None;
            let img = parts.iter().skip(1).find(|p| !p.starts_with("--")).copied().unwrap_or("");
            if img != "scratch" && !stage_aliases.contains(&img.to_ascii_lowercase()) {
                let valid_pin = img.split_once("@sha256:")
                    .map(|(_, h)| h.len() == 64 && h.chars().all(|c| c.is_ascii_hexdigit()))
                    .unwrap_or(false);
                if !valid_pin {
                    findings.push(format!("stage {stage_idx}: unpinned base image '{img}'"));
                }
            }
            for w in parts.windows(2) {
                if w[0].eq_ignore_ascii_case("AS") {
                    stage_aliases.insert(w[1].to_ascii_lowercase());
                }
            }
        } else if instr == "USER" && parts.len() >= 2 {
            final_stage_user = Some(parts[1].to_string());
        }
    }

    match final_stage_user.as_deref() {
        None => findings.push("final stage missing USER instruction".into()),
        Some(u) if u == "0" || u.eq_ignore_ascii_case("root") || u.starts_with("0:") || u.to_ascii_lowercase().starts_with("root:") => {
            findings.push(format!("final stage runs as root ('{u}')"));
        }
        _ => {}
    }
    findings
}
