export function findUnpinnedActions(doc: WorkflowDoc): string[] {
  const issues: string[] = [];
  for (const [jobId, job] of Object.entries(doc.jobs ?? {})) {
    if (job.uses && !job.uses.startsWith("./")) {
      const ref = job.uses.split("@")[1] ?? "";
      if (!COMMIT_SHA_RE.test(ref)) {
        issues.push(`job '${jobId}' reusable workflow not SHA-pinned: ${job.uses}`);
      }
    }
    for (const [idx, step] of (job.steps ?? []).entries()) {
      if (!step.uses || step.uses.startsWith("./")) continue;
      if (step.uses.startsWith("docker://")) {
        if (!/@sha256:[0-9a-f]{64}$/i.test(step.uses)) {
          issues.push(`job '${jobId}' step[${idx}] docker action missing sha256 digest: ${step.uses}`);
        }
        continue;
      }
      const atIdx = step.uses.lastIndexOf("@");
      const ref = atIdx === -1 ? "" : step.uses.slice(atIdx + 1);
      if (!COMMIT_SHA_RE.test(ref)) {
        issues.push(`job '${jobId}' step[${idx}] action not pinned to 40-hex SHA: ${step.uses}`);
      }
    }
  }
  return issues;
}
