package verifier

import (
	"bufio"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"os"
	"strings"
)

func VerifyManifest(baseDir string, manifest io.Reader, maxFileBytes int64) error {
	root, err := os.OpenRoot(baseDir)
	if err != nil {
		return err
	}
	defer root.Close()

	scanner := bufio.NewScanner(manifest)
	count := 0
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		if len(line) < 67 || (line[64] != ' ') || (line[65] != ' ' && line[65] != '*') {
			return errors.New("malformed manifest line")
		}
		expected, err := hex.DecodeString(line[:64])
		if err != nil {
			return fmt.Errorf("invalid hex digest: %w", err)
		}
		relPath := line[66:]
		f, err := root.Open(relPath)
		if err != nil {
			return err
		}
		info, err := f.Stat()
		if err != nil {
			f.Close()
			return err
		}
		if !info.Mode().IsRegular() || info.Size() > maxFileBytes {
			f.Close()
			return fmt.Errorf("invalid file mode or size for %s", relPath)
		}
		h := sha256.New()
		_, copyErr := io.Copy(h, io.LimitReader(f, maxFileBytes+1))
		f.Close()
		if copyErr != nil {
			return copyErr
		}
		if subtle.ConstantTimeCompare(h.Sum(nil), expected) != 1 {
			return fmt.Errorf("checksum mismatch: %s", relPath)
		}
		count++
	}
	if err := scanner.Err(); err != nil {
		return err
	}
	if count == 0 {
		return errors.New("manifest contained zero entries")
	}
	return nil
}
