use sha2::{Digest, Sha256};
use std::fs::OpenOptions;
use std::io::{BufRead, Read};
use std::os::unix::fs::OpenOptionsExt;
use std::path::{Component, Path, PathBuf};
use subtle::ConstantTimeEq;

fn safe_join(root: &Path, rel: &str) -> Result<PathBuf, &'static str> {
    if rel.is_empty() || rel.starts_with('-') {
        return Err("unsafe relative path");
    }
    let mut out = root.to_path_buf();
    for comp in Path::new(rel).components() {
        match comp {
            Component::Normal(seg) => out.push(seg),
            _ => return Err("path traversal component rejected"),
        }
    }
    Ok(out)
}

pub fn verify_manifest<R: BufRead>(root: &Path, reader: R) -> Result<usize, &'static str> {
    let mut verified = 0usize;
    for line_res in reader.lines() {
        let line = line_res.map_err(|_| "io read error")?;
        if line.trim().is_empty() {
            continue;
        }
        if line.len() < 67 {
            return Err("short manifest line");
        }
        let (hex_part, rest) = line.split_at(64);
        let rel = rest.strip_prefix("  ").or_else(|| rest.strip_prefix(" *")).ok_or("bad separator")?;
        let expected = hex::decode(hex_part).map_err(|_| "invalid hex")?;
        let target = safe_join(root, rel)?;

        let mut file = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|_| "open failed or symlink blocked")?;

        let mut hasher = Sha256::new();
        let mut buf = [0u8; 32 * 1024];
        loop {
            let n = file.read(&mut buf).map_err(|_| "read error")?;
            if n == 0 {
                break;
            }
            hasher.update(&buf[..n]);
        }
        let actual = hasher.finalize();
        if actual.as_slice().ct_eq(expected.as_slice()).unwrap_u8() != 1 {
            return Err("sha256 mismatch");
        }
        verified += 1;
    }
    if verified == 0 {
        return Err("empty manifest");
    }
    Ok(verified)
}
