    const sumFile = path.join(workDir, "SHA256SUMS");
    await writeFile(sumFile, `${expectedHex.toLowerCase()}  artifact.bin\n`, { mode: 0o600 });
    await execFileAsync("sha256sum", ["--strict", "-c", "--", sumFile], { cwd: workDir });
    return true;
  } finally {
