import hashlib
import hmac
from typing import Sequence

def merkle_leaf(rel_path: str, file_sha256: bytes) -> bytes:
    if len(file_sha256) != 32 or "\x00" in rel_path:
        raise ValueError("invalid leaf inputs")
    h = hashlib.sha256()
    h.update(b"\x00")
    h.update(rel_path.encode("utf-8"))
    h.update(b"\x00")
    h.update(file_sha256)
    return h.digest()

def merkle_parent(left: bytes, right: bytes) -> bytes:
    return hashlib.sha256(b"\x01" + left + right).digest()

def verify_merkle_proof(
    rel_path: str,
    file_sha256: bytes,
    proof: Sequence[tuple[str, bytes]],
    expected_root: bytes,
) -> bool:
    if len(expected_root) != 32:
        return False
    node = merkle_leaf(rel_path, file_sha256)
    for side, sibling in proof:
        if len(sibling) != 32:
            return False
        if side == "L":
            node = merkle_parent(sibling, node)
        elif side == "R":
            node = merkle_parent(node, sibling)
        else:
            raise ValueError(f"invalid proof direction: {side!r}")
    return hmac.compare_digest(node, expected_root)
