import ast

SUBPROC_FUNCS = {"run", "Popen", "call", "check_call", "check_output"}
GUARDED_BINS = {"rm", "cp", "mv", "tar", "sha256sum", "chmod", "chown"}

def find_missing_double_dash(source: str) -> list[tuple[int, str]]:
    tree = ast.parse(source)
    findings: list[tuple[int, str]] = []

    for node in ast.walk(tree):
        if not isinstance(node, ast.Call) or not node.args:
            continue
        func = node.func
        if not (
            isinstance(func, ast.Attribute)
            and isinstance(func.value, ast.Name)
            and func.value.id == "subprocess"
            and func.attr in SUBPROC_FUNCS
        ):
            continue

        cmd = node.args[0]
        if not isinstance(cmd, (ast.List, ast.Tuple)) or not cmd.elts:
            continue
        first = cmd.elts[0]
        if not (isinstance(first, ast.Constant) and isinstance(first.value, str)):
            continue
        prog = first.value.rsplit("/", 1)[-1]
        if prog not in GUARDED_BINS:
            continue

        saw_terminator = False
        for elt in cmd.elts[1:]:
            if isinstance(elt, ast.Constant) and elt.value == "--":
                saw_terminator = True
                break
            if not isinstance(elt, ast.Constant) and not saw_terminator:
                findings.append((node.lineno, f"{prog} called with dynamic arg before '--'"))
                break
    return findings
