    if der_chain.len() < 2 {
        return Err("chain must include at least leaf and issuer");
    }
    let mut certs = Vec::with_capacity(der_chain.len());
    for der in der_chain {
        let (rem, c) = parse_x509_certificate(der).map_err(|_| "bad DER cert")?;
        if !rem.is_empty() {
            return Err("trailing DER data");
        }
        certs.push(c);
    }
    if certs[0].is_ca() {
        return Err("leaf cannot assert CA:TRUE");
    }
    for (depth, issuer) in certs[1..].iter().enumerate() {
        let bc = issuer
            .basic_constraints()
            .map_err(|_| "invalid BasicConstraints")?
            .ok_or("issuer missing BasicConstraints")?
            .value;
        if !bc.ca {
            return Err("issuer has CA:FALSE");
        }
        if let Some(max_len) = bc.path_len_constraint {
            if depth > max_len as usize {
                return Err("pathLenConstraint exceeded");
            }
        }
        let ku = issuer
            .key_usage()
            .map_err(|_| "invalid KeyUsage")?
            .ok_or("issuer missing KeyUsage")?
            .value;
        if !ku.key_cert_sign() {
            return Err("issuer missing keyCertSign bit");
        }
    }
    Ok(())
}
