```typescript
import { X509Certificate, timingSafeEqual } from "node:crypto";

export function verifyChainToPinnedRoot(
  chainPems: readonly string[],
  pinnedRootSha256ColonHex: string,
): void {
  if (chainPems.length < 2 || chainPems.length > 4) {
    throw new Error("Invalid certificate chain length");
  }
  const certs = chainPems.map((p) => new X509Certificate(p));
  if (certs[0].ca) {
    throw new Error("Leaf certificate must have CA:FALSE");
  }
  for (let i = 0; i < certs.length - 1; i++) {
    const child = certs[i];
    const issuer = certs[i + 1];
    if (!issuer.ca) {
      throw new Error(`Certificate at index ${i + 1} is not a CA`);
    }
    if (!child.checkIssued(issuer) || !child.verify(issuer.publicKey)) {
      throw new Error(`Signature chain broken at index ${i}`);
    }
  }
  const root = certs[certs.length - 1];
  if (!root.checkIssued(root) || !root.verify(root.publicKey)) {
    throw new Error("Terminal certificate is not a valid self-signed root");
  }
  const a = Buffer.from(root.fingerprint256.toUpperCase());
  const b = Buffer.from(pinnedRootSha256ColonHex.toUpperCase());
  if (a.length !== b.length || !timingSafeEqual(a, b)) {
    throw new Error("Root fingerprint256 mismatch");
  }
}
```

