from typing import Callable, Awaitable

class MaxBodyBytesMiddleware:
    def __init__(self, app: Callable, max_bytes: int = 1_048_576) -> None:
        self.app = app
        self.max_bytes = max_bytes

    async def __call__(self, scope: dict, receive: Callable[[], Awaitable[dict]], send: Callable[[dict], Awaitable[None]]) -> None:
        if scope["type"] != "http":
            await self.app(scope, receive, send)
            return

        for k, v in scope.get("headers", []):
            if k.lower() == b"content-length":
                try:
                    if int(v) > self.max_bytes:
                        await self._reject_413(send)
                        return
                except ValueError:
                    await self._reject_413(send)
                    return

        seen = 0
        rejected = False

        async def bounded_receive() -> dict:
            nonlocal seen, rejected
            msg = await receive()
            if msg["type"] == "http.request":
                seen += len(msg.get("body", b""))
                if seen > self.max_bytes:
                    rejected = True
                    raise OverflowError("request body exceeded max_bytes")
            return msg

        try:
            await self.app(scope, bounded_receive, send)
        except OverflowError:
            if rejected:
                await self._reject_413(send)
            else:
                raise

    @staticmethod
    async def _reject_413(send: Callable[[dict], Awaitable[None]]) -> None:
        await send({
            "type": "http.response.start",
            "status": 413,
            "headers": [(b"content-type", b"text/plain; charset=utf-8")],
        })
        await send({"type": "http.response.body", "body": b"request body too large"})
