import hashlib
import hmac


def verify_rfc6962_inclusion(
    leaf_data: bytes,
    leaf_index: int,
    tree_size: int,
    audit_path: list[bytes],
    expected_root: bytes,
) -> bool:
    if len(expected_root) != 32 or tree_size <= 0 or not (0 <= leaf_index < tree_size):
        return False
    if any(len(node) != 32 for node in audit_path):
        return False

    fn = leaf_index
    sn = tree_size - 1
    acc = hashlib.sha256(b"\x00" + leaf_data).digest()

    for sibling in audit_path:
        if sn == 0:
            return False
        if (fn & 1) == 1 or fn == sn:
            acc = hashlib.sha256(b"\x01" + sibling + acc).digest()
            while (fn & 1) == 0 and fn != 0:
                fn >>= 1
                sn >>= 1
        else:
            acc = hashlib.sha256(b"\x01" + acc + sibling).digest()
        fn >>= 1
        sn >>= 1

    return sn == 0 and hmac.compare_digest(acc, expected_root)
