```go
package rsacrt

import (
	"crypto/subtle"
	"errors"
	"math/big"
)

type CRTKey struct {
	N, E   *big.Int
	P, Q   *big.Int
	Dp, Dq *big.Int
	QInv   *big.Int
}

func SignCheckedCRT(k *CRTKey, msgRep *big.Int) ([]byte, error) {
	if msgRep.Sign() <= 0 || msgRep.Cmp(k.N) >= 0 {
		return nil, errors.New("message representative out of range")
	}
	sp := new(big.Int).Exp(msgRep, k.Dp, k.P)
	sq := new(big.Int).Exp(msgRep, k.Dq, k.Q)

	diff := new(big.Int).Sub(sp, sq)
	diff.Mod(diff, k.P)
	h := new(big.Int).Mul(k.QInv, diff)
	h.Mod(h, k.P)

	sig := new(big.Int).Mul(h, k.Q)
	sig.Add(sig, sq)
	sig.Mod(sig, k.N)

	check := new(big.Int).Exp(sig, k.E, k.N)
	modLen := (k.N.BitLen() + 7) / 8
	if subtle.ConstantTimeCompare(check.FillBytes(make([]byte, modLen)), msgRep.FillBytes(make([]byte, modLen))) != 1 {
		return nil, errors.New("rsa-crt fault check failed")
	}
	return sig.FillBytes(make([]byte, modLen)), nil
}
