use sha2::{Digest, Sha256};
use subtle::ConstantTimeEq;

pub fn verify_merkle_branch(
    leaf_payload: &[u8],
    mut index: u64,
    siblings: &[[u8; 32]],
    expected_root: &[u8; 32],
) -> bool {
    if siblings.len() > 64 {
        return false;
    }
    if siblings.len() < 64 && (index >> siblings.len()) != 0 {
        return false;
    }

    let mut current: [u8; 32] = {
        let mut h = Sha256::new();
        h.update([0x00]);
        h.update(leaf_payload);
        h.finalize().into()
    };

    for sib in siblings {
        let mut h = Sha256::new();
        h.update([0x01]);
        if (index & 1) == 0 {
            h.update(current);
            h.update(sib);
        } else {
            h.update(sib);
            h.update(current);
        }
        current = h.finalize().into();
        index >>= 1;
    }

    current.ct_eq(expected_root).into()
}
