export function bits2int(buf: Uint8Array, qlen: number): bigint {
  if (qlen <= 0) {
    throw new RangeError("qlen must be positive");
  }
  let v = 0n;
  for (const b of buf) {
    v = (v << 8n) | BigInt(b);
  }
  const blen = buf.length * 8;
  if (blen > qlen) {
    v >>= BigInt(blen - qlen);
  }
  return v;
}

export function int2octets(x: bigint, q: bigint, qlen: number): Uint8Array {
  if (x <= 0n || x >= q) {
    throw new RangeError("scalar out of subgroup range [1, q-1]");
  }
  const rlen = Math.ceil(qlen / 8);
  const out = new Uint8Array(rlen);
  let tmp = x;
  for (let i = rlen - 1; i >= 0; i--) {
    out[i] = Number(tmp & 0xffn);
    tmp >>= 8n;
  }
  return out;
}
