def reconstruct_shamir_gfp(shares: list[tuple[int, int]], threshold: int, prime: int) -> int:
    if threshold < 2 or len(shares) < threshold:
        raise ValueError("insufficient shares for threshold")

    subset = shares[:threshold]
    seen_x: set[int] = set()
    for x, y in subset:
        if not (1 <= x < prime) or not (0 <= y < prime):
            raise ValueError("share coordinate out of GF(p) bounds")
        if x in seen_x:
            raise ValueError("duplicate share x-coordinate")
        seen_x.add(x)

    secret = 0
    for i, (xi, yi) in enumerate(subset):
        num = 1
        den = 1
        for j, (xj, _) in enumerate(subset):
            if i == j:
                continue
            num = (num * (-xj % prime)) % prime
            den = (den * ((xi - xj) % prime)) % prime
        lagrange_0 = (num * pow(den, -1, prime)) % prime
        secret = (secret + yi * lagrange_0) % prime

    return secret
