package ghalint

import (
	"fmt"
	"regexp"
	"strings"

	"gopkg.in/yaml.v3"
)

var sha40Re = regexp.MustCompile(`^[0-9a-fA-F]{40}$`)

func CheckActionPins(rawYAML []byte) ([]string, error) {
	var doc yaml.Node
	if err := yaml.Unmarshal(rawYAML, &doc); err != nil {
		return nil, err
	}
	var findings []string
	var visit func(n *yaml.Node)
	visit = func(n *yaml.Node) {
		if n == nil {
			return
		}
		if n.Kind == yaml.MappingNode {
			for i := 0; i+1 < len(n.Content); i += 2 {
				k, v := n.Content[i], n.Content[i+1]
				if k.Value == "uses" && v.Kind == yaml.ScalarNode {
					ref := strings.TrimSpace(v.Value)
					if !strings.HasPrefix(ref, "./") && !strings.HasPrefix(ref, "docker://") {
						idx := strings.LastIndexByte(ref, '@')
						if idx == -1 || !sha40Re.MatchString(ref[idx+1:]) {
							fmtStr := fmt.Sprintf("%d:%d unpinned uses %q", v.Line, v.Column, ref)
							findings = append(findings, fmtStr)
						}
					}
				}
				visit(v)
			}
			return
		}
		for _, c := range n.Content {
			visit(c)
		}
	}
	visit(&doc)
	return findings, nil
}
