use serde_json::Value;

pub fn has_tls_deny_statement(policy_json: &str) -> Result<bool, serde_json::Error> {
    let doc: Value = serde_json::from_str(policy_json)?;
    let stmts = match doc.get("Statement") {
        Some(Value::Array(arr)) => arr.clone(),
        Some(single @ Value::Object(_)) => vec![single.clone()],
        _ => return Ok(false),
    };
    for stmt in stmts {
        if stmt.get("Effect").and_then(Value::as_str) != Some("Deny") {
            continue;
        }
        let principal_all = match stmt.get("Principal") {
            Some(Value::String(s)) => s == "*",
            Some(Value::Object(m)) => m.get("AWS").and_then(Value::as_str) == Some("*"),
            _ => false,
        };
        let cond_false = stmt
            .pointer("/Condition/Bool/aws:SecureTransport")
            .map(|v| v == "false" || v == false)
            .unwrap_or(false);
        if principal_all && cond_false {
            return Ok(true);
        }
    }
    Ok(false)
}
