const SECRET_NAME_RE = /(?:SECRET|TOKEN|PASSWORD|PASSWD|PRIVATE_KEY|API_KEY|AWS_ACCESS_KEY_ID)/i;

export interface DockerFinding {
  line: number;
  instruction: "ARG" | "ENV";
  variable: string;
}

export function scanDockerfileSecrets(dockerfile: string): DockerFinding[] {
  const rawLines = dockerfile.split(/\r?\n/);
  const findings: DockerFinding[] = [];
  let buf = "";
  let startLine = 1;

  for (let i = 0; i < rawLines.length; i++) {
    const trimmed = rawLines[i].trim();
    if (!buf) startLine = i + 1;
    if (trimmed.startsWith("#")) continue;
    if (trimmed.endsWith("\\")) {
      buf += trimmed.slice(0, -1) + " ";
      continue;
    }
    const full = (buf + trimmed).trim();
    buf = "";
    const m = /^(ARG|ENV)\s+(.+)$/i.exec(full);
    if (!m) continue;
    const instr = m[1].toUpperCase() as "ARG" | "ENV";
    const tokens = m[2].split(/\s+/);
    for (const tok of tokens) {
      const varName = tok.split("=")[0];
      if (varName && SECRET_NAME_RE.test(varName)) {
        findings.push({ line: startLine, instruction: instr, variable: varName });
      }
    }
  }
  return findings;
}
