use std::str::FromStr;
use tokio_postgres::{Error, GenericClient, Row};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum EncounterSort {
    TriageAcuityAsc,
    EncounterTsDesc,
    DischargeTsDesc,
}

impl FromStr for EncounterSort {
    type Err = &'static str;

    fn from_str(raw: &str) -> Result<Self, Self::Err> {
        match raw {
            "triage_acuity:asc" => Ok(Self::TriageAcuityAsc),
            "encounter_ts:desc" => Ok(Self::EncounterTsDesc),
            "discharge_ts:desc" => Ok(Self::DischargeTsDesc),
            _ => Err("disallowed sort option"),
        }
    }
}

impl EncounterSort {
    pub const fn as_sql_order_by(self) -> &'static str {
        match self {
            Self::TriageAcuityAsc => "\"triage_acuity\" ASC NULLS LAST, \"encounter_id\" DESC",
            Self::EncounterTsDesc => "\"encounter_ts\" DESC NULLS LAST, \"encounter_id\" DESC",
            Self::DischargeTsDesc => "\"discharge_ts\" DESC NULLS LAST, \"encounter_id\" DESC",
        }
    }
}

pub async fn fetch_encounters<C: GenericClient>(
    client: &C,
    department_code: &str,
    sort: EncounterSort,
