    "raw",
    secretBytes,
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign", "verify"],
  );
}

export async function mintCsrfToken(key: CryptoKey, sessionId: string): Promise<string> {
  const nonce = crypto.getRandomValues(new Uint8Array(16));
  const nonceHex = Buffer.from(nonce).toString("hex");
  const msg = new TextEncoder().encode(`${sessionId}:${nonceHex}`);
  const mac = await crypto.subtle.sign("HMAC", key, msg);
  return `${nonceHex}.${Buffer.from(mac).toString("base64url")}`;
}

export async function verifyCsrfToken(
  key: CryptoKey,
  sessionId: string,
  token: string,
): Promise<boolean> {
  const parts = token.split(".");
  if (parts.length !== 2 || !/^[0-9a-f]{32}$/.test(parts[0])) return false;
  const sig = Buffer.from(parts[1], "base64url");
  if (sig.byteLength !== 32) return false;
  const msg = new TextEncoder().encode(`${sessionId}:${parts[0]}`);
  return crypto.subtle.verify("HMAC", key, sig, msg);
}
