use nom::{
    bytes::complete::take,
    error::{Error, ErrorKind},
    number::complete::u8 as be_u8,
    Err, IResult,
};

pub fn parse_strict_dns_name(mut input: &[u8]) -> IResult<&[u8], Vec<&[u8]>> {
    let mut labels = Vec::new();
    let mut total_ascii_len: usize = 0;

    loop {
        let (rest, len) = be_u8(input)?;
        if len == 0 {
            return Ok((rest, labels));
        }
        if (len & 0xC0) != 0 || len > 63 {
            return Err(Err::Failure(Error::new(input, ErrorKind::Verify)));
        }
        let step = usize::from(len) + usize::from(!labels.is_empty());
        total_ascii_len = total_ascii_len
            .checked_add(step)
            .filter(|&n| n <= 253)
            .ok_or_else(|| Err::Failure(Error::new(input, ErrorKind::TooLarge)))?;
        let (next, label) = take(len)(rest)?;
        labels.push(label);
        input = next;
    }
}
