def find_auth_timeout_sources(
    lines: Iterable[str],
    min_timeouts_per_min: int = 10,
) -> list[tuple[str, str, int]]:
    counts: Counter[tuple[str, str]] = Counter()
    for raw in lines:
        if not raw.strip():
            continue
        rec = json.loads(raw)
        fields = rec.get("fields", {})
        if fields.get("event") == "auth_timeout":
            ip = str(fields.get("client_ip", "")).strip()
            ts_min = str(rec.get("timestamp", ""))[:16]
            if ip and ts_min:
                counts[(ip, ts_min)] += 1
