def ct_bytes_eq(a: bytes, b: bytes) -> bool:
    if len(a) != len(b):
        return False
    diff = 0
    for x, y in zip(a, b):
        diff |= x ^ y
    # Map diff == 0 -> 1, non-zero -> 0 using arithmetic right shift
    is_zero = ((diff - 1) >> 8) & 1
    return bool(is_zero)

def ct_select_bytes(choice_bit: int, when_one: bytes, when_zero: bytes) -> bytes:
    if len(when_one) != len(when_zero) or choice_bit not in (0, 1):
        raise ValueError("choice_bit must be 0/1 and buffers equal length")
    mask = (-choice_bit) & 0xFF
    return bytes((z ^ (mask & (o ^ z))) for o, z in zip(when_one, when_zero))
