import ipaddress
from cryptography import x509
from cryptography.x509.oid import ExtensionOID

def _dns_in_subtree(host: str, constraint: str) -> bool:
    h = host.rstrip(".").lower()
    c = constraint.rstrip(".").lower()
    if c.startswith("."):
        return h.endswith(c) and len(h) > len(c)
    return h == c or h.endswith("." + c)

def check_leaf_against_ca_name_constraints(leaf: x509.Certificate, ca: x509.Certificate) -> None:
    nc = ca.extensions.get_extension_for_oid(ExtensionOID.NAME_CONSTRAINTS).value
    san = leaf.extensions.get_extension_for_oid(ExtensionOID.SUBJECT_ALTERNATIVE_NAME).value

    perm_dns = [g.value for g in (nc.permitted_subtrees or []) if isinstance(g, x509.DNSName)]
    excl_dns = [g.value for g in (nc.excluded_subtrees or []) if isinstance(g, x509.DNSName)]
    perm_ip = [g.value for g in (nc.permitted_subtrees or []) if isinstance(g, x509.IPAddress)]
    excl_ip = [g.value for g in (nc.excluded_subtrees or []) if isinstance(g, x509.IPAddress)]

    for dns in san.get_values_for_type(x509.DNSName):
        if any(_dns_in_subtree(dns, ex) for ex in excl_dns):
            raise ValueError(f"DNS SAN {dns!r} blocked by excluded_subtrees")
        if perm_dns and not any(_dns_in_subtree(dns, pm) for pm in perm_dns):
            raise ValueError(f"DNS SAN {dns!r} outside permitted_subtrees")

    for ip_val in san.get_values_for_type(x509.IPAddress):
        ip_addr = ipaddress.ip_address(ip_val)
        if any(ip_addr in net for net in excl_ip):
            raise ValueError(f"IP SAN {ip_addr} blocked by excluded_subtrees")
        if perm_ip and not any(ip_addr in net for net in perm_ip):
            raise ValueError(f"IP SAN {ip_addr} outside permitted_subtrees")
