```rust
use x509_parser::extensions::GeneralName;
use x509_parser::prelude::*;

pub fn verify_spiffe_svid_uri(der: &[u8], expected_trust_domain: &str) -> Result<String, &'static str> {
    let (_, cert) = parse_x509_certificate(der).map_err(|_| "invalid DER SVID")?;
    if cert.is_ca() {
        return Err("workload SVID must not be a CA");
    }
    let san = cert
        .subject_alternative_name()
        .map_err(|_| "bad SAN")?
        .ok_or("missing SAN")?
        .value;
    let uris: Vec<&str> = san
        .general_names
        .iter()
        .filter_map(|g| match g {
            GeneralName::URI(u) => Some(*u),
            _ => None,
        })
        .collect();
    if uris.len() != 1 {
        return Err("X509-SVID must contain exactly one URI SAN");
    }
    let uri = uris[0];
    if uri.contains('?') || uri.contains('#') || uri.ends_with('/') {
        return Err("malformed SPIFFE ID syntax");
    }
    let rest = uri.strip_prefix("spiffe://").ok_or("URI SAN not spiffe://")?;
    let (td, path) = rest.split_once('/').ok_or("missing SPIFFE workload path")?;
    if !td.eq_ignore_ascii_case(expected_trust_domain) || path.is_empty() {
        return Err("SPIFFE trust domain mismatch or empty path");
    }
    if path.split('/').any(|seg| seg.is_empty() || seg == "." || seg == "..") {
        return Err("dot or empty segment in SPIFFE workload path");
    }
    Ok(uri.to_string())
}
