import (
	"crypto/sha256"
	"crypto/subtle"
	"math/bits"
)

func hashChildren(left, right []byte) []byte {
	h := sha256.New()
	h.Write([]byte{0x01})
	h.Write(left)
	h.Write(right)
	return h.Sum(nil)
}

func VerifyConsistency(first, second uint64, proof [][]byte, oldRoot, newRoot []byte) bool {
	if first == 0 || first > second || len(oldRoot) != 32 || len(newRoot) != 32 {
		return false
	}
	if first == second {
		return len(proof) == 0 && subtle.ConstantTimeCompare(oldRoot, newRoot) == 1
	}
	if len(proof) == 0 {
		return false
	}
	for _, n := range proof {
		if len(n) != 32 {
			return false
		}
	}

	fn := first - 1
	sn := second - 1
	for (fn & 1) == 1 {
		fn >>= 1
		sn >>= 1
	}

	var fr, sr []byte
	idx := 0
	if bits.OnesCount64(first) == 1 {
		fr = oldRoot
		sr = oldRoot
	} else {
		fr = proof[0]
		sr = proof[0]
		idx = 1
	}

	for ; idx < len(proof); idx++ {
		c := proof[idx]
		if sn == 0 {
			return false
		}
		if (fn & 1) == 1 || fn == sn {
			fr = hashChildren(c, fr)
			sr = hashChildren(c, sr)
			for (fn & 1) == 0 && fn != 0 {
				fn >>= 1
				sn >>= 1
			}
		} else {
			sr = hashChildren(sr, c)
		}
		fn >>= 1
		sn >>= 1
	}

	return sn == 0 &&
		subtle.ConstantTimeCompare(fr, oldRoot) == 1 &&
		subtle.ConstantTimeCompare(sr, newRoot) == 1
}
