use hmac::{Hmac, Mac};
use sha2::Sha256;
use zeroize::{Zeroize, ZeroizeOnDrop};

type HmacSha256 = Hmac<Sha256>;

#[derive(Zeroize, ZeroizeOnDrop)]
pub struct Rfc6979Drbg {
    k: [u8; 32],
    v: [u8; 32],
}

impl Rfc6979Drbg {
    pub fn new(x_octets: &[u8], h1_octets: &[u8], extra: &[u8]) -> Self {
        let mut k = [0x00u8; 32];
        let mut v = [0x01u8; 32];

        for sep in [0x00u8, 0x01u8] {
            let mut mac = HmacSha256::new_from_slice(&k).expect("32-byte key valid");
