            k = mac.finalize().into_bytes().into();

            let mut mac_v = HmacSha256::new_from_slice(&k).expect("32-byte key valid");
            mac_v.update(&v);
            v = mac_v.finalize().into_bytes().into();
        }
        Self { k, v }
    }

    pub fn next_block(&mut self) -> [u8; 32] {
        let mut mac_v = HmacSha256::new_from_slice(&self.k).expect("32-byte key valid");
        mac_v.update(&self.v);
        self.v = mac_v.finalize().into_bytes().into();
        let out = self.v;

        let mut mac_k = HmacSha256::new_from_slice(&self.k).expect("32-byte key valid");
