CREATE TABLE signed_tree_heads (
    log_id BYTEA NOT NULL CHECK (octet_length(log_id) = 32),
    tree_size BIGINT NOT NULL CHECK (tree_size >= 0),
    root_hash BYTEA NOT NULL CHECK (octet_length(root_hash) = 32),
