    findings: list[dict] = []

    for line_no, raw in enumerate(lines, start=1):
        raw = raw.strip()
        if not raw:
            continue
        try:
            rec = json.loads(raw)
        except json.JSONDecodeError:
            findings.append({"line": line_no, "reason": "malformed_json"})
            continue

        cid = str(rec.get("ceremony_id", ""))
        ev_type = rec.get("event")
        if not cid:
            continue
        st = sessions[cid]

        if ev_type == "share_submitted":
            cust = rec.get("custodian_id")
            sx = rec.get("share_x")
            if cust in st["custodians"]:
                findings.append({"ceremony_id": cid, "line": line_no, "reason": "duplicate_custodian", "custodian_id": cust})
            if sx in st["xs"] or not isinstance(sx, int) or sx <= 0:
                findings.append({"ceremony_id": cid, "line": line_no, "reason": "invalid_or_duplicate_share_x", "share_x": sx})
            st["custodians"].add(cust)
            st["xs"].add(sx)
        elif ev_type == "secret_reconstructed":
            if len(st["custodians"]) < required_quorum or not rec.get("change_ticket_approved", False):
                findings.append({
