import ast

BANNED_RANDOM_FUNCS = {"randint", "randrange", "getrandbits", "choice", "random", "randbytes"}


def audit_weak_prng_ast(source: str) -> list[tuple[int, str]]:
    tree = ast.parse(source)
    random_aliases: set[str] = set()
    direct_funcs: set[str] = set()
    findings: list[tuple[int, str]] = []

    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                if alias.name == "random":
                    random_aliases.add(alias.asname or "random")
        elif isinstance(node, ast.ImportFrom) and node.module == "random":
            for alias in node.names:
                if alias.name in BANNED_RANDOM_FUNCS or alias.name == "*":
                    direct_funcs.add(alias.asname or alias.name)

    for node in ast.walk(tree):
        if isinstance(node, ast.Call):
            if isinstance(node.func, ast.Attribute) and isinstance(node.func.value, ast.Name):
                if node.func.value.id in random_aliases and node.func.attr in BANNED_RANDOM_FUNCS:
                    findings.append((node.lineno, f"weak PRNG call {node.func.value.id}.{node.func.attr}"))
            elif isinstance(node.func, ast.Name) and node.func.id in direct_funcs:
                findings.append((node.lineno, f"weak PRNG call random.{node.func.id}"))
    return findings
