func encodeAAD(parts ...string) []byte {
	var out []byte
	var lenBuf [4]byte
	for _, p := range parts {
		binary.BigEndian.PutUint32(lenBuf[:], uint32(len(p)))
		out = append(out, lenBuf[:]...)
		out = append(out, p...)
	}
	return out
}

func SealAES256GCM(key []byte, plaintext []byte, tenantID, recordID string) ([]byte, error) {
	if len(key) != 32 {
		return nil, errors.New("aes-256-gcm requires a 32-byte key")
	}
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, err
	}
	aad := encodeAAD(tenantID, recordID)
	return gcm.Seal(nonce, nonce, plaintext, aad), nil
}

func OpenAES256GCM(key []byte, blob []byte, tenantID, recordID string) ([]byte, error) {
	if len(key) != 32 {
		return nil, errors.New("aes-256-gcm requires a 32-byte key")
