import { createDecipheriv } from "node:crypto";

function encodeAAD(...fields: string[]): Buffer {
  const parts: Buffer[] = [];
  for (const f of fields) {
    const raw = Buffer.from(f, "utf8");
    const hdr = Buffer.allocUnsafe(4);
    hdr.writeUInt32BE(raw.byteLength, 0);
    parts.push(hdr, raw);
  }
  return Buffer.concat(parts);
}

export function openGoGcmBlob(key: Buffer, blob: Buffer, tenantId: string, recordId: string): Buffer {
  if (key.byteLength !== 32) {
    throw new Error("AES-256-GCM requires a 32-byte key");
  }
  if (blob.byteLength < 28) {
    throw new Error("Ciphertext blob shorter than 28 bytes");
  }
  const nonce = blob.subarray(0, 12);
  const tag = blob.subarray(blob.byteLength - 16);
  const ciphertext = blob.subarray(12, blob.byteLength - 16);

  const decipher = createDecipheriv("aes-256-gcm", key, nonce, { authTagLength: 16 });
  decipher.setAAD(encodeAAD(tenantId, recordId));
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
}
