import re

ARCHIVE_EXT_RE = re.compile(r"\.(?:tar|tar\.gz|tgz|tar\.bz2|tbz2|tar\.xz|txz|tar\.zst)$", re.IGNORECASE)

def lint_dockerfile_add(dockerfile_text: str) -> list[tuple[int, str]]:
    issues: list[tuple[int, str]] = []
    logical = ""
    start_line = 1
    for idx, raw in enumerate(dockerfile_text.splitlines(), start=1):
        stripped = raw.strip()
        if not logical:
            start_line = idx
        if not stripped or stripped.startswith("#"):
            continue
        if stripped.endswith("\\"):
            logical += stripped[:-1] + " "
            continue
        stmt = (logical + stripped).strip()
        logical = ""
        parts = stmt.split()
        if not parts or parts[0].upper() != "ADD":
            continue
        args = [p for p in parts[1:] if not p.startswith("--")]
        if len(args) < 2:
            continue
        sources = args[:-1]
        for src in sources:
            if src.lower().startswith(("http://", "https://")):
                issues.append((start_line, f"ADD with remote URL '{src}' lacks cryptographic checksum verification"))
            elif not ARCHIVE_EXT_RE.search(src):
                issues.append((start_line, f"use COPY instead of ADD for non-archive source '{src}'"))
