package tfverify

import (
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"errors"
	"io"
	"os"
	"strings"
)

func VerifyProviderArchiveSHA256(zipPath string, expectedHex string) (bool, error) {
	expBytes, err := hex.DecodeString(strings.TrimSpace(expectedHex))
	if err != nil || len(expBytes) != sha256.Size {
		return false, errors.New("invalid expected sha256 hex digest")
	}
	f, err := os.Open(zipPath)
	if err != nil {
		return false, err
	}
	defer f.Close()

	h := sha256.New()
	if _, err := io.Copy(h, f); err != nil {
		return false, err
	}
	actual := h.Sum(nil)
	return subtle.ConstantTimeCompare(actual, expBytes) == 1, nil
}
