import shlex

FETCHERS = {"curl", "wget"}
INTERPRETERS = {"sh", "bash", "ash", "dash", "zsh", "python", "python3"}
WRAPPERS = {"sudo", "env", "/usr/bin/env"}

def _lead_binary(segment: str) -> str:
    try:
        tokens = shlex.split(segment, comments=True)
    except ValueError:
        tokens = segment.split()
    for tok in tokens:
        if "=" in tok and not tok.startswith("-"):
            continue
        base = tok.rsplit("/", 1)[-1]
        if base in WRAPPERS or tok.startswith("-"):
            continue
        return base
    return ""

def find_pipe_to_shell_runs(dockerfile: str) -> list[tuple[int, str]]:
    findings: list[tuple[int, str]] = []
    buf = ""
    start = 1
    for lineno, raw in enumerate(dockerfile.splitlines(), 1):
        s = raw.strip()
        if not buf:
            start = lineno
        if not s or s.startswith("#"):
            continue
        if s.endswith("\\"):
            buf += s[:-1] + " "
            continue
        full = (buf + s).strip()
        buf = ""
        if not full.upper().startswith("RUN ") or full[4:].lstrip().startswith("["):
            continue
        script = full[4:].strip()
        stages = [seg.strip() for seg in script.split("|")]
        bins = [_lead_binary(seg) for seg in stages]
        for i, b in enumerate(bins[:-1]):
            if b in FETCHERS and any(dst in INTERPRETERS for dst in bins[i + 1:]):
                findings.append((start, f"unsafe fetch-pipe-exec in RUN: {script}"))
                break
    return findings
