	"created_at:desc":   {colQuoted: `"created_at"`, cmpOp: "<", orderSQL: `"created_at" DESC, "key_id" DESC`},
	"created_at:asc":    {colQuoted: `"created_at"`, cmpOp: ">", orderSQL: `"created_at" ASC, "key_id" ASC`},
	"expires_at:asc":    {colQuoted: `"expires_at"`, cmpOp: ">", orderSQL: `"expires_at" ASC, "key_id" ASC`},
	"last_used_at:desc": {colQuoted: `"last_used_at"`, cmpOp: "<", orderSQL: `"last_used_at" DESC NULLS LAST, "key_id" DESC`},
}

type ApiKeyItem struct {
	KeyID     string
	KeyPrefix string
	CreatedAt time.Time
	ExpiresAt time.Time
}

func ListActiveKeysPage(
	ctx context.Context,
	tx *sql.Tx,
	orgID string,
	sortToken string,
	cursorTS time.Time,
	cursorID string,
	limit int,
) ([]ApiKeyItem, error) {
	spec, ok := keySortAllowlist[sortToken]
	if !ok {
		return nil, errors.New("disallowed sort token")
	}
	if limit < 1 || limit > 100 {
		limit = 50
	}
	if _, err := tx.ExecContext(ctx, "SELECT set_config('app.org_id', $1, true)", orgID); err != nil {
		return nil, err
	}

	query := "SELECT key_id, key_prefix, created_at, expires_at FROM iam.v_active_api_keys " +
		"WHERE (" + spec.colQuoted + ", \"key_id\") " + spec.cmpOp + " ($1, $2::uuid) " +
		"ORDER BY " + spec.orderSQL + " LIMIT $3"

	rows, err := tx.QueryContext(ctx, query, cursorTS, cursorID, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var out []ApiKeyItem
	for rows.Next() {
		var item ApiKeyItem
		if err := rows.Scan(&item.KeyID, &item.KeyPrefix, &item.CreatedAt, &item.ExpiresAt); err != nil {
			return nil, err
		}
		out = append(out, item)
	}
	return out, rows.Err()
}
