use crc32fast::hash as crc32;
use sqlx::PgPool;

const IAM_REVOKE_CLASS_ID: i32 = 0x4941_4d52; // "IAMR"

pub async fn emergency_revoke_principal_keys(
    pool: &PgPool,
    org_id: uuid::Uuid,
    principal_id: uuid::Uuid,
    incident_ticket: &str,
    actor_arn: &str,
) -> Result<u64, String> {
    let ticket = incident_ticket.trim();
    if ticket.len() < 4 || !ticket.chars().all(|c| c.is_ascii_alphanumeric() || c == '-') {
        return Err("invalid incident ticket identifier".into());
    }

    let obj_id = crc32(principal_id.as_bytes()) as i32;
    let mut tx = pool.begin().await.map_err(|e| e.to_string())?;

    sqlx::query("SELECT pg_advisory_xact_lock($1, $2)")
        .bind(IAM_REVOKE_CLASS_ID)
        .bind(obj_id)
        .execute(&mut *tx)
        .await
        .map_err(|e| e.to_string())?;

    sqlx::query("SELECT set_config('app.actor_arn', $1, true), set_config('app.incident_ticket', $2, true)")
        .bind(actor_arn)
        .bind(ticket)
        .execute(&mut *tx)
        .await
        .map_err(|e| e.to_string())?;

    let res = sqlx::query(
        "UPDATE iam.api_keys
         SET revoked_at = clock_timestamp(), revoke_reason = $3
         WHERE org_id = $1 AND principal_id = $2 AND revoked_at IS NULL",
    )
    .bind(org_id)
    .bind(principal_id)
    .bind(ticket)
    .execute(&mut *tx)
    .await
    .map_err(|e| e.to_string())?;

    tx.commit().await.map_err(|e| e.to_string())?;
    Ok(res.rows_affected())
}
