var triggerTamperRe = regexp.MustCompile(`(?i)\b(disable\s+trigger|drop\s+trigger)\b.*?\b([a-z0-9_.]*(?:api_key_events|_audit))\b`)

type TamperAlert struct {
	AuditType string
	Statement string
	Object    string
}

func ScanPgAuditTriggerTamper(r io.Reader) ([]TamperAlert, error) {
	var alerts []TamperAlert
	scanner := bufio.NewScanner(r)
	scanner.Buffer(make([]byte, 64*1024), 2*1024*1024)

	for scanner.Scan() {
		line := scanner.Text()
		idx := strings.Index(line, "AUDIT: ")
		if idx < 0 {
			continue
		}
		payload := line[idx+len("AUDIT: "):]
		rec, err := csv.NewReader(strings.NewReader(payload)).Read()
		if err != nil || len(rec) < 8 {
			continue
		}
		auditType, className, objectName, stmt := rec[0], rec[3], rec[5], rec[7]
		if !strings.EqualFold(className, "DDL") {
			continue
		}
		if triggerTamperRe.MatchString(stmt) || strings.HasSuffix(strings.ToLower(objectName), "_audit") {
			alerts = append(alerts, TamperAlert{
				AuditType: auditType,
				Statement: stmt,
				Object:    objectName,
			})
		}
	}
	return alerts, scanner.Err()
}
