#[derive(Clone)]
pub struct BearerTimeoutService<S> {
    inner: S,
    expected_sha256: Arc<Zeroizing<[u8; 32]>>,
    timeout: Duration,
}

impl<S, B> Service<Request<B>> for BearerTimeoutService<S>
where
    S: Service<Request<B>, Response = Response<B>> + Clone + Send + 'static,
    S::Future: Send + 'static,
    S::Error: Send + 'static,
    B: Default + Send + 'static,
{
    type Response = Response<B>;
    type Error = S::Error;
    type Future = Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>> + Send>>;

    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.inner.poll_ready(cx)
    }

    fn call(&mut self, req: Request<B>) -> Self::Future {
        let ok = req
            .headers()
            .get(AUTHORIZATION)
            .and_then(|v| v.to_str().ok())
            .and_then(|s| s.strip_prefix("Bearer "))
            .map(|tok| {
                let digest: [u8; 32] = Sha256::digest(tok.as_bytes()).into();
                bool::from(digest.ct_eq(self.expected_sha256.as_slice()))
            })
            .unwrap_or(false);

