import { createHmac, timingSafeEqual } from "node:crypto";

export async function verifyRequestAuth(
  req: Request,
  hmacSecret: Uint8Array,
  introspectUrl: string,
): Promise<boolean> {
  const bearer = req.headers.get("authorization")?.replace(/^Bearer\s+/i, "");
  const sigHex = req.headers.get("x-token-mac") ?? "";
  if (!bearer || !/^[0-9a-f]{64}$/i.test(sigHex)) {
    return false;
  }
  const expected = createHmac("sha256", hmacSecret).update(bearer).digest();
  const provided = Buffer.from(sigHex, "hex");
  if (expected.length !== provided.length || !timingSafeEqual(expected, provided)) {
    return false;
  }
  const res = await fetch(introspectUrl, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ token: bearer }),
    signal: AbortSignal.timeout(1500),
  });
  if (!res.ok) return false;
  const data = (await res.json()) as { active?: boolean };
  return data.active === true;
}
