import hashlib
import hmac

EMPTY_LEAF_HASH = hashlib.sha256(b"\x00" + b"\x00" * 32).digest()


def verify_smt_non_inclusion(
    key: bytes,
    siblings: list[bytes],
    expected_root: bytes,
) -> bool:
    if len(siblings) != 256 or len(expected_root) != 32:
        return False
    if any(len(s) != 32 for s in siblings):
        return False

    path_bits = int.from_bytes(hashlib.sha256(key).digest(), "big")
    curr = EMPTY_LEAF_HASH

    for level in range(256):
        sib = siblings[level]
        bit = (path_bits >> level) & 1
        if bit == 0:
            curr = hashlib.sha256(b"\x01" + curr + sib).digest()
        else:
            curr = hashlib.sha256(b"\x01" + sib + curr).digest()

    return hmac.compare_digest(curr, expected_root)
