package rfc6979

import (
	"crypto/elliptic"
	"crypto/hmac"
	"crypto/sha256"
	"errors"
	"math/big"
)

func hmacSHA256(key []byte, chunks ...[]byte) []byte {
	mac := hmac.New(sha256.New, key)
	for _, c := range chunks {
		mac.Write(c)
	}
	return mac.Sum(nil)
}

func GenerateP256Nonce(privD *big.Int, msgHash []byte) (*big.Int, error) {
	n := elliptic.P256().Params().N
	if privD.Sign() <= 0 || privD.Cmp(n) >= 0 || len(msgHash) != 32 {
		return nil, errors.New("invalid private scalar or digest length")
	}
	xOct := privD.FillBytes(make([]byte, 32))
	h1 := new(big.Int).SetBytes(msgHash)
	h1.Mod(h1, n)
	h1Oct := h1.FillBytes(make([]byte, 32))

	k := make([]byte, 32)
	v := make([]byte, 32)
	for i := range v {
		v[i] = 0x01
	}

	k = hmacSHA256(k, v, []byte{0x00}, xOct, h1Oct)
	v = hmacSHA256(k, v)
	k = hmacSHA256(k, v, []byte{0x01}, xOct, h1Oct)
	v = hmacSHA256(k, v)

	for {
		v = hmacSHA256(k, v)
		cand := new(big.Int).SetBytes(v)
		if cand.Sign() > 0 && cand.Cmp(n) < 0 {
			return cand, nil
		}
		k = hmacSHA256(k, v, []byte{0x00})
		v = hmacSHA256(k, v)
	}
