```typescript
import { createHash, timingSafeEqual } from "node:crypto";

function sha256Prefixed(prefix: number, ...parts: Buffer[]): Buffer {
  const h = createHash("sha256");
  h.update(Buffer.from([prefix]));
  for (const p of parts) {
    h.update(p);
  }
  return h.digest();
}

export function verifyCtInclusionProof(
  leafBytes: Buffer,
  leafIndex: bigint,
  treeSize: bigint,
  auditPath: Buffer[],
  expectedRoot: Buffer
): boolean {
  if (expectedRoot.length !== 32 || treeSize <= 0n || leafIndex < 0n || leafIndex >= treeSize) {
    return false;
  }
  if (auditPath.some((p) => p.length !== 32)) {
    return false;
  }

  let fn = leafIndex;
  let sn = treeSize - 1n;
  let r = sha256Prefixed(0x00, leafBytes);

  for (const p of auditPath) {
    if (sn === 0n) {
      return false;
    }
    if ((fn & 1n) === 1n || fn === sn) {
      r = sha256Prefixed(0x01, p, r);
      while ((fn & 1n) === 0n && fn !== 0n) {
        fn >>= 1n;
        sn >>= 1n;
      }
    } else {
      r = sha256Prefixed(0x01, r, p);
    }
    fn >>= 1n;
    sn >>= 1n;
  }

  return sn === 0n && timingSafeEqual(r, expectedRoot);
}
