package auth

import (
	"crypto/rsa"
	"errors"
	"sync"
	"time"
	"golang.org/x/sync/singleflight"
)

type JWKSCache struct {
	mu         sync.RWMutex
	sf         singleflight.Group
	keys       map[string]*rsa.PublicKey
	lastFetch  time.Time
	minRefresh time.Duration
	fetch      func() (map[string]*rsa.PublicKey, error)
}

func (c *JWKSCache) GetKey(kid string) (*rsa.PublicKey, error) {
	c.mu.RLock()
	k, ok := c.keys[kid]
	canRefresh := time.Since(c.lastFetch) >= c.minRefresh
	c.mu.RUnlock()
	if ok {
		return k, nil
	}
	if !canRefresh {
		return nil, errors.New("unknown kid during cooldown")
	}
	_, err, _ := c.sf.Do("jwks", func() (any, error) {
		fresh, err := c.fetch()
		if err != nil {
			return nil, err
		}
		c.mu.Lock()
		c.keys = fresh
		c.lastFetch = time.Now()
		c.mu.Unlock()
		return nil, nil
	})
	if err != nil {
		return nil, err
	}
	c.mu.RLock()
	defer c.mu.RUnlock()
	k, ok = c.keys[kid]
	if !ok {
		return nil, errors.New("kid not found after rotation refresh")
	}
	return k, nil
}
