```typescript
export interface JwkEntry {
  kid: string;
  kty: string;
  alg: string;
  publicKeyPem: string;
}

export class PinnedJwksCache {
  private cache = new Map<string, JwkEntry>();
  private inflight: Promise<void> | null = null;
  private lastRefreshMs = 0;

  constructor(
    private readonly loadJwks: () => Promise<JwkEntry[]>,
    private readonly cooldownMs = 30_000,
    private readonly maxKeys = 32,
  ) {}

  async getByKid(kid: string): Promise<JwkEntry> {
    if (!kid || kid.length > 128) throw new Error("invalid kid");
    const hit = this.cache.get(kid);
    if (hit) return hit;
    const now = Date.now();
    if (now - this.lastRefreshMs < this.cooldownMs) {
      throw new Error("unknown kid during refresh cooldown");
    }
    if (!this.inflight) {
      this.inflight = this.refresh().finally(() => {
        this.inflight = null;
      });
    }
    await this.inflight;
    const after = this.cache.get(kid);
    if (!after) throw new Error("kid absent after rotation sync");
    return after;
  }

  private async refresh(): Promise<void> {
    const entries = await this.loadJwks();
    if (entries.length > this.maxKeys) throw new Error("jwks key count exceeded");
    const next = new Map<string, JwkEntry>();
    for (const item of entries) {
      if (item.kid && item.alg) next.set(item.kid, item);
    }
    this.cache = next;
    this.lastRefreshMs = Date.now();
  }
}
