import base64
import hashlib
import json
from typing import Dict

def rfc7638_thumbprint(jwk: Dict[str, str]) -> str:
    if any(priv in jwk for priv in ("d", "p", "q", "dp", "dq", "qi")):
        raise ValueError("private key fields forbidden")
    kty = jwk.get("kty")
    if kty == "EC":
        canonical = {"crv": jwk["crv"], "kty": "EC", "x": jwk["x"], "y": jwk["y"]}
    elif kty == "RSA":
        canonical = {"e": jwk["e"], "kty": "RSA", "n": jwk["n"]}
    elif kty == "OKP":
        canonical = {"crv": jwk["crv"], "kty": "OKP", "x": jwk["x"]}
    else:
        raise ValueError(f"unsupported kty: {kty}")
    payload = json.dumps(canonical, separators=(",", ":"), sort_keys=True).encode("ascii")
    digest = hashlib.sha256(payload).digest()
    return base64.urlsafe_b64encode(digest).rstrip(b"=").decode("ascii")
