package rootfs

import (
	"errors"
	"io"
	"os"
)

func ReadConfinedFile(baseDir, relPath string, maxBytes int64) ([]byte, error) {
	root, err := os.OpenRoot(baseDir)
	if err != nil {
		return nil, err
	}
	defer root.Close()

	f, err := root.Open(relPath)
	if err != nil {
		return nil, err
	}
	defer f.Close()

	fi, err := f.Stat()
	if err != nil {
		return nil, err
	}
	if !fi.Mode().IsRegular() {
		return nil, errors.New("refusing to read non-regular file")
	}
	if fi.Size() > maxBytes {
		return nil, errors.New("confined file exceeds maxBytes")
	}

	data, err := io.ReadAll(io.LimitReader(f, maxBytes+1))
	if err != nil {
		return nil, err
	}
	if int64(len(data)) > maxBytes {
		return nil, errors.New("confined file grew past maxBytes")
	}
	return data, nil
}
