use cap_std::{ambient_authority, fs::Dir};
use std::io::{self, Read};
use std::path::Path;

pub fn read_confined_cap(base_dir: &Path, rel_path: &Path, max_bytes: u64) -> io::Result<Vec<u8>> {
    let dir = Dir::open_ambient_dir(base_dir, ambient_authority())?;
    let file = dir.open(rel_path)?;
    let meta = file.metadata()?;
    if !meta.is_file() {
        return Err(io::Error::new(io::ErrorKind::InvalidInput, "not a regular file"));
    }
    if meta.len() > max_bytes {
        return Err(io::Error::new(io::ErrorKind::FileTooLarge, "exceeds max_bytes"));
    }
    let mut buf = Vec::with_capacity(meta.len() as usize);
    file.take(max_bytes + 1).read_to_end(&mut buf)?;
    if buf.len() as u64 > max_bytes {
        return Err(io::Error::new(io::ErrorKind::FileTooLarge, "grew past max_bytes"));
    }
    Ok(buf)
}
