import { open, realpath } from "node:fs/promises";
import path from "node:path";

export async function readConfinedBlob(baseDir: string, relPath: string, maxBytes: number): Promise<Buffer> {
  if (relPath.includes("\0") || path.isAbsolute(relPath)) {
    throw new Error("Invalid relative path");
  }
  const rootReal = await realpath(baseDir);
  const candidate = path.resolve(rootReal, relPath);
  if (!candidate.startsWith(rootReal + path.sep)) {
    throw new Error("Path escapes confined root");
  }
  const targetReal = await realpath(candidate);
  if (!targetReal.startsWith(rootReal + path.sep)) {
    throw new Error("Symlink target escapes confined root");
  }

  const fh = await open(targetReal, "r");
  try {
    const st = await fh.stat();
    if (!st.isFile() || st.size > maxBytes) {
      throw new Error("Disallowed file type or size limit exceeded");
    }
    const buf = Buffer.allocUnsafe(st.size);
    const { bytesRead } = await fh.read(buf, 0, st.size, 0);
    return buf.subarray(0, bytesRead);
  } finally {
    await fh.close();
  }
}
