func CheckMTLSBoundRequest(r *http.Request, expectedX5tS256 string) error {
	if r.TLS == nil || len(r.TLS.PeerCertificates) == 0 || len(r.TLS.VerifiedChains) == 0 {
		return errors.New("missing verified mTLS client certificate")
	}
	leaf := r.TLS.PeerCertificates[0]
	if leaf.IsCA {
		return errors.New("CA certificate invalid as mTLS client")
	}
	hasClientAuth := false
	for _, u := range leaf.ExtKeyUsage {
		if u == x509.ExtKeyUsageClientAuth {
			hasClientAuth = true
			break
		}
	}
	if !hasClientAuth {
		return errors.New("client certificate missing ExtKeyUsageClientAuth")
	}
	sum := sha256.Sum256(leaf.Raw)
	actual := base64.RawURLEncoding.EncodeToString(sum[:])
	if len(actual) != len(expectedX5tS256) ||
		subtle.ConstantTimeCompare([]byte(actual), []byte(expectedX5tS256)) != 1 {
		return errors.New("x5t#S256 certificate thumbprint mismatch")
	}
	return nil
}
