```typescript
import { createHash, timingSafeEqual } from "node:crypto";
import { TLSSocket } from "node:tls";

export function assertMtlsBoundSocket(
  socket: unknown,
  cnfX5tS256: string,
): void {
  if (!(socket instanceof TLSSocket) || !socket.authorized) {
    throw new Error("Peer mTLS socket is not authorized");
  }
  const peerCert = socket.getPeerX509Certificate();
  if (!peerCert || peerCert.ca) {
    throw new Error("Missing or invalid non-CA peer X509Certificate");
  }
  const thumb = createHash("sha256").update(peerCert.raw).digest("base64url");
  const a = Buffer.from(thumb, "utf8");
  const b = Buffer.from(cnfX5tS256, "utf8");
  if (a.length !== b.length || !timingSafeEqual(a, b)) {
    throw new Error("RFC 8705 x5t#S256 thumbprint mismatch");
  }
}
