BANNED_JSON_KEYS = {"__proto__", "constructor", "prototype", "__class__"}


def parse_strict_json(raw: str, max_depth: int = 8) -> Any:
    def check_pairs(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        out: dict[str, Any] = {}
        for k, v in pairs:
            if k in BANNED_JSON_KEYS:
                raise ValueError(f"forbidden JSON key: {k}")
            if k in out:
                raise ValueError(f"duplicate JSON key: {k}")
            out[k] = v
