    def check_depth(node: Any, depth: int = 0) -> None:
        if depth > max_depth:
            raise ValueError("JSON max depth exceeded")
        if isinstance(node, dict):
            for val in node.values():
                check_depth(val, depth + 1)
        elif isinstance(node, list):
            for item in node:
                check_depth(item, depth + 1)

    check_depth(parsed)
