                if matches!(k.as_str(), "__proto__" | "constructor" | "prototype") {
                    return Err(M::Error::custom("reserved key blocked"));
                }
                if map.insert(k, v).is_some() {
                    return Err(M::Error::custom("duplicate key blocked"));
                }
            }
            Ok(map)
        }
    }
    deserializer.deserialize_map(SafeMapVisitor)
}
