func SummarizeImpersonationSubnets(r io.Reader) ([]string, error) {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 64*1024), 2*1024*1024)
	seen := make(map[netip.Prefix]struct{})
	for sc.Scan() {
		var ev auditEvent
		if err := json.Unmarshal(sc.Bytes(), &ev); err != nil || ev.Verb != "impersonate" {
			continue
		}
		for _, rawIP := range ev.SourceIPs {
			addr, err := netip.ParseAddr(rawIP)
			if err != nil {
				continue
			}
			bits := 24
			if addr.Is6() {
				bits = 64
			}
			if pfx, err := addr.Prefix(bits); err == nil {
				seen[pfx] = struct{}{}
			}
		}
	}
	out := make([]string, 0, len(seen))
	for pfx := range seen {
		out = append(out, pfx.String())
	}
	sort.Strings(out)
	return out, sc.Err()
}
