pub fn cluster_wide_secret_lists<R: BufRead>(reader: R) -> Vec<String> {
    let mut flagged = Vec::new();
    for line in reader.lines().map_while(Result::ok) {
        let Ok(ev) = serde_json::from_str::<K8sAuditEvent>(&line) else {
