```typescript
import * as readline from "node:readline";
import { Readable } from "node:stream";

interface K8sEvent {
  requestReceivedTimestamp?: string;
  user?: { username?: string };
  responseStatus?: { code?: number };
}

export interface JitterStats {
  count: number;
  meanSec: number;
  pstdevSec: number;
}

export async function rbacForbiddenJitter(
  stream: Readable,
  minEvents = 4
): Promise<Record<string, JitterStats>> {
  const byUser = new Map<string, number[]>();
  const rl = readline.createInterface({ input: stream, crlfDelay: Infinity });
  for await (const line of rl) {
    if (!line.trim()) continue;
    const ev = JSON.parse(line) as K8sEvent;
    if (ev.responseStatus?.code !== 403 || !ev.requestReceivedTimestamp) continue;
    const user = ev.user?.username ?? "unknown";
    const ts = Date.parse(ev.requestReceivedTimestamp) / 1000;
    if (!Number.isNaN(ts)) {
      const arr = byUser.get(user) ?? [];
      arr.push(ts);
      byUser.set(user, arr);
    }
  }
  const out: Record<string, JitterStats> = {};
  for (const [user, stamps] of byUser) {
    if (stamps.length < minEvents) continue;
    stamps.sort((a, b) => a - b);
    const deltas = stamps.slice(1).map((t, i) => t - stamps[i]);
    const mean = deltas.reduce((s, x) => s + x, 0) / deltas.length;
    const variance = deltas.reduce((s, x) => s + (x - mean) ** 2, 0) / deltas.length;
    out[user] = {
      count: stamps.length,
      meanSec: Number(mean.toFixed(4)),
      pstdevSec: Number(Math.sqrt(variance).toFixed(4)),
    };
  }
  return out;
}
