use serde_json::Value;

pub fn validate_gha_oidc_trust(policy_json: &str) -> Result<Vec<String>, serde_json::Error> {
    let doc: Value = serde_json::from_str(policy_json)?;
    let mut issues = Vec::new();
    let Some(stmts) = doc.get("Statement").and_then(Value::as_array) else {
        return Ok(vec!["missing Statement array".into()]);
    };

    for (idx, stmt) in stmts.iter().enumerate() {
        if stmt.get("Effect").and_then(Value::as_str) != Some("Allow") {
            continue;
        }
        let fed = stmt.pointer("/Principal/Federated").and_then(Value::as_str).unwrap_or("");
        if !fed.contains("token.actions.githubusercontent.com") {
            continue;
        }
        let sub_cond = stmt
            .pointer("/Condition/StringEquals/token.actions.githubusercontent.com:sub")
            .or_else(|| stmt.pointer("/Condition/StringLike/token.actions.githubusercontent.com:sub"))
            .and_then(Value::as_str);

        match sub_cond {
            None => issues.push(format!("statement[{idx}]: missing OIDC sub claim condition")),
            Some(sub) => {
                let repo_part = sub.strip_prefix("repo:").unwrap_or("").split(':').next().unwrap_or("");
                if repo_part.is_empty() || repo_part.contains('*') {
                    issues.push(format!("statement[{idx}]: wildcard repo in OIDC sub condition '{sub}'"));
                }
            }
        }
    }
    Ok(issues)
}
