var badChmodRe = regexp.MustCompile(`\bchmod\s+(?:-[a-zA-Z]+\s+)*(?:[0-7]?[2467][0-7]{3}|[0-7]*[2367]|(?:[ugoa]*\+[rwxXst]*s)|(?:[oa]\+[rwx]*w))\b`)

func AuditDockerfileChmod(src string) []string {
	var findings []string
	lines := strings.Split(src, "\n")
	var buf strings.Builder
	startLine := 1

	for i, raw := range lines {
		trimmed := strings.TrimSpace(raw)
		if buf.Len() == 0 {
			startLine = i + 1
		}
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		if strings.HasSuffix(trimmed, "\\") {
			buf.WriteString(strings.TrimSuffix(trimmed, "\\"))
			buf.WriteByte(' ')
			continue
		}
		buf.WriteString(trimmed)
		full := buf.String()
		buf.Reset()

		if strings.HasPrefix(strings.ToUpper(full), "RUN ") {
			if m := badChmodRe.FindString(full); m != "" {
				findings = append(findings, fmt.Sprintf("line %d: dangerous chmod in RUN (%s)", startLine, m))
			}
		}
	}
	return findings
}
