from typing import Awaitable, Callable

class BoundedAuthMiddleware:
    def __init__(self, app, mac_secret: bytes, verify_token: Callable[[str], Awaitable[bool]], timeout_s: float = 1.5):
        self.app = app
        self.mac_secret = mac_secret
        self.verify_token = verify_token
        self.timeout_s = timeout_s

    async def __call__(self, scope, receive, send):
        if scope["type"] != "http":
            return await self.app(scope, receive, send)
        hdrs = {k.lower(): v for k, v in scope.get("headers", [])}
        auth = hdrs.get(b"authorization", b"").decode("latin1")
        mac_hex = hdrs.get(b"x-internal-mac", b"").decode("latin1")
        if not auth.startswith("Bearer "):
            return await self._reject(send, 401)
        token = auth[7:]
        exp_mac = hmac.new(self.mac_secret, token.encode("utf-8"), hashlib.sha256).hexdigest()
        if not hmac.compare_digest(exp_mac, mac_hex):
            return await self._reject(send, 401)
        try:
            ok = await asyncio.wait_for(self.verify_token(token), timeout=self.timeout_s)
        except TimeoutError:
            return await self._reject(send, 504)
        if not ok:
            return await self._reject(send, 401)
        await self.app(scope, receive, send)

    @staticmethod
    async def _reject(send, status: int) -> None:
        await send({"type": "http.response.start", "status": status, "headers": [(b"content-length", b"0")]})
        await send({"type": "http.response.body", "body": b""})
