package dnswire

import "errors"

var ErrMalformedQName = errors.New("malformed or non-canonical DNS QNAME")

func ParseDNSQName(pkt []byte, offset int) ([]string, int, error) {
	if offset < 0 || offset >= len(pkt) {
		return nil, 0, ErrMalformedQName
	}
	var labels []string
	start := offset
	for {
		if offset >= len(pkt) || (offset-start)+1 > 255 {
			return nil, 0, ErrMalformedQName
		}
		l := int(pkt[offset])
		offset++
		if l == 0 {
			return labels, offset, nil
		}
		if (l&0xC0) != 0 || l > 63 || offset+l > len(pkt) || (offset-start)+l > 255 {
			return nil, 0, ErrMalformedQName
		}
		labels = append(labels, string(pkt[offset:offset+l]))
		offset += l
	}
}
