use nom::{
    bytes::complete::{tag, take},
    combinator::verify,
    error::{Error, ErrorKind},
    number::complete::{be_u16, u8 as nom_u8},
    Err, IResult,
};
use std::net::{Ipv4Addr, Ipv6Addr};

#[derive(Debug, PartialEq, Eq)]
pub enum SocksTarget<'a> {
    V4(Ipv4Addr, u16),
    Domain(&'a str, u16),
    V6(Ipv6Addr, u16),
}

pub fn parse_socks5_connect(input: &[u8]) -> IResult<&[u8], SocksTarget<'_>> {
    let (input, _) = tag([0x05, 0x01, 0x00])(input)?;
    let (input, atyp) = nom_u8(input)?;
    match atyp {
        0x01 => {
            let (input, raw) = take(4usize)(input)?;
            let (input, port) = verify(be_u16, |&p| p > 0)(input)?;
            let octets: [u8; 4] = raw.try_into().map_err(|_| Err::Failure(Error::new(input, ErrorKind::Digit)))?;
            Ok((input, SocksTarget::V4(Ipv4Addr::from(octets), port)))
        }
        0x03 => {
            let (input, dlen) = verify(nom_u8, |&n| n > 0)(input)?;
            let (input, raw) = take(dlen)(input)?;
            let host = std::str::from_utf8(raw)
                .ok()
                .filter(|s| s.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'.'))
                .ok_or_else(|| Err::Failure(Error::new(input, ErrorKind::AlphaNumeric)))?;
            let (input, port) = verify(be_u16, |&p| p > 0)(input)?;
            Ok((input, SocksTarget::Domain(host, port)))
        }
        0x04 => {
            let (input, raw) = take(16usize)(input)?;
            let (input, port) = verify(be_u16, |&p| p > 0)(input)?;
            let octets: [u8; 16] = raw.try_into().map_err(|_| Err::Failure(Error::new(input, ErrorKind::Digit)))?;
            Ok((input, SocksTarget::V6(Ipv6Addr::from(octets), port)))
        }
        _ => Err(Err::Failure(Error::new(input, ErrorKind::Tag))),
    }
}
