```typescript
export interface GrpcWebFrame {
  isTrailer: boolean;
  payload: Uint8Array;
}

const MAX_GRPC_FRAME = 4 * 1024 * 1024;

export function parseGrpcWebFrames(buf: Uint8Array): GrpcWebFrame[] {
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const frames: GrpcWebFrame[] = [];
  let offset = 0;

  while (offset < buf.byteLength) {
    if (buf.byteLength - offset < 5) {
      throw new RangeError("truncated gRPC-Web 5-byte frame header");
    }
    const flag = view.getUint8(offset);
    if (flag !== 0x00 && flag !== 0x80) {
      throw new Error(`unsupported gRPC-Web frame flag: 0x${flag.toString(16)}`);
    }
    const frameLen = view.getUint32(offset + 1, false);
    if (frameLen > MAX_GRPC_FRAME || frameLen > buf.byteLength - (offset + 5)) {
      throw new RangeError(`invalid or oversized gRPC-Web frame: ${frameLen}`);
    }
    frames.push({
      isTrailer: flag === 0x80,
      payload: buf.subarray(offset + 5, offset + 5 + frameLen),
    });
    offset += 5 + frameLen;
  }
  return frames;
}
