```python
import struct
from cryptography.hazmat.primitives.ciphers.aead import AESGCM

def derive_chunk_nonce(iv_prefix4: bytes, seq: int) -> bytes:
    if len(iv_prefix4) != 4 or not (0 <= seq < (1 << 64) - 1):
        raise ValueError("invalid 4-byte IV prefix or chunk sequence number")
    return iv_prefix4 + struct.pack(">Q", seq)

def build_chunk_aad(stream_id: bytes, seq: int, is_final: bool) -> bytes:
    if len(stream_id) != 16:
        raise ValueError("stream_id must be 16 bytes")
    return stream_id + struct.pack(">QB", seq, 1 if is_final else 0)

def seal_stream_chunk(key: bytes, iv_prefix4: bytes, stream_id: bytes, seq: int, is_final: bool, plaintext: bytes) -> bytes:
    nonce = derive_chunk_nonce(iv_prefix4, seq)
    aad = build_chunk_aad(stream_id, seq, is_final)
    return AESGCM(key).encrypt(nonce, plaintext, aad)

def open_stream_chunk(key: bytes, iv_prefix4: bytes, stream_id: bytes, seq: int, is_final: bool, ciphertext: bytes) -> bytes:
    nonce = derive_chunk_nonce(iv_prefix4, seq)
    aad = build_chunk_aad(stream_id, seq, is_final)
    return AESGCM(key).decrypt(nonce, ciphertext, aad)
