import time
from urllib.parse import urlsplit, urlunsplit

ALLOWED_DPOP_ALGS = {"ES256", "ES384", "EdDSA", "PS256", "RS256"}
PRIVATE_JWK_FIELDS = {"d", "p", "q", "dp", "dq", "qi", "k"}

def normalize_htu(uri: str) -> str:
    parts = urlsplit(uri)
    if parts.scheme not in ("https", "http") or not parts.netloc:
        raise ValueError("invalid htu")
    return urlunsplit((parts.scheme.lower(), parts.netloc.lower(), parts.path or "/", "", ""))

def validate_dpop_structure(header: dict, claims: dict, method: str, target_uri: str, max_skew: int = 60) -> None:
    if str(header.get("typ", "")).lower() != "dpop+jwt":
        raise ValueError("bad dpop typ")
    if header.get("alg") not in ALLOWED_DPOP_ALGS:
        raise ValueError("disallowed dpop alg")
    jwk = header.get("jwk")
    if not isinstance(jwk, dict) or PRIVATE_JWK_FIELDS.intersection(jwk):
        raise ValueError("invalid or private jwk in header")
    if claims.get("htm") != method.upper():
        raise ValueError("htm mismatch")
    if normalize_htu(str(claims.get("htu", ""))) != normalize_htu(target_uri):
        raise ValueError("htu mismatch")
    iat = int(claims.get("iat", 0))
    if abs(int(time.time()) - iat) > max_skew or not claims.get("jti"):
        raise ValueError("stale iat or missing jti")
