func ExtractSingleDPoPHeader(r *http.Request) (string, error) {
	vals := r.Header.Values("DPoP")
	if len(vals) != 1 || strings.TrimSpace(vals[0]) == "" {
		return "", errors.New("expected exactly one non-empty DPoP header")
	}
	return strings.TrimSpace(vals[0]), nil
}

func VerifyHtmHtu(htmClaim, htuClaim string, r *http.Request, scheme, host string) error {
	if htmClaim != r.Method {
		return errors.New("dpop htm mismatch")
	}
	u, err := url.Parse(htuClaim)
	if err != nil || u.RawQuery != "" || u.Fragment != "" {
		return errors.New("dpop htu must omit query and fragment")
	}
	expected := strings.ToLower(scheme) + "://" + strings.ToLower(host) + r.URL.EscapedPath()
	candidate := strings.ToLower(u.Scheme) + "://" + strings.ToLower(u.Host) + u.EscapedPath()
	if candidate != expected {
		return errors.New("dpop htu mismatch")
	}
	return nil
