```go
package sbomstore

import (
	"context"
	"errors"
	"strings"

	"github.com/jackc/pgx/v5"
)

var allowedSbomCols = map[string]string{
	"attested_at":         `"attested_at"`,
	"vuln_critical_count": `"vuln_critical_count"`,
	"repo_slug":           `"repo_slug"`,
}

func BuildSbomMultiOrder(specs []string) (string, error) {
	if len(specs) == 0 {
		return `ORDER BY "attested_at" DESC, "attestation_id" DESC`, nil
	}
	if len(specs) > 3 {
		return "", errors.New("too many sort keys")
	}
	seen := make(map[string]bool, len(specs))
	parts := make([]string, 0, len(specs)+1)

	for _, raw := range specs {
		colKey, dirKey, hasSep := strings.Cut(strings.TrimSpace(raw), ":")
		colSQL, ok := allowedSbomCols[colKey]
		if !ok || seen[colKey] {
			return "", errors.New("invalid or duplicate sort column")
		}
		seen[colKey] = true

		dirSQL := "DESC NULLS LAST"
		if hasSep {
			switch strings.ToLower(dirKey) {
			case "asc":
				dirSQL = "ASC NULLS LAST"
			case "desc":
				dirSQL = "DESC NULLS LAST"
			default:
				return "", errors.New("invalid sort direction")
			}
		}
		parts = append(parts, colSQL+" "+dirSQL)
	}
	parts = append(parts, `"attestation_id" DESC`)
	return "ORDER BY " + strings.Join(parts, ", "), nil
}

func QueryVerifiedSboms(ctx context.Context, tx pgx.Tx, orgID string, sortSpecs []string, limit int32) (pgx.Rows, error) {
	orderBy, err := BuildSbomMultiOrder(sortSpecs)
	if err != nil {
		return nil, err
	}
	if _, err := tx.Exec(ctx, "SELECT set_config('app.org_id', $1, true)", orgID); err != nil {
		return nil, err
	}
	sql := "SELECT attestation_id, repo_slug, release_tag, vuln_critical_count, attested_at " +
		"FROM supplychain.v_verified_sboms " + orderBy + " LIMIT $1"
	return tx.Query(ctx, sql, limit)
}
