import { createHash } from "node:crypto";
import { Pool, PoolClient } from "pg";

const SAFE_META_RE = /^[a-zA-Z0-9._:@/-]{3,128}$/;

function toSignedInt32(tag: string, input: string): number {
  const buf = createHash("sha256").update(`${tag}:${input}`).digest();
  return buf.readInt32BE(0);
}

export async function withAuditContextAndXactLock<T>(
  pool: Pool,
  namespace: string,
  resourceKey: string,
  actorSub: string,
  buildRunId: string,
  fn: (client: PoolClient) => Promise<T>
): Promise<T> {
  if (!SAFE_META_RE.test(actorSub) || !SAFE_META_RE.test(buildRunId)) {
    throw new Error("Invalid audit metadata format");
  }
  const classId = toSignedInt32("ns", namespace);
  const objId = toSignedInt32(namespace, resourceKey);

  const client = await pool.connect();
  try {
    await client.query("BEGIN");
    await client.query("SELECT pg_advisory_xact_lock($1, $2)", [classId, objId]);
    await client.query(
      "SELECT set_config('app.actor_sub', $1, true), set_config('app.build_run_id', $2, true)",
      [actorSub, buildRunId]
    );
    const result = await fn(client);
    await client.query("COMMIT");
    return result;
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}
