import hashlib
import hmac
import json

def merkle_leaf_hash(row: dict) -> bytes:
    payload = json.dumps(row, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(b"\x00" + payload).digest()

def merkle_node_hash(left: bytes, right: bytes) -> bytes:
    return hashlib.sha256(b"\x01" + left + right).digest()

def compute_merkle_root(leaves: list[bytes]) -> bytes:
    if not leaves:
        return hashlib.sha256(b"").digest()
    level = list(leaves)
    while len(level) > 1:
        nxt: list[bytes] = []
        for i in range(0, len(level), 2):
            if i + 1 < len(level):
                nxt.append(merkle_node_hash(level[i], level[i + 1]))
            else:
                nxt.append(level[i])
        level = nxt
    return level[0]

def verify_inclusion_proof(
    row: dict,
    proof: list[tuple[str, bytes]],
    expected_root: bytes,
) -> bool:
    acc = merkle_leaf_hash(row)
    for side, sibling in proof:
        if side == "L":
            acc = merkle_node_hash(sibling, acc)
        elif side == "R":
            acc = merkle_node_hash(acc, sibling)
        else:
            raise ValueError("proof side must be 'L' or 'R'")
    return hmac.compare_digest(acc, expected_root)
