package edwebhook

import (
	"bytes"
	"crypto/ed25519"
	"encoding/hex"
	"errors"
	"io"
	"net/http"
	"strconv"
	"time"
)

func VerifySignedBody(w http.ResponseWriter, r *http.Request, pub ed25519.PublicKey, maxBytes int64) ([]byte, error) {
	if len(pub) != ed25519.PublicKeySize {
		return nil, errors.New("invalid ed25519 public key length")
	}
	tsStr := r.Header.Get("X-Signature-Timestamp")
	sigHex := r.Header.Get("X-Signature-Ed25519")
	ts, err := strconv.ParseInt(tsStr, 10, 64)
	if err != nil {
		return nil, errors.New("malformed timestamp header")
	}
	delta := time.Now().Unix() - ts
	if delta < -300 || delta > 300 {
		return nil, errors.New("timestamp outside 300s replay window")
	}
	sig, err := hex.DecodeString(sigHex)
	if err != nil || len(sig) != ed25519.SignatureSize {
		return nil, errors.New("malformed ed25519 signature")
	}
	r.Body = http.MaxBytesReader(w, r.Body, maxBytes)
	body, err := io.ReadAll(r.Body)
	if err != nil {
		return nil, err
	}
	var msg bytes.Buffer
	msg.WriteString("webhook-v1\x00")
	msg.WriteString(tsStr)
	msg.WriteByte(0)
	msg.Write(body)
	if !ed25519.Verify(pub, msg.Bytes(), sig) {
		return nil, errors.New("ed25519 signature verification failed")
	}
	r.Body = io.NopCloser(bytes.NewReader(body))
	return body, nil
}
