from cryptography import x509
from cryptography.hazmat.primitives.asymmetric import ec, padding, rsa
from cryptography.x509 import ocsp
from cryptography.x509.oid import ExtensionOID, ExtendedKeyUsageOID

def _verify_sig(pub, sig: bytes, tbs: bytes, hash_alg) -> None:
    if isinstance(pub, rsa.RSAPublicKey):
        pub.verify(sig, tbs, padding.PKCS1v15(), hash_alg)
    elif isinstance(pub, ec.EllipticCurvePublicKey):
        pub.verify(sig, tbs, ec.ECDSA(hash_alg))
    else:
        raise ValueError("unsupported OCSP signer key type")

def verify_stapled_ocsp(
    ocsp_der: bytes,
    leaf: x509.Certificate,
    issuer: x509.Certificate,
    now: datetime | None = None,
) -> None:
    ts = now or datetime.now(timezone.utc)
    resp = ocsp.load_der_ocsp_response(ocsp_der)
    if resp.response_status != ocsp.OCSPResponseStatus.SUCCESSFUL:
        raise ValueError(f"unsuccessful OCSP status: {resp.response_status}")
    if resp.serial_number != leaf.serial_number:
        raise ValueError("OCSP serial number mismatch")
    if resp.certificate_status != ocsp.OCSPCertStatus.GOOD:
        raise ValueError(f"certificate not GOOD: {resp.certificate_status}")
    if resp.this_update_utc > ts + timedelta(minutes=5):
        raise ValueError("OCSP this_update in future")
    if resp.next_update_utc is None or ts > resp.next_update_utc:
        raise ValueError("OCSP staple expired or missing next_update")
    if resp.certificates:
        signer = resp.certificates[0]
        issuer.public_key()  # verify delegated responder was issued by same CA
        _verify_sig(issuer.public_key(), signer.signature, signer.tbs_certificate_bytes, signer.signature_hash_algorithm)
        eku = signer.extensions.get_extension_for_oid(ExtensionOID.EXTENDED_KEY_USAGE).value
        if ExtendedKeyUsageOID.OCSP_SIGNING not in eku:
            raise ValueError("delegated responder missing id-kp-OCSPSigning")
        signer.extensions.get_extension_for_oid(ExtensionOID.OCSP_NO_CHECK)
        _verify_sig(signer.public_key(), resp.signature, resp.tbs_response_bytes, resp.signature_hash_algorithm)
    else:
        _verify_sig(issuer.public_key(), resp.signature, resp.tbs_response_bytes, resp.signature_hash_algorithm)
