PP2_MAGIC = b"\r\n\r\n\x00\r\nQUIT\n"

def parse_proxy_v2_client_ip(buf: bytes) -> tuple[str, int]:
    if len(buf) < 16 or buf[:12] != PP2_MAGIC:
        raise ValueError("invalid Proxy Protocol v2 signature")
    ver_cmd, fam_proto, payload_len = struct.unpack_from(">BBH", buf, 12)
