        return str(ipaddress.IPv4Address(buf[16:20])), total_len
    if fam == 0x20:
        if payload_len < 36:
            raise ValueError("truncated IPv6 Proxy v2 block")
        return str(ipaddress.IPv6Address(buf[16:32])), total_len
