const DECODER = new TextDecoder("utf-8", { fatal: true });

export function decodeDnsNameBounded(pkt: Uint8Array, startOffset: number): string {
  const labels: string[] = [];
  let pos = startOffset;
  let hops = 0;
  let totalLen = 0;

  while (true) {
    if (pos < 0 || pos >= pkt.byteLength) {
      throw new RangeError("DNS name offset out of packet bounds");
    }
    const b = pkt[pos];
    if (b === 0) {
      return labels.join(".");
    }
    if ((b & 0xc0) === 0xc0) {
      if (pos + 1 >= pkt.byteLength || ++hops > 16) {
        throw new Error("truncated or excessive DNS compression pointer hops");
      }
      const target = ((b & 0x3f) << 8) | pkt[pos + 1];
      if (target >= pos) {
        throw new Error("non-backward DNS compression pointer rejected");
      }
      pos = target;
      continue;
    }
    if ((b & 0xc0) !== 0 || b > 63 || pos + 1 + b > pkt.byteLength) {
      throw new RangeError("invalid DNS label header or truncated label");
    }
    totalLen += b + (labels.length > 0 ? 1 : 0);
    if (totalLen > 253) {
      throw new RangeError("DNS domain name exceeds 253-byte limit");
    }
    labels.push(DECODER.decode(pkt.subarray(pos + 1, pos + 1 + b)));
    pos += 1 + b;
  }
}
