```go
package shamir

import (
	"errors"
	"math/big"
)

type Share struct {
	X *big.Int
	Y *big.Int
}

func ReconstructGFp(shares []Share, threshold int, prime *big.Int) (*big.Int, error) {
	if threshold < 2 || len(shares) < threshold {
		return nil, errors.New("not enough shares for threshold")
	}
	sub := shares[:threshold]
	seen := make(map[string]struct{}, threshold)

	for _, s := range sub {
		if s.X == nil || s.Y == nil || s.X.Sign() <= 0 || s.X.Cmp(prime) >= 0 {
			return nil, errors.New("invalid share X coordinate")
		}
		if s.Y.Sign() < 0 || s.Y.Cmp(prime) >= 0 {
			return nil, errors.New("invalid share Y coordinate")
		}
		key := s.X.Text(16)
		if _, dup := seen[key]; dup {
			return nil, errors.New("duplicate share X coordinate")
		}
		seen[key] = struct{}{}
	}

	secret := big.NewInt(0)
	for i := 0; i < threshold; i++ {
		num := big.NewInt(1)
		den := big.NewInt(1)
		for j := 0; j < threshold; j++ {
			if i == j {
				continue
			}
			negXj := new(big.Int).Neg(sub[j].X)
			negXj.Mod(negXj, prime)
			num.Mul(num, negXj)
			num.Mod(num, prime)

			diff := new(big.Int).Sub(sub[i].X, sub[j].X)
			diff.Mod(diff, prime)
			den.Mul(den, diff)
			den.Mod(den, prime)
		}
		invDen := new(big.Int).ModInverse(den, prime)
		if invDen == nil {
			return nil, errors.New("non-invertible denominator mod prime")
		}
		term := new(big.Int).Mul(sub[i].Y, num)
		term.Mod(term, prime)
		term.Mul(term, invDen)
		term.Mod(term, prime)

		secret.Add(secret, term)
		secret.Mod(secret, prime)
	}
	return secret, nil
}
