```typescript
import { createHmac, randomBytes } from "node:crypto";

const P256_N = 0xffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551n;

function hmac256(key: Buffer, ...chunks: Buffer[]): Buffer {
  const mac = createHmac("sha256", key);
  for (const c of chunks) mac.update(c);
  return mac.digest();
}

function bigIntTo32Bytes(x: bigint): Buffer {
  return Buffer.from(x.toString(16).padStart(64, "0"), "hex");
}

export function hedgedRfc6979P256(privD: bigint, msgDigest32: Buffer): bigint {
  if (privD <= 0n || privD >= P256_N || msgDigest32.length !== 32) {
    throw new RangeError("invalid P-256 scalar or 32-byte digest");
  }
  const xOct = bigIntTo32Bytes(privD);
  const h1Mod = BigInt("0x" + msgDigest32.toString("hex")) % P256_N;
  const h1Oct = bigIntTo32Bytes(h1Mod);
  const hedge = randomBytes(32);

  let k = Buffer.alloc(32, 0x00);
  let v = Buffer.alloc(32, 0x01);

  k = hmac256(k, v, Buffer.from([0x00]), xOct, h1Oct, hedge);
  v = hmac256(k, v);
  k = hmac256(k, v, Buffer.from([0x01]), xOct, h1Oct, hedge);
  v = hmac256(k, v);

  while (true) {
    v = hmac256(k, v);
    const cand = BigInt("0x" + v.toString("hex"));
    if (cand >= 1n && cand < P256_N) {
      return cand;
    }
    k = hmac256(k, v, Buffer.from([0x00]));
    v = hmac256(k, v);
  }
}
