import secrets


def generate_refresh_deltas(participant_xs: list[int], threshold: int, prime: int) -> dict[int, int]:
    if threshold < 2 or len(participant_xs) < threshold:
        raise ValueError("insufficient participants for threshold refresh")
    if len(set(participant_xs)) != len(participant_xs):
        raise ValueError("duplicate participant x-coordinates")
    if any(not (1 <= x < prime) for x in participant_xs):
        raise ValueError("participant x out of GF(p) range")

    coeffs = [secrets.randbelow(prime) for _ in range(threshold - 1)]
    deltas: dict[int, int] = {}
    for x in participant_xs:
        val = 0
        x_pow = x
        for c in coeffs:
            val = (val + c * x_pow) % prime
            x_pow = (x_pow * x) % prime
        deltas[x] = val
    return deltas


def apply_share_refresh(share_x: int, share_y: int, incoming_deltas: list[int], prime: int) -> tuple[int, int]:
    if not (1 <= share_x < prime) or not (0 <= share_y < prime):
        raise ValueError("invalid share coordinate")
    updated_y = (share_y + sum(incoming_deltas)) % prime
    return share_x, updated_y
