package deadlinehttp

import (
	"context"
	"errors"
	"net/http"
	"time"
)

var ErrRouteBudgetExpired = errors.New("route execution deadline exceeded")

func WithRouteLimits(timeout time.Duration, maxBytes int64, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		now := time.Now()
		rc := http.NewResponseController(w)
		_ = rc.SetReadDeadline(now.Add(timeout))
		_ = rc.SetWriteDeadline(now.Add(timeout + time.Second))

		r.Body = http.MaxBytesReader(w, r.Body, maxBytes)
		ctx, cancel := context.WithTimeoutCause(r.Context(), timeout, ErrRouteBudgetExpired)
		defer cancel()

		next.ServeHTTP(w, r.WithContext(ctx))
	})
}
