import asyncio
from typing import Callable, Awaitable

class RouteDeadlineMiddleware:
    def __init__(self, app: Callable, budget_s: float = 3.0) -> None:
        self.app = app
        self.budget_s = budget_s

    async def __call__(self, scope: dict, receive: Callable[[], Awaitable[dict]], send: Callable[[dict], Awaitable[None]]) -> None:
        if scope["type"] != "http":
            await self.app(scope, receive, send)
            return

        started = False

        async def tracked_send(msg: dict) -> None:
            nonlocal started
            if msg["type"] == "http.response.start":
                started = True
            await send(msg)

        try:
            async with asyncio.timeout(self.budget_s):
                await self.app(scope, receive, tracked_send)
        except TimeoutError:
            if not started:
                await send({
                    "type": "http.response.start",
                    "status": 504,
                    "headers": [(b"content-type", b"text/plain; charset=utf-8")],
