	if !ok {
		return nil, errors.New("disallowed withdrawal sort option")
	}
	if limit < 1 || limit > 100 {
		limit = 25
	}
	if _, err := tx.Exec(ctx, "SELECT set_config('app.vault_desk_id', $1, true)", vaultDeskID); err != nil {
		return nil, err
	}

	q := "SELECT intent_id, asset_code, amount_sats FROM custody.v_pending_withdrawals ORDER BY " + orderSQL + " LIMIT $1"
	rows, err := tx.Query(ctx, q, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var items []PendingWithdrawal
	for rows.Next() {
		var w PendingWithdrawal
		if err := rows.Scan(&w.IntentID, &w.AssetCode, &w.AmountSats); err != nil {
			return nil, err
		}
		items = append(items, w)
	}
	return items, rows.Err()
}
