CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE OR REPLACE FUNCTION custody.chain_vault_journal_insert()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $$
DECLARE
    v_prev BYTEA;
    v_payload TEXT;
BEGIN
    PERFORM pg_catalog.pg_advisory_xact_lock(1129665364, NEW.wallet_slot);

    SELECT j.chain_hash
    INTO v_prev
    FROM custody.vault_transfer_journal j
    WHERE j.wallet_slot = NEW.wallet_slot
    ORDER BY j.journal_seq DESC
    LIMIT 1;

    NEW.prev_chain_hash := COALESCE(v_prev, pg_catalog.decode(repeat('00', 32), 'hex'));
    NEW.recorded_at := pg_catalog.clock_timestamp();

    v_payload := pg_catalog.encode(NEW.prev_chain_hash, 'hex')
        || '|' || NEW.wallet_slot::text
        || '|' || NEW.psbt_id::text
        || '|' || NEW.event_kind
        || '|' || NEW.recorded_at::text;

    NEW.chain_hash := public.digest(pg_catalog.convert_to(v_payload, 'UTF8'), 'sha256');
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION custody.block_journal_tamper()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'custody.vault_transfer_journal is immutable (% rejected)', TG_OP
        USING ERRCODE = 'insufficient_privilege';
END;
$$;

CREATE TRIGGER trg_vault_journal_chain_ins
    BEFORE INSERT ON custody.vault_transfer_journal
    FOR EACH ROW EXECUTE FUNCTION custody.chain_vault_journal_insert();

CREATE TRIGGER trg_vault_journal_no_mod
