impl ChallengeVault {
    pub fn new(ttl: Duration) -> Self {
        Self { pending: HashMap::new(), ttl }
    }

    pub fn issue(&mut self, session_id: String, challenge: Vec<u8>) -> Result<(), &'static str> {
        if challenge.len() < 16 {
            return Err("challenge below 16-byte minimum");
        }
        self.pending.insert(session_id, (challenge, Instant::now()));
        Ok(())
    }

