export interface CollectedClientData {
  type: string;
  challenge: string;
  origin: string;
  crossOrigin?: boolean;
}

export function verifyWebAuthnOrigin(
  clientDataBytes: Uint8Array,
  expectedType: "webauthn.create" | "webauthn.get",
  allowedOrigins: ReadonlySet<string>,
): CollectedClientData {
  const text = new TextDecoder("utf-8", { fatal: true }).decode(clientDataBytes);
  const parsed = JSON.parse(text) as CollectedClientData;
  if (parsed.type !== expectedType) {
    throw new Error("invalid ceremony type");
  }
  if (parsed.crossOrigin === true) {
    throw new Error("crossOrigin WebAuthn assertions not permitted");
  }
  let normalizedOrigin: string;
  try {
    const url = new URL(parsed.origin);
    if (url.protocol !== "https:" || url.pathname !== "/" || url.search || url.hash) {
      throw new Error("non-canonical origin");
    }
    normalizedOrigin = url.origin;
  } catch {
    throw new Error("malformed origin in clientDataJSON");
  }
  if (!allowedOrigins.has(normalizedOrigin)) {
    throw new Error("origin not in allowlist");
  }
  return parsed;
}
