const MIN_PBKDF2_ITERS = 600_000;
const MAX_PBKDF2_ITERS = 5_000_000;

export async function deriveVaultAesKey(
  passphrase: string,
  salt: Uint8Array,
  iterations = MIN_PBKDF2_ITERS,
): Promise<CryptoKey> {
  if (salt.byteLength < 16) {
    throw new Error("PBKDF2 salt must be at least 16 bytes");
  }
  if (!Number.isInteger(iterations) || iterations < MIN_PBKDF2_ITERS || iterations > MAX_PBKDF2_ITERS) {
    throw new Error("PBKDF2 iterations out of policy bounds");
  }
  const baseKey = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(passphrase),
    "PBKDF2",
    false,
    ["deriveKey"],
  );
  return crypto.subtle.deriveKey(
    { name: "PBKDF2", salt, iterations, hash: "SHA-256" },
    baseKey,
    { name: "AES-GCM", length: 256 },
    false,
    ["encrypt", "decrypt"],
  );
}
