import ipaddress
import json
from typing import Iterable

def summarize_unanswered_external_responders(lines: Iterable[str]) -> list[str]:
    v4_nets, v6_nets = [], []
    for raw in lines:
        ev = json.loads(raw)
        if ev.get("conn_state") != "S0":
            continue
        try:
            ip = ipaddress.ip_address(ev.get("id.resp_h", ""))
        except ValueError:
            continue
        if ip.is_private or ip.is_loopback or ip.is_link_local or ip.is_multicast:
