        if ip.version == 4:
            v4_nets.append(ipaddress.ip_network(f"{ip}/32"))
        else:
            v6_nets.append(ipaddress.ip_network(f"{ip}/128"))
    collapsed = [str(n) for n in ipaddress.collapse_addresses(v4_nets)]
    collapsed.extend(str(n) for n in ipaddress.collapse_addresses(v6_nets))
    return collapsed
