```go
package zeektriage

import (
	"bufio"
	"encoding/json"
	"io"
	"math"
	"sort"
)

type zeekConn struct {
	Ts    float64 `json:"ts"`
	OrigH string  `json:"id.orig_h"`
	RespH string  `json:"id.resp_h"`
}

type PairKey struct {
	Orig, Resp string
}

func ComputePairJitter(r io.Reader, minConns int) (map[PairKey]float64, error) {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 64*1024), 1024*1024)
	series := make(map[PairKey][]float64)
	for sc.Scan() {
		var c zeekConn
		if err := json.Unmarshal(sc.Bytes(), &c); err != nil || c.OrigH == "" || c.RespH == "" {
			continue
		}
		k := PairKey{Orig: c.OrigH, Resp: c.RespH}
		series[k] = append(series[k], c.Ts)
	}
	out := make(map[PairKey]float64)
	for k, ts := range series {
		if len(ts) < minConns {
			continue
		}
		sort.Float64s(ts)
		deltas := make([]float64, 0, len(ts)-1)
		var sum float64
		for i := 1; i < len(ts); i++ {
			d := ts[i] - ts[i-1]
			deltas = append(deltas, d)
			sum += d
		}
		mean := sum / float64(len(deltas))
		var sq float64
		for _, d := range deltas {
			diff := d - mean
			sq += diff * diff
		}
		out[k] = math.Sqrt(sq / float64(len(deltas)))
	}
	return out, sc.Err()
}
```

