use serde::Deserialize;
use std::io::BufRead;

#[derive(Deserialize)]
struct ZeekConn {
    uid: String,
    proto: String,
    duration: Option<f64>,
    orig_bytes: Option<u64>,
}

pub fn triage_long_or_heavy_tcp<R: BufRead>(
    reader: R,
    max_duration_secs: f64,
    max_orig_bytes: u64,
) -> Vec<String> {
    let mut uids = Vec::new();
