        let long = c.duration.unwrap_or(0.0) >= max_duration_secs;
        let heavy = c.orig_bytes.unwrap_or(0) >= max_orig_bytes;
        if long || heavy {
            uids.push(c.uid);
        }
    }
    uids
}
