```typescript
import * as readline from "node:readline";
import { Readable } from "node:stream";

interface ZeekConnRecord {
  "id.orig_h"?: string;
  orig_bytes?: number;
  resp_bytes?: number;
}

export async function computeProducerRatios(
  input: Readable,
  minTotalBytes = 1_048_576
): Promise<Map<string, number>> {
  const totals = new Map<string, { orig: number; resp: number }>();
  const rl = readline.createInterface({ input, crlfDelay: Infinity });
  for await (const line of rl) {
    if (!line.trim()) continue;
    const rec = JSON.parse(line) as ZeekConnRecord;
    const host = rec["id.orig_h"];
    if (!host) continue;
    const cur = totals.get(host) ?? { orig: 0, resp: 0 };
    cur.orig += Math.max(0, rec.orig_bytes ?? 0);
    cur.resp += Math.max(0, rec.resp_bytes ?? 0);
    totals.set(host, cur);
  }
  const ratios = new Map<string, number>();
  for (const [host, { orig, resp }] of totals) {
    const sum = orig + resp;
    if (sum >= minTotalBytes) {
      ratios.set(host, Number(((orig - resp) / sum).toFixed(4)));
    }
  }
  return ratios;
}
```

