import ast

def find_strict_ip_network_calls(source: str) -> list[int]:
    tree = ast.parse(source)
    flagged: list[int] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call) or not node.args:
            continue
        is_ip_net = (
            (isinstance(node.func, ast.Attribute) and node.func.attr == "ip_network")
            or (isinstance(node.func, ast.Name) and node.func.id == "ip_network")
        )
        if not is_ip_net:
            continue
        if isinstance(node.args[0], ast.Constant):
            continue
        has_strict_false = any(
            kw.arg == "strict"
            and isinstance(kw.value, ast.Constant)
            and kw.value.value is False
            for kw in node.keywords
        )
        if not has_strict_false:
            flagged.append(node.lineno)
    return sorted(flagged)
