package firewall

import (
	"context"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"time"
)

func StageAndCommitNftConfig(parentCtx context.Context, ruleset []byte, expectedHex string, destPath string) error {
	expected, err := hex.DecodeString(expectedHex)
	if err != nil || len(expected) != sha256.Size {
		return errors.New("invalid expected sha256")
	}
	sum := sha256.Sum256(ruleset)
	if subtle.ConstantTimeCompare(sum[:], expected) != 1 {
		return errors.New("ruleset checksum mismatch")
	}

	tmpDir, err := os.MkdirTemp(filepath.Dir(destPath), ".nftstage-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir)

	candidate := filepath.Join(tmpDir, "nftables.conf")
	if err := os.WriteFile(candidate, ruleset, 0o600); err != nil {
		return err
	}

	ctx, cancel := context.WithTimeout(parentCtx, 5*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, "/usr/sbin/nft", "--check", "--file", "--", candidate)
	if out, err := cmd.CombinedOutput(); err != nil {
		return errors.New("nft validation failed: " + string(out))
	}
	return os.Rename(candidate, destPath)
}
