```rust
use sha2::{Digest, Sha256};
use std::fs::{self, Permissions};
use std::os::unix::fs::PermissionsExt;
use std::path::Path;
use std::process::Command;
use subtle::ConstantTimeEq;
use tempfile::Builder;

pub fn extract_and_verify_binary(
    archive: &Path,
    member_rel: &str,
    expected_sha256: &[u8; 32],
) -> Result<Vec<u8>, &'static str> {
    if member_rel.starts_with('/') || member_rel.starts_with('-') || member_rel.contains("..") {
        return Err("unsafe member path");
    }
    let tmp = Builder::new()
        .prefix("fw-extract-")
        .permissions(Permissions::from_mode(0o700))
        .tempdir()
        .map_err(|_| "tempdir creation failed")?;

    let status = Command::new("tar")
        .arg("--no-same-owner")
        .arg("--no-same-permissions")
        .arg("-C")
        .arg(tmp.path())
        .arg("-xzf")
        .arg("--")
        .arg(archive)
        .arg(member_rel)
        .status()
        .map_err(|_| "failed to spawn tar")?;

    if !status.success() {
        return Err("tar extraction failed");
    }
    let target = tmp.path().join(member_rel);
    let meta = fs::symlink_metadata(&target).map_err(|_| "missing target")?;
    if !meta.file_type().is_file() {
        return Err("extracted entry is not a regular file");
    }
    let data = fs::read(&target).map_err(|_| "read failed")?;
    let digest = Sha256::digest(&data);
    if digest.as_slice().ct_eq(expected_sha256).unwrap_u8() != 1 {
        return Err("sha256 verification failed");
    }
    Ok(data)
}
