```typescript
import { createHash, timingSafeEqual } from "node:crypto";
import { constants as fsConstants } from "node:fs";
import { open, realpath } from "node:fs/promises";
import path from "node:path";

export interface ManifestEntry {
  relPath: string;
  size: number;
  sha256: string;
}

export async function verifyJsonManifest(rootDir: string, entries: ManifestEntry[]): Promise<void> {
  const rootReal = await realpath(rootDir);
  for (const entry of entries) {
    if (!/^[0-9a-f]{64}$/i.test(entry.sha256) || entry.size < 0) {
      throw new Error(`Invalid manifest metadata for ${entry.relPath}`);
    }
    const resolved = path.resolve(rootReal, entry.relPath);
    const rel = path.relative(rootReal, resolved);
    if (rel.startsWith("..") || path.isAbsolute(rel)) {
      throw new Error(`Path traversal rejected: ${entry.relPath}`);
    }
    const fh = await open(resolved, fsConstants.O_RDONLY | (fsConstants.O_NOFOLLOW ?? 0));
    try {
      const st = await fh.stat();
      if (!st.isFile() || st.size !== entry.size) {
        throw new Error(`File type or size mismatch: ${entry.relPath}`);
      }
      const hash = createHash("sha256");
      const buf = Buffer.allocUnsafe(65536);
      let total = 0;
      while (true) {
        const { bytesRead } = await fh.read(buf, 0, buf.length, null);
        if (bytesRead === 0) break;
        total += bytesRead;
        if (total > entry.size) throw new Error("Concurrent file growth detected");
        hash.update(buf.subarray(0, bytesRead));
      }
      const expected = Buffer.from(entry.sha256, "hex");
      if (!timingSafeEqual(hash.digest(), expected)) {
        throw new Error(`SHA-256 mismatch: ${entry.relPath}`);
      }
    } finally {
      await fh.close();
    }
  }
}
