package bsdsum

import (
	"bufio"
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"errors"
	"io"
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"syscall"
)

var bsdLineRe = regexp.MustCompile(`^SHA256 \(([^)]+)\) = ([0-9a-fA-F]{64})$`)

func VerifyBSDManifest(rootDir string, r io.Reader) error {
	cleanRoot, err := filepath.Abs(rootDir)
	if err != nil {
		return err
	}
	sc := bufio.NewScanner(r)
	seen := 0
	for sc.Scan() {
		line := strings.TrimSpace(sc.Text())
		if line == "" {
			continue
		}
		m := bsdLineRe.FindStringSubmatch(line)
		if m == nil {
			return errors.New("invalid BSD SHA256 line")
		}
		rel, hexDig := m[1], m[2]
		if strings.HasPrefix(rel, "/") || strings.HasPrefix(rel, "-") || strings.Contains(rel, "..") {
			return errors.New("unsafe path in BSD manifest")
		}
		full := filepath.Join(cleanRoot, rel)
		if !strings.HasPrefix(full, cleanRoot+string(filepath.Separator)) {
			return errors.New("escaped root directory")
		}
		expected, err := hex.DecodeString(hexDig)
		if err != nil {
			return err
		}
		f, err := os.OpenFile(full, os.O_RDONLY|syscall.O_NOFOLLOW, 0)
		if err != nil {
			return err
		}
		h := sha256.New()
		_, copyErr := io.Copy(h, f)
		f.Close()
		if copyErr != nil {
			return copyErr
		}
		if subtle.ConstantTimeCompare(h.Sum(nil), expected) != 1 {
			return errors.New("digest mismatch for " + rel)
		}
		seen++
	}
	if seen == 0 {
		return errors.New("empty BSD manifest")
	}
	return sc.Err()
}
