use std::io::Write;
use std::net::Ipv4Addr;
use std::path::Path;
use tempfile::NamedTempFile;

fn parse_strict_cidr(s: &str) -> Result<(Ipv4Addr, u8), &'static str> {
    let (ip_str, len_str) = s.split_once('/').ok_or("missing prefix length")?;
    let ip: Ipv4Addr = ip_str.parse().map_err(|_| "invalid ipv4 address")?;
    let plen: u8 = len_str.parse().map_err(|_| "invalid prefix length")?;
    if !(8..=32).contains(&plen) {
        return Err("prefix length out of safe bounds (8..=32)");
