pub fn write_egress_set_atomic(dest: &Path, set_name: &str, cidrs: &[&str]) -> Result<(), &'static str> {
    if set_name.is_empty() || !set_name.chars().all(|c| c.is_ascii_alphanumeric() || c == '_') {
        return Err("invalid nft set identifier");
    }
    let parent = dest.parent().ok_or("missing parent directory")?;
    let mut tmp = NamedTempFile::new_in(parent).map_err(|_| "tempfile create failed")?;

    let mut elems = Vec::with_capacity(cidrs.len());
    for raw in cidrs {
        let (ip, plen) = parse_strict_cidr(raw)?;
        elems.push(format!("{}/{}", ip, plen));
    }
    let body = format!("define {} = {{ {} }}\n", set_name, elems.join(", "));
    tmp.write_all(body.as_bytes()).map_err(|_| "write failed")?;
    tmp.as_file().sync_all().map_err(|_| "fsync failed")?;
    tmp.persist(dest).map_err(|_| "atomic persist failed")?;
    Ok(())
}
