import { createHash, timingSafeEqual } from "node:crypto";
import { readdir, readFile } from "node:fs/promises";
import path from "node:path";

async function listRegularFiles(base: string, rel = ""): Promise<string[]> {
  const full = path.join(base, rel);
  const entries = await readdir(full, { withFileTypes: true });
  const out: string[] = [];
  for (const ent of entries) {
    const childRel = rel ? `${rel}/${ent.name}` : ent.name;
    if (ent.isSymbolicLink()) {
      throw new Error(`Symlink rejected: ${childRel}`);
    }
    if (ent.isDirectory()) {
      out.push(...(await listRegularFiles(base, childRel)));
    } else if (ent.isFile()) {
      out.push(childRel);
    } else {
      throw new Error(`Unsupported file type: ${childRel}`);
    }
  }
  return out;
}

export async function verifyStrictTreeManifest(
  rootDir: string,
  manifest: Record<string, string>
): Promise<void> {
  const diskFiles = await listRegularFiles(rootDir);
  const diskSet = new Set(diskFiles);
  const manifestKeys = Object.keys(manifest);

  for (const f of diskFiles) {
    if (!Object.hasOwn(manifest, f)) {
      throw new Error(`Unmanifested extra file found: ${f}`);
    }
  }
  for (const k of manifestKeys) {
    if (!diskSet.has(k)) {
      throw new Error(`Missing manifested file: ${k}`);
    }
    const expected = Buffer.from(manifest[k], "hex");
    const actual = createHash("sha256").update(await readFile(path.join(rootDir, k))).digest();
    if (expected.length !== 32 || !timingSafeEqual(actual, expected)) {
      throw new Error(`Digest mismatch: ${k}`);
    }
  }
}
