import re
from dataclasses import dataclass, field
from typing import Iterable

ANSI_CTRL_RE = re.compile(r"\x1b\[[0-9;]*[A-Za-z]|[\x00-\x1f\x7f-\x9f]")

@dataclass
class ManifestCheckReport:
    ok: list[str] = field(default_factory=list)
    checksum_mismatch: list[str] = field(default_factory=list)
    missing_or_unreadable: list[str] = field(default_factory=list)

def parse_sha256sum_output(lines: Iterable[str]) -> ManifestCheckReport:
    report = ManifestCheckReport()
    for raw in lines:
        clean = ANSI_CTRL_RE.sub("", raw).strip()
        if not clean or clean.startswith("sha256sum: WARNING:"):
            continue
        path, sep, status = clean.rpartition(": ")
        if not sep or not path:
            continue
        if status == "OK":
            report.ok.append(path)
        elif status == "FAILED":
            report.checksum_mismatch.append(path)
        elif status == "FAILED open or read":
            report.missing_or_unreadable.append(path)
    return report
