package authmanifest

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/binary"
	"sort"
)

type Record struct {
	RelPath string
	Size    uint64
	SHA256  [32]byte
}

func ComputeManifestMAC(key []byte, records []Record) []byte {
	sorted := append([]Record(nil), records...)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].RelPath < sorted[j].RelPath })

	mac := hmac.New(sha256.New, key)
	mac.Write([]byte("manifest-v1\x00"))
	var buf8 [8]byte
	binary.BigEndian.PutUint64(buf8[:], uint64(len(sorted)))
	mac.Write(buf8[:])

	for _, rec := range sorted {
		binary.BigEndian.PutUint64(buf8[:], uint64(len(rec.RelPath)))
		mac.Write(buf8[:])
		mac.Write([]byte(rec.RelPath))
		binary.BigEndian.PutUint64(buf8[:], rec.Size)
		mac.Write(buf8[:])
		mac.Write(rec.SHA256[:])
	}
	return mac.Sum(nil)
}

func VerifyManifestMAC(key []byte, records []Record, expectedMAC []byte) bool {
	actual := ComputeManifestMAC(key, records)
	return hmac.Equal(actual, expectedMAC)
}
