def decode_dns_wire_name(packet: bytes, start: int) -> bytes:
    mv = memoryview(packet)
    visited: set[int] = set()
    parts: list[bytes] = []
    pos = start
    total = 0

    while True:
        if pos < 0 or pos >= len(mv):
            raise ValueError("DNS offset out of bounds")
        b = mv[pos]
        if b == 0:
            return b".".join(parts)
        if (b & 0xC0) == 0xC0:
            if pos + 1 >= len(mv):
                raise ValueError("truncated DNS compression pointer")
            ptr = ((b & 0x3F) << 8) | mv[pos + 1]
            if ptr in visited or ptr >= len(mv):
                raise ValueError("cyclic or out-of-bounds DNS pointer")
            visited.add(ptr)
            pos = ptr
            continue
        if (b & 0xC0) != 0 or b > 63 or pos + 1 + b > len(mv):
            raise ValueError("invalid DNS label length")
        total += b + (1 if parts else 0)
        if total > 253:
            raise ValueError("DNS wire name exceeds 253 bytes")
        parts.append(bytes(mv[pos + 1 : pos + 1 + b]))
        pos += 1 + b
