package proxyv2

import (
	"bytes"
	"encoding/binary"
	"errors"
	"io"
	"net/netip"
)

var pp2Magic = []byte("\r\n\r\n\x00\r\nQUIT\n")

func ReadProxyV2(r io.Reader) (netip.Addr, error) {
	var hdr [16]byte
	if _, err := io.ReadFull(r, hdr[:]); err != nil {
		return netip.Addr{}, err
	}
	if !bytes.Equal(hdr[:12], pp2Magic) || hdr[12] != 0x21 {
		return netip.Addr{}, errors.New("invalid Proxy Protocol v2 header")
	}
	payloadLen := int(binary.BigEndian.Uint16(hdr[14:16]))
	if payloadLen > 216 {
		return netip.Addr{}, errors.New("oversized Proxy Protocol v2 payload")
	}
	buf := make([]byte, payloadLen)
	if _, err := io.ReadFull(r, buf); err != nil {
		return netip.Addr{}, err
	}
	switch hdr[13] & 0xF0 {
	case 0x10:
		if len(buf) < 12 {
			return netip.Addr{}, errors.New("short IPv4 payload")
		}
		return netip.AddrFrom4([4]byte(buf[0:4])), nil
	case 0x20:
		if len(buf) < 36 {
			return netip.Addr{}, errors.New("short IPv6 payload")
		}
		return netip.AddrFrom16([16]byte(buf[0:16])), nil
	default:
		return netip.Addr{}, errors.New("unsupported address family")
	}
}
