use http::{Request, Response, StatusCode};
use std::{future::Future, pin::Pin, sync::Arc, task::{Context, Poll}, time::Duration};
use tower::Service;

#[derive(Clone)]
pub struct PeerCertThumbprint(pub [u8; 32]);

pub trait RevocationChecker: Send + Sync + 'static {
    fn is_cert_good(&self, sha256: [u8; 32]) -> Pin<Box<dyn Future<Output = Result<bool, ()>> + Send>>;
}

#[derive(Clone)]
pub struct MtlsOcspService<S, C> {
    inner: S,
    checker: Arc<C>,
    ocsp_timeout: Duration,
}

impl<S, C, B> Service<Request<B>> for MtlsOcspService<S, C>
where
    S: Service<Request<B>, Response = Response<B>> + Clone + Send + 'static,
    S::Future: Send + 'static,
    S::Error: Send + 'static,
    C: RevocationChecker,
    B: Default + Send + 'static,
{
    type Response = Response<B>;
    type Error = S::Error;
    type Future = Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>> + Send>>;

    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.inner.poll_ready(cx)
    }

    fn call(&mut self, req: Request<B>) -> Self::Future {
        let Some(thumb) = req.extensions().get::<PeerCertThumbprint>().cloned() else {
            return Box::pin(async { Ok(empty_status(StatusCode::UNAUTHORIZED)) });
        };
        let checker = Arc::clone(&self.checker);
        let mut svc = self.inner.clone();
        let limit = self.ocsp_timeout;
        Box::pin(async move {
            match tokio::time::timeout(limit, checker.is_cert_good(thumb.0)).await {
                Ok(Ok(true)) => svc.call(req).await,
                Ok(Ok(false)) => Ok(empty_status(StatusCode::UNAUTHORIZED)),
                Ok(Err(())) | Err(_) => Ok(empty_status(StatusCode::SERVICE_UNAVAILABLE)),
            }
        })
    }
}

fn empty_status<B: Default>(code: StatusCode) -> Response<B> {
    let mut r = Response::new(B::default());
    *r.status_mut() = code;
    r
}
