```typescript
const MAX_WS_BINARY_BYTES = 64 * 1024;

export async function handleBoundedBinaryMessage<T>(
  raw: unknown,
  timeoutMs: number,
  processor: (payload: Uint8Array, signal: AbortSignal) => Promise<T>,
): Promise<T> {
  if (!(raw instanceof Uint8Array)) {
    throw new TypeError("expected binary Uint8Array WebSocket frame");
  }
  if (raw.byteLength === 0 || raw.byteLength > MAX_WS_BINARY_BYTES) {
    throw new RangeError(`binary WebSocket frame out of bounds: ${raw.byteLength}`);
  }
  const ctl = new AbortController();
  const timer = setTimeout(() => ctl.abort(new Error("frame handler timeout")), timeoutMs);
  try {
    return await processor(raw, ctl.signal);
  } finally {
    clearTimeout(timer);
  }
}
