use sha2::{Digest, Sha256};
use std::collections::HashMap;
use std::fs::{self, OpenOptions};
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::Path;
use subtle::ConstantTimeEq;

pub fn verify_flat_dir_manifest(
    dir: &Path,
    entries: &[(&str, [u8; 32])],
) -> Result<(), &'static str> {
    let mut expected_map = HashMap::with_capacity(entries.len());
    for &(name, digest) in entries {
        if name.is_empty() || name.contains('/') || name.starts_with('.') || name.starts_with('-') {
            return Err("unsafe filename in manifest");
        }
        if expected_map.insert(name, digest).is_some() {
            return Err("duplicate filename in manifest");
        }
    }

    let mut seen_count = 0usize;
    for ent_res in fs::read_dir(dir).map_err(|_| "read_dir failed")? {
        let ent = ent_res.map_err(|_| "dir entry error")?;
        let ft = ent.file_type().map_err(|_| "file_type error")?;
        if !ft.is_file() {
            return Err("non-regular file or symlink present in staging dir");
        }
        let fname = ent.file_name();
        let name_str = fname.to_str().ok_or("non-utf8 filename")?;
        let expected = expected_map.get(name_str).ok_or("unmanifested extra file present")?;

        let mut fh = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(ent.path())
            .map_err(|_| "open failed")?;
        let mut hasher = Sha256::new();
        let mut buf = [0u8; 16384];
        loop {
            let n = fh.read(&mut buf).map_err(|_| "read error")?;
            if n == 0 {
                break;
            }
            hasher.update(&buf[..n]);
        }
        if hasher.finalize().as_slice().ct_eq(expected).unwrap_u8() != 1 {
            return Err("sha256 digest mismatch");
        }
        seen_count += 1;
    }
    if seen_count != expected_map.len() {
        return Err("missing manifested files");
    }
    Ok(())
}
