import net from "node:net";

export function renderValidatedNftSet(setName: string, cidrs: string[]): string {
  if (!/^[a-z_][a-z0-9_]{1,31}$/.test(setName)) {
    throw new Error(`Invalid nftables set name: ${setName}`);
  }
  if (cidrs.length === 0) {
    throw new Error("Allowlist CIDR array must not be empty");
  }
  const normalized = new Set<string>();
  for (const raw of cidrs) {
    const parts = raw.split("/");
    if (parts.length !== 2) {
      throw new Error(`Invalid CIDR syntax: ${raw}`);
    }
    const [ip, maskStr] = parts;
    if (!net.isIPv4(ip) || !/^\d{1,2}$/.test(maskStr)) {
      throw new Error(`Invalid IPv4 or prefix: ${raw}`);
    }
    const mask = Number(maskStr);
    const firstOctet = Number(ip.split(".")[0]);
    if (mask < 8 || mask > 32 || firstOctet === 0 || firstOctet === 127 || firstOctet >= 224) {
      throw new Error(`Disallowed or overly broad IPv4 CIDR: ${raw}`);
    }
    normalized.add(`${ip}/${mask}`);
  }
  const sorted = [...normalized].sort();
  return [
    `set ${setName} {`,
    `    type ipv4_addr`,
    `    flags interval`,
    `    elements = { ${sorted.join(", ")} }`,
    `}`,
  ].join("\n");
}
