use ed25519_dalek::{Signature, VerifyingKey};
use sha2::{Digest, Sha256};
use subtle::ConstantTimeEq;

const DOMAIN: &[u8] = b"release-sha256sums-v1\0";

pub fn verify_signed_manifest_bytes(
    pubkey: &VerifyingKey,
    manifest_bytes: &[u8],
    sig_bytes: &[u8; 64],
    artifacts: &[(&str, &[u8])],
) -> Result<(), &'static str> {
    let mut signed_msg = Vec::with_capacity(DOMAIN.len() + manifest_bytes.len());
    signed_msg.extend_from_slice(DOMAIN);
    signed_msg.extend_from_slice(manifest_bytes);

    let sig = Signature::from_bytes(sig_bytes);
    pubkey.verify_strict(&signed_msg, &sig).map_err(|_| "ed25519 signature invalid")?;

    let text = core::str::from_utf8(manifest_bytes).map_err(|_| "manifest not utf8")?;
    let mut expected_entries = Vec::new();
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        let (hex_str, rest) = line.split_at_checked(64).ok_or("malformed line")?;
        let name = rest.strip_prefix("  ").ok_or("missing two-space separator")?;
        let digest = hex::decode(hex_str).map_err(|_| "bad hex")?;
        expected_entries.push((name, digest));
    }
    if expected_entries.len() != artifacts.len() {
        return Err("artifact count mismatch");
    }
    for ((exp_name, exp_hash), (act_name, data)) in expected_entries.iter().zip(artifacts.iter()) {
        if exp_name != act_name {
            return Err("artifact name mismatch");
        }
        let actual = Sha256::digest(data);
        if actual.as_slice().ct_eq(exp_hash.as_slice()).unwrap_u8() != 1 {
            return Err("artifact sha256 mismatch");
        }
    }
    Ok(())
}
