export interface ScriptFinding {
  scriptName: string;
  reason: string;
}

const PIPE_TO_SHELL_RE = /\b(?:curl|wget)\b[^|\n]*\|\s*(?:env\s+)?(?:sh|bash|zsh)\b/;
const FILE_CMD_RE = /(?:^|[;&|]+\s*)(rm|cp|mv)\s+([^;&|\n]+)/g;

export function auditPackageJsonScripts(pkgJsonText: string): ScriptFinding[] {
  const parsed = JSON.parse(pkgJsonText) as { scripts?: Record<string, unknown> };
  const scripts = parsed.scripts ?? {};
  const findings: ScriptFinding[] = [];

  for (const [name, rawCmd] of Object.entries(scripts)) {
    if (typeof rawCmd !== "string") continue;
    if (PIPE_TO_SHELL_RE.test(rawCmd)) {
      findings.push({ scriptName: name, reason: "network fetch piped directly to shell without SHA-256 check" });
    }
    for (const match of rawCmd.matchAll(FILE_CMD_RE)) {
      const [, bin, argsPart] = match;
      const tokens = argsPart.trim().split(/\s+/);
      const ddashIdx = tokens.indexOf("--");
      const unsafeVar = tokens.some((tok, idx) => tok.includes("$") && (ddashIdx === -1 || idx < ddashIdx));
      if (unsafeVar) {
        findings.push({ scriptName: name, reason: `${bin} expands variable without preceding '--' guard` });
      }
    }
  }
  return findings;
}
