func DownloadVerifiedArtifact(ctx context.Context, client *http.Client, url, expectedHex, dstPath string, maxBytes int64) error {
	expected, err := hex.DecodeString(expectedHex)
	if err != nil || len(expected) != sha256.Size {
		return errors.New("invalid sha256 hex")
	}
	tmpDir, err := os.MkdirTemp(filepath.Dir(dstPath), ".dlstage-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir)

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return err
	}
	resp, err := client.Do(req)
	if err != nil {
		return err
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return errors.New("unexpected HTTP status")
	}

	staged := filepath.Join(tmpDir, "artifact.part")
	f, err := os.OpenFile(staged, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600)
	if err != nil {
		return err
	}
	h := sha256.New()
	written, copyErr := io.Copy(f, io.TeeReader(io.LimitReader(resp.Body, maxBytes+1), h))
	syncErr := f.Sync()
	closeErr := f.Close()
	if copyErr != nil || syncErr != nil || closeErr != nil {
		return errors.New("failed writing staged artifact")
	}
	if written > maxBytes {
		return errors.New("artifact exceeded maxBytes cap")
	}
	if subtle.ConstantTimeCompare(h.Sum(nil), expected) != 1 {
		return errors.New("artifact sha256 mismatch")
	}
	return os.Rename(staged, dstPath)
}
