import { createHash, timingSafeEqual } from "node:crypto";
import { createWriteStream } from "node:fs";
import { mkdtemp, rename, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { Readable } from "node:stream";

export async function receiveVerifiedUpload(
  body: Readable,
  expectedSha256Hex: string,
  destFile: string,
  maxBytes = 25 * 1024 * 1024
): Promise<void> {
  if (!/^[0-9a-f]{64}$/i.test(expectedSha256Hex)) {
    throw new Error("Invalid X-Content-SHA256 header");
  }
  const workDir = await mkdtemp(path.join(tmpdir(), "upload-q-"));
  const staged = path.join(workDir, "payload.bin");
  try {
    const hash = createHash("sha256");
    const out = createWriteStream(staged, { mode: 0o600, flags: "wx" });
    let seen = 0;
    for await (const chunk of body) {
      const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
      seen += buf.length;
      if (seen > maxBytes) {
        out.destroy();
        throw new Error("Upload exceeds maximum allowed size");
      }
      hash.update(buf);
      if (!out.write(buf)) {
        await new Promise<void>((resolve) => out.once("drain", resolve));
      }
    }
    await new Promise<void>((resolve, reject) => out.end((err?: Error | null) => (err ? reject(err) : resolve())));
    const expected = Buffer.from(expectedSha256Hex, "hex");
    if (!timingSafeEqual(hash.digest(), expected)) {
      throw new Error("Uploaded payload SHA-256 mismatch");
    }
    await rename(staged, destFile);
  } finally {
    await rm(workDir, { recursive: true, force: true });
  }
}
