import re
from collections import Counter
from datetime import datetime
from typing import Iterable

UID_RE = re.compile(r"\bUID=(\d+)\b")

def detect_egress_drop_spikes(
    lines: Iterable[str],
    spike_threshold: int = 20,
) -> list[tuple[int, int, int]]:
    buckets: Counter[tuple[int, int]] = Counter()
    for raw in lines:
        if "NFT_EGRESS_DROP:" not in raw:
            continue
        parts = raw.split(None, 1)
        if len(parts) < 2:
            continue
        uid_match = UID_RE.search(parts[1])
        if not uid_match:
            continue
        try:
            dt = datetime.fromisoformat(parts[0].replace("Z", "+00:00"))
            uid = int(uid_match.group(1))
        except ValueError:
            continue
        window = (int(dt.timestamp()) // 60) * 60
        buckets[(window, uid)] += 1

    spikes = [
        (win, uid, cnt)
        for (win, uid), cnt in buckets.items()
        if cnt >= spike_threshold
    ]
    return sorted(spikes)
