package astaudit

import (
	"go/ast"
	"go/parser"
	"go/token"
	"path/filepath"
	"strconv"
)

var guardedTools = map[string]bool{"rm": true, "cp": true, "mv": true, "tar": true, "sha256sum": true}

func AuditExecDoubleDash(src string) ([]int, error) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "check.go", src, 0)
	if err != nil {
		return nil, err
	}
	var lines []int
	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok {
			return true
		}
		pkg, ok := sel.X.(*ast.Ident)
		if !ok || pkg.Name != "exec" {
			return true
		}
		cmdIdx := -1
		if sel.Sel.Name == "Command" && len(call.Args) >= 2 {
			cmdIdx = 0
		} else if sel.Sel.Name == "CommandContext" && len(call.Args) >= 3 {
			cmdIdx = 1
		} else {
			return true
		}
		lit, ok := call.Args[cmdIdx].(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING {
			return true
		}
		binName, err := strconv.Unquote(lit.Value)
		if err != nil || !guardedTools[filepath.Base(binName)] {
			return true
		}
		sawDash := false
		for _, arg := range call.Args[cmdIdx+1:] {
			if bl, ok := arg.(*ast.BasicLit); ok && bl.Kind == token.STRING {
				if v, err := strconv.Unquote(bl.Value); err == nil && v == "--" {
					sawDash = true
					break
				}
				continue
			}
			if !sawDash {
				lines = append(lines, fset.Position(call.Pos()).Line)
				break
			}
		}
		return true
	})
	return lines, nil
}
