package xchacharing

import (
	"crypto/cipher"
	"crypto/rand"
	"encoding/binary"
	"errors"
	"io"

	"golang.org/x/crypto/chacha20poly1305"
)

type KeyRing struct {
	activeKID uint16
	aeads     map[uint16]cipher.AEAD
}

func NewKeyRing(active uint16, rawKeys map[uint16][]byte) (*KeyRing, error) {
	ring := &KeyRing{activeKID: active, aeads: make(map[uint16]cipher.AEAD, len(rawKeys))}
	for kid, k := range rawKeys {
		aead, err := chacha20poly1305.NewX(k)
		if err != nil {
			return nil, err
		}
		ring.aeads[kid] = aead
	}
	if _, ok := ring.aeads[active]; !ok {
		return nil, errors.New("active kid missing from keyring")
	}
	return ring, nil
}

func (kr *KeyRing) Seal(plaintext, contextAAD []byte) ([]byte, error) {
	aead := kr.aeads[kr.activeKID]
	out := make([]byte, 2+aead.NonceSize(), 2+aead.NonceSize()+len(plaintext)+aead.Overhead())
	binary.BigEndian.PutUint16(out[:2], kr.activeKID)
	if _, err := io.ReadFull(rand.Reader, out[2:]); err != nil {
		return nil, err
	}
	aad := append(out[:2:2], contextAAD...)
	return aead.Seal(out, out[2:], plaintext, aad), nil
}

func (kr *KeyRing) Open(blob, contextAAD []byte) ([]byte, error) {
	if len(blob) < 2+chacha20poly1305.NonceSizeX+chacha20poly1305.Overhead {
		return nil, errors.New("xchacha20poly1305 token too short")
	}
	kid := binary.BigEndian.Uint16(blob[:2])
	aead, ok := kr.aeads[kid]
	if !ok {
		return nil, errors.New("unknown or retired kid")
	}
	aad := append(blob[:2:2], contextAAD...)
	nonceEnd := 2 + aead.NonceSize()
	return aead.Open(nil, blob[2:nonceEnd], blob[nonceEnd:], aad)
}
