const BANNED_SEGMENTS: &[&str] = &[
    ".git", ".ssh", ".aws", ".npmrc", ".pypirc", ".env", "terraform.tfstate", "id_rsa", "id_ed25519",
];

pub fn lint_dockerfile_copy_leaks(dockerfile: &str) -> Vec<(usize, String)> {
    let mut findings = Vec::new();
    for (idx, raw) in dockerfile.lines().enumerate() {
        let line = raw.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let parts: Vec<&str> = line.split_whitespace().collect();
        if !parts.first().map(|s| s.eq_ignore_ascii_case("COPY")).unwrap_or(false) {
            continue;
        }
        let positional: Vec<&str> = parts.into_iter().skip(1).filter(|p| !p.starts_with("--")).collect();
        if positional.len() < 2 {
            continue;
        }
        for &src in &positional[..positional.len() - 1] {
            let clean = src.trim_matches(|c| c == '"' || c == ''');
            if clean == "." || clean == "/" || clean == "/root" {
                findings.push((idx + 1, format!("broad COPY source '{clean}' risks leaking build secrets")));
                continue;
            }
            for seg in clean.split('/') {
                if BANNED_SEGMENTS.iter().any(|b| b.eq_ignore_ascii_case(seg)) {
                    findings.push((idx + 1, format!("COPY leaks sensitive path '{clean}'")));
                    break;
                }
            }
        }
    }
    findings
}
