const WRITE_METHODS = new Set(["PUT", "POST", "DELETE"]);

export function auditS3CorsPlans(plan: { resource_changes?: TfChange[] }): string[] {
  const issues: string[] = [];
  for (const rc of plan.resource_changes ?? []) {
    if (rc.type !== "aws_s3_bucket_cors_configuration" || !rc.change.after) continue;
    if (rc.change.actions.length === 1 && rc.change.actions[0] === "delete") continue;

    for (const [idx, rule] of (rc.change.after.cors_rule ?? []).entries()) {
      const origins = rule.allowed_origins ?? [];
      const methods = (rule.allowed_methods ?? []).map((m) => m.toUpperCase());
      const hasWildcardOrigin = origins.some((o) => o === "*" || o.includes("://*"));
      const badMethods = methods.filter((m) => WRITE_METHODS.has(m));
      if (hasWildcardOrigin && badMethods.length > 0) {
        issues.push(`${rc.address} rule[${idx}]: wildcard CORS origin paired with ${badMethods.join(",")}`);
      }
    }
  }
  return issues;
}
