const SAFE_METHODS = new Set(["GET", "HEAD", "OPTIONS"]);

export function strictJsonAndFetchGuard(req: Request, res: Response, next: NextFunction): void {
  res.vary("Sec-Fetch-Dest, Sec-Fetch-Mode, Sec-Fetch-Site");
  if (SAFE_METHODS.has(req.method)) {
    next();
    return;
