use axum::{
    extract::Request,
    http::{header, Method, StatusCode},
    middleware::Next,
    response::Response,
};

pub async fn strict_json_fetch_guard(req: Request, next: Next) -> Result<Response, StatusCode> {
    if matches!(*req.method(), Method::GET | Method::HEAD | Method::OPTIONS) {
        return Ok(next.run(req).await);
    }
    let sfs = req.headers().get("sec-fetch-site").and_then(|v| v.to_str().ok()).unwrap_or("");
    if !sfs.is_empty() && sfs != "same-origin" && sfs != "none" {
        return Err(StatusCode::FORBIDDEN);
    }
    let ctype = req
        .headers()
        .get(header::CONTENT_TYPE)
        .and_then(|v| v.to_str().ok())
        .and_then(|s| s.split(';').next())
        .map(str::trim)
        .unwrap_or("");
    if !ctype.eq_ignore_ascii_case("application/json") {
        return Err(StatusCode::UNSUPPORTED_MEDIA_TYPE);
    }
    Ok(next.run(req).await)
}
