package merkle

import (
	"crypto/sha256"
	"crypto/subtle"
)

type IndexedNode struct {
	Pos  uint64
	Hash [32]byte
}

func VerifyBalancedMultiProof(
	treeSize uint64,
	leafIndices []uint64,
	leafPayloads [][]byte,
	auxProof [][32]byte,
	expectedRoot [32]byte,
) bool {
	if treeSize == 0 || (treeSize&(treeSize-1)) != 0 {
		return false
	}
	if len(leafIndices) == 0 || len(leafIndices) != len(leafPayloads) {
		return false
	}

	queue := make([]IndexedNode, len(leafIndices))
	for i, idx := range leafIndices {
		if idx >= treeSize || (i > 0 && idx <= leafIndices[i-1]) {
			return false
		}
		h := sha256.New()
		h.Write([]byte{0x00})
		h.Write(leafPayloads[i])
		var digest [32]byte
		copy(digest[:], h.Sum(nil))
		queue[i] = IndexedNode{Pos: treeSize + idx, Hash: digest}
	}

	proofIdx := 0
	for len(queue) > 0 {
		curr := queue[0]
		queue = queue[1:]
		if curr.Pos == 1 {
			if len(queue) != 0 || proofIdx != len(auxProof) {
				return false
			}
			return subtle.ConstantTimeCompare(curr.Hash[:], expectedRoot[:]) == 1
		}

		var left, right [32]byte
		if (curr.Pos & 1) == 0 {
			left = curr.Hash
			if len(queue) > 0 && queue[0].Pos == curr.Pos^1 {
				right = queue[0].Hash
				queue = queue[1:]
			} else if proofIdx < len(auxProof) {
				right = auxProof[proofIdx]
				proofIdx++
			} else {
				return false
			}
		} else {
			right = curr.Hash
			if proofIdx < len(auxProof) {
				left = auxProof[proofIdx]
				proofIdx++
			} else {
				return false
			}
		}

		h := sha256.New()
		h.Write([]byte{0x01})
		h.Write(left[:])
		h.Write(right[:])
		var parent [32]byte
		copy(parent[:], h.Sum(nil))
		queue = append(queue, IndexedNode{Pos: curr.Pos >> 1, Hash: parent})
	}
	return false
}
