```typescript
export interface GFpShare {
  x: bigint;
  y: bigint;
}

function mod(a: bigint, m: bigint): bigint {
  const r = a % m;
  return r < 0n ? r + m : r;
}

function modInv(a: bigint, m: bigint): bigint {
  let [t, newT] = [0n, 1n];
  let [r, newR] = [m, mod(a, m)];
  while (newR !== 0n) {
    const q = r / newR;
    [t, newT] = [newT, t - q * newT];
    [r, newR] = [newR, r - q * newR];
  }
  if (r !== 1n) {
    throw new Error("element not invertible modulo prime");
  }
  return t < 0n ? t + m : t;
}

export function reconstructGFp(shares: GFpShare[], threshold: number, prime: bigint): bigint {
  if (threshold < 2 || shares.length < threshold || prime <= 2n) {
    throw new Error("invalid threshold or prime");
  }
  const sub = shares.slice(0, threshold);
  const seen = new Set<bigint>();

  for (const s of sub) {
    if (s.x <= 0n || s.x >= prime || s.y < 0n || s.y >= prime) {
      throw new RangeError("share coordinate out of GF(p) bounds");
    }
    if (seen.has(s.x)) {
      throw new Error("duplicate share x-coordinate");
    }
    seen.add(s.x);
  }

  let acc = 0n;
  for (let i = 0; i < threshold; i++) {
    let num = 1n;
    let den = 1n;
    for (let j = 0; j < threshold; j++) {
      if (i === j) continue;
      num = mod(num * -sub[j].x, prime);
      den = mod(den * (sub[i].x - sub[j].x), prime);
    }
    const basis = mod(num * modInv(den, prime), prime);
    acc = mod(acc + sub[i].y * basis, prime);
  }
  return acc;
}
