const MaxSSHPacketLen = 35000

func ValidateSSHPacketHeader(hdr [5]byte, cipherBlockSize uint32) (payloadLen uint32, padLen uint8, err error) {
	if cipherBlockSize < 8 || (cipherBlockSize&(cipherBlockSize-1)) != 0 {
		return 0, 0, errors.New("invalid cipher block size")
	}
	pktLen := binary.BigEndian.Uint32(hdr[0:4])
	pad := hdr[4]
	if pktLen < 12 || pktLen > MaxSSHPacketLen || pad < 4 {
		return 0, 0, errors.New("SSH packet or padding length out of bounds")
	}
	if (4+pktLen)%cipherBlockSize != 0 || uint32(pad)+1 >= pktLen {
		return 0, 0, errors.New("SSH block alignment or payload underflow")
	}
