use nom::{
    bytes::complete::take,
    combinator::verify,
    error::{Error, ErrorKind},
    number::complete::{be_u32, u8 as nom_u8},
    Err, IResult,
};

const MAX_SSH_PACKET: u32 = 35_000;

pub fn parse_ssh_binary_packet(input: &[u8]) -> IResult<&[u8], &[u8]> {
    let (rest, pkt_len) = verify(be_u32, |&n| {
        (12..=MAX_SSH_PACKET).contains(&n) && (4 + n) % 8 == 0
    })(input)?;
    let (frame_tail, frame_body) = take(pkt_len)(rest)?;
    let (after_pad_hdr, pad_len) = verify(nom_u8, |&p| p >= 4)(frame_body)?;
    let payload_len = usize::try_from(pkt_len)
        .ok()
        .and_then(|total| total.checked_sub(1 + usize::from(pad_len)))
        .filter(|&plen| plen > 0)
        .ok_or_else(|| Err::Failure(Error::new(input, ErrorKind::LengthValue)))?;
    let (padding, payload) = take(payload_len)(after_pad_hdr)?;
    let _ = take(pad_len)(padding)?;
    Ok((frame_tail, payload))
}
