import { createDecipheriv } from "node:crypto";

export async function withZeroizedDek<T>(
  kek: Uint8Array,
  iv: Uint8Array,
  ciphertextWithTag: Uint8Array,
  aad: Uint8Array,
  fn: (dek: Readonly<Uint8Array>) => Promise<T>,
): Promise<T> {
  if (kek.byteLength !== 32 || iv.byteLength !== 12 || ciphertextWithTag.byteLength < 48) {
    throw new Error("invalid AES-256-GCM envelope dimensions");
  }
  const ct = ciphertextWithTag.subarray(0, ciphertextWithTag.byteLength - 16);
  const tag = ciphertextWithTag.subarray(ciphertextWithTag.byteLength - 16);
  const decipher = createDecipheriv("aes-256-gcm", kek, iv, { authTagLength: 16 });
  decipher.setAAD(aad);
  decipher.setAuthTag(tag);
  const dek = Buffer.concat([decipher.update(ct), decipher.final()]);
  try {
    return await fn(dek);
  } finally {
    dek.fill(0);
  }
}
