class ReplayWindow64:
    def __init__(self) -> None:
        self.highest: int = 0
        self.bitmap: int = 0

    def is_valid_candidate(self, seq: int) -> bool:
        if seq <= 0:
            return False
        if seq > self.highest:
            return True
        diff = self.highest - seq
        if diff >= 64:
            return False
        return ((self.bitmap >> diff) & 1) == 0

