        if not self.is_valid_candidate(seq):
            raise ValueError("replayed or stale sequence number")
        if seq > self.highest:
            shift = seq - self.highest
            self.bitmap = 1 if shift >= 64 else ((self.bitmap << shift) & ((1 << 64) - 1)) | 1
            self.highest = seq
        else:
