import json
import statistics
from collections import defaultdict
from datetime import datetime
from typing import Iterable

def suricata_dns_beacon_jitter(
    lines: Iterable[str], min_queries: int = 8
) -> dict[tuple[str, str], float]:
    buckets: dict[tuple[str, str], list[float]] = defaultdict(list)
    for raw in lines:
        ev = json.loads(raw)
        if ev.get("event_type") != "dns":
            continue
        dns = ev.get("dns") or {}
        if dns.get("type") != "query":
            continue
        rrname = (dns.get("rrname") or "").rstrip(".").lower()
        labels = rrname.split(".")
        if len(labels) < 2 or not ev.get("src_ip") or not ev.get("timestamp"):
            continue
        base = ".".join(labels[-2:])
        ts = datetime.fromisoformat(ev["timestamp"].replace("Z", "+00:00")).timestamp()
        buckets[(ev["src_ip"], base)].append(ts)
    result: dict[tuple[str, str], float] = {}
    for key, stamps in buckets.items():
        if len(stamps) < min_queries:
            continue
        stamps.sort()
        deltas = [b - a for a, b in zip(stamps, stamps[1:]) if b >= a]
        if len(deltas) >= 2:
            result[key] = round(statistics.pstdev(deltas), 4)
    return result
