func resolveReportOrder(field, dir string) (string, error) {
	isAsc := dir == "asc"
	if dir != "asc" && dir != "desc" && dir != "" {
		return "", errors.New("invalid sort direction")
	}
	switch field {
	case "cvss_score":
		if isAsc {
			return `"cvss_score" ASC NULLS LAST, "report_id" DESC`, nil
		}
		return `"cvss_score" DESC NULLS LAST, "report_id" DESC`, nil
	case "bounty_cents":
