			return `"bounty_cents" ASC NULLS LAST, "report_id" DESC`, nil
		}
		return `"bounty_cents" DESC NULLS LAST, "report_id" DESC`, nil
	case "submitted_at", "":
		if isAsc {
			return `"submitted_at" ASC, "report_id" ASC`, nil
		}
		return `"submitted_at" DESC, "report_id" DESC`, nil
	default:
		return "", errors.New("disallowed sort field")
	}
}

func ListProgramReports(ctx context.Context, tx pgx.Tx, programID, sortField, sortDir string, limit int32) (pgx.Rows, error) {
	orderClause, err := resolveReportOrder(sortField, sortDir)
	if err != nil {
		return nil, err
	}
	if _, err := tx.Exec(ctx, "SELECT set_config('app.program_id', $1, true)", programID); err != nil {
		return nil, err
	}
	query := "SELECT report_id, title, cvss_score, bounty_cents, submitted_at " +
		"FROM bounty.v_program_reports ORDER BY " + orderClause + " LIMIT $1"
	return tx.Query(ctx, query, limit)
}
