        .await?;

    let res = sqlx::query(
        "UPDATE bounty.reports
         SET is_public = true, disclosed_at = clock_timestamp()
         WHERE cve_id = $1
           AND is_public = false
           AND embargo_until <= clock_timestamp()",
    )
    .bind(cve_id)
    .execute(&mut *tx)
    .await?;

    tx.commit().await?;
    if res.rows_affected() == 1 {
        Ok(PublishOutcome::Published)
    } else {
