  }
  const safeLimit = Math.min(Math.max(Math.trunc(limit), 1), 200);

  const client = await pool.connect();
  try {
    await client.query("BEGIN READ ONLY");
    await client.query("SELECT set_config('app.program_id', $1, true)", [programId]);
    const res = await client.query(
      `SELECT audit_seq, report_id, action_type, triager_handle, logged_at
       FROM bounty.v_disclosure_audit
       ORDER BY ${AUDIT_SORT_MAP[sortBy]} ${dir}, "audit_seq" DESC
       LIMIT $1`,
      [safeLimit]
    );
    await client.query("COMMIT");
    return res.rows;
  } catch (err) {
    await client.query("ROLLBACK");
    throw err;
  } finally {
    client.release();
  }
}
