import json
from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives.asymmetric.ed25519 import (
    Ed25519PrivateKey,
    Ed25519PublicKey,
)

def canonical_checkpoint_bytes(table_fqn: str, max_seq: int, tip_sha256: str, ts_iso: str) -> bytes:
    doc = {
        "v": 1,
        "table": table_fqn,
        "max_seq": max_seq,
        "tip_sha256": tip_sha256.lower(),
        "ts": ts_iso,
    }
    return b"pg-audit-ckpt-v1|" + json.dumps(doc, sort_keys=True, separators=(",", ":")).encode("utf-8")

def sign_audit_checkpoint(
    priv_key: Ed25519PrivateKey,
    table_fqn: str,
    max_seq: int,
    tip_sha256: str,
    ts_iso: str,
) -> str:
    msg = canonical_checkpoint_bytes(table_fqn, max_seq, tip_sha256, ts_iso)
    return priv_key.sign(msg).hex()

def verify_audit_checkpoint(
    pub_key: Ed25519PublicKey,
    table_fqn: str,
    max_seq: int,
    tip_sha256: str,
    ts_iso: str,
    sig_hex: str,
) -> bool:
    msg = canonical_checkpoint_bytes(table_fqn, max_seq, tip_sha256, ts_iso)
    try:
        pub_key.verify(bytes.fromhex(sig_hex), msg)
        return True
    except (ValueError, InvalidSignature):
        return False
