```go
package sqlastcheck

import (
	"go/ast"
	"go/parser"
	"go/token"
	"regexp"
	"strconv"
)

var rawOrderFmtRe = regexp.MustCompile(`(?i)\border\s+by\s+%[sv]`)

func isSanitizeCall(expr ast.Expr) bool {
	call, ok := expr.(*ast.CallExpr)
	if !ok {
		return false
	}
	sel, ok := call.Fun.(*ast.SelectorExpr)
	return ok && sel.Sel.Name == "Sanitize"
}

func FindRawOrderBySprintf(filename string, src []byte) ([]int, error) {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, filename, src, 0)
	if err != nil {
		return nil, err
	}
	var lines []int

	ast.Inspect(file, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok || len(call.Args) < 2 {
			return true
		}
		sel, ok := call.Fun.(*ast.SelectorExpr)
		if !ok || sel.Sel.Name != "Sprintf" {
			return true
		}
		lit, ok := call.Args[0].(*ast.BasicLit)
		if !ok || lit.Kind != token.STRING {
			return true
		}
		unquoted, err := strconv.Unquote(lit.Value)
		if err != nil || !rawOrderFmtRe.MatchString(unquoted) {
			return true
		}
		for _, arg := range call.Args[1:] {
			if !isSanitizeCall(arg) {
				lines = append(lines, fset.Position(call.Pos()).Line)
				break
			}
		}
		return true
	})
	return lines, nil
}
