package csraudit

import (
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rsa"
	"crypto/x509"
	"errors"
	"strings"
)

func ValidateTenantCSR(csrDER []byte, tenantSuffix string) (*x509.CertificateRequest, error) {
	csr, err := x509.ParseCertificateRequest(csrDER)
	if err != nil {
		return nil, err
	}
	if err := csr.CheckSignature(); err != nil {
		return nil, errors.New("invalid CSR proof-of-possession signature")
	}
	if len(csr.IPAddresses) > 0 || len(csr.EmailAddresses) > 0 || len(csr.URIs) > 0 {
		return nil, errors.New("disallowed IP, email, or URI SAN in CSR")
	}
	switch pub := csr.PublicKey.(type) {
	case *rsa.PublicKey:
		if pub.N.BitLen() < 3072 || pub.E < 65537 {
			return nil, errors.New("weak RSA key in CSR")
		}
	case *ecdsa.PublicKey:
		if pub.Curve != elliptic.P256() && pub.Curve != elliptic.P384() {
			return nil, errors.New("disallowed ECDSA curve in CSR")
		}
	default:
		return nil, errors.New("unsupported public key algorithm in CSR")
	}
	sfx := "." + strings.TrimPrefix(strings.ToLower(tenantSuffix), ".")
	if len(csr.DNSNames) == 0 {
		return nil, errors.New("CSR must request at least one DNS SAN")
	}
	for _, d := range csr.DNSNames {
		norm := strings.ToLower(strings.TrimSuffix(d, "."))
		if strings.Contains(norm, "*") || !strings.HasSuffix(norm, sfx) {
			return nil, errors.New("unauthorized or wildcard DNS SAN in CSR")
		}
	}
	return csr, nil
}
