use x509_parser::certification_request::X509CertificationRequest;
use x509_parser::extensions::ParsedExtension;
use x509_parser::prelude::FromDer;

pub fn audit_pkcs10_csr(der: &[u8]) -> Result<(), &'static str> {
    let (rem, csr) = X509CertificationRequest::from_der(der).map_err(|_| "invalid DER CSR")?;
    if !rem.is_empty() {
        return Err("trailing bytes after DER CSR");
    }
    csr.verify_signature().map_err(|_| "CSR proof-of-possession signature failed")?;
    if let Some(exts) = csr.requested_extensions() {
        for ext in exts {
            match ext {
                ParsedExtension::BasicConstraints(_) => {
                    return Err("CSR must not supply BasicConstraints");
                }
                ParsedExtension::KeyUsage(_) => {
                    return Err("CSR must not supply KeyUsage");
                }
                ParsedExtension::Unparsed | ParsedExtension::UnsupportedExtension { .. } => {
                    return Err("unknown extension OID in CSR rejected");
                }
                _ => {}
            }
        }
    }
    Ok(())
}
