import { isIP } from "node:net";

const LABEL_RE = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/;

export function validateAcmeOrderDnsIdentifiers(
  identifiers: readonly { type: string; value: string }[],
): string[] {
  if (identifiers.length === 0 || identifiers.length > 25) {
    throw new Error("Identifier count must be between 1 and 25");
  }
  const normalized = new Set<string>();
  for (const id of identifiers) {
    if (id.type !== "dns") {
      throw new Error(`Unsupported ACME identifier type: ${id.type}`);
    }
    const host = id.value.trim().toLowerCase();
    if (host.length > 253 || host.includes("*") || isIP(host) !== 0) {
      throw new Error(`Rejected wildcard, oversized, or IP identifier: ${host}`);
    }
    const labels = host.split(".");
    if (labels.length < 2 || !labels.every((l) => LABEL_RE.test(l))) {
      throw new Error(`Invalid RFC 1123 hostname: ${host}`);
    }
    normalized.add(host);
  }
  return [...normalized];
}
