func hasUnsafeCacheTrigger(on interface{}) bool {
	switch v := on.(type) {
	case string:
		return v == "pull_request_target" || v == "issue_comment"
	case []interface{}:
		for _, item := range v {
			if s, ok := item.(string); ok && (s == "pull_request_target" || s == "issue_comment") {
				return true
			}
		}
	case map[string]interface{}:
		_, prt := v["pull_request_target"]
		_, ic := v["issue_comment"]
		return prt || ic
	}
	return false
