	if !hasUnsafeCacheTrigger(wf.On) {
		return nil, nil
	}
	var findings []string
	for jobID, job := range wf.Jobs {
		for idx, st := range job.Steps {
			if strings.HasPrefix(st.Uses, "actions/cache@") || strings.HasPrefix(st.Uses, "actions/cache/restore@") {
