package ghalint

import (
	"fmt"
	"regexp"
	"strings"

	"gopkg.in/yaml.v3"
)

var sha256PinRe = regexp.MustCompile(`@sha256:[0-9a-fA-F]{64}$`)

func inspectContainerNode(label string, n *yaml.Node, out *[]string) {
	if n.Kind == yaml.ScalarNode {
		if !sha256PinRe.MatchString(n.Value) {
			*out = append(*out, fmt.Sprintf("%d:%d %s image %q missing @sha256 pin", n.Line, n.Column, label, n.Value))
		}
		return
	}
	if n.Kind != yaml.MappingNode {
		return
	}
	for i := 0; i+1 < len(n.Content); i += 2 {
		k, v := n.Content[i], n.Content[i+1]
		if k.Value == "image" && v.Kind == yaml.ScalarNode && !sha256PinRe.MatchString(v.Value) {
			*out = append(*out, fmt.Sprintf("%d:%d %s image %q missing @sha256 pin", v.Line, v.Column, label, v.Value))
		}
		if k.Value == "options" && v.Kind == yaml.ScalarNode && strings.Contains(v.Value, "--privileged") {
			*out = append(*out, fmt.Sprintf("%d:%d %s uses --privileged container option", v.Line, v.Column, label))
		}
	}
}

func AuditJobContainers(raw []byte) ([]string, error) {
	var root yaml.Node
	if err := yaml.Unmarshal(raw, &root); err != nil {
		return nil, err
	}
	var out []string
	if len(root.Content) == 0 || root.Content[0].Kind != yaml.MappingNode {
		return nil, nil
	}
	top := root.Content[0]
	for i := 0; i+1 < len(top.Content); i += 2 {
		if top.Content[i].Value == "jobs" && top.Content[i+1].Kind == yaml.MappingNode {
			jobs := top.Content[i+1]
			for j := 0; j+1 < len(jobs.Content); j += 2 {
				jobID, jobMap := jobs.Content[j].Value, jobs.Content[j+1]
				if jobMap.Kind != yaml.MappingNode {
					continue
				}
				for f := 0; f+1 < len(jobMap.Content); f += 2 {
					fk, fv := jobMap.Content[f], jobMap.Content[f+1]
					if fk.Value == "container" {
						inspectContainerNode("job "+jobID+" container", fv, &out)
					} else if fk.Value == "services" && fv.Kind == yaml.MappingNode {
						for s := 0; s+1 < len(fv.Content); s += 2 {
							inspectContainerNode("job "+jobID+" service "+fv.Content[s].Value, fv.Content[s+1], &out)
						}
					}
				}
			}
		}
	}
	return out, nil
}
