import base64

P256_P = 0xFFFFFFFF00000001000000000000000000000000FFFFFFFFFFFFFFFFFFFFFFFF
P256_B = 0x5AC635D8AA3A93E7B3EBBD55769886BC651D06B0CC53B0F63BCE3C3E27D2604B

def _b64u_to_32b(val: str) -> int:
    padded = val + "=" * (-len(val) % 4)
    raw = base64.urlsafe_b64decode(padded.encode("ascii"))
    if len(raw) != 32:
        raise ValueError("P-256 coordinate must be 32 bytes")
    n = int.from_bytes(raw, "big")
    if not (0 <= n < P256_P):
        raise ValueError("coordinate outside field prime")
    return n

def is_valid_p256_jwk_point(jwk: dict) -> bool:
    if jwk.get("kty") != "EC" or jwk.get("crv") != "P-256":
        return False
    try:
        x = _b64u_to_32b(jwk["x"])
        y = _b64u_to_32b(jwk["y"])
    except (KeyError, ValueError):
        return False
    lhs = pow(y, 2, P256_P)
    rhs = (pow(x, 3, P256_P) - 3 * x + P256_B) % P256_P
    return lhs == rhs and not (x == 0 and y == 0)
