const UTF8_STRICT = new TextDecoder("utf-8", { fatal: true });

export function decodeMqttUtf8String(
  buf: Uint8Array,
  offset = 0,
): { value: string; nextOffset: number } {
  if (buf.byteLength - offset < 2) {
    throw new RangeError("truncated MQTT UTF-8 string length header");
  }
  const strLen = (buf[offset] << 8) | buf[offset + 1];
  const end = offset + 2 + strLen;
  if (end > buf.byteLength) {
    throw new RangeError("truncated MQTT UTF-8 string body");
  }
  const value = UTF8_STRICT.decode(buf.subarray(offset + 2, end));
  if (/[\u0000-\u001f\u007f-\u009f]/.test(value)) {
    throw new Error("MQTT UTF-8 string contains forbidden NUL or control characters");
  }
  return { value, nextOffset: end };
}
