package upload

import (
	"errors"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"regexp"
)

var safeNameRe = regexp.MustCompile(`^[a-zA-Z0-9._-]{1,128}$`)

func StreamMultipartToRoot(w http.ResponseWriter, r *http.Request, baseDir string, maxBody int64) error {
	r.Body = http.MaxBytesReader(w, r.Body, maxBody)
	mr, err := r.MultipartReader()
	if err != nil {
		http.Error(w, "expected multipart/form-data", http.StatusBadRequest)
		return err
	}
	root, err := os.OpenRoot(baseDir)
	if err != nil {
		http.Error(w, "storage unavailable", http.StatusInternalServerError)
		return err
	}
	defer root.Close()

	part, err := mr.NextPart()
	if err != nil {
		http.Error(w, "missing upload part", http.StatusBadRequest)
		return err
	}
	defer part.Close()

	name := filepath.Base(part.FileName())
	if !safeNameRe.MatchString(name) || name == "." || name == ".." {
		http.Error(w, "invalid filename", http.StatusBadRequest)
		return errors.New("unsafe upload filename")
	}
	dst, err := root.OpenFile(name, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
	if err != nil {
		http.Error(w, "cannot create target file", http.StatusConflict)
		return err
	}
	if _, err := io.Copy(dst, part); err != nil {
		_ = dst.Close()
		_ = root.Remove(name)
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			http.Error(w, "upload too large", http.StatusRequestEntityTooLarge)
			return err
		}
		http.Error(w, "upload read failed", http.StatusBadRequest)
		return err
	}
	return dst.Close()
}
