use axum::extract::Multipart;
use axum::http::StatusCode;
use cap_std::fs::{Dir, OpenOptions};
use std::io::Write;

pub async fn ingest_confined_multipart(
    dir: &Dir,
    mut mp: Multipart,
    max_bytes: usize,
) -> Result<usize, StatusCode> {
    let Some(mut field) = mp.next_field().await.map_err(|_| StatusCode::BAD_REQUEST)? else {
        return Err(StatusCode::BAD_REQUEST);
    };
    let name = field.file_name().ok_or(StatusCode::BAD_REQUEST)?.to_string();
    if name.is_empty() || name.contains('/') || name.contains("..") {
        return Err(StatusCode::BAD_REQUEST);
    }
    let mut opts = OpenOptions::new();
    opts.write(true).create_new(true);
    let mut out = dir.open_with(&name, &opts).map_err(|_| StatusCode::CONFLICT)?;

    let mut total = 0usize;
    while let Some(chunk) = field.chunk().await.map_err(|_| StatusCode::BAD_REQUEST)? {
        total = total.saturating_add(chunk.len());
        if total > max_bytes {
            drop(out);
            let _ = dir.remove_file(&name);
            return Err(StatusCode::PAYLOAD_TOO_LARGE);
        }
        out.write_all(&chunk).map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?;
    }
    Ok(total)
}
