import { IncomingMessage } from "node:http";
import path from "node:path";

export function streamBoundedSingleUpload(req: IncomingMessage, safeDestFile: string, maxBytes: number): Promise<void> {
  return new Promise((resolve, reject) => {
    const bb = busboy({ headers: req.headers, limits: { files: 1, fields: 4, fileSize: maxBytes } });
    let sawFile = false;

    bb.on("file", (_field, fileStream) => {
      sawFile = true;
      const out = createWriteStream(path.resolve(safeDestFile), { flags: "wx", mode: 0o600 });
      fileStream.pipe(out);
      fileStream.on("limit", () => {
        out.destroy();
      });
      out.on("close", async () => {
        if (fileStream.truncated) {
          await unlink(safeDestFile).catch(() => undefined);
          reject(Object.assign(new Error("Upload exceeded maxBytes"), { statusCode: 413 }));
        }
      });
      out.on("error", reject);
    });
    bb.on("finish", () => (sawFile ? resolve() : reject(new Error("No file uploaded"))));
    bb.on("error", reject);
    req.pipe(bb);
  });
}
