import re

BROAD_COPY_RE = re.compile(r"^\s*(?:COPY|ADD)\s+(?:--\S+\s+)*(?:\.|(?:\./))\s+\S+", re.IGNORECASE | re.MULTILINE)
REQUIRED_IGNORES = {".git", ".env", ".aws", "*.tfstate"}

def audit_dockerignore_context(dockerfile_text: str, dockerignore_text: str | None) -> list[str]:
    if not BROAD_COPY_RE.search(dockerfile_text):
        return []
    if dockerignore_text is None:
        return ["Dockerfile copies '.' build context without a .dockerignore file"]

    present: set[str] = set()
    for raw in dockerignore_text.splitlines():
        entry = raw.strip().rstrip("/")
        if not entry or entry.startswith("#") or entry.startswith("!"):
            continue
        present.add(entry)

    missing = sorted(req for req in REQUIRED_IGNORES if req not in present)
    if missing:
        return [f".dockerignore missing sensitive exclusions while Dockerfile copies '.': {missing}"]
    return []
