```typescript
interface IamStatement {
  Sid?: string;
  Effect: string;
  Principal?: { AWS?: string | string[] } | string;
  Action: string | string[];
  Condition?: Record<string, Record<string, unknown>>;
}

function isAccountRootOnly(principal: IamStatement["Principal"]): boolean {
  if (!principal || typeof principal === "string") return false;
  const aws = Array.isArray(principal.AWS) ? principal.AWS : principal.AWS ? [principal.AWS] : [];
  return aws.length > 0 && aws.every((arn) => /^arn:aws:iam::\d{12}:root$/.test(arn));
}

export function auditKmsDecryptConditions(policyJson: string): string[] {
  const doc = JSON.parse(policyJson) as { Statement?: IamStatement[] };
  const findings: string[] = [];

  for (const [idx, stmt] of (doc.Statement ?? []).entries()) {
    if (stmt.Effect !== "Allow" || isAccountRootOnly(stmt.Principal)) continue;
    const actions = Array.isArray(stmt.Action) ? stmt.Action : [stmt.Action];
    const grantsDecrypt = actions.some((a) => {
      const low = a.toLowerCase();
      return low === "kms:*" || low === "*" || low === "kms:decrypt";
    });
    if (!grantsDecrypt) continue;

    const condKeys = Object.values(stmt.Condition ?? {}).flatMap((m) => Object.keys(m));
    const hasGuard = condKeys.some(
      (k) => k.toLowerCase() === "kms:viaservice" || k.toLowerCase().startsWith("kms:encryptioncontext:")
    );
    if (!hasGuard) {
      findings.push(`Statement[${idx}] (${stmt.Sid ?? "no-sid"}): kms:Decrypt granted without kms:ViaService or EncryptionContext condition`);
    }
  }
  return findings;
}
