```python
import json

def lint_exec_form_entrypoints(dockerfile_src: str) -> list[tuple[int, str]]:
    issues: list[tuple[int, str]] = []
    buf = ""
    start = 1
    for lineno, raw in enumerate(dockerfile_src.splitlines(), 1):
        s = raw.strip()
        if not buf:
            start = lineno
        if not s or s.startswith("#"):
            continue
        if s.endswith("\\"):
            buf += s[:-1] + " "
            continue
        full = (buf + s).strip()
        buf = ""
        parts = full.split(None, 1)
        if len(parts) < 2:
            continue
        instr, rest = parts[0].upper(), parts[1].strip()
        if instr not in {"ENTRYPOINT", "CMD"}:
            continue
        if not rest.startswith("["):
            issues.append((start, f"{instr} uses shell form instead of JSON exec array: {rest}"))
            continue
        try:
            parsed = json.loads(rest)
            if not isinstance(parsed, list) or not all(isinstance(x, str) for x in parsed):
                issues.append((start, f"{instr} JSON exec array must contain only strings"))
        except json.JSONDecodeError:
            issues.append((start, f"{instr} malformed JSON array syntax (use double quotes): {rest}"))
    return issues
