```rust
use chrono::DateTime;
use serde::Deserialize;
use std::collections::HashMap;
use std::io::BufRead;

#[derive(Deserialize)]
struct Identity {
    #[serde(rename = "accessKeyId")]
    access_key_id: Option<String>,
}

#[derive(Deserialize)]
struct StsEvent {
    #[serde(rename = "eventTime")]
    event_time: String,
    #[serde(rename = "eventName")]
    event_name: String,
    #[serde(rename = "userIdentity")]
    user_identity: Option<Identity>,
}

pub fn caller_identity_jitter<R: BufRead>(reader: R, min_calls: usize) -> HashMap<String, f64> {
    let mut by_key: HashMap<String, Vec<f64>> = HashMap::new();
    for line in reader.lines().map_while(Result::ok) {
        let Ok(ev) = serde_json::from_str::<StsEvent>(&line) else {
            continue;
        };
        if ev.event_name != "GetCallerIdentity" {
            continue;
        }
        let Some(ak) = ev.user_identity.and_then(|u| u.access_key_id) else {
            continue;
        };
        if let Ok(dt) = DateTime::parse_from_rfc3339(&ev.event_time) {
            by_key.entry(ak).or_default().push(dt.timestamp_millis() as f64 / 1000.0);
        }
    }
    let mut out = HashMap::new();
    for (ak, mut ts) in by_key {
        if ts.len() < min_calls {
            continue;
        }
        ts.sort_by(|a, b| a.total_cmp(b));
        let deltas: Vec<f64> = ts.windows(2).map(|w| w[1] - w[0]).collect();
        let mean = deltas.iter().sum::<f64>() / deltas.len() as f64;
        let var = deltas.iter().map(|d| (d - mean).powi(2)).sum::<f64>() / deltas.len() as f64;
        out.insert(ak, var.sqrt());
    }
    out
}
