```python
import hashlib
import hmac


def _hash_node(left: bytes, right: bytes) -> bytes:
    return hashlib.sha256(b"\x01" + left + right).digest()


def verify_rfc9162_consistency(
    first_size: int,
    second_size: int,
    proof: list[bytes],
    first_root: bytes,
    second_root: bytes,
) -> bool:
    if first_size <= 0 or first_size > second_size:
        return False
    if len(first_root) != 32 or len(second_root) != 32:
        return False
    if first_size == second_size:
        return len(proof) == 0 and hmac.compare_digest(first_root, second_root)
    if not proof or any(len(p) != 32 for p in proof):
        return False

    fn = first_size - 1
    sn = second_size - 1
    while (fn & 1) == 1:
        fn >>= 1
        sn >>= 1

    if (first_size & (first_size - 1)) == 0:
        fr = first_root
        sr = first_root
        idx = 0
    else:
        fr = proof[0]
        sr = proof[0]
        idx = 1

    for c in proof[idx:]:
        if sn == 0:
            return False
        if (fn & 1) == 1 or fn == sn:
            fr = _hash_node(c, fr)
            sr = _hash_node(c, sr)
            while (fn & 1) == 0 and fn != 0:
                fn >>= 1
                sn >>= 1
        else:
            sr = _hash_node(sr, c)
        fn >>= 1
        sn >>= 1

    return (
        sn == 0
        and hmac.compare_digest(fr, first_root)
        and hmac.compare_digest(sr, second_root)
    )
