package shamir

import (
	"crypto/rand"
	"errors"
	"math/big"
)

func SplitSecretGFp(secret *big.Int, threshold, total int, prime *big.Int) ([]Share, error) {
	if prime == nil || prime.Cmp(big.NewInt(3)) <= 0 {
		return nil, errors.New("invalid prime modulus")
	}
	if secret == nil || secret.Sign() < 0 || secret.Cmp(prime) >= 0 {
		return nil, errors.New("secret out of GF(p) bounds")
	}
	if threshold < 2 || total < threshold || big.NewInt(int64(total)).Cmp(prime) >= 0 {
		return nil, errors.New("invalid threshold or total share count")
	}

	coeffs := make([]*big.Int, threshold)
	coeffs[0] = new(big.Int).Set(secret)
	for i := 1; i < threshold; i++ {
		c, err := rand.Int(rand.Reader, prime)
		if err != nil {
			return nil, err
		}
		coeffs[i] = c
	}
	defer func() {
		for _, c := range coeffs {
			if c != nil {
				c.SetInt64(0)
			}
		}
	}()

	shares := make([]Share, total)
	for idx := 1; idx <= total; idx++ {
		x := big.NewInt(int64(idx))
		y := big.NewInt(0)
		for j := threshold - 1; j >= 0; j-- {
			y.Mul(y, x)
			y.Add(y, coeffs[j])
			y.Mod(y, prime)
		}
		shares[idx-1] = Share{X: x, Y: y}
	}
	return shares, nil
}
