```rust
use sha2::{Digest, Sha256};
use subtle::ConstantTimeEq;

pub fn verify_smt_inclusion(
    key: &[u8],
    value: &[u8],
    siblings: &[[u8; 32]; 256],
    expected_root: &[u8; 32],
) -> bool {
    let key_hash: [u8; 32] = Sha256::digest(key).into();
    let val_hash: [u8; 32] = Sha256::digest(value).into();

    let mut curr: [u8; 32] = {
        let mut h = Sha256::new();
        h.update([0x00]);
        h.update(key_hash);
        h.update(val_hash);
        h.finalize().into()
    };

    for level in 0..256usize {
        let byte_idx = 31 - (level / 8);
        let bit = (key_hash[byte_idx] >> (level % 8)) & 1;
        let mut h = Sha256::new();
        h.update([0x01]);
        if bit == 0 {
            h.update(curr);
            h.update(siblings[level]);
        } else {
            h.update(siblings[level]);
            h.update(curr);
        }
        curr = h.finalize().into();
    }

    curr.ct_eq(expected_root).into()
}
