const P256_N = 0xffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551n;
const P256_HALF_N = P256_N >> 1n;

export function isCanonicalLowSP256(r: bigint, s: bigint): boolean {
  if (r <= 0n || r >= P256_N) return false;
  if (s <= 0n || s > P256_HALF_N) return false;
  return true;
}

export function normalizeLowSP256(r: bigint, s: bigint): { r: bigint; s: bigint } {
  if (r <= 0n || r >= P256_N || s <= 0n || s >= P256_N) {
    throw new RangeError("ECDSA (r, s) out of P-256 scalar bounds");
