def verify_reconstruct_consistent_gfp(
    shares: list[tuple[int, int]],
    threshold: int,
    prime: int,
) -> int:
    if threshold < 2 or len(shares) < threshold:
        raise ValueError("insufficient shares")

    seen_x: set[int] = set()
    for x, y in shares:
        if not (1 <= x < prime) or not (0 <= y < prime) or x in seen_x:
            raise ValueError("invalid or duplicate share coordinate")
        seen_x.add(x)

