```rust
use blake2::{Blake2s256, Digest};
use sqlx::PgPool;

const POLICY_RECONCILE_CLASS: i32 = 0x4b38_5350; // "K8SP"

fn cluster_lock_id(cluster_id: &str) -> i32 {
    let mut h = Blake2s256::new();
    h.update(b"k8s-policy-bundle:");
    h.update(cluster_id.as_bytes());
    let out = h.finalize();
    i32::from_be_bytes(out[..4].try_into().expect("4 bytes"))
}

pub async fn reconcile_cluster_policy_bundle(
    pool: &PgPool,
    cluster_id: &str,
    bundle_digest: &str,
    controller_pod: &str,
) -> Result<bool, sqlx::Error> {
    let mut tx = pool.begin().await?;
    let locked: bool = sqlx::query_scalar("SELECT pg_try_advisory_xact_lock($1, $2)")
        .bind(POLICY_RECONCILE_CLASS)
        .bind(cluster_lock_id(cluster_id))
        .fetch_one(&mut *tx)
        .await?;

    if !locked {
        tx.rollback().await?;
        return Ok(false);
    }

    sqlx::query("SELECT set_config('app.controller_pod', $1, true)")
        .bind(controller_pod)
        .execute(&mut *tx)
        .await?;

    sqlx::query(
        "INSERT INTO k8s_gov.cluster_policy_state (cluster_id, bundle_digest, synced_at)
         VALUES ($1, $2, clock_timestamp())
         ON CONFLICT (cluster_id) DO UPDATE
           SET bundle_digest = EXCLUDED.bundle_digest,
               synced_at = EXCLUDED.synced_at
         WHERE k8s_gov.cluster_policy_state.bundle_digest <> EXCLUDED.bundle_digest",
    )
    .bind(cluster_id)
    .bind(bundle_digest)
    .execute(&mut *tx)
    .await?;

    tx.commit().await?;
    Ok(true)
}
