from pathlib import Path

XACT_LOCK_STMT_RE = re.compile(r"\bpg_advisory_xact_lock(?:_shared)?\s*\(", re.IGNORECASE)

def summarize_advisory_lock_timeouts(jsonlog_path: Path) -> list[dict]:
    buckets: Counter[tuple[str, str]] = Counter()
    with jsonlog_path.open("r", encoding="utf-8", errors="replace") as fh:
        for line in fh:
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except json.JSONDecodeError:
                continue
            if rec.get("state_code") != "55P03":
                continue
            stmt = str(rec.get("statement") or rec.get("query") or "")
            if not XACT_LOCK_STMT_RE.search(stmt):
                continue
            ts_minute = str(rec.get("timestamp", ""))[:16]
            app = str(rec.get("application_name") or "unknown")
            buckets[(ts_minute, app)] += 1

    return [
        {"minute": minute, "application_name": app, "timeouts": count}
        for (minute, app), count in buckets.most_common()
    ]
