from cryptography import x509
from cryptography.x509.oid import ExtensionOID, ExtendedKeyUsageOID

HANDLED_CRITICAL_OIDS = {
    ExtensionOID.BASIC_CONSTRAINTS,
    ExtensionOID.KEY_USAGE,
    ExtensionOID.EXTENDED_KEY_USAGE,
    ExtensionOID.SUBJECT_ALTERNATIVE_NAME,
}

def verify_codesign_leaf_policy(cert: x509.Certificate, now: datetime | None = None) -> None:
    ts = now or datetime.now(timezone.utc)
    if ts < cert.not_valid_before_utc or ts > cert.not_valid_after_utc:
        raise ValueError("code-signing certificate outside validity window")
    for ext in cert.extensions:
        if ext.critical and ext.oid not in HANDLED_CRITICAL_OIDS:
            raise ValueError(f"unhandled critical X.509 extension OID: {ext.oid.dotted_string}")
    bc = cert.extensions.get_extension_for_oid(ExtensionOID.BASIC_CONSTRAINTS).value
    if bc.ca:
        raise ValueError("CA certificate rejected as code-signing leaf")
    ku = cert.extensions.get_extension_for_oid(ExtensionOID.KEY_USAGE).value
    if not ku.digital_signature or ku.key_cert_sign or ku.crl_sign:
        raise ValueError("invalid KeyUsage for code-signing leaf")
    eku = cert.extensions.get_extension_for_oid(ExtensionOID.EXTENDED_KEY_USAGE).value
    if list(eku) != [ExtendedKeyUsageOID.CODE_SIGNING]:
        raise ValueError("code-signing leaf must assert solely id-kp-codeSigning EKU")
