	"crypto"
	"crypto/tls"
	"crypto/x509"
	"errors"
)

type equalPubKey interface {
	Equal(crypto.PublicKey) bool
}

func VerifyTLSCertKeyPair(pair tls.Certificate) (*x509.Certificate, error) {
	if len(pair.Certificate) == 0 || pair.PrivateKey == nil {
		return nil, errors.New("incomplete tls.Certificate bundle")
	}
	leaf, err := x509.ParseCertificate(pair.Certificate[0])
	if err != nil {
		return nil, err
	}
	if len(leaf.UnhandledCriticalExtensions) > 0 {
		return nil, errors.New("leaf contains unhandled critical X.509 extensions")
	}
	signer, ok := pair.PrivateKey.(crypto.Signer)
	if !ok {
		return nil, errors.New("private key does not implement crypto.Signer")
	}
	eq, ok := leaf.PublicKey.(equalPubKey)
	if !ok || !eq.Equal(signer.Public()) {
		return nil, errors.New("private key public component does not match leaf X.509 SPKI")
	}
	return leaf, nil
}
