use x509_parser::extensions::ParsedExtension;
use x509_parser::prelude::*;

pub fn verify_rfc3161_tsa_leaf(der: &[u8]) -> Result<(), &'static str> {
    let (rem, cert) = parse_x509_certificate(der).map_err(|_| "invalid DER cert")?;
    if !rem.is_empty() || cert.is_ca() {
        return Err("invalid DER or CA bit set on TSA leaf");
    }
    let mut saw_critical_tsa_eku = false;
    for ext in cert.extensions() {
        match ext.parsed_extension() {
            ParsedExtension::ExtendedKeyUsage(eku) => {
                if !ext.critical {
                    return Err("RFC 3161 requires critical ExtendedKeyUsage on TSA cert");
                }
                if !eku.time_stamping
                    || eku.any
                    || eku.server_auth
                    || eku.client_auth
                    || eku.code_signing
                    || eku.email_protection
                    || eku.ocsp_signing
                    || !eku.other.is_empty()
                {
                    return Err("TSA ExtendedKeyUsage must contain ONLY id-kp-timeStamping");
                }
                saw_critical_tsa_eku = true;
            }
            ParsedExtension::BasicConstraints(_) | ParsedExtension::KeyUsage(_) => {}
            _ if ext.critical => {
                return Err("unhandled critical X.509 extension on TSA cert");
            }
            _ => {}
        }
    }
    if !saw_critical_tsa_eku {
        return Err("missing critical id-kp-timeStamping EKU");
    }
    Ok(())
}
