package mqttwire

import (
	"errors"
	"io"
)

func ReadMQTTVarint(r io.ByteReader, maxAllowed uint32) (uint32, error) {
	var value uint32
	var shift uint
	for idx := 0; idx < 4; idx++ {
		b, err := r.ReadByte()
		if err != nil {
			return 0, err
		}
		if idx > 0 && b == 0x00 {
			return 0, errors.New("non-canonical overlong MQTT varint")
		}
		value |= uint32(b&0x7F) << shift
		if (b & 0x80) == 0 {
			if value > maxAllowed {
				return 0, errors.New("MQTT packet exceeds maxAllowed quota")
			}
			return value, nil
		}
		shift += 7
	}
	return 0, errors.New("malformed MQTT varint (>4 bytes)")
}
