package gzguard

import (
	"compress/gzip"
	"errors"
	"io"
	"net/http"
	"strings"
)

func ReadBoundedPossiblyGzipped(
	w http.ResponseWriter,
	r *http.Request,
	maxWireBytes int64,
	maxDecodedBytes int64,
) ([]byte, error) {
	r.Body = http.MaxBytesReader(w, r.Body, maxWireBytes)
	if !strings.EqualFold(r.Header.Get("Content-Encoding"), "gzip") {
		return io.ReadAll(r.Body)
	}
	gz, err := gzip.NewReader(r.Body)
	if err != nil {
		http.Error(w, "malformed gzip stream", http.StatusBadRequest)
		return nil, err
	}
	defer gz.Close()

	out, err := io.ReadAll(io.LimitReader(gz, maxDecodedBytes+1))
	if err != nil {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			http.Error(w, "compressed payload too large", http.StatusRequestEntityTooLarge)
			return nil, err
		}
		http.Error(w, "failed to gunzip body", http.StatusBadRequest)
		return nil, err
	}
	if int64(len(out)) > maxDecodedBytes {
		http.Error(w, "decompressed payload exceeds limit", http.StatusRequestEntityTooLarge)
		return nil, errors.New("gzip bomb detected")
	}
	return out, nil
}
