use flate2::read::GzDecoder;
use std::io::{self, Read};

pub fn decode_gzip_bounded(
    compressed: &[u8],
    max_wire_bytes: usize,
    max_decoded_bytes: usize,
) -> io::Result<Vec<u8>> {
    if compressed.len() > max_wire_bytes {
        return Err(io::Error::new(io::ErrorKind::FileTooLarge, "wire bytes exceed limit"));
    }
    let decoder = GzDecoder::new(compressed);
    let mut out = Vec::new();
    decoder.take((max_decoded_bytes + 1) as u64).read_to_end(&mut out)?;
    if out.len() > max_decoded_bytes {
        return Err(io::Error::new(io::ErrorKind::FileTooLarge, "gzip bomb exceeded decoded cap"));
    }
    Ok(out)
