```typescript
import { IncomingMessage } from "node:http";
import { createGunzip } from "node:zlib";

export async function readBoundedGzipBody(
  req: IncomingMessage,
  maxWireBytes: number,
  maxDecodedBytes: number,
): Promise<Buffer> {
  const gunzip = createGunzip({ maxOutputLength: maxDecodedBytes });
  let wireSeen = 0;
  req.on("data", (chunk: Buffer) => {
    wireSeen += chunk.byteLength;
    if (wireSeen > maxWireBytes) {
      req.destroy(new Error("Compressed body exceeded maxWireBytes"));
      gunzip.destroy();
    }
  });
  req.pipe(gunzip);

  const out: Buffer[] = [];
  for await (const decodedChunk of gunzip) {
    out.push(Buffer.isBuffer(decodedChunk) ? decodedChunk : Buffer.from(decodedChunk));
  }
  return Buffer.concat(out);
}
