use sha2::{Digest, Sha256};
use subtle::ConstantTimeEq;

pub fn verify_okp_ed25519_jkt(x_b64u: &str, expected_jkt: &str) -> Result<(), &'static str> {
    if x_b64u.len() != 43 || expected_jkt.len() != 43 {
