use sqlx::PgPool;
use uuid::Uuid;

const GIFTCARD_LOCK_SEED: i64 = 0x4749_4654_4352_4431; // "GIFTCRD1"

pub async fn transfer_giftcard_balance(
    pool: &PgPool,
    src_card_id: Uuid,
    dst_card_id: Uuid,
    cents: i64,
    support_agent: &str,
) -> Result<(), String> {
    if src_card_id == dst_card_id || cents <= 0 {
        return Err("invalid giftcard transfer arguments".into());
    }

    let mut ordered = [src_card_id.to_string(), dst_card_id.to_string()];
    ordered.sort();

    let mut tx = pool.begin().await.map_err(|e| e.to_string())?;
    for key in &ordered {
        sqlx::query("SELECT pg_advisory_xact_lock(hashtextextended($1, $2))")
            .bind(key)
            .bind(GIFTCARD_LOCK_SEED)
            .execute(&mut *tx)
            .await
            .map_err(|e| e.to_string())?;
    }

    sqlx::query("SELECT set_config('app.support_agent', $1, true)")
        .bind(support_agent)
        .execute(&mut *tx)
        .await
        .map_err(|e| e.to_string())?;

    let debited = sqlx::query(
        "UPDATE promo.giftcards
         SET balance_cents = balance_cents - $2
         WHERE card_id = $1 AND balance_cents >= $2",
    )
    .bind(src_card_id)
    .bind(cents)
    .execute(&mut *tx)
    .await
    .map_err(|e| e.to_string())?;

    if debited.rows_affected() != 1 {
        tx.rollback().await.map_err(|e| e.to_string())?;
        return Err("insufficient source giftcard balance".into());
    }

    sqlx::query("UPDATE promo.giftcards SET balance_cents = balance_cents + $2 WHERE card_id = $1")
        .bind(dst_card_id)
        .bind(cents)
        .execute(&mut *tx)
        .await
        .map_err(|e| e.to_string())?;

    tx.commit().await.map_err(|e| e.to_string())?;
    Ok(())
}
