CREATE SCHEMA IF NOT EXISTS promo;

CREATE TABLE promo.redemption_ledger (
    ledger_id        BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    merchant_id      UUID NOT NULL,
    campaign_id      UUID NOT NULL,
    claim_id         UUID NOT NULL,
    customer_id      UUID NOT NULL,
    discount_cents   INT NOT NULL CHECK (discount_cents > 0),
    checkout_session TEXT NOT NULL,
    redeemed_at      TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()
);

CREATE OR REPLACE FUNCTION promo.record_claim_to_ledger()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog
AS $$
DECLARE
    v_merchant UUID;
    v_campaign UUID;
    v_session  TEXT := COALESCE(NULLIF(pg_catalog.current_setting('app.checkout_session', true), ''), 'unset');
BEGIN
    SELECT v.merchant_id, v.campaign_id
    INTO STRICT v_merchant, v_campaign
    FROM promo.vouchers v
    WHERE v.voucher_id = NEW.voucher_id;

    INSERT INTO promo.redemption_ledger
        (merchant_id, campaign_id, claim_id, customer_id, discount_cents, checkout_session)
    VALUES
        (v_merchant, v_campaign, NEW.claim_id, NEW.customer_id, NEW.discount_cents, v_session);
    RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION promo.forbid_ledger_edit()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'promo.redemption_ledger is append-only (% blocked)', TG_OP
        USING ERRCODE = 'insufficient_privilege';
END;
$$;

CREATE TRIGGER trg_voucher_claims_to_ledger
    AFTER INSERT ON promo.voucher_claims
    FOR EACH ROW EXECUTE FUNCTION promo.record_claim_to_ledger();

CREATE TRIGGER trg_redemption_ledger_no_mod
    BEFORE UPDATE OR DELETE ON promo.redemption_ledger
    FOR EACH ROW EXECUTE FUNCTION promo.forbid_ledger_edit();

CREATE TRIGGER trg_redemption_ledger_no_trunc
    BEFORE TRUNCATE ON promo.redemption_ledger
    FOR EACH STATEMENT EXECUTE FUNCTION promo.forbid_ledger_edit();

CREATE VIEW promo.v_campaign_redemptions
WITH (security_invoker = true) AS
SELECT ledger_id, merchant_id, campaign_id, claim_id, customer_id, discount_cents, redeemed_at
FROM promo.redemption_ledger;
