import hashlib
import hmac
import unicodedata

def normalize_voucher_code(raw_code: str) -> str:
    cleaned = unicodedata.normalize("NFKC", raw_code).strip().upper()
    return cleaned.replace("-", "").replace(" ", "")

def derive_voucher_lookup_mac(pepper: bytes, campaign_id: str, raw_code: str) -> str:
    if len(pepper) < 32:
        raise ValueError("pepper must be at least 32 bytes")
    norm = normalize_voucher_code(raw_code)
    msg = f"promo-v1|{campaign_id}|{norm}".encode("utf-8")
    return hmac.new(pepper, msg, hashlib.sha256).hexdigest()

def verify_voucher_mac(pepper: bytes, campaign_id: str, raw_code: str, stored_hex: str) -> bool:
    computed = derive_voucher_lookup_mac(pepper, campaign_id, raw_code)
    return hmac.compare_digest(computed, stored_hex.lower())
