PR_CHECKOUT_RE = re.compile(r"gh\s+pr\s+checkout|refs/pull/", re.IGNORECASE)

def audit_issue_comment_pr_checkout(workflow_yaml: str) -> list[str]:
    doc = yaml.safe_load(workflow_yaml) or {}
    on_cfg = doc.get("on", doc.get(True, {}))
    has_ic = (
        on_cfg == "issue_comment"
        or (isinstance(on_cfg, (list, dict)) and "issue_comment" in on_cfg)
    )
    if not has_ic:
        return []

    findings: list[str] = []
