        if not isinstance(job, dict) or job.get("environment"):
            continue
        for idx, step in enumerate(job.get("steps") or []):
            blob = f"{step.get('run', '')} {(step.get('with') or {}).get('ref', '')}"
            if PR_CHECKOUT_RE.search(blob):
                findings.append(
                    f"job '{job_id}' step[{idx}] checks out PR head on issue_comment without a protected 'environment' gate"
