pub fn lint_dockerfile_pip_flags(dockerfile: &str) -> Vec<(usize, String)> {
    let mut issues = Vec::new();
    let mut buf = String::new();
    let mut start_line = 1usize;

    for (idx, raw) in dockerfile.lines().enumerate() {
        let trimmed = raw.trim();
        if buf.is_empty() {
            start_line = idx + 1;
        }
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        if let Some(stripped) = trimmed.strip_suffix('\\') {
            buf.push_str(stripped);
            buf.push(' ');
            continue;
        }
        buf.push_str(trimmed);
        let full = buf.trim().to_string();
        buf.clear();

        if !full.get(..4).map(|p| p.eq_ignore_ascii_case("RUN ")).unwrap_or(false) {
            continue;
        }
        if !full.contains("pip ") && !full.contains("pip3 ") {
            continue;
        }
        if full.contains("--trusted-host") {
            issues.push((start_line, "pip --trusted-host disables TLS certificate verification".into()));
        }
        if full.contains("--extra-index-url") {
            issues.push((start_line, "pip --extra-index-url enables PyPI dependency confusion; use --index-url".into()));
        }
        if full.contains("http://") {
            issues.push((start_line, "pip install references cleartext http:// package source".into()));
        }
    }
    issues
}
