```go
package s3log

import (
	"regexp"
	"strings"
)

var s3TokenRe = regexp.MustCompile(`\[[^\]]+\]|"[^"]*"|\S+`)

type UnencryptedPut struct {
	Bucket      string
	Key         string
	RemoteIP    string
	Requester   string
	CipherSuite string
}

func FindCleartextObjectPuts(lines []string) []UnencryptedPut {
	var hits []UnencryptedPut
	for _, line := range lines {
		toks := s3TokenRe.FindAllString(strings.TrimSpace(line), -1)
		// Standard S3 access log format has >= 22 tokens; index 7 is operation, 21 is cipher suite
		if len(toks) < 22 {
			continue
		}
		op := toks[7]
		if op != "REST.PUT.OBJECT" && op != "REST.POST.BUCKET" {
			continue
		}
		cipher := toks[21]
		if cipher == "-" {
			hits = append(hits, UnencryptedPut{
				Bucket:      toks[1],
				RemoteIP:    toks[3],
				Requester:   toks[4],
				Key:         toks[8],
				CipherSuite: cipher,
			})
		}
	}
	return hits
}
