```python
import yaml

def find_duplicate_yaml_keys(yaml_text: str) -> list[tuple[int, str]]:
    root = yaml.compose(yaml_text, Loader=yaml.SafeLoader)
    duplicates: list[tuple[int, str]] = []

    def visit(node: yaml.Node) -> None:
        if isinstance(node, yaml.MappingNode):
            seen: dict[str, int] = {}
            for k_node, v_node in node.value:
                if isinstance(k_node, yaml.ScalarNode):
                    key_name = k_node.value
                    line_no = k_node.start_mark.line + 1
                    if key_name in seen:
                        duplicates.append(
                            (line_no, f"duplicate YAML key '{key_name}' (first defined at line {seen[key_name]})")
                        )
                    else:
                        seen[key_name] = line_no
                visit(v_node)
        elif isinstance(node, yaml.SequenceNode):
            for child in node.value:
                visit(child)

    if root is not None:
        visit(root)
    return duplicates
