from typing import Iterable

INTERACTIVE_SUBS = {"exec", "attach", "portforward"}

def external_pod_exec_cidrs(lines: Iterable[str]) -> list[str]:
    v4, v6 = [], []
    for raw in lines:
        ev = json.loads(raw)
        obj = ev.get("objectRef") or {}
        if obj.get("resource") != "pods" or obj.get("subresource") not in INTERACTIVE_SUBS:
