import ast

SUBPROC_CALLS = {"run", "Popen", "call", "check_call", "check_output"}

def find_shell_true_invocations(source: str) -> list[int]:
    tree = ast.parse(source)
    lines: list[int] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        is_subproc = (
            isinstance(node.func, ast.Attribute)
            and node.func.attr in SUBPROC_CALLS
            and isinstance(node.func.value, ast.Name)
            and node.func.value.id == "subprocess"
        )
        if not is_subproc:
