package netstr

import "errors"

var ErrInvalidNetstring = errors.New("malformed or non-canonical netstring")

func ParseCanonicalNetstring(buf []byte, maxPayloadBytes int) (payload, rest []byte, err error) {
	colon := -1
	for i := 0; i < len(buf) && i < 10; i++ {
		if buf[i] == ':' {
			colon = i
			break
		}
		if buf[i] < '0' || buf[i] > '9' {
			return nil, nil, ErrInvalidNetstring
		}
	}
	if colon <= 0 || (colon > 1 && buf[0] == '0') {
		return nil, nil, ErrInvalidNetstring
	}
	n := 0
	for i := 0; i < colon; i++ {
		n = n*10 + int(buf[i]-'0')
		if n > maxPayloadBytes {
			return nil, nil, ErrInvalidNetstring
		}
	}
	end := colon + 1 + n
	if end >= len(buf) || buf[end] != ',' {
		return nil, nil, ErrInvalidNetstring
	}
	return buf[colon+1 : end], buf[end+1:], nil
}
