use nom::{
    bytes::complete::tag,
    combinator::{all_consuming, map_res, verify},
    multi::length_data,
    number::complete::be_u16,
    IResult,
};

pub fn parse_tls_sni_extension(ext_data: &[u8]) -> IResult<&[u8], &str> {
    let (_, list_bytes) = all_consuming(length_data(verify(be_u16, |&n| n >= 4)))(ext_data)?;
    let (rest, _) = tag([0x00])(list_bytes)?;
    all_consuming(map_res(
        length_data(verify(be_u16, |&n| (1..=253).contains(&n))),
        |raw: &[u8]| {
            let host = std::str::from_utf8(raw).map_err(|_| "non-utf8 SNI")?;
            if host.starts_with('.') || host.ends_with('.') || host.contains("..") {
                return Err("invalid empty SNI label");
            }
            if !host.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'-' || b == b'.') {
                return Err("illegal byte in SNI hostname");
            }
            Ok(host)
        },
    ))(rest)
}
