import hashlib
import hmac
from collections import deque


def verify_merkle_multiproof(
    tree_size: int,
    leaf_indices: list[int],
    leaf_payloads: list[bytes],
    aux_hashes: list[bytes],
    expected_root: bytes,
) -> bool:
    if tree_size <= 0 or (tree_size & (tree_size - 1)) != 0:
        return False
    if not leaf_indices or len(leaf_indices) != len(leaf_payloads) or len(expected_root) != 32:
        return False
    if any(len(h) != 32 for h in aux_hashes):
        return False

    q: deque[tuple[int, bytes]] = deque()
    for i, idx in enumerate(leaf_indices):
        if not (0 <= idx < tree_size) or (i > 0 and idx <= leaf_indices[i - 1]):
            return False
        digest = hashlib.sha256(b"\x00" + leaf_payloads[i]).digest()
        q.append((tree_size + idx, digest))

    aux_pos = 0
    while q:
        pos, h_val = q.popleft()
        if pos == 1:
            return not q and aux_pos == len(aux_hashes) and hmac.compare_digest(h_val, expected_root)

        if (pos & 1) == 0:
            left = h_val
            if q and q[0][0] == (pos ^ 1):
                _, right = q.popleft()
            elif aux_pos < len(aux_hashes):
                right = aux_hashes[aux_pos]
                aux_pos += 1
            else:
                return False
        else:
            right = h_val
            if aux_pos < len(aux_hashes):
                left = aux_hashes[aux_pos]
                aux_pos += 1
            else:
                return False

        parent = hashlib.sha256(b"\x01" + left + right).digest()
        q.append((pos >> 1, parent))

    return False
