```rust
pub const MERSENNE_61: u64 = (1u64 << 61) - 1;

fn mod_add(a: u64, b: u64) -> u64 {
    ((a as u128 + b as u128) % (MERSENNE_61 as u128)) as u64
}

fn mod_sub(a: u64, b: u64) -> u64 {
    ((a as u128 + MERSENNE_61 as u128 - (b % MERSENNE_61) as u128) % (MERSENNE_61 as u128)) as u64
}

fn mod_mul(a: u64, b: u64) -> u64 {
    ((a as u128 * b as u128) % (MERSENNE_61 as u128)) as u64
}

fn mod_pow(mut base: u64, mut exp: u64) -> u64 {
    let mut acc = 1u64;
    base %= MERSENNE_61;
    while exp > 0 {
        if (exp & 1) == 1 {
            acc = mod_mul(acc, base);
        }
        base = mod_mul(base, base);
        exp >>= 1;
    }
    acc
}

pub fn reconstruct_m61(shares: &[(u64, u64)], threshold: usize) -> Result<u64, &'static str> {
    if threshold < 2 || shares.len() < threshold {
        return Err("insufficient shares for threshold");
    }
    let sub = &shares[..threshold];
    for (i, &(xi, yi)) in sub.iter().enumerate() {
        if xi == 0 || xi >= MERSENNE_61 || yi >= MERSENNE_61 {
            return Err("coordinate out of GF(2^61 - 1) range");
        }
        if sub[..i].iter().any(|&(prev_x, _)| prev_x == xi) {
            return Err("duplicate share x-coordinate");
        }
    }

    let mut secret = 0u64;
    for (i, &(xi, yi)) in sub.iter().enumerate() {
        let mut num = 1u64;
        let mut den = 1u64;
        for (j, &(xj, _)) in sub.iter().enumerate() {
            if i == j {
                continue;
            }
            num = mod_mul(num, mod_sub(0, xj));
            den = mod_mul(den, mod_sub(xi, xj));
        }
        let inv_den = mod_pow(den, MERSENNE_61 - 2);
        let term = mod_mul(yi, mod_mul(num, inv_den));
        secret = mod_add(secret, term);
    }
    Ok(secret)
}
