import { createHash, timingSafeEqual } from "node:crypto";

function buildEmptySubtreeTable(): Buffer[] {
  const table: Buffer[] = new Array(256);
  let curr = createHash("sha256").update(Buffer.alloc(33, 0x00)).digest();
  for (let lvl = 0; lvl < 256; lvl++) {
    table[lvl] = curr;
    curr = createHash("sha256").update(Buffer.from([0x01])).update(curr).update(curr).digest();
  }
  return table;
}

const EMPTY_SUBTREES = buildEmptySubtreeTable();

export function verifyCompactSmtNonInclusion(
  key: Buffer,
  presentMask32: Buffer,
  compactSiblings: Buffer[],
  expectedRoot: Buffer
): boolean {
  if (presentMask32.length !== 32 || expectedRoot.length !== 32) return false;
  if (compactSiblings.some((s) => s.length !== 32)) return false;

  const keyHash = createHash("sha256").update(key).digest();
  let curr = createHash("sha256").update(Buffer.alloc(33, 0x00)).digest();
  let sibCursor = 0;

  for (let lvl = 0; lvl < 256; lvl++) {
    const byteIdx = 31 - Math.floor(lvl / 8);
    const bitOffset = lvl % 8;
    const hasCustomSib = ((presentMask32[byteIdx] >> bitOffset) & 1) === 1;

    let sib: Buffer;
    if (hasCustomSib) {
      if (sibCursor >= compactSiblings.length) return false;
      sib = compactSiblings[sibCursor++];
    } else {
      sib = EMPTY_SUBTREES[lvl];
    }

    const pathBit = (keyHash[byteIdx] >> bitOffset) & 1;
    const h = createHash("sha256").update(Buffer.from([0x01]));
    if (pathBit === 0) {
      h.update(curr).update(sib);
    } else {
      h.update(sib).update(curr);
    }
    curr = h.digest();
  }

  return sibCursor === compactSiblings.length && timingSafeEqual(curr, expectedRoot);
}
