```python
import hashlib

EMPTY_TREE_ROOT = hashlib.sha256(b"").digest()


def _largest_pow2_less_than(n: int) -> int:
    return 1 << ((n - 1).bit_length() - 1)


def rfc6962_root(leaves: list[bytes]) -> bytes:
    n = len(leaves)
    if n == 0:
        return EMPTY_TREE_ROOT
    if n == 1:
        return hashlib.sha256(b"\x00" + leaves[0]).digest()
    k = _largest_pow2_less_than(n)
    left = rfc6962_root(leaves[:k])
    right = rfc6962_root(leaves[k:])
    return hashlib.sha256(b"\x01" + left + right).digest()


def rfc6962_audit_path(leaf_index: int, leaves: list[bytes]) -> list[bytes]:
    n = len(leaves)
    if not (0 <= leaf_index < n):
        raise IndexError("leaf_index out of bounds")
    if n == 1:
        return []
    k = _largest_pow2_less_than(n)
    if leaf_index < k:
        sub_path = rfc6962_audit_path(leaf_index, leaves[:k])
        sub_path.append(rfc6962_root(leaves[k:]))
        return sub_path
    sub_path = rfc6962_audit_path(leaf_index - k, leaves[k:])
    sub_path.append(rfc6962_root(leaves[:k]))
    return sub_path
```

