import ast
import re

SENSITIVE_NAME_RE = re.compile(r"(?:merkle_root|expected_root|root_hash|digest|hmac|mac_tag)", re.IGNORECASE)


def _extract_name(node: ast.AST) -> str:
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        return node.attr
    return ""


def find_non_ct_digest_comparisons(source: str) -> list[tuple[int, str]]:
