        operands = [node.left] + list(node.comparators)
        for op, left_n, right_n in zip(node.ops, operands, operands[1:]):
            if isinstance(op, (ast.Eq, ast.NotEq)):
                ln, rn = _extract_name(left_n), _extract_name(right_n)
                if SENSITIVE_NAME_RE.search(ln) or SENSITIVE_NAME_RE.search(rn):
                    issues.append((node.lineno, f"non-constant-time comparison between '{ln or 'expr'}' and '{rn or 'expr'}'"))
