import hashlib
import hmac
import json
from typing import Any

def _no_duplicate_keys(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    out: dict[str, Any] = {}
    for k, v in pairs:
        if k in out:
            raise ValueError(f"duplicate JSON key rejected: {k!r}")
        out[k] = v
    return out

def _reject_nonfinite(token: str) -> None:
    raise ValueError(f"non-standard JSON constant rejected: {token}")

def verify_and_load_strict_json(raw_body: bytes, sig_hex: str, secret_key: bytes) -> dict[str, Any]:
    expected = hmac.new(secret_key, raw_body, hashlib.sha256).hexdigest()
    if not hmac.compare_digest(expected.encode("ascii"), sig_hex.lower().encode("ascii")):
        raise ValueError("HMAC-SHA256 verification failed")
    obj = json.loads(
        raw_body.decode("utf-8"),
        object_pairs_hook=_no_duplicate_keys,
        parse_constant=_reject_nonfinite,
    )
    if not isinstance(obj, dict):
        raise ValueError("top-level JSON payload must be an object")
    return obj
