use serde_json::Value;

const KMS_HDR: &str = "s3:x-amz-server-side-encryption-aws-kms-key-id";

pub fn check_s3_kms_header_bypass(policy_json: &str) -> Result<Vec<String>, serde_json::Error> {
    let doc: Value = serde_json::from_str(policy_json)?;
    let mut warnings = Vec::new();
    let Some(stmts) = doc.get("Statement").and_then(Value::as_array) else {
        return Ok(warnings);
    };

    for (idx, stmt) in stmts.iter().enumerate() {
        if stmt.get("Effect").and_then(Value::as_str) != Some("Deny") {
            continue;
        }
        let Some(cond) = stmt.get("Condition").and_then(Value::as_object) else {
            continue;
        };
        let uses_plain_sne = cond
            .get("StringNotEquals")
            .and_then(|m| m.get(KMS_HDR))
            .is_some();
        let has_null_guard = cond
            .get("Null")
            .and_then(|m| m.get(KMS_HDR))
            .is_some();

        if uses_plain_sne && !has_null_guard {
            warnings.push(format!(
                "Statement[{idx}]: StringNotEquals on {KMS_HDR} can be bypassed by omitting the header; use StringNotEqualsIfExists or add a Null condition"
            ));
        }
    }
    Ok(warnings)
}
