func VerifyGitHubSignature256(secret []byte, rawBody []byte, sigHeader string) bool {
	if len(secret) == 0 || !strings.HasPrefix(sigHeader, "sha256=") {
		return false
	}
	sigBytes, err := hex.DecodeString(strings.TrimPrefix(sigHeader, "sha256="))
	if err != nil || len(sigBytes) != sha256.Size {
		return false
	}
