package streamaead

import (
	"crypto/cipher"
	"encoding/binary"
	"errors"
	"io"
)

const MaxChunkPlaintext = 64 * 1024

func OpenStream(aead cipher.AEAD, r io.Reader, dst io.Writer, streamAAD []byte) error {
	if aead.NonceSize() != 12 {
		return errors.New("requires 12-byte nonce AEAD")
	}
	var prefix [8]byte
	if _, err := io.ReadFull(r, prefix[:]); err != nil {
		return err
	}
	var nonce [12]byte
	copy(nonce[:8], prefix[:])

	var hdr [5]byte
	var seq uint32
	for {
		if _, err := io.ReadFull(r, hdr[:]); err != nil {
			return errors.New("unexpected EOF before final authenticated chunk")
		}
		isFinal := hdr[0]
		if isFinal > 1 {
			return errors.New("invalid final-chunk marker")
		}
		ctLen := binary.BigEndian.Uint32(hdr[1:5])
		if ctLen < uint32(aead.Overhead()) || ctLen > uint32(MaxChunkPlaintext+aead.Overhead()) {
			return errors.New("chunk length outside bounds")
		}
		ct := make([]byte, ctLen)
		if _, err := io.ReadFull(r, ct); err != nil {
			return err
		}
		binary.BigEndian.PutUint32(nonce[8:12], seq)
		aad := append(append([]byte(nil), streamAAD...), isFinal)
		pt, err := aead.Open(nil, nonce[:], ct, aad)
		if err != nil {
			return err
		}
		if _, err := dst.Write(pt); err != nil {
			return err
		}
		if isFinal == 1 {
			var extra [1]byte
			if n, _ := r.Read(extra[:]); n != 0 {
				return errors.New("trailing bytes after final chunk")
			}
			return nil
		}
		if seq == ^uint32(0) {
			return errors.New("chunk counter exhausted")
		}
		seq++
	}
}
