use aes_gcm::aead::{Aead, KeyInit, Payload};
use aes_gcm::{Aes256Gcm, Nonce};
use std::io::{self, Read, Write};

pub fn open_chunked_gcm<R: Read, W: Write>(
    key: &[u8; 32],
    mut reader: R,
    mut writer: W,
    stream_aad: &[u8],
) -> io::Result<()> {
    let cipher = Aes256Gcm::new(key.into());
    let mut prefix = [0u8; 8];
    reader.read_exact(&mut prefix)?;
    let mut seq: u32 = 0;

    loop {
        let mut hdr = [0u8; 5];
        reader.read_exact(&mut hdr).map_err(|_| {
            io::Error::new(io::ErrorKind::UnexpectedEof, "truncated before final chunk")
        })?;
        let is_final = hdr[0];
        let ct_len = u32::from_be_bytes([hdr[1], hdr[2], hdr[3], hdr[4]]) as usize;
        if is_final > 1 || !(16..=(65536 + 16)).contains(&ct_len) {
            return Err(io::Error::new(io::ErrorKind::InvalidData, "bad chunk header"));
