use sha2::{Digest, Sha256};
use subtle::ConstantTimeEq;

fn hash_interior(left: &[u8; 32], right: &[u8; 32]) -> [u8; 32] {
    let mut h = Sha256::new();
    h.update([0x01]);
    h.update(left);
    h.update(right);
    h.finalize().into()
