pub fn verify_rfc9162_consistency(
    first: u64,
    second: u64,
    proof: &[[u8; 32]],
    first_root: &[u8; 32],
    second_root: &[u8; 32],
) -> bool {
    if first == 0 || first > second {
        return false;
    }
    if first == second {
        return proof.is_empty() && bool::from(first_root.ct_eq(second_root));
    }
    if proof.is_empty() {
        return false;
    }

    let mut fn_idx = first - 1;
    let mut sn_idx = second - 1;
    while (fn_idx & 1) == 1 {
        fn_idx >>= 1;
        sn_idx >>= 1;
    }

    let (mut fr, mut sr, start) = if first.is_power_of_two() {
        (*first_root, *first_root, 0usize)
    } else {
        (proof[0], proof[0], 1usize)
    };

    for c in &proof[start..] {
        if sn_idx == 0 {
            return false;
        }
        if (fn_idx & 1) == 1 || fn_idx == sn_idx {
            fr = hash_interior(c, &fr);
            sr = hash_interior(c, &sr);
            while (fn_idx & 1) == 0 && fn_idx != 0 {
                fn_idx >>= 1;
                sn_idx >>= 1;
            }
        } else {
            sr = hash_interior(&sr, c);
        }
        fn_idx >>= 1;
        sn_idx >>= 1;
    }

    sn_idx == 0
        && bool::from(fr.ct_eq(first_root))
        && bool::from(sr.ct_eq(second_root))
}
