import { createHmac, timingSafeEqual } from "node:crypto";

const DOMAIN = Buffer.from("SHAMIR-ENVELOPE-V1\x00", "utf8");

export function packShareEnvelope(
  macKey32: Buffer,
  ceremonyId16: Buffer,
  threshold: number,
  x: number,
  y32: Buffer
): Buffer {
  if (macKey32.length !== 32 || ceremonyId16.length !== 16 || y32.length !== 32) {
    throw new RangeError("invalid buffer lengths");
  }
