    throw new RangeError("invalid threshold or x index");
  }
  const header = Buffer.alloc(19);
  header[0] = 1;
  ceremonyId16.copy(header, 1);
  header[17] = threshold;
  header[18] = x;

  const tag = createHmac("sha256", macKey32).update(DOMAIN).update(header).update(y32).digest();
  return Buffer.concat([header, y32, tag]);
}

export function unpackShareEnvelope(
  macKey32: Buffer,
  expectedCeremonyId16: Buffer,
  wire: Buffer
): { threshold: number; x: number; y: bigint } {
  if (macKey32.length !== 32 || expectedCeremonyId16.length !== 16 || wire.length !== 83) {
    throw new Error("invalid share envelope size");
  }
  const header = wire.subarray(0, 19);
  const y32 = wire.subarray(19, 51);
  const wireTag = wire.subarray(51, 83);

  const expectedTag = createHmac("sha256", macKey32).update(DOMAIN).update(header).update(y32).digest();
  if (!timingSafeEqual(wireTag, expectedTag)) {
    throw new Error("share envelope HMAC verification failed");
