use http::{Request, Response, StatusCode};
use std::{future::Future, pin::Pin, sync::Arc, task::{Context, Poll}, time::Duration};
use tokio::sync::Semaphore;
use tower::Service;

#[derive(Clone)]
pub struct BoundedAuthAdmission<S> {
    inner: S,
    sem: Arc<Semaphore>,
    deadline: Duration,
}

impl<S> BoundedAuthAdmission<S> {
    pub fn new(inner: S, max_in_flight: usize, deadline: Duration) -> Self {
        Self { inner, sem: Arc::new(Semaphore::new(max_in_flight)), deadline }
    }
}

impl<S, B> Service<Request<B>> for BoundedAuthAdmission<S>
where
    S: Service<Request<B>, Response = Response<B>> + Clone + Send + 'static,
    S::Future: Send + 'static,
    S::Error: Send + 'static,
    B: Default + Send + 'static,
{
    type Response = Response<B>;
    type Error = S::Error;
    type Future = Pin<Box<dyn Future<Output = Result<Self::Response, Self::Error>> + Send>>;

    fn poll_ready(&mut self, cx: &mut Context<'_>) -> Poll<Result<(), Self::Error>> {
        self.inner.poll_ready(cx)
    }

    fn call(&mut self, req: Request<B>) -> Self::Future {
        let Ok(permit) = Arc::clone(&self.sem).try_acquire_owned() else {
            return Box::pin(async {
                let mut r = Response::new(B::default());
                *r.status_mut() = StatusCode::SERVICE_UNAVAILABLE;
                Ok(r)
            });
        };
        let fut = self.inner.call(req);
        let limit = self.deadline;
        Box::pin(async move {
            let _guard = permit;
            match tokio::time::timeout(limit, fut).await {
                Ok(res) => res,
                Err(_) => {
                    let mut r = Response::new(B::default());
                    *r.status_mut() = StatusCode::GATEWAY_TIMEOUT;
                    Ok(r)
                }
            }
        })
    }
}
