```typescript
export function parseCanonicalNetstring(
  buf: Uint8Array,
  maxBytes = 65_536,
): { payload: Uint8Array; rest: Uint8Array } {
  let colon = -1;
  for (let i = 0; i < buf.byteLength && i < 8; i++) {
    const b = buf[i];
    if (b === 0x3a) {
      colon = i;
      break;
    }
    if (b < 0x30 || b > 0x39) {
      throw new Error("non-digit byte in netstring length header");
    }
  }
  if (colon <= 0 || (colon > 1 && buf[0] === 0x30)) {
    throw new Error("missing colon or non-canonical leading zero in netstring");
  }
  let len = 0;
  for (let i = 0; i < colon; i++) {
    len = len * 10 + (buf[i] - 0x30);
    if (len > maxBytes) {
      throw new RangeError("netstring exceeds maxBytes ceiling");
    }
  }
  const end = colon + 1 + len;
  if (end >= buf.byteLength || buf[end] !== 0x2c) {
    throw new RangeError("truncated netstring or missing trailing comma");
  }
  return { payload: buf.subarray(colon + 1, end), rest: buf.subarray(end + 1) };
}
