import shlex

DANGEROUS_LD_VARS = {"LD_PRELOAD", "LD_LIBRARY_PATH", "LD_AUDIT"}

def _parse_env_pairs(rest: str) -> list[tuple[str, str]]:
    if "=" in rest.split()[0]:
        tokens = shlex.split(rest)
        pairs = []
        for tok in tokens:
            if "=" in tok:
                k, v = tok.split("=", 1)
                pairs.append((k, v))
        return pairs
    parts = rest.split(None, 1)
    return [(parts[0], parts[1])] if len(parts) == 2 else []

def lint_dockerfile_env_hijack(dockerfile: str) -> list[tuple[int, str]]:
    findings: list[tuple[int, str]] = []
    for lineno, raw in enumerate(dockerfile.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith("#") or not line.upper().startswith("ENV "):
            continue
        for key, val in _parse_env_pairs(line[4:].strip()):
            ukey = key.upper()
            if ukey in DANGEROUS_LD_VARS:
                findings.append((lineno, f"ENV sets dangerous dynamic linker variable {key}"))
            elif ukey == "PATH":
                for seg in val.split(":"):
                    clean = seg.strip()
                    if clean in {"", "."} or (not clean.startswith("/") and not clean.startswith("$")):
                        findings.append((lineno, f"ENV PATH contains relative or empty segment '{seg}'"))
    return findings
