const NUMERIC_USER_RE = /^(\d+)(?::(\d+))?$/;

export function checkNumericFinalUser(dockerfile: string): string[] {
  let seenFrom = false;
  let finalUser: string | null = null;

  for (const raw of dockerfile.split(/\r?\n/)) {
    const line = raw.trim();
    if (!line || line.startsWith("#")) continue;
    const parts = line.split(/\s+/);
    const instr = parts[0].toUpperCase();
    if (instr === "FROM") {
      seenFrom = true;
      finalUser = null;
    } else if (instr === "USER" && parts[1]) {
      finalUser = parts[1];
    }
  }

  if (!seenFrom) return ["Dockerfile contains no FROM instruction"];
  if (!finalUser) return ["final stage missing USER instruction"];

  const m = NUMERIC_USER_RE.exec(finalUser);
  if (!m) {
    return [`final stage USER '${finalUser}' is symbolic; use numeric UID (e.g. 65532:65532) for runAsNonRoot compatibility`];
  }
  const uid = Number(m[1]);
  if (uid === 0) {
    return ["final stage USER UID cannot be 0 (root)"];
  }
  return [];
}
