import ast

PUBLIC_ACLS = {"public-read", "public-read-write", "authenticated-read"}

class CdktfS3Auditor(ast.NodeVisitor):
    def __init__(self) -> None:
        self.bucket_lines: list[int] = []
        self.pab_count = 0
        self.findings: list[tuple[int, str]] = []

    def visit_Call(self, node: ast.Call) -> None:
        fn_name = ""
        if isinstance(node.func, ast.Name):
            fn_name = node.func.id
        elif isinstance(node.func, ast.Attribute):
            fn_name = node.func.attr

        if fn_name == "S3Bucket":
            self.bucket_lines.append(node.lineno)
            for kw in node.keywords:
                if kw.arg == "acl" and isinstance(kw.value, ast.Constant):
                    if str(kw.value.value) in PUBLIC_ACLS:
                        self.findings.append((node.lineno, f"S3Bucket sets public ACL '{kw.value.value}'"))
        elif fn_name == "S3BucketPublicAccessBlock":
            self.pab_count += 1
        self.generic_visit(node)

def audit_cdktf_s3(source: str) -> list[tuple[int, str]]:
    auditor = CdktfS3Auditor()
    auditor.visit(ast.parse(source))
    if len(auditor.bucket_lines) > auditor.pab_count:
        auditor.findings.append(
            (auditor.bucket_lines[0], "fewer S3BucketPublicAccessBlock constructs than S3Bucket constructs")
