import { createCipheriv, randomBytes } from "node:crypto";

function sealRandomNonceGcm(key: Buffer, plaintext: Buffer, aad: Buffer): Buffer {
  const nonce = randomBytes(12);
  const cipher = createCipheriv("aes-256-gcm", key, nonce, { authTagLength: 16 });
  cipher.setAAD(aad);
  const ct = Buffer.concat([cipher.update(plaintext), cipher.final()]);
  return Buffer.concat([nonce, ct, cipher.getAuthTag()]);
}

export function sealGo124Envelope(kek: Buffer, plaintext: Buffer, aad: Buffer): { wrappedDek: Buffer; ciphertext: Buffer } {
  if (kek.byteLength !== 32) {
    throw new Error("KEK must be 32 bytes");
  }
  const dek = randomBytes(32);
  try {
    const ciphertext = sealRandomNonceGcm(dek, plaintext, aad);
    const wrappedDek = sealRandomNonceGcm(kek, dek, aad);
    return { wrappedDek, ciphertext };
  } finally {
    dek.fill(0);
  }
}
