```go
package tarextract

import (
	"archive/tar"
	"crypto/sha256"
	"crypto/subtle"
	"errors"
	"io"
	"os"
	"path/filepath"
	"strings"
)

func ExtractVerifiedTar(r io.Reader, destDir string, expected map[string][32]byte, maxFile int64) error {
	tmpDir, err := os.MkdirTemp(destDir, ".tarext-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir)

	tr := tar.NewReader(r)
	seen := make(map[string]bool, len(expected))
	for {
		hdr, err := tr.Next()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return err
		}
		if hdr.Typeflag == tar.TypeDir {
			continue
		}
		if hdr.Typeflag != tar.TypeReg {
			return errors.New("non-regular tar entry rejected")
		}
		clean := filepath.ToSlash(filepath.Clean(hdr.Name))
		if strings.HasPrefix(clean, "/") || strings.HasPrefix(clean, "..") || strings.HasPrefix(clean, "-") || seen[clean] {
			return errors.New("unsafe or duplicate tar entry: " + hdr.Name)
		}
		want, ok := expected[clean]
		if !ok || hdr.Size > maxFile {
			return errors.New("unmanifested or oversized tar entry: " + clean)
		}
		staged := filepath.Join(tmpDir, filepath.FromSlash(clean))
		if err := os.MkdirAll(filepath.Dir(staged), 0o700); err != nil {
			return err
		}
		f, err := os.OpenFile(staged, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600)
		if err != nil {
			return err
		}
		h := sha256.New()
		_, copyErr := io.Copy(f, io.TeeReader(io.LimitReader(tr, maxFile+1), h))
		f.Close()
		if copyErr != nil {
			return copyErr
		}
		if subtle.ConstantTimeCompare(h.Sum(nil), want[:]) != 1 {
			return errors.New("sha256 mismatch: " + clean)
		}
		seen[clean] = true
	}
	if len(seen) != len(expected) {
		return errors.New("missing manifested entries in tar")
	}
	for rel := range seen {
		dst := filepath.Join(destDir, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
			return err
		}
		if err := os.Rename(filepath.Join(tmpDir, filepath.FromSlash(rel)), dst); err != nil {
			return err
		}
	}
	return nil
}
