use std::fs;
use std::path::Path;
use std::process::Command;

pub fn run_sha256sum_strict(work_dir: &Path, manifest_name: &str) -> Result<(), &'static str> {
    if manifest_name.is_empty() || manifest_name.contains('/') || manifest_name.contains('\0') {
        return Err("manifest name must be a plain filename");
    }
    let dir_meta = fs::symlink_metadata(work_dir).map_err(|_| "stat work_dir failed")?;
    if !dir_meta.file_type().is_dir() {
        return Err("work_dir must be a real non-symlink directory");
    }
    let manifest_path = work_dir.join(manifest_name);
    let file_meta = fs::symlink_metadata(&manifest_path).map_err(|_| "stat manifest failed")?;
    if !file_meta.file_type().is_file() {
        return Err("manifest must be a regular non-symlink file");
    }

    let status = Command::new("/usr/bin/sha256sum")
        .current_dir(work_dir)
        .env_clear()
        .env("PATH", "/usr/bin:/bin")
        .env("LC_ALL", "C")
        .args(["--strict", "--quiet", "-c", "--", manifest_name])
        .status()
        .map_err(|_| "failed spawning sha256sum")?;

    if status.success() {
        Ok(())
    } else {
        Err("sha256sum verification failed")
    }
}
