package journalnft

import (
	"bufio"
	"encoding/json"
	"io"
	"net/netip"
	"strconv"
	"strings"
)

type DropRecord struct {
	Host  string
	DstIP netip.Addr
	DPort uint16
	Proto string
}

type journalEntry struct {
	Hostname string          `json:"_HOSTNAME"`
	Message  json.RawMessage `json:"MESSAGE"`
}

func decodeJournalMsg(raw json.RawMessage) string {
	var s string
	if err := json.Unmarshal(raw, &s); err == nil {
		return s
	}
	var b []byte
	if err := json.Unmarshal(raw, &b); err == nil {
		return string(b)
	}
	return ""
}

func ParseJournalNftDrops(r io.Reader) ([]DropRecord, error) {
	var out []DropRecord
	sc := bufio.NewScanner(r)
	for sc.Scan() {
		var je journalEntry
		if err := json.Unmarshal(sc.Bytes(), &je); err != nil {
			continue
		}
		msg := decodeJournalMsg(je.Message)
		if !strings.Contains(msg, "NFT_EGRESS_DROP:") {
			continue
		}
		var dst netip.Addr
		var dport uint16
		var proto string
		for _, f := range strings.Fields(msg) {
			if v, ok := strings.CutPrefix(f, "DST="); ok {
				dst, _ = netip.ParseAddr(v)
			} else if v, ok := strings.CutPrefix(f, "DPT="); ok {
				if p, err := strconv.ParseUint(v, 10, 16); err == nil {
					dport = uint16(p)
				}
			} else if v, ok := strings.CutPrefix(f, "PROTO="); ok {
				proto = v
			}
		}
		if dst.IsValid() && proto != "" {
			out = append(out, DropRecord{Host: je.Hostname, DstIP: dst, DPort: dport, Proto: proto})
		}
	}
	return out, sc.Err()
}
