import ast

def _is_digest_call(expr: ast.AST) -> bool:
    return (
        isinstance(expr, ast.Call)
        and isinstance(expr.func, ast.Attribute)
        and expr.func.attr in {"digest", "hexdigest"}
        and not expr.args
    )

def audit_non_constant_time_digest_compare(source: str) -> list[tuple[int, str]]:
    tree = ast.parse(source)
    issues: list[tuple[int, str]] = []

    for node in ast.walk(tree):
        if not isinstance(node, ast.Compare):
            continue
        if not any(isinstance(op, (ast.Eq, ast.NotEq)) for op in node.ops):
            continue
        operands = [node.left, *node.comparators]
        if any(_is_digest_call(op) for op in operands):
            issues.append((
                node.lineno,
                "direct ==/!= on digest()/hexdigest(); use hmac.compare_digest",
            ))
    return issues
