package strictmanifest

import (
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"encoding/json"
	"errors"
	"io"
	"os"
	"path/filepath"
	"strings"
	"syscall"
)

type Entry struct {
	Path   string `json:"path"`
	Size   int64  `json:"size"`
	SHA256 string `json:"sha256"`
}

type ManifestDoc struct {
	Version int     `json:"version"`
	Entries []Entry `json:"entries"`
}

func VerifyJSONManifest(rootDir string, r io.Reader, maxEntries int) error {
	dec := json.NewDecoder(io.LimitReader(r, 4<<20))
	dec.DisallowUnknownFields()
	var doc ManifestDoc
	if err := dec.Decode(&doc); err != nil {
		return err
	}
	if doc.Version != 1 || len(doc.Entries) == 0 || len(doc.Entries) > maxEntries {
		return errors.New("invalid manifest version or entry count")
	}
	rootAbs, err := filepath.Abs(rootDir)
	if err != nil {
		return err
	}
	seen := make(map[string]bool, len(doc.Entries))
	for _, e := range doc.Entries {
		if e.Path == "" || e.Size < 0 || strings.HasPrefix(e.Path, "/") || strings.HasPrefix(e.Path, "-") || strings.Contains(e.Path, "..") {
			return errors.New("unsafe manifest entry")
		}
		if seen[e.Path] {
			return errors.New("duplicate entry: " + e.Path)
		}
		seen[e.Path] = true
		want, err := hex.DecodeString(e.SHA256)
		if err != nil || len(want) != sha256.Size {
			return errors.New("invalid sha256 hex")
		}
		full := filepath.Join(rootAbs, e.Path)
		if !strings.HasPrefix(full, rootAbs+string(filepath.Separator)) {
			return errors.New("path escaped root")
		}
		f, err := os.OpenFile(full, os.O_RDONLY|syscall.O_NOFOLLOW, 0)
		if err != nil {
			return err
		}
		st, err := f.Stat()
		if err != nil || !st.Mode().IsRegular() || st.Size() != e.Size {
			f.Close()
			return errors.New("stat/size mismatch")
		}
		h := sha256.New()
		_, copyErr := io.Copy(h, io.LimitReader(f, e.Size+1))
		f.Close()
		if copyErr != nil || subtle.ConstantTimeCompare(h.Sum(nil), want) != 1 {
			return errors.New("digest mismatch")
		}
	}
	return nil
}
