import { createHash, timingSafeEqual } from "node:crypto";
import { execFile } from "node:child_process";
import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { promisify } from "node:util";

const execFileAsync = promisify(execFile);

export async function inspectAndVerifyTarGz(
  archivePath: string,
  expectedDigests: Record<string, string>
): Promise<void> {
  const { stdout } = await execFileAsync("tar", ["-ztvf", "--", archivePath], { maxBuffer: 4 * 1024 * 1024 });
  for (const line of stdout.split("\n")) {
    if (!line.trim()) continue;
    const mode = line[0];
    if (mode !== "-" && mode !== "d") {
      throw new Error(`Disallowed tar entry type (${mode}): ${line}`);
    }
    const fields = line.trim().split(/\s+/);
    const entryName = fields[fields.length - 1];
    if (entryName.startsWith("/") || entryName.startsWith("-") || entryName.includes("..")) {
      throw new Error(`Unsafe tar entry path: ${entryName}`);
    }
  }

  const stageDir = await mkdtemp(path.join(tmpdir(), "tar-safe-"));
  try {
    await execFileAsync("tar", [
      "--no-same-owner",
      "--no-same-permissions",
      "-C",
      stageDir,
      "-xzf",
      "--",
      archivePath,
    ]);
    for (const [rel, hex] of Object.entries(expectedDigests)) {
      const buf = await readFile(path.join(stageDir, rel));
      const actual = createHash("sha256").update(buf).digest();
      const want = Buffer.from(hex, "hex");
      if (want.length !== 32 || !timingSafeEqual(actual, want)) {
        throw new Error(`SHA-256 mismatch for ${rel}`);
      }
    }
  } finally {
    await rm(stageDir, { recursive: true, force: true });
  }
}
