#[derive(Debug, Default, PartialEq, Eq)]
pub struct Sha256LogSummary {
    pub ok_count: usize,
    pub failed_files: Vec<String>,
    pub format_warnings: usize,
}

pub fn summarize_sha256sum_log(log: &str) -> Sha256LogSummary {
    let mut summary = Sha256LogSummary::default();
    for raw_line in log.lines() {
        let clean: String = raw_line.chars().filter(|c| !c.is_control()).collect();
        let trimmed = clean.trim();
        if trimmed.is_empty() {
            continue;
        }
        if trimmed.starts_with("sha256sum: WARNING:") && trimmed.contains("improperly formatted") {
            summary.format_warnings += 1;
            continue;
        }
        if let Some((path, status)) = trimmed.rsplit_once(": ") {
            if path.starts_with("sha256sum:") {
                continue;
            }
            match status {
                "OK" => summary.ok_count += 1,
                "FAILED" | "FAILED open or read" => summary.failed_files.push(path.to_string()),
                _ => {}
            }
        }
    }
    summary
}
