def audit_insecure_temp_usage(source: str) -> list[tuple[int, str]]:
    tree = ast.parse(source)
    findings: list[tuple[int, str]] = []

    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        func = node.func
        if (
            isinstance(func, ast.Attribute)
            and isinstance(func.value, ast.Name)
            and func.value.id == "tempfile"
            and func.attr == "mktemp"
        ):
            findings.append((node.lineno, "tempfile.mktemp() is vulnerable to TOCTOU races; use mkstemp or TemporaryDirectory"))
