```go
package nftrender

import (
	"errors"
	"fmt"
	"net/netip"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

func WriteCanonicalV4Set(destPath, setName string, rawPrefixes []string) error {
	if len(rawPrefixes) == 0 {
		return errors.New("empty prefix list")
	}
	seen := make(map[string]struct{}, len(rawPrefixes))
	for _, raw := range rawPrefixes {
		pfx, err := netip.ParsePrefix(strings.TrimSpace(raw))
		if err != nil || !pfx.Addr().Is4() {
			return fmt.Errorf("invalid ipv4 prefix: %q", raw)
		}
		pfx = pfx.Masked()
		a := pfx.Addr()
		if pfx.Bits() < 8 || a.IsUnspecified() || a.IsLoopback() || a.IsMulticast() {
			return fmt.Errorf("disallowed ipv4 prefix: %s", pfx)
		}
		seen[pfx.String()] = struct{}{}
	}
	items := make([]string, 0, len(seen))
	for s := range seen {
		items = append(items, s)
	}
	sort.Strings(items)
	body := fmt.Sprintf("set %s {\n    type ipv4_addr\n    flags interval\n    elements = { %s }\n}\n", setName, strings.Join(items, ", "))

	f, err := os.CreateTemp(filepath.Dir(destPath), ".nftset-*")
	if err != nil {
		return err
	}
	tmpName := f.Name()
	defer os.Remove(tmpName)
	if _, err := f.WriteString(body); err != nil {
		f.Close()
		return err
	}
	if err := f.Chmod(0o640); err != nil {
		f.Close()
		return err
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	return os.Rename(tmpName, destPath)
}
