use base64::Engine;
use base64::engine::general_purpose::STANDARD;
use sha2::{Digest, Sha256};
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::{Component, Path};
use subtle::ConstantTimeEq;

pub fn verify_sri_entries(root: &Path, items: &[(&str, &str)]) -> Result<(), &'static str> {
    if items.is_empty() {
        return Err("empty sri manifest");
    }
    for &(rel_path, sri) in items {
        let b64 = sri.strip_prefix("sha256-").ok_or("expected sha256- prefix")?;
        let expected = STANDARD.decode(b64).map_err(|_| "invalid base64")?;
        if expected.len() != 32 {
            return Err("invalid sha256 byte length");
        }
        let mut target = root.to_path_buf();
        for comp in Path::new(rel_path).components() {
            match comp {
                Component::Normal(seg) => target.push(seg),
                _ => return Err("path traversal rejected"),
            }
        }
        let mut fh = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|_| "open failed or symlink blocked")?;
        let mut hasher = Sha256::new();
        let mut buf = [0u8; 16384];
        loop {
            let n = fh.read(&mut buf).map_err(|_| "read error")?;
            if n == 0 {
                break;
            }
            hasher.update(&buf[..n]);
        }
        if hasher.finalize().as_slice().ct_eq(expected.as_slice()).unwrap_u8() != 1 {
            return Err("sri sha256 mismatch");
        }
    }
    Ok(())
}
