```typescript
import { createHash, timingSafeEqual } from "node:crypto";
import { constants as fsConst, createReadStream } from "node:fs";
import { open, realpath } from "node:fs/promises";
import path from "node:path";
import readline from "node:readline";
import { Readable } from "node:stream";

const LINE_RE = /^([0-9a-f]{64})  ([^\0\r\n]+)$/i;

export async function verifyLargeSha256Sums(rootDir: string, manifestStream: Readable): Promise<number> {
  const rootReal = await realpath(rootDir);
  const seen = new Set<string>();
  const rl = readline.createInterface({ input: manifestStream, crlfDelay: Infinity });

  for await (const line of rl) {
    if (!line.trim()) continue;
    if (line.length > 512) throw new Error("Manifest line exceeds 512 chars");
    const m = LINE_RE.exec(line);
    if (!m) throw new Error("Malformed SHA256SUMS line");
    const [, hexDig, relPath] = m;
    if (relPath.startsWith("/") || relPath.startsWith("-") || seen.has(relPath)) {
      throw new Error(`Unsafe or duplicate path: ${relPath}`);
    }
    const full = path.resolve(rootReal, relPath);
    const rel = path.relative(rootReal, full);
    if (rel.startsWith("..") || path.isAbsolute(rel)) {
      throw new Error(`Path traversal rejected: ${relPath}`);
    }
    const fh = await open(full, fsConst.O_RDONLY | (fsConst.O_NOFOLLOW ?? 0));
    const hash = createHash("sha256");
    for await (const chunk of createReadStream("", { fd: fh.fd, autoClose: true })) {
      hash.update(chunk as Buffer);
    }
    if (!timingSafeEqual(hash.digest(), Buffer.from(hexDig, "hex"))) {
      throw new Error(`Digest mismatch for ${relPath}`);
    }
    seen.add(relPath);
  }
  if (seen.size === 0) throw new Error("Empty manifest");
  return seen.size;
}
