```rust
use sha2::{Digest, Sha256};
use std::io::Read;
use subtle::ConstantTimeEq;

const CHUNK_CAP: usize = 4096;

pub fn hash_indexed_chunk(index: u64, data: &[u8]) -> [u8; 32] {
    let mut h = Sha256::new();
    h.update([0x00]);
    h.update(index.to_be_bytes());
    h.update((data.len() as u32).to_be_bytes());
    h.update(data);
    h.finalize().into()
}

pub fn verify_indexed_stream<R: Read>(
    mut reader: R,
    expected_chunks: &[[u8; 32]],
) -> Result<(), &'static str> {
    let mut buf = [0u8; CHUNK_CAP];
    for (idx, expected) in expected_chunks.iter().enumerate() {
        let mut filled = 0usize;
        while filled < CHUNK_CAP {
            let n = reader.read(&mut buf[filled..]).map_err(|_| "io read error")?;
            if n == 0 {
                break;
            }
            filled += n;
        }
        if filled == 0 {
            return Err("stream truncated early");
        }
        let actual = hash_indexed_chunk(idx as u64, &buf[..filled]);
        if actual.ct_eq(expected).unwrap_u8() != 1 {
            return Err("indexed chunk digest mismatch");
        }
    }
    let mut extra = [0u8; 1];
    if reader.read(&mut extra).map_err(|_| "io read error")? != 0 {
        return Err("unexpected trailing bytes after final chunk");
    }
    Ok(())
}
```

