```typescript
export interface ShellAuditIssue {
  line: number;
  issue: string;
}

const EXTRACT_RE = /\b(?:tar\s+[^#\n]*(?:-[A-Za-z]*x|--extract)|unzip\b)/;
const MKTEMP_DIR_RE = /\bmktemp\s+[^#\n]*-d\b/;
const SHA256_CHK_RE = /\b(?:sha256sum|shasum)\b[^#\n]*(?:-c|--check)\b/;

export function auditArchiveExtractionScript(script: string): ShellAuditIssue[] {
  const lines = script.split(/\r?\n/);
  const activeLines = lines.map((l) => l.replace(/#.*$/, "").trim());
  const hasMktempDir = activeLines.some((l) => MKTEMP_DIR_RE.test(l));
  const hasSha256Check = activeLines.some((l) => SHA256_CHK_RE.test(l));

  const issues: ShellAuditIssue[] = [];
  activeLines.forEach((clean, i) => {
    if (!EXTRACT_RE.test(clean)) return;
    if (!hasMktempDir) {
      issues.push({ line: i + 1, issue: "archive extracted without allocating a 'mktemp -d' staging directory" });
    }
    if (!hasSha256Check) {
      issues.push({ line: i + 1, issue: "archive extracted without 'sha256sum -c' manifest verification" });
    }
  });
  return issues;
}
