```go
package s3triage

import (
	"compress/gzip"
	"encoding/json"
	"fmt"
	"io"
)

type ctBundle struct {
	Records []struct {
		EventID   string `json:"eventID"`
		EventName string `json:"eventName"`
		ErrorCode string `json:"errorCode"`
	} `json:"Records"`
}

func ExtractPutBucketPolicyIDs(r io.Reader, maxBytes int64) ([]string, error) {
	gz, err := gzip.NewReader(r)
	if err != nil {
		return nil, err
	}
	defer gz.Close()

	limited := io.LimitReader(gz, maxBytes+1)
	raw, err := io.ReadAll(limited)
	if err != nil {
		return nil, err
	}
	if int64(len(raw)) > maxBytes {
		return nil, fmt.Errorf("decompressed cloudtrail payload exceeds %d bytes", maxBytes)
	}
	var b ctBundle
	if err := json.Unmarshal(raw, &b); err != nil {
		return nil, err
	}
	var ids []string
	for _, rec := range b.Records {
		if rec.EventName == "PutBucketPolicy" && rec.ErrorCode == "" {
			ids = append(ids, rec.EventID)
		}
	}
	return ids, nil
}
