import base64
import binascii
from pydantic import SecretBytes, SecretStr, field_validator
from pydantic_settings import BaseSettings, SettingsConfigDict

class RuntimeSecretsConfig(BaseSettings):
    model_config = SettingsConfigDict(
        secrets_dir="/run/secrets",
        env_prefix="APP_",
        extra="forbid",
        frozen=True,
        hide_input_in_errors=True,
    )

    db_dsn: SecretStr
    aead_master_key_b64: SecretBytes

    @field_validator("db_dsn")
    @classmethod
    def _require_tls_dsn(cls, v: SecretStr) -> SecretStr:
        raw = v.get_secret_value()
        if not raw.startswith("postgresql://") or "sslmode=verify-full" not in raw:
            raise ValueError("db_dsn must enforce postgresql:// with sslmode=verify-full")
