    @field_validator("aead_master_key_b64", mode="before")
    @classmethod
    def _decode_exact_32b_key(cls, v: str | bytes) -> bytes:
        txt = v.decode("ascii").strip() if isinstance(v, bytes) else str(v).strip()
        try:
            raw = base64.b64decode(txt, validate=True)
        except binascii.Error as exc:
