package secretmount

import (
	"bytes"
	"errors"
	"io"
	"os"
	"path/filepath"
)

func LoadMountedSecret(dir, name string) ([]byte, error) {
	if filepath.Base(name) != name || name == "." || name == ".." {
		return nil, errors.New("invalid secret filename")
	}
	p := filepath.Join(dir, name)
	lfi, err := os.Lstat(p)
	if err != nil {
		return nil, err
	}
	if lfi.Mode()&os.ModeSymlink != 0 || !lfi.Mode().IsRegular() {
		return nil, errors.New("secret must be a regular non-symlink file")
	}
	if lfi.Mode().Perm()&0o077 != 0 {
		return nil, errors.New("secret file has group or world permissions")
	}
	f, err := os.Open(p)
	if err != nil {
		return nil, err
	}
	defer f.Close()
	raw, err := io.ReadAll(io.LimitReader(f, 4097))
	if err != nil || len(raw) > 4096 {
		return nil, errors.New("secret read error or exceeds 4096 bytes")
	}
	trimmed := bytes.TrimRight(raw, "\r\n")
	if len(trimmed) < 16 {
		return nil, errors.New("secret shorter than 16 bytes")
	}
	return trimmed, nil
}
