```rust
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::{MetadataExt, OpenOptionsExt};
use std::path::Path;
use zeroize::Zeroizing;

pub fn read_strict_secret_file(path: &Path) -> Result<Zeroizing<Vec<u8>>, &'static str> {
    let mut file = OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_NOFOLLOW)
        .open(path)
        .map_err(|_| "failed to open secret file without following symlinks")?;

    let meta = file.metadata().map_err(|_| "metadata stat failed")?;
    if !meta.is_file() || (meta.mode() & 0o077) != 0 {
        return Err("secret file must be regular with 0600/0400 permissions");
    }
    if meta.len() < 16 || meta.len() > 4096 {
        return Err("secret file size out of [16, 4096] byte bounds");
    }
    let mut buf = Zeroizing::new(Vec::with_capacity(meta.len() as usize));
    file.read_to_end(&mut buf).map_err(|_| "failed reading secret")?;
    while buf.last().copied() == Some(b'\n') || buf.last().copied() == Some(b'\r') {
        buf.pop();
    }
    if buf.len() < 16 {
        return Err("trimmed secret shorter than 16 bytes");
    }
    Ok(buf)
}
