import re
import time
from typing import Dict, Set, Tuple

MAX_AGE_RE = re.compile(r"\bmax-age=(\d+)\b", re.IGNORECASE)

def parse_clamped_ttl(cache_control: str, min_s: int = 60, max_s: int = 86400, default_s: int = 600) -> int:
    if "no-store" in cache_control.lower():
        return min_s
    m = MAX_AGE_RE.search(cache_control)
    if not m:
        return default_s
    return max(min_s, min(max_s, int(m.group(1))))

class TombstoneJwksStore:
    def __init__(self) -> None:
        self.keys: Dict[str, Tuple[dict, float]] = {}
        self.revoked_kids: Set[str] = set()

    def revoke_kid(self, kid: str) -> None:
        self.revoked_kids.add(kid)
        self.keys.pop(kid, None)

    def lookup(self, kid: str, stale_grace_s: float = 300.0) -> dict:
        if kid in self.revoked_kids:
            raise PermissionError("revoked kid tombstone matched")
        entry = self.keys.get(kid)
        if not entry:
            raise KeyError("kid not cached")
        jwk, exp = entry
        if time.monotonic() > exp + stale_grace_s:
            raise KeyError("cached kid expired past stale grace")
        return jwk
