package jwks

import (
	"errors"
	"io"
	"net/http"
)

const maxJWKSBytes = 64 * 1024

func FetchConditionalJWKS(client *http.Client, uri, prevETag string) ([]byte, string, bool, error) {
	req, err := http.NewRequest(http.MethodGet, uri, nil)
	if err != nil {
		return nil, "", false, err
	}
	if prevETag != "" {
		req.Header.Set("If-None-Match", prevETag)
	}
	resp, err := client.Do(req)
	if err != nil {
		return nil, "", false, err
	}
	defer resp.Body.Close()
	if resp.StatusCode == http.StatusNotModified {
		return nil, prevETag, true, nil
	}
	if resp.StatusCode != http.StatusOK {
		return nil, "", false, errors.New("unexpected jwks status")
	}
	body, err := io.ReadAll(io.LimitReader(resp.Body, maxJWKSBytes+1))
	if err != nil || len(body) > maxJWKSBytes {
		return nil, "", false, errors.New("jwks payload exceeded 64KiB limit")
	}
	return body, resp.Header.Get("ETag"), false, nil
}
