use std::collections::{HashMap, HashSet};
use std::time::{Duration, Instant};

pub struct RotationDiff {
    pub active: HashMap<String, Vec<u8>>,
    pub retiring: HashMap<String, (Vec<u8>, Instant)>,
}

pub fn apply_jwks_rotation(
    old_active: HashMap<String, Vec<u8>>,
    fresh: HashMap<String, Vec<u8>>,
    revoked_kids: &HashSet<String>,
    grace: Duration,
) -> RotationDiff {
    let mut retiring = HashMap::new();
    let deadline = Instant::now() + grace;
    for (kid, key) in old_active {
        if !fresh.contains_key(&kid) && !revoked_kids.contains(&kid) {
            retiring.insert(kid, (key, deadline));
        }
    }
    let active = fresh
        .into_iter()
        .filter(|(kid, _)| !revoked_kids.contains(kid))
        .collect();
    RotationDiff { active, retiring }
}
