```typescript
export class EmergencyRevocableJwks {
  private keys = new Map<string, CryptoKey>();
  private denylistedKids = new Set<string>();
  private expiresAtMs = 0;

  revokeKidImmediately(kid: string): void {
    this.denylistedKids.add(kid);
    this.keys.delete(kid);
  }

  ingestKeyset(incoming: ReadonlyMap<string, CryptoKey>, cacheControlHeader = ""): void {
    const match = /max-age=(\d+)/i.exec(cacheControlHeader);
    const rawSec = match ? Number.parseInt(match[1], 10) : 600;
    const clampedSec = Math.min(86_400, Math.max(60, rawSec));
    const next = new Map<string, CryptoKey>();
    for (const [kid, key] of incoming) {
      if (!this.denylistedKids.has(kid)) next.set(kid, key);
    }
    this.keys = next;
    this.expiresAtMs = Date.now() + clampedSec * 1000;
  }

  resolve(kid: string): CryptoKey {
    if (this.denylistedKids.has(kid)) throw new Error("kid emergency-revoked");
    if (Date.now() > this.expiresAtMs) throw new Error("jwks cache expired");
    const key = this.keys.get(kid);
    if (!key) throw new Error("unknown kid");
    return key;
  }
}
