```typescript
const ASCII_DOMAIN_RE = /^[a-zA-Z0-9.-]{1,253}$/;

export function parseSocks5Address(
  buf: Uint8Array,
  offset = 0,
): { host: string; port: number; bytesRead: number } {
  if (offset >= buf.byteLength) {
    throw new RangeError("empty SOCKS5 address slice");
  }
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const atyp = buf[offset];
  let host: string;
  let portPos: number;

  if (atyp === 0x01) {
    if (buf.byteLength - offset < 7) throw new RangeError("short IPv4 SOCKS5 address");
    host = `${buf[offset + 1]}.${buf[offset + 2]}.${buf[offset + 3]}.${buf[offset + 4]}`;
    portPos = offset + 5;
  } else if (atyp === 0x03) {
    if (buf.byteLength - offset < 4) throw new RangeError("short domain SOCKS5 header");
    const dlen = buf[offset + 1];
    if (dlen === 0 || buf.byteLength - offset < 2 + dlen + 2) {
      throw new RangeError("truncated SOCKS5 domain");
    }
    host = new TextDecoder("utf-8", { fatal: true }).decode(buf.subarray(offset + 2, offset + 2 + dlen));
    if (!ASCII_DOMAIN_RE.test(host)) throw new Error("invalid SOCKS5 domain bytes");
    portPos = offset + 2 + dlen;
  } else if (atyp === 0x04) {
    if (buf.byteLength - offset < 19) throw new RangeError("short IPv6 SOCKS5 address");
    const parts: string[] = [];
    for (let i = offset + 1; i < offset + 17; i += 2) {
      parts.push(view.getUint16(i, false).toString(16));
    }
    host = parts.join(":");
    portPos = offset + 17;
  } else {
    throw new Error(`unsupported SOCKS5 ATYP: ${atyp}`);
  }
  const port = view.getUint16(portPos, false);
  if (port === 0) throw new Error("SOCKS5 port 0 rejected");
  return { host, port, bytesRead: portPos + 2 - offset };
}
