use std::io::{self, Read};

pub fn verify_ed25519ph_stream<R: Read>(
    pubkey: &[u8; 32],
    sig_bytes: &[u8; 64],
    reader: R,
    max_bytes: u64,
) -> Result<(), &'static str> {
