```typescript
import { ed25519ph } from "@noble/curves/ed25519";
import { createHash } from "node:crypto";
import { Readable } from "node:stream";

export async function verifyStreamEd25519ph(
  src: Readable,
  pubKey32: Uint8Array,
  sig64: Uint8Array,
  contextUtf8: string,
  maxBytes: number,
): Promise<boolean> {
  const h = createHash("sha512");
  let seen = 0;
  for await (const chunk of src) {
    const buf = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
    seen += buf.byteLength;
    if (seen > maxBytes) {
      src.destroy();
      throw new RangeError("Artifact exceeded maxBytes");
    }
    h.update(buf);
  }
  const digest = h.digest();
  const ctx = Buffer.from(contextUtf8, "utf8");
  return ed25519ph.verify(sig64, digest, pubKey32, { context: ctx, prehash: false });
}
