import ipaddress
import json
from typing import Iterable

def privileged_pod_creator_cidrs(lines: Iterable[str]) -> list[str]:
    v4, v6 = [], []
    for raw in lines:
        ev = json.loads(raw)
        obj = ev.get("objectRef") or {}
        if obj.get("resource") != "pods" or ev.get("verb") != "create":
            continue
        spec = ((ev.get("requestObject") or {}).get("spec")) or {}
        host_ns = bool(spec.get("hostNetwork") or spec.get("hostPID") or spec.get("hostIPC"))
        priv_ctr = any(
            ((c.get("securityContext") or {}).get("privileged") is True)
            for c in (spec.get("containers") or []) + (spec.get("initContainers") or [])
        )
        if not (host_ns or priv_ctr):
            continue
        for s in ev.get("sourceIPs") or []:
            try:
                ip = ipaddress.ip_address(s)
            except ValueError:
                continue
            if ip.version == 4:
                v4.append(ipaddress.ip_network(f"{ip}/32"))
            else:
                v6.append(ipaddress.ip_network(f"{ip}/128"))
    out = [str(n) for n in ipaddress.collapse_addresses(v4)]
    out.extend(str(n) for n in ipaddress.collapse_addresses(v6))
    return out
