use crc32fast::hash as crc32;
use sqlx::PgPool;
use uuid::Uuid;

const CASE_SEAL_CLASS: i32 = 0x4643_534c; // "FCSL"

pub async fn seal_forensic_case(
    pool: &PgPool,
    case_id: Uuid,
    lead_investigator: &str,
) -> Result<(), String> {
    let mut tx = pool.begin().await.map_err(|e| e.to_string())?;
    let obj_id = crc32(case_id.as_bytes()) as i32;

    sqlx::query("SELECT pg_advisory_xact_lock($1, $2)")
        .bind(CASE_SEAL_CLASS)
        .bind(obj_id)
        .execute(&mut *tx)
        .await
        .map_err(|e| e.to_string())?;

    sqlx::query("SELECT set_config('app.lead_investigator', $1, true)")
        .bind(lead_investigator)
        .execute(&mut *tx)
        .await
        .map_err(|e| e.to_string())?;

    let checked_out: i64 = sqlx::query_scalar(
        "SELECT count(*) FROM forensics.case_artifacts WHERE case_id = $1 AND external_checkout = true",
    )
    .bind(case_id)
    .fetch_one(&mut *tx)
    .await
    .map_err(|e| e.to_string())?;

    if checked_out > 0 {
        tx.rollback().await.map_err(|e| e.to_string())?;
        return Err("cannot seal case while artifacts remain checked out externally".into());
    }

    sqlx::query("UPDATE forensics.cases SET is_sealed = true, sealed_at = clock_timestamp() WHERE case_id = $1")
        .bind(case_id)
        .execute(&mut *tx)
        .await
        .map_err(|e| e.to_string())?;

    tx.commit().await.map_err(|e| e.to_string())?;
    Ok(())
}
