def summarize_pgaudit_view_reads(csv_path: Path) -> dict[str, list[str]]:
    relations_by_user: dict[str, set[str]] = defaultdict(set)
    with csv_path.open("r", encoding="utf-8", errors="replace", newline="") as fh:
        for row in csv.reader(fh):
            if len(row) < 14:
                continue
            db_user = row[1]
            message = row[13]
            if db_user not in LOW_PRIV_USERS or "AUDIT: " not in message:
                continue
            audit_tail = message.split("AUDIT: ", 1)[1]
            parsed = next(csv.reader([audit_tail]), [])
            if len(parsed) >= 7 and parsed[3].upper() == "READ":
                object_type = parsed[5].upper()
                object_name = parsed[6]
                if object_type in {"TABLE", "VIEW"}:
                    relations_by_user[db_user].add(f"{object_type}:{object_name}")

    return {u: sorted(rels) for u, rels in sorted(relations_by_user.items())}
