import sqlglot
from sqlglot import exp

def find_unsafe_postgres_views(ddl_sql: str) -> list[str]:
    statements = sqlglot.parse(ddl_sql, read="postgres")
    unsafe_views: list[str] = []

    for stmt in statements:
        if not isinstance(stmt, exp.Create):
            continue
        if (stmt.args.get("kind") or "").upper() != "VIEW":
            continue

        view_name = stmt.this.sql(dialect="postgres")
        props = stmt.args.get("properties")
        props_sql = props.sql(dialect="postgres").lower() if props else ""

        has_invoker = any(
            token in props_sql.replace(" ", "")
            for token in ("security_invoker=true", "security_invoker=on", "security_invoker=1")
        )
        if not has_invoker:
            unsafe_views.append(view_name)

    return unsafe_views
