func decodeExact(raw []byte, dst any) error {
	dec := json.NewDecoder(bytes.NewReader(raw))
	dec.DisallowUnknownFields()
	if err := dec.Decode(dst); err != nil {
		return err
	}
	if dec.More() {
		return errors.New("trailing JSON tokens")
	}
	return nil
}

func DecodeStrictCommand(raw []byte) (any, error) {
	if len(raw) == 0 || len(raw) > 16384 {
		return nil, errors.New("command payload outside [1, 16384] byte limit")
	}
	var env envelope
	if err := json.Unmarshal(raw, &env); err != nil {
		return nil, err
	}
	switch env.Type {
	case "key.rotate":
		var cmd KeyRotateCmd
		return &cmd, decodeExact(raw, &cmd)
	case "key.revoke":
		var cmd KeyRevokeCmd
		return &cmd, decodeExact(raw, &cmd)
	default:
		return nil, errors.New("unknown command discriminator")
	}
}
