import struct
import time

class StatelessDPoPNonce:
    def __init__(self, secret: bytes, step_s: int = 60) -> None:
        if len(secret) < 32:
            raise ValueError("secret too short")
        self.secret = secret
        self.step_s = step_s

    def _nonce_for_epoch(self, epoch: int, client_hint: str) -> str:
        msg = struct.pack(">Q", epoch) + b":" + client_hint.encode("utf-8")
        mac = hmac.new(self.secret, msg, hashlib.sha256).digest()[:18]
        raw = struct.pack(">Q", epoch) + mac
        return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")

    def issue(self, client_hint: str = "") -> str:
        return self._nonce_for_epoch(int(time.time()) // self.step_s, client_hint)

    def verify(self, candidate: str, client_hint: str = "") -> bool:
        cur = int(time.time()) // self.step_s
        for ep in (cur, cur - 1):
            expected = self._nonce_for_epoch(ep, client_hint)
            if hmac.compare_digest(candidate.encode("ascii"), expected.encode("ascii")):
                return True
        return False
