```typescript
import { createHmac, timingSafeEqual } from "node:crypto";

export class DualSlotDPoPNonce {
  constructor(
    private readonly secret: Buffer,
    private readonly bucketSec = 60,
  ) {}

  private makeForSlot(slot: number, jkt: string): string {
    return createHmac("sha256", this.secret)
      .update(`${slot}:${jkt}`, "utf8")
      .digest("base64url");
  }

  issue(jkt: string, nowMs = Date.now()): string {
    const slot = Math.floor(nowMs / 1000 / this.bucketSec);
    return this.makeForSlot(slot, jkt);
  }

  verify(nonce: string | undefined, jkt: string, nowMs = Date.now()): boolean {
    if (!nonce || nonce.length !== 43) return false;
    const curSlot = Math.floor(nowMs / 1000 / this.bucketSec);
    const candBuf = Buffer.from(nonce, "ascii");
    for (const s of [curSlot, curSlot - 1]) {
      const expBuf = Buffer.from(this.makeForSlot(s, jkt), "ascii");
      if (candBuf.length === expBuf.length && timingSafeEqual(candBuf, expBuf)) {
        return true;
      }
    }
    return false;
  }
}
