		line := strings.TrimSpace(raw)
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		fields := strings.Fields(line)
		instr := strings.ToUpper(fields[0])
		if instr == "HEALTHCHECK" && len(fields) >= 2 && strings.EqualFold(fields[1], "NONE") {
			issues = append(issues, fmt.Sprintf("line %d: HEALTHCHECK NONE disables container health monitoring", idx+1))
		} else if instr == "EXPOSE" {
			for _, tok := range fields[1:] {
				port := strings.Split(tok, "/")[0]
				if desc, bad := bannedDebugPorts[port]; bad {
					issues = append(issues, fmt.Sprintf("line %d: EXPOSE %s opens %s port", idx+1, tok, desc))
				}
			}
		}
	}
	return issues
