import re
import yaml

DISPATCH_INPUT_RE = re.compile(r"\$\{\{\s*(?:github\.event\.)?inputs\.([a-zA-Z0-9_-]+)\s*\}\}")

def lint_workflow_dispatch_inputs(yaml_src: str) -> list[tuple[int, str]]:
    parsed = yaml.safe_load(yaml_src) or {}
    on_block = parsed.get("on", parsed.get(True)) or {}
    wd = on_block.get("workflow_dispatch") if isinstance(on_block, dict) else None
    if not isinstance(wd, dict):
        return []

    unsafe_inputs: set[str] = set()
    for name, spec in (wd.get("inputs") or {}).items():
        inp_type = (spec or {}).get("type", "string") if isinstance(spec, dict) else "string"
        if inp_type not in {"boolean", "choice", "environment"}:
            unsafe_inputs.add(name)

    root = yaml.compose(yaml_src, Loader=yaml.SafeLoader)
    findings: list[tuple[int, str]] = []

    def walk(node: yaml.Node) -> None:
        if isinstance(node, yaml.MappingNode):
            for k, v in node.value:
                if isinstance(k, yaml.ScalarNode) and k.value == "run" and isinstance(v, yaml.ScalarNode):
                    for m in DISPATCH_INPUT_RE.finditer(v.value):
                        if m.group(1) in unsafe_inputs:
                            findings.append(
                                (v.start_mark.line + 1, f"free-form dispatch input '{m.group(1)}' interpolated directly into run")
                            )
                else:
                    walk(v)
        elif isinstance(node, yaml.SequenceNode):
            for c in node.value:
                walk(c)

    if root is not None and unsafe_inputs:
        walk(root)
    return findings
