	if privD == nil || privD.Sign() <= 0 || privD.Cmp(n) >= 0 || len(digest48) != 48 {
		return nil, errors.New("invalid P-384 private scalar or SHA-384 digest")
	}

	xOct := privD.FillBytes(make([]byte, 48))
	h1 := new(big.Int).SetBytes(digest48)
	h1.Mod(h1, n)
	h1Oct := h1.FillBytes(make([]byte, 48))

	hedge := make([]byte, 48)
	if _, err := rand.Read(hedge); err != nil {
		return nil, err
