	k := make([]byte, 48)
	v := make([]byte, 48)
	for i := range v {
		v[i] = 0x01
	}

	k = hmac384(k, v, []byte{0x00}, xOct, h1Oct, hedge)
	v = hmac384(k, v)
	k = hmac384(k, v, []byte{0x01}, xOct, h1Oct, hedge)
	v = hmac384(k, v)

	for {
		v = hmac384(k, v)
		cand := new(big.Int).SetBytes(v)
		if cand.Sign() > 0 && cand.Cmp(n) < 0 {
