import { createHash, timingSafeEqual } from "node:crypto";

function hashInterior(left: Buffer, right: Buffer): Buffer {
  return createHash("sha256").update(Buffer.from([0x01])).update(left).update(right).digest();
}

function isPowerOfTwo(x: bigint): boolean {
  return x > 0n && (x & (x - 1n)) === 0n;
}

export function verifyConsistencyRfc9162(
  first: bigint,
  second: bigint,
  proof: Buffer[],
  firstRoot: Buffer,
  secondRoot: Buffer
): boolean {
  if (first <= 0n || first > second || firstRoot.length !== 32 || secondRoot.length !== 32) {
    return false;
  }
  if (first === second) {
    return proof.length === 0 && timingSafeEqual(firstRoot, secondRoot);
  }
  if (proof.length === 0 || proof.some((n) => n.length !== 32)) {
    return false;
  }

  let fn = first - 1n;
  let sn = second - 1n;
  while ((fn & 1n) === 1n) {
    fn >>= 1n;
    sn >>= 1n;
  }

  let fr: Buffer;
  let sr: Buffer;
  let idx: number;
  if (isPowerOfTwo(first)) {
    fr = firstRoot;
    sr = firstRoot;
    idx = 0;
  } else {
    fr = proof[0];
    sr = proof[0];
    idx = 1;
  }

  for (; idx < proof.length; idx++) {
    const c = proof[idx];
    if (sn === 0n) return false;
    if ((fn & 1n) === 1n || fn === sn) {
      fr = hashInterior(c, fr);
      sr = hashInterior(c, sr);
      while ((fn & 1n) === 0n && fn !== 0n) {
        fn >>= 1n;
        sn >>= 1n;
      }
    } else {
      sr = hashInterior(sr, c);
    }
    fn >>= 1n;
    sn >>= 1n;
  }

  return sn === 0n && timingSafeEqual(fr, firstRoot) && timingSafeEqual(sr, secondRoot);
}
