		}
		allShort := true
		for _, ttl := range rec.TTLs {
			if ttl > 5.0 {
				allShort = false
				break
			}
		}
		if allShort && rec.Query != "" {
			seen[rec.Query] = struct{}{}
		}
	}
	out := make([]string, 0, len(seen))
	for q := range seen {
		out = append(out, q)
	}
	return out, sc.Err()
}
