pub fn long_dns_query_pairs<R: BufRead>(reader: R, min_len: usize) -> Vec<(String, String)> {
    let mut pairs = BTreeSet::new();
    for line in reader.lines().map_while(Result::ok) {
        let Ok(rec) = serde_json::from_str::<DnsLog>(&line) else {
            continue;
        };
        let Some(q) = rec.query else {
            continue;
        };
        let trimmed = q.trim_end_matches('.').to_ascii_lowercase();
        if trimmed.len() < min_len {
            continue;
        }
        let parts: Vec<&str> = trimmed.split('.').collect();
        if parts.len() >= 2 {
            let base = format!("{}.{}", parts[parts.len() - 2], parts[parts.len() - 1]);
            pairs.insert((rec.orig_h, base));
        }
    }
    pairs.into_iter().collect()
}
