       ORDER BY ${DRAWDOWN_SORT_SQL[sortBy]} ${dir}, "drawdown_id" DESC
       LIMIT $2`,
      [contractId, safeLimit]
    );
    await client.query("COMMIT");
    return res.rows;
  } catch (err) {
