CREATE SCHEMA IF NOT EXISTS billing;

CREATE TABLE billing.invoice_mutation_audit (
    audit_id      BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    tenant_id     UUID NOT NULL,
    invoice_id    UUID NOT NULL,
    billing_actor TEXT NOT NULL DEFAULT COALESCE(current_setting('app.billing_actor', true), session_user),
    old_status    TEXT,
    new_status    TEXT NOT NULL,
    changed_at    TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp()
);

CREATE OR REPLACE FUNCTION billing.deny_invoice_audit_tamper()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION 'billing.invoice_mutation_audit is append-only (% blocked)', TG_OP
        USING ERRCODE = 'insufficient_privilege';
END;
$$;

CREATE TRIGGER trg_invoice_audit_no_mod
    BEFORE UPDATE OR DELETE ON billing.invoice_mutation_audit
    FOR EACH ROW EXECUTE FUNCTION billing.deny_invoice_audit_tamper();

CREATE TRIGGER trg_invoice_audit_no_trunc
    BEFORE TRUNCATE ON billing.invoice_mutation_audit
    FOR EACH STATEMENT EXECUTE FUNCTION billing.deny_invoice_audit_tamper();

CREATE OR REPLACE FUNCTION billing.guard_and_audit_invoices()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog
AS $$
BEGIN
    IF TG_OP = 'DELETE' AND OLD.status <> 'DRAFT' THEN
        RAISE EXCEPTION 'Cannot delete non-draft invoice %', OLD.invoice_id
            USING ERRCODE = 'integrity_constraint_violation';
    END IF;

    IF TG_OP = 'UPDATE' AND OLD.status = 'FINALIZED' THEN
        IF NEW.total_cents <> OLD.total_cents OR NEW.invoice_number IS DISTINCT FROM OLD.invoice_number THEN
            RAISE EXCEPTION 'Finalized invoice % amounts and number are immutable', OLD.invoice_id
                USING ERRCODE = 'integrity_constraint_violation';
        END IF;
    END IF;

    IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status) THEN
        INSERT INTO billing.invoice_mutation_audit (tenant_id, invoice_id, old_status, new_status)
        VALUES (NEW.tenant_id, NEW.invoice_id, CASE WHEN TG_OP = 'UPDATE' THEN OLD.status ELSE NULL END, NEW.status);
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;

CREATE VIEW billing.v_tenant_invoices
WITH (security_invoker = true) AS
SELECT invoice_id, tenant_id, invoice_number, status, total_cents, period_end, due_at
FROM billing.invoices;
