```python
import ast

def _has_tx_context(func_node: ast.FunctionDef | ast.AsyncFunctionDef) -> bool:
    arg_names = {a.arg.lower() for a in func_node.args.args}
    if arg_names & {"tx", "trx", "txn"}:
        return True
    for child in ast.walk(func_node):
        if isinstance(child, (ast.With, ast.AsyncWith)):
            for item in child.items:
                expr = item.context_expr
                if isinstance(expr, ast.Call) and isinstance(expr.func, ast.Attribute):
                    if expr.func.attr in {"transaction", "begin", "begin_nested"}:
                        return True
    return False

def find_autocommit_advisory_xact_locks(py_source: str) -> list[tuple[int, str]]:
    tree = ast.parse(py_source)
    issues: list[tuple[int, str]] = []
    for node in ast.walk(tree):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        uses_xact_lock = any(
            isinstance(c, ast.Constant)
            and isinstance(c.value, str)
            and "pg_advisory_xact_lock" in c.value.lower()
            for c in ast.walk(node)
        )
        if uses_xact_lock and not _has_tx_context(node):
            issues.append((node.lineno, node.name))
    return issues
```

