const MAX_TTL_MS = 90 * 24 * 60 * 60 * 1000;

export function createBoundedExpirySchema(nowMs: number = Date.now()) {
  return z
    .string()
    .max(64)
    .datetime({ offset: true })
    .transform((iso, ctx) => {
      const ms = Date.parse(iso);
      if (Number.isNaN(ms) || ms <= nowMs) {
        ctx.addIssue({ code: z.ZodIssueCode.custom, message: "Expiry must be in the future" });
