package safetar

import (
	"archive/tar"
	"errors"
	"io"
	"os"
	"path/filepath"
	"strings"
)

func ExtractTarConfined(r io.Reader, destDir string, maxFiles int, maxTotalBytes int64) error {
	root, err := os.OpenRoot(destDir)
	if err != nil {
		return err
	}
	defer root.Close()

	tr := tar.NewReader(r)
	var filesSeen int
	var totalBytes int64

	for {
		hdr, err := tr.Next()
		if errors.Is(err, io.EOF) {
			return nil
		}
		if err != nil {
			return err
		}
		filesSeen++
		if filesSeen > maxFiles {
			return errors.New("tar archive exceeds maxFiles quota")
		}
		cleanRel := filepath.Clean(hdr.Name)
		if strings.HasPrefix(cleanRel, "/") || cleanRel == ".." || strings.HasPrefix(cleanRel, "../") {
			return errors.New("tar entry path traversal rejected")
		}
		switch hdr.Typeflag {
		case tar.TypeDir:
			if cleanRel != "." {
				if err := root.Mkdir(cleanRel, 0o750); err != nil && !errors.Is(err, os.ErrExist) {
					return err
				}
			}
		case tar.TypeReg:
			rem := (maxTotalBytes - totalBytes) + 1
			f, err := root.OpenFile(cleanRel, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
			if err != nil {
				return err
			}
			n, copyErr := io.Copy(f, io.LimitReader(tr, rem))
			closeErr := f.Close()
			totalBytes += n
			if copyErr != nil {
				return copyErr
			}
			if closeErr != nil {
				return closeErr
			}
			if totalBytes > maxTotalBytes {
				return errors.New("tar archive exceeded maxTotalBytes")
			}
		default:
			return errors.New("disallowed tar entry type (symlink/hardlink/device)")
		}
	}
}
