use cap_std::fs::{Dir, OpenOptions};
use std::io::{self, Read};
use std::path::Component;
use tar::{Archive, EntryType};

pub fn unpack_tar_into_cap_dir<R: Read>(
    reader: R,
    root: &Dir,
    max_files: usize,
    max_bytes: u64,
) -> io::Result<u64> {
    let mut archive = Archive::new(reader);
    let mut total_bytes = 0u64;

    for (idx, entry_res) in archive.entries()?.enumerate() {
        if idx >= max_files {
            return Err(io::Error::new(io::ErrorKind::InvalidData, "max_files exceeded"));
        }
        let entry = entry_res?;
        let path = entry.path()?.into_owned();
        if path.components().any(|c| !matches!(c, Component::Normal(_))) {
            return Err(io::Error::new(io::ErrorKind::PermissionDenied, "unsafe tar path"));
        }
        match entry.header().entry_type() {
            EntryType::Directory => root.create_dir_all(&path)?,
            EntryType::Regular => {
                if let Some(parent) = path.parent() {
                    if !parent.as_os_str().is_empty() {
                        root.create_dir_all(parent)?;
                    }
                }
                let mut opts = OpenOptions::new();
                opts.write(true).create_new(true);
                let mut dst = root.open_with(&path, &opts)?;
                let rem = (max_bytes - total_bytes) + 1;
                let n = io::copy(&mut entry.take(rem), &mut dst)?;
                total_bytes += n;
                if total_bytes > max_bytes {
                    return Err(io::Error::new(io::ErrorKind::FileTooLarge, "max_bytes exceeded"));
                }
            }
            _ => return Err(io::Error::new(io::ErrorKind::PermissionDenied, "links/devices disallowed")),
        }
    }
    Ok(total_bytes)
}
