```typescript
import path from "node:path";

const S_IFMT = 0o170000;
const S_IFLNK = 0o120000;

export interface ZipEntryMeta {
  fileName: string;
  uncompressedSize: number;
  externalFileAttributes: number;
}

export function validateArchiveEntries(
  rootDir: string,
  entries: readonly ZipEntryMeta[],
  maxEntries: number,
  maxTotalBytes: number,
): string[] {
  if (entries.length > maxEntries) {
    throw new RangeError("Archive exceeds maxEntries quota");
  }
  const resolvedRoot = path.resolve(rootDir);
  let total = 0;
  const safeTargets: string[] = [];

  for (const e of entries) {
    const unixMode = (e.externalFileAttributes >>> 16) & S_IFMT;
    if (unixMode === S_IFLNK) {
      throw new Error(`Symlink entry disallowed: ${e.fileName}`);
    }
    if (e.fileName.includes("\\") || e.fileName.includes("\0") || path.isAbsolute(e.fileName)) {
      throw new Error(`Unsafe archive entry path: ${e.fileName}`);
    }
    const target = path.resolve(resolvedRoot, e.fileName);
    if (!target.startsWith(resolvedRoot + path.sep)) {
      throw new Error(`Zip-Slip traversal blocked: ${e.fileName}`);
    }
    total += e.uncompressedSize;
    if (total > maxTotalBytes || e.uncompressedSize < 0) {
      throw new RangeError("Archive exceeds maxTotalBytes quota");
    }
    safeTargets.push(target);
  }
  return safeTargets;
}
