import hashlib
import struct

def compute_archive_merkle_root(entries: list[tuple[str, bytes]]) -> bytes:
    if not entries:
        return hashlib.sha256(b"\x00").digest()
    leaves = []
    for rel_path, file_sha256 in sorted(entries, key=lambda x: x[0]):
        if len(file_sha256) != 32:
            raise ValueError("each file_sha256 must be 32 bytes")
        p_bytes = rel_path.encode("utf-8")
        leaf_data = b"\x00" + struct.pack(">I", len(p_bytes)) + p_bytes + file_sha256
        leaves.append(hashlib.sha256(leaf_data).digest())

    level = leaves
    while len(level) > 1:
        nxt = []
        for i in range(0, len(level), 2):
            if i + 1 < len(level):
                nxt.append(hashlib.sha256(b"\x01" + level[i] + level[i + 1]).digest())
            else:
                nxt.append(level[i])
        level = nxt
    return level[0]
