def multi_category_alert_hosts(
    lines: Iterable[str], min_categories: int = 3
) -> dict[str, dict]:
    cats: dict[str, set[str]] = defaultdict(set)
    stamps: dict[str, list[float]] = defaultdict(list)
    for raw in lines:
        ev = json.loads(raw)
        if ev.get("event_type") != "alert" or not ev.get("timestamp"):
            continue
        cat = str((ev.get("alert") or {}).get("category") or "uncategorized")
        ts = datetime.fromisoformat(ev["timestamp"].replace("Z", "+00:00")).timestamp()
        for field in ("src_ip", "dest_ip"):
            try:
                ip = ipaddress.ip_address(ev.get(field, ""))
            except ValueError:
                continue
            if ip.is_private:
                key = str(ip)
                cats[key].add(cat)
                stamps[key].append(ts)
    out: dict[str, dict] = {}
    for host, cset in cats.items():
        if len(cset) < min_categories:
            continue
        ts_list = sorted(stamps[host])
        deltas = [b - a for a, b in zip(ts_list, ts_list[1:])]
        jitter = round(statistics.pstdev(deltas), 4) if len(deltas) >= 2 else 0.0
        out[host] = {"categories": sorted(cset), "alerts": len(ts_list), "pstdev_sec": jitter}
