```go
package alertdedup

import (
	"bufio"
	"encoding/json"
	"io"
	"time"
)

type eveAlert struct {
	Timestamp string `json:"timestamp"`
	EventType string `json:"event_type"`
	SrcIP     string `json:"src_ip"`
	DestIP    string `json:"dest_ip"`
	Alert     struct {
		SignatureID uint64 `json:"signature_id"`
	} `json:"alert"`
}

type dedupKey struct {
	src, dst string
	sid      uint64
}

func DeduplicateAlerts(r io.Reader, cooldownSec int64) (int, error) {
	sc := bufio.NewScanner(r)
	sc.Buffer(make([]byte, 64*1024), 1024*1024)
	lastSeen := make(map[dedupKey]int64)
	kept := 0
	for sc.Scan() {
		var ev eveAlert
		if err := json.Unmarshal(sc.Bytes(), &ev); err != nil || ev.EventType != "alert" {
			continue
		}
		t, err := time.Parse("2006-01-02T15:04:05.999999999-0700", ev.Timestamp)
		if err != nil {
			t, err = time.Parse(time.RFC3339Nano, ev.Timestamp)
			if err != nil {
				continue
			}
		}
		sec := t.Unix()
		k := dedupKey{src: ev.SrcIP, dst: ev.DestIP, sid: ev.Alert.SignatureID}
		if prev, ok := lastSeen[k]; !ok || sec-prev >= cooldownSec {
			lastSeen[k] = sec
			kept++
		}
	}
	return kept, sc.Err()
}
