import * as readline from "node:readline";
import { Readable } from "node:stream";

interface EveCorrelated {
  event_type?: string;
  community_id?: string;
  dns?: { type?: string; rrname?: string };
  alert?: { signature_id?: number; signature?: string };
}

export async function correlateAlertWithDns(
  input: Readable
): Promise<Array<{ communityId: string; sid: number; rrname: string }>> {
  const dnsByCid = new Map<string, string>();
  const alerts: Array<{ cid: string; sid: number }> = [];
  const rl = readline.createInterface({ input, crlfDelay: Infinity });
  for await (const line of rl) {
    if (!line.trim()) continue;
    const ev = JSON.parse(line) as EveCorrelated;
    if (!ev.community_id) continue;
    if (ev.event_type === "dns" && ev.dns?.type === "query" && ev.dns.rrname) {
      dnsByCid.set(ev.community_id, ev.dns.rrname);
    } else if (ev.event_type === "alert" && ev.alert?.signature_id !== undefined) {
      alerts.push({ cid: ev.community_id, sid: ev.alert.signature_id });
    }
  }
  return alerts
    .filter((a) => dnsByCid.has(a.cid))
    .map((a) => ({
      communityId: a.cid,
      sid: a.sid,
      rrname: dnsByCid.get(a.cid)!,
    }));
}
