		validTo, _ := rc.Change.After["valid_to"].(string)
		if strings.TrimSpace(validTo) == "" {
			errs = append(errs, fmt.Sprintf("%s: imported KMS key material missing valid_to expiration", rc.Address))
			continue
		}
		ts, err := time.Parse(time.RFC3339, validTo)
		if err != nil {
			errs = append(errs, fmt.Sprintf("%s: invalid valid_to RFC3339 timestamp %q", rc.Address, validTo))
