interface ConcurrencyCfg {
  group?: string;
  "cancel-in-progress"?: boolean;
}

export interface DeployWorkflow {
  concurrency?: string | ConcurrencyCfg;
  jobs?: Record<
    string,
    {
      environment?: unknown;
      permissions?: Record<string, string>;
      concurrency?: string | ConcurrencyCfg;
    }
  >;
}

function normalizeConcurrency(c?: string | ConcurrencyCfg): { group: string; cancel: boolean } | null {
  if (!c) return null;
  if (typeof c === "string") return { group: c.trim(), cancel: false };
  return { group: (c.group ?? "").trim(), cancel: Boolean(c["cancel-in-progress"]) };
}

export function auditDeployConcurrency(wf: DeployWorkflow): string[] {
  const errors: string[] = [];
  for (const [jobId, job] of Object.entries(wf.jobs ?? {})) {
    const isDeploy = Boolean(job.environment) || job.permissions?.["id-token"] === "write";
    if (!isDeploy) continue;

    const eff = normalizeConcurrency(job.concurrency ?? wf.concurrency);
    if (!eff || !eff.group) {
      errors.push(`job '${jobId}': deployment/OIDC job missing concurrency group serialization`);
    } else if (eff.cancel) {
      errors.push(`job '${jobId}': deployment job sets cancel-in-progress: true, risking state corruption`);
    }
  }
  return errors;
}
