package ociverify

import (
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
)

func ComputeOCIChainID(diffIDs []string) string {
	if len(diffIDs) == 0 {
		return ""
	}
	chainID := diffIDs[0]
	for _, diffID := range diffIDs[1:] {
		sum := sha256.Sum256([]byte(chainID + " " + diffID))
		chainID = "sha256:" + hex.EncodeToString(sum[:])
	}
	return chainID
}

func VerifyOCIChainID(diffIDs []string, expectedChainID string) bool {
	actual := ComputeOCIChainID(diffIDs)
	if len(actual) == 0 || len(actual) != len(expectedChainID) {
		return false
	}
	return subtle.ConstantTimeCompare([]byte(actual), []byte(expectedChainID)) == 1
}
