def parse_netstring_view(buf: bytes, max_len: int = 65_536) -> tuple[memoryview, memoryview]:
    mv = memoryview(buf)
    colon = -1
    for i in range(min(len(mv), 7)):
        b = mv[i]
        if b == 0x3A:
            colon = i
            break
        if not (0x30 <= b <= 0x39):
            raise ValueError("non-digit byte in netstring header")
    if colon <= 0 or (colon > 1 and mv[0] == 0x30):
        raise ValueError("missing colon or leading zero in netstring")
    n = int(bytes(mv[:colon]).decode("ascii"))
    end = colon + 1 + n
    if n > max_len or end >= len(mv) or mv[end] != 0x2C:
