type Attr struct {
	Type  uint8
	Value []byte
}

func ParseRADIUSAttributes(pkt []byte) ([]Attr, error) {
	if len(pkt) < 20 || len(pkt) > 4096 {
		return nil, errors.New("RADIUS datagram size out of bounds")
