```typescript
export function readCborStringHeader(
  buf: Uint8Array,
  offset = 0,
  maxBytes = 262_144,
): { majorType: 2 | 3; length: number; payloadOffset: number } {
  if (offset >= buf.byteLength) {
    throw new RangeError("empty CBOR buffer");
  }
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const initial = view.getUint8(offset);
  const major = initial >> 5;
  const ai = initial & 0x1f;
  if (major !== 2 && major !== 3) {
    throw new Error(`expected CBOR byte/text string (2/3), got major ${major}`);
  }
  if (ai === 31 || ai > 26) {
    throw new Error("indefinite or 64-bit CBOR string headers forbidden");
  }
  let length: number;
  let hdrLen: number;
  if (ai < 24) {
    length = ai;
    hdrLen = 1;
  } else if (ai === 24) {
    if (buf.byteLength - offset < 2) throw new RangeError("short CBOR u8 header");
    length = view.getUint8(offset + 1);
    hdrLen = 2;
  } else if (ai === 25) {
    if (buf.byteLength - offset < 3) throw new RangeError("short CBOR u16 header");
    length = view.getUint16(offset + 1, false);
    hdrLen = 3;
  } else {
    if (buf.byteLength - offset < 5) throw new RangeError("short CBOR u32 header");
    length = view.getUint32(offset + 1, false);
    hdrLen = 5;
  }
  const payloadOffset = offset + hdrLen;
  if (length > maxBytes || length > buf.byteLength - payloadOffset) {
    throw new RangeError("CBOR string exceeds maxBytes or buffer bounds");
  }
  return { majorType: major, length, payloadOffset };
}
