import "math/big"

func VerifyFeldmanShare(
	shareX, shareY *big.Int,
	commitments []*big.Int,
	p, q, g *big.Int,
) bool {
	one := big.NewInt(1)
	if len(commitments) == 0 || shareX.Cmp(one) < 0 || shareX.Cmp(q) >= 0 {
		return false
	}
	if shareY.Sign() < 0 || shareY.Cmp(q) >= 0 || g.Cmp(one) <= 0 {
		return false
	}
