	xPow := big.NewInt(1)
	for _, cj := range commitments {
		if cj == nil || cj.Cmp(one) < 0 || cj.Cmp(p) >= 0 {
			return false
		}
		if new(big.Int).Exp(cj, q, p).Cmp(one) != 0 {
			return false
		}
		term := new(big.Int).Exp(cj, xPow, p)
		rhs.Mul(rhs, term)
		rhs.Mod(rhs, p)

		xPow.Mul(xPow, shareX)
		xPow.Mod(xPow, q)
	}

