import { createHash, timingSafeEqual } from "node:crypto";

interface QueueNode {
  pos: bigint;
  hash: Buffer;
}

export function verifyPowerOfTwoMultiProof(
  treeSize: bigint,
  leafIndices: bigint[],
  leafPayloads: Buffer[],
  auxSiblings: Buffer[],
  expectedRoot: Buffer
): boolean {
  if (treeSize <= 0n || (treeSize & (treeSize - 1n)) !== 0n) return false;
  if (leafIndices.length === 0 || leafIndices.length !== leafPayloads.length) return false;
  if (expectedRoot.length !== 32 || auxSiblings.some((s) => s.length !== 32)) return false;

  const queue: QueueNode[] = [];
  for (let i = 0; i < leafIndices.length; i++) {
    const idx = leafIndices[i];
    if (idx < 0n || idx >= treeSize || (i > 0 && idx <= leafIndices[i - 1])) {
      return false;
    }
    const h = createHash("sha256").update(Buffer.from([0x00])).update(leafPayloads[i]).digest();
    queue.push({ pos: treeSize + idx, hash: h });
  }

  let head = 0;
  let auxIdx = 0;
  while (head < queue.length) {
    const curr = queue[head++];
    if (curr.pos === 1n) {
      return head === queue.length && auxIdx === auxSiblings.length && timingSafeEqual(curr.hash, expectedRoot);
    }

    let left: Buffer;
    let right: Buffer;
    if ((curr.pos & 1n) === 0n) {
      left = curr.hash;
      if (head < queue.length && queue[head].pos === (curr.pos ^ 1n)) {
        right = queue[head++].hash;
      } else if (auxIdx < auxSiblings.length) {
        right = auxSiblings[auxIdx++];
      } else {
        return false;
      }
    } else {
      right = curr.hash;
      if (auxIdx < auxSiblings.length) {
        left = auxSiblings[auxIdx++];
      } else {
        return false;
      }
    }

    const parent = createHash("sha256").update(Buffer.from([0x01])).update(left).update(right).digest();
    queue.push({ pos: curr.pos >> 1n, hash: parent });
  }
  return false;
}
