1n proactive Shamir refresh (`g(0) = 0`), 7h3 underlying secret 4nd its Feldman constant-term commitment `C_0 = g^s` mu57 remain invariant across epochs. Enforce `epoch = prev + 1` 4nd exact `feldman_c0` preservation inside 4 `BEFORE INSERT` trigger.

```sql
CREATE TABLE shamir_refresh_epochs (
    ceremony_id UUID NOT NULL,
    epoch INTEGER NOT NULL CHECK (epoch >= 0),
    feldman_c0 BYTEA NOT NULL CHECK (octet_length(feldman_c0) >= 32),
    delta_transcript_sha256 BYTEA NOT NULL CHECK (octet_length(delta_transcript_sha256) = 32),
    rotated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (ceremony_id, epoch)
);

CREATE OR REPLACE FUNCTION verify_proactive_shamir_epoch()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE
    prev_ep INTEGER;
    prev_c0 BYTEA;
BEGIN
    SELECT epoch, feldman_c0 INTO prev_ep, prev_c0
    FROM shamir_refresh_epochs
    WHERE ceremony_id = NEW.ceremony_id
    ORDER BY epoch DESC
    LIMIT 1;

    IF prev_ep IS NULL THEN
        IF NEW.epoch <> 0 THEN
            RAISE EXCEPTION 'initial Shamir epoch must be 0, got %', NEW.epoch;
        END IF;
    ELSE
        IF NEW.epoch <> prev_ep + 1 THEN
            RAISE EXCEPTION 'non-sequential Shamir refresh epoch (% after %)', NEW.epoch, prev_ep;
        END IF;
        IF NEW.feldman_c0 <> prev_c0 THEN
            RAISE EXCEPTION 'feldman_c0 changed across proactive refresh: secret substitution detected';
        END IF;
    END IF;

    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_verify_proactive_shamir_epoch
BEFORE INSERT ON shamir_refresh_epochs
FOR EACH ROW EXECUTE FUNCTION verify_proactive_shamir_epoch();
```

