ALLOWED_KMS_ALGS = {"ECDSA_SHA_256", "ECDSA_SHA_384", "RSASSA_PSS_SHA_256", "RSASSA_PSS_SHA_384"}


def audit_cloudtrail_kms_sign(lines: Iterable[str], expected_vpce: str) -> list[dict]:
    alerts: list[dict] = []

    for line_no, raw in enumerate(lines, start=1):
        raw = raw.strip()
        if not raw:
            continue
        try:
            ev = json.loads(raw)
        except json.JSONDecodeError:
            continue
        if ev.get("eventSource") != "kms.amazonaws.com" or ev.get("eventName") != "Sign":
            continue

        params = ev.get("requestParameters") or {}
        alg = str(params.get("signingAlgorithm", ""))
        key_id = str(params.get("keyId", "unknown"))
        vpce = ev.get("vpcEndpointId")
        err_code = ev.get("errorCode")

        reasons: list[str] = []
        if alg and alg not in ALLOWED_KMS_ALGS:
            reasons.append(f"disallowed_signing_alg:{alg}")
        if vpce != expected_vpce:
            reasons.append(f"unexpected_vpce:{vpce}")
        if err_code:
            reasons.append(f"kms_error:{err_code}")

        if reasons:
            alerts.append({
                "line": line_no,
                "eventTime": ev.get("eventTime"),
                "keyId": key_id,
                "sourceIPAddress": ev.get("sourceIPAddress"),
                "reasons": reasons,
            })
    return alerts
