    await client.query("SELECT set_config('app.revoker_id', $1, true)", [revokerId]);

    const res = await client.query(
      `INSERT INTO pki.crl_entries (ca_profile, serial_hex, reason_code, revoked_at)
       VALUES ($1, $2, $3, clock_timestamp())
       ON CONFLICT (ca_profile, serial_hex) DO NOTHING`,
      [caProfile, serialHex.toLowerCase(), reasonCode]
    );
    await client.query("COMMIT");
    return (res.rowCount ?? 0) === 1;
  } catch (err) {
    await client.query("ROLLBACK");
