CREATE TRIGGER trg_pki_journal_no_trunc
    BEFORE TRUNCATE ON pki.cert_issuance_journal
    FOR EACH STATEMENT EXECUTE FUNCTION pki.forbid_pki_journal_mutation();

CREATE OR REPLACE FUNCTION pki.guard_crl_entry_integrity()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
