        RAISE EXCEPTION 'Revoked certificates cannot be removed from pki.crl_entries'
            USING ERRCODE = 'insufficient_privilege';
    END IF;
    IF TG_OP = 'UPDATE' AND OLD.reason_code = 'keyCompromise' AND NEW.reason_code <> 'keyCompromise' THEN
        RAISE EXCEPTION 'Cannot downgrade keyCompromise revocation reason'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$$;

