```rust
use syn::{visit::Visit, File, LitStr, Macro};

#[derive(Debug, PartialEq, Eq)]
pub struct RustSqlIssue {
    pub rule: &'static str,
    pub snippet: String,
}

#[derive(Default)]
struct SqlMacroVisitor {
    issues: Vec<RustSqlIssue>,
}

impl<'ast> Visit<'ast> for SqlMacroVisitor {
    fn visit_lit_str(&mut self, node: &'ast LitStr) {
        let val = node.value().to_lowercase();
        if val.contains("pg_advisory_lock(") || val.contains("pg_try_advisory_lock(") {
            self.issues.push(RustSqlIssue {
                rule: "SESSION_ADVISORY_LOCK",
                snippet: node.value(),
            });
        }
    }

    fn visit_macro(&mut self, mac: &'ast Macro) {
        if mac.path.is_ident("format") {
            let tokens_str = mac.tokens.to_string();
            let lower = tokens_str.to_lowercase();
            if lower.contains("order by") && tokens_str.contains("{}") && !tokens_str.contains("as_sql_order_by") {
                self.issues.push(RustSqlIssue {
                    rule: "RAW_FORMAT_ORDER_BY",
                    snippet: tokens_str,
                });
            }
        }
        syn::visit::visit_macro(self, mac);
    }
}

pub fn audit_rust_sql_source(source: &str) -> Result<Vec<RustSqlIssue>, syn::Error> {
    let ast: File = syn::parse_file(source)?;
    let mut visitor = SqlMacroVisitor::default();
    visitor.visit_file(&ast);
    Ok(visitor.issues)
}
