package pemguard

import (
	"bytes"
	"crypto/x509"
	"encoding/pem"
	"errors"
)

func ParseSingleLeafPEM(raw []byte) (*x509.Certificate, error) {
	if len(raw) == 0 || len(raw) > 16384 {
		return nil, errors.New("PEM input outside [1, 16384] byte limit")
	}
	block, rest := pem.Decode(bytes.TrimSpace(raw))
	if block == nil || block.Type != "CERTIFICATE" {
		return nil, errors.New("expected single PEM CERTIFICATE block")
	}
	if len(block.Headers) > 0 {
		return nil, errors.New("PEM headers forbidden in CERTIFICATE block")
	}
	if len(bytes.TrimSpace(rest)) > 0 {
		return nil, errors.New("unexpected trailing data or extra PEM blocks")
	}
	cert, err := x509.ParseCertificate(block.Bytes)
	if err != nil {
		return nil, err
	}
	if cert.IsCA {
		return nil, errors.New("CA certificate rejected")
	}
	return cert, nil
}
