var ErrUpstreamTimeout = errors.New("upstream fetch deadline exceeded")

func NewHardenedClient() *http.Client {
	return &http.Client{
		CheckRedirect: func(_ *http.Request, _ []*http.Request) error {
			return http.ErrUseLastResponse
		},
		Transport: &http.Transport{
			DialContext:           (&net.Dialer{Timeout: 2 * time.Second}).DialContext,
			TLSHandshakeTimeout:   3 * time.Second,
			ResponseHeaderTimeout: 4 * time.Second,
			DisableCompression:    true,
		},
	}
}

func FetchBounded(parent context.Context, cli *http.Client, url string, budget time.Duration, maxBytes int64) ([]byte, error) {
	ctx, cancel := context.WithTimeoutCause(parent, budget, ErrUpstreamTimeout)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, err
	}
	resp, err := cli.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	body, err := io.ReadAll(io.LimitReader(resp.Body, maxBytes+1))
	if err != nil {
		return nil, err
	}
	if int64(len(body)) > maxBytes {
		return nil, errors.New("upstream response exceeded maxBytes")
	}
	return body, nil
}
