```typescript
export async function fetchBoundedBytes(url: string, budgetMs: number, maxBytes: number): Promise<Uint8Array> {
  const resp = await fetch(url, {
    method: "GET",
    redirect: "error",
    signal: AbortSignal.timeout(budgetMs),
    headers: { "Accept-Encoding": "identity" },
  });
  if (!resp.body) {
    return new Uint8Array(0);
  }
  const reader = resp.body.getReader();
  const chunks: Uint8Array[] = [];
  let seen = 0;

  while (true) {
    const { done, value } = await reader.read();
    if (done) break;
    seen += value.byteLength;
    if (seen > maxBytes) {
      await reader.cancel("maxBytes exceeded");
      throw new RangeError(`Upstream response exceeded ${maxBytes} bytes`);
    }
    chunks.push(value);
  }
  const out = new Uint8Array(seen);
  let offset = 0;
  for (const c of chunks) {
    out.set(c, offset);
    offset += c.byteLength;
  }
  return out;
}
