import (
	"bytes"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"io"
	"net/http"
	"time"
)

func BinaryIngestHMAC(secret []byte, bodyDeadline time.Duration, next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_ = http.NewResponseController(w).SetReadDeadline(time.Now().Add(bodyDeadline))
		r.Body = http.MaxBytesReader(w, r.Body, 65536)
		raw, err := io.ReadAll(r.Body)
		if err != nil {
			http.Error(w, "body too large or read timeout", http.StatusRequestEntityTooLarge)
			return
		}
		sig, err := hex.DecodeString(r.Header.Get("X-Body-HMAC"))
		if err != nil || len(sig) != sha256.Size {
			http.Error(w, "invalid signature header", http.StatusUnauthorized)
			return
		}
		mac := hmac.New(sha256.New, secret)
		mac.Write(raw)
		if !hmac.Equal(sig, mac.Sum(nil)) {
			http.Error(w, "bad signature", http.StatusUnauthorized)
			return
		}
		r.Body = io.NopCloser(bytes.NewReader(raw))
		next.ServeHTTP(w, r)
	})
}
