```rust
use axum::{body::{to_bytes, Body}, http::{Request, StatusCode}};
use ed25519_dalek::{Signature, VerifyingKey};
use std::time::{Duration, SystemTime, UNIX_EPOCH};

pub async fn verify_ed25519_request(
    req: Request<Body>,
    vk: &VerifyingKey,
) -> Result<Request<Body>, StatusCode> {
    let (parts, body) = req.into_parts();
    let ts: u64 = parts
        .headers
        .get("x-timestamp")
        .and_then(|v| v.to_str().ok())
        .and_then(|s| s.parse().ok())
        .ok_or(StatusCode::UNAUTHORIZED)?;
    let now = SystemTime::now().duration_since(UNIX_EPOCH).map_err(|_| StatusCode::INTERNAL_SERVER_ERROR)?.as_secs();
    if now.abs_diff(ts) > 60 {
        return Err(StatusCode::UNAUTHORIZED);
    }
    let sig_hex = parts.headers.get("x-signature-ed25519").and_then(|v| v.to_str().ok()).ok_or(StatusCode::UNAUTHORIZED)?;
    let sig_bytes: [u8; 64] = hex::decode(sig_hex).ok().and_then(|v| v.try_into().ok()).ok_or(StatusCode::UNAUTHORIZED)?;
    let sig = Signature::from_bytes(&sig_bytes);

    let raw_body = tokio::time::timeout(Duration::from_secs(2), to_bytes(body, 65_536))
        .await
        .map_err(|_| StatusCode::REQUEST_TIMEOUT)?
        .map_err(|_| StatusCode::PAYLOAD_TOO_LARGE)?;

    let mut msg = Vec::with_capacity(32 + raw_body.len());
    msg.extend_from_slice(&ts.to_be_bytes());
    msg.extend_from_slice(parts.method.as_str().as_bytes());
    msg.extend_from_slice(parts.uri.path().as_bytes());
    msg.extend_from_slice(&raw_body);
    vk.verify_strict(&msg, &sig).map_err(|_| StatusCode::UNAUTHORIZED)?;

    Ok(Request::from_parts(parts, Body::from(raw_body)))
}
