export function verifyCertBoundClaim(
  proxyCertSha256Hex: string | undefined,
  cnfX5tS256: string | undefined,
): boolean {
  if (!proxyCertSha256Hex || !cnfX5tS256) {
    return false;
  }
  if (!/^[0-9a-f]{64}$/i.test(proxyCertSha256Hex) || !/^[A-Za-z0-9_-]{43}$/.test(cnfX5tS256)) {
