```typescript
import * as readline from "node:readline";
import { Readable } from "node:stream";

interface CtRegionRecord {
  awsRegion?: string;
  eventTime?: string;
}

export async function findRegionalTelemetryGaps(
  input: Readable,
  maxGapMinutes = 30
): Promise<Array<{ region: string; maxGapMin: number }>> {
  const byRegion = new Map<string, number[]>();
  const rl = readline.createInterface({ input, crlfDelay: Infinity });
  for await (const line of rl) {
    if (!line.trim()) continue;
    const ev = JSON.parse(line) as CtRegionRecord;
    if (!ev.awsRegion || !ev.eventTime) continue;
    const ms = Date.parse(ev.eventTime);
    if (Number.isNaN(ms)) continue;
    const arr = byRegion.get(ev.awsRegion) ?? [];
    arr.push(ms);
    byRegion.set(ev.awsRegion, arr);
  }
  const alerts: Array<{ region: string; maxGapMin: number }> = [];
  for (const [region, stamps] of byRegion) {
    stamps.sort((a, b) => a - b);
    let maxGapMs = 0;
    for (let i = 1; i < stamps.length; i++) {
      maxGapMs = Math.max(maxGapMs, stamps[i] - stamps[i - 1]);
    }
    const maxGapMin = Number((maxGapMs / 60_000).toFixed(2));
    if (maxGapMin > maxGapMinutes) {
      alerts.push({ region, maxGapMin });
    }
  }
  return alerts;
}
