package gqlguard

import (
	"bytes"
	"encoding/json"
	"io"
	"net/http"
	"strings"
)

func ProtectGraphQL(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if sfs := r.Header.Get("Sec-Fetch-Site"); sfs != "" && sfs != "same-origin" && sfs != "none" {
			http.Error(w, "forbidden fetch site", http.StatusForbidden)
			return
		}
		if r.Method == http.MethodPost {
			if !strings.HasPrefix(strings.ToLower(r.Header.Get("Content-Type")), "application/json") {
				http.Error(w, "json required", http.StatusUnsupportedMediaType)
				return
			}
			raw, err := io.ReadAll(io.LimitReader(r.Body, 65536))
			if err != nil {
				http.Error(w, "read error", http.StatusBadRequest)
				return
			}
			trimmed := bytes.TrimSpace(raw)
			if len(trimmed) > 0 && trimmed[0] == '[' {
				var arr []json.RawMessage
				if json.Unmarshal(trimmed, &arr) != nil || len(arr) == 0 || len(arr) > 5 {
					http.Error(w, "batch limit exceeded", http.StatusBadRequest)
					return
				}
			}
			r.Body = io.NopCloser(bytes.NewReader(raw))
		}
		next.ServeHTTP(w, r)
	})
}
