import ast

SAFE_YAML_LOADERS = {"SafeLoader", "CSafeLoader"}

class DeserializationLinter(ast.NodeVisitor):
    def __init__(self) -> None:
        self.findings: list[tuple[int, str]] = []

    def visit_Call(self, node: ast.Call) -> None:
        if isinstance(node.func, ast.Attribute) and isinstance(node.func.value, ast.Name):
            mod, fn = node.func.value.id, node.func.attr
            if mod == "pickle" and fn in {"load", "loads"}:
                self.findings.append((node.lineno, f"unsafe {mod}.{fn}() deserialization in CI script"))
            elif mod == "yaml" and fn == "load":
                has_safe = False
                for kw in node.keywords:
                    if kw.arg == "Loader":
                        loader_name = (
                            kw.value.id if isinstance(kw.value, ast.Name)
                            else kw.value.attr if isinstance(kw.value, ast.Attribute)
                            else ""
                        )
                        if loader_name in SAFE_YAML_LOADERS:
                            has_safe = True
                if not has_safe:
                    self.findings.append((node.lineno, "yaml.load() without SafeLoader; use yaml.safe_load()"))
        self.generic_visit(node)

def audit_python_deserialization(src: str) -> list[tuple[int, str]]:
    linter = DeserializationLinter()
    linter.visit(ast.parse(src))
    return linter.findings
