```python
import hashlib
import hmac
import struct


def verify_indexed_merkle_exclusion(
    target_key: int,
    low_key: int,
    low_next_idx: int,
    low_next_key: int,
    leaf_index: int,
     siblings: list[bytes],
    expected_root: bytes,
) -> bool:
    u256_max = (1 << 256) - 1
    if not (0 < target_key <= u256_max) or not (0 <= low_key <= u256_max) or not (0 <= low_next_key <= u256_max):
        return False
    if low_next_idx < 0 or leaf_index < 0 or len(expected_root) != 32:
        return False
    if any(len(s) != 32 for s in siblings) or (leaf_index >> len(siblings)) != 0:
        return False

    if not (low_key < target_key):
        return False
    if low_next_key == 0:
        if low_next_idx != 0:
            return False
    elif not (target_key < low_next_key):
        return False

    leaf_bytes = (
        low_key.to_bytes(32, "big")
        + struct.pack(">Q", low_next_idx)
        + low_next_key.to_bytes(32, "big")
    )
    curr = hashlib.sha256(b"\x00" + leaf_bytes).digest()
    idx = leaf_index
    for sib in siblings:
        if (idx & 1) == 0:
            curr = hashlib.sha256(b"\x01" + curr + sib).digest()
        else:
            curr = hashlib.sha256(b"\x01" + sib + curr).digest()
        idx >>= 1

    return hmac.compare_digest(curr, expected_root)
