func buildShareAAD(ceremonyID [16]byte, threshold uint8, shareX uint32) []byte {
	aad := make([]byte, 0, 14+16+1+4)
	aad = append(aad, "SHAMIR-GCM-V1\x00"...)
	aad = append(aad, ceremonyID[:]...)
	aad = append(aad, threshold)
	var xBuf [4]byte
	binary.BigEndian.PutUint32(xBuf[:], shareX)
	aad = append(aad, xBuf[:]...)
	return aad
}

func SealShamirShareGCM(key32 []byte, ceremonyID [16]byte, threshold uint8, shareX uint32, shareY []byte) ([]byte, error) {
	if len(key32) != 32 || threshold < 2 || shareX == 0 || len(shareY) == 0 {
		return nil, errors.New("invalid Shamir AEAD parameters")
	}
	block, err := aes.NewCipher(key32)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, gcm.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, err
	}
	aad := buildShareAAD(ceremonyID, threshold, shareX)
	return gcm.Seal(nonce, nonce, shareY, aad), nil
}

func OpenShamirShareGCM(key32 []byte, ceremonyID [16]byte, threshold uint8, shareX uint32, sealed []byte) ([]byte, error) {
	if len(key32) != 32 || threshold < 2 || shareX == 0 {
		return nil, errors.New("invalid Shamir AEAD parameters")
	}
	block, err := aes.NewCipher(key32)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	ns := gcm.NonceSize()
	if len(sealed) < ns+gcm.Overhead()+1 {
		return nil, errors.New("ciphertext too short")
	}
	aad := buildShareAAD(ceremonyID, threshold, shareX)
	return gcm.Open(nil, sealed[:ns], sealed[ns:], aad)
