import { randomBytes } from "node:crypto";

function mod(a: bigint, m: bigint): bigint {
  const r = a % m;
  return r < 0n ? r + m : r;
}

function modPow(base: bigint, exp: bigint, m: bigint): bigint {
  let acc = 1n;
  let b = mod(base, m);
  let e = exp;
  while (e > 0n) {
    if ((e & 1n) === 1n) acc = (acc * b) % m;
    b = (b * b) % m;
    e >>= 1n;
  }
  return acc;
}

function gcd(a: bigint, b: bigint): bigint {
  while (b !== 0n) [a, b] = [b, a % b];
  return a;
}

function modInv(a: bigint, m: bigint): bigint {
  let [t, newT] = [0n, 1n];
  let [r, newR] = [m, mod(a, m)];
  while (newR !== 0n) {
    const q = r / newR;
    [t, newT] = [newT, t - q * newT];
    [r, newR] = [newR, r - q * newR];
  }
  if (r !== 1n) throw new Error("not coprime");
  return t < 0n ? t + m : t;
}

export function rsaCrtSignChecked(
  msg: bigint,
  n: bigint,
  e: bigint,
  p: bigint,
  q: bigint,
  dp: bigint,
  dq: bigint,
  qinv: bigint
): bigint {
  if (msg <= 0n || msg >= n) throw new RangeError("msg out of range");

  let r: bigint;
  do {
    r = mod(BigInt("0x" + randomBytes(64).toString("hex")), n - 3n) + 2n;
  } while (gcd(r, n) !== 1n);

  const blinded = (msg * modPow(r, e, n)) % n;
  const sp = modPow(blinded % p, dp, p);
  const sq = modPow(blinded % q, dq, q);
  const h = (qinv * mod(sp - sq, p)) % p;
  const sBlinded = (sq + h * q) % n;
  const sig = (sBlinded * modInv(r, n)) % n;

  if (modPow(sig, e, n) !== msg) {
    throw new Error("RSA-CRT fault check failed");
  }
  return sig;
}
