CREATE TABLE smt_state_transitions (
    namespace_id TEXT NOT NULL CHECK (length(btrim(namespace_id)) > 0),
    version BIGINT NOT NULL CHECK (version >= 1),
    prev_root BYTEA NOT NULL CHECK (octet_length(prev_root) = 32),
    new_root BYTEA NOT NULL CHECK (octet_length(new_root) = 32 AND new_root <> prev_root),
    batch_proof_sha256 BYTEA NOT NULL CHECK (octet_length(batch_proof_sha256) = 32),
    committed_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (namespace_id, version)
);

CREATE OR REPLACE FUNCTION enforce_smt_root_chain()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE
    last_ver BIGINT;
    last_root BYTEA;
BEGIN
    SELECT version, new_root INTO last_ver, last_root
    FROM smt_state_transitions
    WHERE namespace_id = NEW.namespace_id
    ORDER BY version DESC
    LIMIT 1;

    IF last_ver IS NULL THEN
        IF NEW.version <> 1 THEN
            RAISE EXCEPTION 'initial SMT version must be 1, got %', NEW.version;
        END IF;
    ELSE
        IF NEW.version <> last_ver + 1 THEN
            RAISE EXCEPTION 'non-sequential SMT version (% after %)', NEW.version, last_ver;
        END IF;
        IF NEW.prev_root <> last_root THEN
            RAISE EXCEPTION 'SMT root chain broken: prev_root does not match prior new_root';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;

CREATE TRIGGER trg_smt_root_chain
BEFORE INSERT ON smt_state_transitions
FOR EACH ROW EXECUTE FUNCTION enforce_smt_root_chain();
