```typescript
import { createCipheriv, createDecipheriv, randomBytes } from "node:crypto";

function buildColumnAad(table: string, rowPk: string, column: string): Buffer {
  if (table.includes("\0") || rowPk.includes("\0") || column.includes("\0")) {
    throw new Error("NUL byte forbidden in column AAD identifiers");
  }
  return Buffer.from(`${table}\0${rowPk}\0${column}`, "utf8");
}

export function sealColumnValue(key: Buffer, table: string, rowPk: string, column: string, pt: Buffer): Buffer {
  const nonce = randomBytes(12);
  const cipher = createCipheriv("aes-256-gcm", key, nonce, { authTagLength: 16 });
  cipher.setAAD(buildColumnAad(table, rowPk, column));
  return Buffer.concat([nonce, cipher.update(pt), cipher.final(), cipher.getAuthTag()]);
}

export function openColumnValue(key: Buffer, table: string, rowPk: string, column: string, blob: Buffer): Buffer {
  if (blob.byteLength < 28) throw new Error("Encrypted column too short");
  const decipher = createDecipheriv("aes-256-gcm", key, blob.subarray(0, 12), { authTagLength: 16 });
  decipher.setAAD(buildColumnAad(table, rowPk, column));
  decipher.setAuthTag(blob.subarray(blob.byteLength - 16));
  return Buffer.concat([decipher.update(blob.subarray(12, blob.byteLength - 16)), decipher.final()]);
}
