import struct

def canonical_column_aad(table: str, pk: str, col: str) -> bytes:
    out = bytearray()
    for part in (table, pk, col):
        raw = part.encode("utf-8")
        out.extend(struct.pack(">I", len(raw)))
        out.extend(raw)
    return bytes(out)

def has_aad_collision(t1: tuple[str, str, str], t2: tuple[str, str, str]) -> dict[str, bool]:
