def verify_radius_msg_auth(packet: bytes, shared_secret: bytes) -> bool:
    if len(packet) < 38 or len(packet) > 4096 or not shared_secret:
        return False
    (_code, _ident, pkt_len) = struct.unpack_from(">BBH", packet, 0)
    if pkt_len != len(packet):
