    work = bytearray(packet)
    found_offset = -1
    provided_mac = b""
    pos = 20
    while pos < pkt_len:
        if pkt_len - pos < 2:
            return False
        atype, alen = work[pos], work[pos + 1]
        if alen < 2 or pos + alen > pkt_len:
