            found_offset = pos + 2
            provided_mac = bytes(work[found_offset : found_offset + 16])
            work[found_offset : found_offset + 16] = b"\x00" * 16
        pos += alen
    if found_offset == -1:
        return False
    expected = hmac.new(shared_secret, work, hashlib.md5).digest()
    return hmac.compare_digest(expected, provided_mac)
