```go
package cborwire

import (
	"encoding/binary"
	"errors"
)

func DecodeCBORBytes(buf []byte, maxLen int) (payload, rest []byte, err error) {
	if len(buf) == 0 {
		return nil, nil, errors.New("empty CBOR input")
	}
	major := buf[0] >> 5
	ai := buf[0] & 0x1f
	if major != 2 || ai == 31 || ai > 26 {
		return nil, nil, errors.New("expected definite CBOR byte string (<= u32 len)")
	}
	var n, hdr int
	switch {
	case ai < 24:
		n, hdr = int(ai), 1
	case ai == 24 && len(buf) >= 2:
		n, hdr = int(buf[1]), 2
	case ai == 25 && len(buf) >= 3:
		n, hdr = int(binary.BigEndian.Uint16(buf[1:3])), 3
	case ai == 26 && len(buf) >= 5:
		n, hdr = int(binary.BigEndian.Uint32(buf[1:5])), 5
	default:
		return nil, nil, errors.New("truncated CBOR byte-string header")
	}
	if n > maxLen || len(buf)-hdr < n {
		return nil, nil, errors.New("CBOR byte string exceeds cap or buffer")
	}
	return buf[hdr : hdr+n], buf[hdr+n:], nil
}
