export function validateSshFrameHeader(
  hdr5: Uint8Array,
  blockSize = 8,
): { payloadLen: number; paddingLen: number } {
  if (hdr5.byteLength < 5 || blockSize < 8 || (blockSize & (blockSize - 1)) !== 0) {
    throw new Error("invalid 5-byte SSH header or cipher block size");
  }
  const view = new DataView(hdr5.buffer, hdr5.byteOffset, hdr5.byteLength);
  const packetLen = view.getUint32(0, false);
  const paddingLen = view.getUint8(4);
  if (packetLen < 12 || packetLen > 35_000 || paddingLen < 4) {
    throw new RangeError("SSH packet or padding length out of bounds");
  }
  if ((4 + packetLen) % blockSize !== 0 || paddingLen + 1 >= packetLen) {
    throw new Error("SSH cipher alignment failure or empty payload");
  }
  return { payloadLen: packetLen - paddingLen - 1, paddingLen };
}
