  const ct = await crypto.subtle.encrypt(
    { name: "AES-GCM", iv: makeChunkIv(prefix8, seq), additionalData: makeChunkAad(seq, isFinal), tagLength: 128 },
    key,
    chunk,
  );
  return new Uint8Array(ct);
}

export async function decryptChunkStream(
  key: CryptoKey,
  prefix8: Uint8Array,
  chunks: Uint8Array[],
): Promise<Uint8Array[]> {
  if (chunks.length === 0) throw new Error("empty encrypted stream");
