use serde_json::Value;

fn as_str_vec(v: Option<&Value>) -> Vec<&str> {
    match v {
        Some(Value::String(s)) => vec![s.as_str()],
        Some(Value::Array(arr)) => arr.iter().filter_map(Value::as_str).collect(),
        _ => Vec::new(),
    }
}

pub fn check_wildcard_kms_s3_iam(policy_json: &str) -> Result<Vec<String>, serde_json::Error> {
    let doc: Value = serde_json::from_str(policy_json)?;
    let mut out = Vec::new();
    let Some(stmts) = doc.get("Statement").and_then(Value::as_array) else {
        return Ok(out);
    };

    for (idx, stmt) in stmts.iter().enumerate() {
        if stmt.get("Effect").and_then(Value::as_str) != Some("Allow") {
            continue;
        }
        let resources = as_str_vec(stmt.get("Resource"));
        if !resources.contains(&"*") {
            continue;
        }
        for act in as_str_vec(stmt.get("Action")) {
            let low = act.to_ascii_lowercase();
            if low == "*"
                || low == "kms:*"
                || low == "kms:decrypt"
                || low.starts_with("kms:generatedatakey")
                || low == "s3:*"
                || low == "s3:getobject"
            {
                out.push(format!("Statement[{idx}]: grants '{act}' on wildcard Resource '*'"));
            }
        }
    }
    Ok(out)
}
