const IMMUTABLE_CHMOD_RE = /^--chmod=0?[45][045]{2}$/;

export function lintFinalStageImmutableCopy(dockerfile: string): Array<{ line: number; message: string }> {
  const lines = dockerfile.split(/\r?\n/);
  let lastFromIdx = -1;
  for (let i = 0; i < lines.length; i++) {
    if (/^\s*FROM\s+/i.test(lines[i])) lastFromIdx = i;
  }
  if (lastFromIdx === -1) return [];

  const findings: Array<{ line: number; message: string }> = [];
  for (let i = lastFromIdx + 1; i < lines.length; i++) {
    const trimmed = lines[i].trim();
    if (!/^COPY\s+/i.test(trimmed)) continue;
    const flags = trimmed
      .split(/\s+/)
      .slice(1)
      .filter((t) => t.startsWith("--"));
    const chmodFlag = flags.find((f) => f.toLowerCase().startsWith("--chmod="));
    if (!chmodFlag || !IMMUTABLE_CHMOD_RE.test(chmodFlag)) {
      findings.push({
        line: i + 1,
        message: `final stage COPY missing read-only --chmod (e.g. --chmod=0555 or --chmod=0444): '${trimmed}'`,
      });
    }
  }
  return findings;
}
