```go
package ghalint

import (
	"fmt"
	"regexp"
	"strings"

	"gopkg.in/yaml.v3"
)

var secScannerRe = regexp.MustCompile(`(?i)\b(conftest|opa\s+eval|trivy|tfsec|checkov|hadolint|zizmor|actionlint)\b`)

func AuditMutedSecuritySteps(raw []byte) ([]string, error) {
	var root yaml.Node
	if err := yaml.Unmarshal(raw, &root); err != nil {
		return nil, err
	}
	var out []string
	var walk func(n *yaml.Node)
	walk = func(n *yaml.Node) {
		if n == nil {
			return
		}
		if n.Kind == yaml.MappingNode {
			var isScanner bool
			var coeNode *yaml.Node
			for i := 0; i+1 < len(n.Content); i += 2 {
				k, v := n.Content[i], n.Content[i+1]
				if (k.Value == "run" || k.Value == "uses") && v.Kind == yaml.ScalarNode && secScannerRe.MatchString(v.Value) {
					isScanner = true
				}
				if k.Value == "continue-on-error" {
					coeNode = v
				}
				walk(v)
			}
			if isScanner && coeNode != nil && strings.Contains(strings.ToLower(coeNode.Value), "true") {
				out = append(out, fmt.Sprintf("%d:%d security scanner step muted via continue-on-error: %s", coeNode.Line, coeNode.Column, coeNode.Value))
			}
			return
		}
		for _, c := range n.Content {
			walk(c)
		}
	}
	walk(&root)
	return out, nil
}
