```typescript
import * as readline from "node:readline";
import { Readable } from "node:stream";

interface SarLine {
  requestReceivedTimestamp?: string;
  user?: { username?: string };
  objectRef?: { resource?: string };
}

export async function selfSarProbeJitter(
  input: Readable,
  minProbes = 8
): Promise<Map<string, number>> {
  const stamps = new Map<string, number[]>();
  const rl = readline.createInterface({ input, crlfDelay: Infinity });
  for await (const line of rl) {
    if (!line.trim()) continue;
    const ev = JSON.parse(line) as SarLine;
    if (ev.objectRef?.resource !== "selfsubjectaccessreviews" || !ev.requestReceivedTimestamp) {
      continue;
    }
    const u = ev.user?.username ?? "unknown";
    const sec = Date.parse(ev.requestReceivedTimestamp) / 1000;
    if (!Number.isNaN(sec)) {
      const arr = stamps.get(u) ?? [];
      arr.push(sec);
      stamps.set(u, arr);
    }
  }
  const res = new Map<string, number>();
  for (const [u, ts] of stamps) {
    if (ts.length < minProbes) continue;
    ts.sort((a, b) => a - b);
    const deltas = ts.slice(1).map((t, i) => t - ts[i]);
    const mean = deltas.reduce((s, d) => s + d, 0) / deltas.length;
    const variance = deltas.reduce((s, d) => s + (d - mean) ** 2, 0) / deltas.length;
    res.set(u, Number(Math.sqrt(variance).toFixed(4)));
  }
  return res;
}
