from typing import Iterable

def subtract_approved_v4_cidrs(
    observed_cidrs: Iterable[str],
    approved_cidrs: Iterable[str],
) -> list[str]:
    rem = list(
        ipaddress.collapse_addresses(
            ipaddress.IPv4Network(c, strict=False) for c in observed_cidrs
        )
    )
    allow = list(
        ipaddress.collapse_addresses(
            ipaddress.IPv4Network(c, strict=False) for c in approved_cidrs
        )
    )
    for ok in allow:
        next_rem: list[ipaddress.IPv4Network] = []
        for net in rem:
