func BuildTrustedHTU(r *http.Request, trustedLB *net.IPNet, fallbackHost string) (string, error) {
	hostIPStr, _, err := net.SplitHostPort(r.RemoteAddr)
	if err != nil {
		return "", err
	}
	peerIP := net.ParseIP(hostIPStr)
	scheme := "https"
	host := fallbackHost
