		if xp := r.Header.Get("X-Forwarded-Proto"); xp != "" {
			scheme = strings.ToLower(strings.TrimSpace(xp))
		}
		if xh := r.Header.Get("X-Forwarded-Host"); xh != "" && !strings.Contains(xh, ",") {
			host = strings.ToLower(strings.TrimSpace(xh))
		}
	}
	if scheme != "https" || host == "" {
		return "", errors.New("non-https or empty canonical host")
	}
	return scheme + "://" + strings.TrimSuffix(host, ":443") + r.URL.EscapedPath(), nil
}
