```rust
pub fn normalize_htu_path(raw_path: &str) -> Result<String, &'static str> {
    if !raw_path.starts_with('/') {
        return Err("path must start with '/'");
    }
    let bytes = raw_path.as_bytes();
    let mut out = String::with_capacity(raw_path.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' {
            if i + 2 >= bytes.len() {
                return Err("truncated percent escape");
            }
            let hex = std::str::from_utf8(&bytes[i + 1..i + 3]).map_err(|_| "bad hex")?;
            let val = u8::from_str_radix(hex, 16).map_err(|_| "invalid hex escape")?;
            if val == b'/' || val == b'\\' || val == 0 {
                return Err("encoded slash or null forbidden in htu");
            }
            if val.is_ascii_alphanumeric() || matches!(val, b'-' | b'.' | b'_' | b'~') {
                out.push(val as char);
            } else {
                out.push('%');
                out.push_str(&hex.to_ascii_uppercase());
            }
            i += 3;
        } else {
            out.push(bytes[i] as char);
            i += 1;
        }
    }
    Ok(out)
}
