use crc32fast::hash as crc32;
use sqlx::PgPool;
use uuid::Uuid;

const DNSSEC_DS_CLASS: i32 = 0x4453_5243; // "DSRC"

pub async fn rotate_domain_ds_record(
    pool: &PgPool,
    domain_id: Uuid,
    key_tag: i32,
    alg: i16,
    digest_type: i16,
    digest_hex: &str,
    epp_cltrid: &str,
) -> Result<(), String> {
