    let obj_key = crc32(domain_id.as_bytes()) as i32;

    sqlx::query("SELECT pg_advisory_xact_lock($1, $2)")
        .bind(DNSSEC_DS_CLASS)
        .bind(obj_key)
        .execute(&mut *tx)
        .await
        .map_err(|e| e.to_string())?;

    sqlx::query("SELECT set_config('app.epp_cltrid', $1, true)")
        .bind(epp_cltrid)
        .execute(&mut *tx)
        .await
        .map_err(|e| e.to_string())?;

    let ds_count: i64 = sqlx::query_scalar(
