```go
package ecdsa_strict

import (
	"bytes"
	"crypto/elliptic"
	"encoding/asn1"
	"errors"
	"math/big"
)

type ecdsaSigASN1 struct {
	R, S *big.Int
}

func DecodeCanonicalP256DER(derBytes []byte) (*big.Int, *big.Int, error) {
	if len(derBytes) < 8 || len(derBytes) > 72 {
		return nil, nil, errors.New("invalid P-256 DER signature length")
	}
	var parsed ecdsaSigASN1
	rest, err := asn1.Unmarshal(derBytes, &parsed)
	if err != nil || len(rest) != 0 || parsed.R == nil || parsed.S == nil {
		return nil, nil, errors.New("malformed ASN.1 or trailing bytes")
	}

	canonicalDER, err := asn1.Marshal(parsed)
	if err != nil || !bytes.Equal(canonicalDER, derBytes) {
		return nil, nil, errors.New("non-canonical ASN.1 DER integer encoding")
	}

	n := elliptic.P256().Params().N
	halfN := new(big.Int).Rsh(n, 1)
	if parsed.R.Sign() <= 0 || parsed.R.Cmp(n) >= 0 {
		return nil, nil, errors.New("ECDSA R out of bounds")
	}
	if parsed.S.Sign() <= 0 || parsed.S.Cmp(halfN) > 0 {
		return nil, nil, errors.New("ECDSA S out of canonical low-S bounds")
	}
	return parsed.R, parsed.S, nil
}
