```rust
use curve25519_dalek::scalar::Scalar;
use rand_core::CryptoRngCore;
use zeroize::Zeroizing;

pub fn generate_ristretto_refresh_deltas<R: CryptoRngCore>(
    rng: &mut R,
    participant_xs: &[u64],
    threshold: usize,
) -> Result<Vec<(u64, Scalar)>, &'static str> {
    if threshold < 2 || participant_xs.len() < threshold {
        return Err("insufficient participants for threshold");
    }
    for (i, &x) in participant_xs.iter().enumerate() {
        if x == 0 || participant_xs[..i].contains(&x) {
            return Err("zero or duplicate participant x-coordinate");
        }
    }

    let mut coeffs = Zeroizing::new(Vec::with_capacity(threshold - 1));
    for _ in 0..(threshold - 1) {
        coeffs.push(Scalar::random(rng));
    }

    let mut out = Vec::with_capacity(participant_xs.len());
    for &x_u64 in participant_xs {
        let x = Scalar::from(x_u64);
        let mut x_pow = x;
        let mut acc = Scalar::ZERO;
        for c in coeffs.iter() {
            acc += (*c) * x_pow;
            x_pow *= x;
        }
        out.push((x_u64, acc));
    }
    Ok(out)
}
