function modPow(base: bigint, exp: bigint, m: bigint): bigint {
  let acc = 1n;
  let b = ((base % m) + m) % m;
  let e = exp;
  while (e > 0n) {
    if ((e & 1n) === 1n) acc = (acc * b) % m;
    b = (b * b) % m;
    e >>= 1n;
  }
  return acc;
}

export function verifyFeldmanModP(
  shareX: bigint,
  shareY: bigint,
  commitments: bigint[],
  p: bigint,
  q: bigint,
  g: bigint
): boolean {
  if (commitments.length === 0 || shareX <= 0n || shareX >= q || shareY < 0n || shareY >= q) {
    return false;
  }
  if (p <= 2n || q <= 2n || (p - 1n) % q !== 0n || g <= 1n || g >= p) {
    return false;
  }
  if (modPow(g, q, p) !== 1n) {
    return false;
  }

  let rhs = 1n;
  let xPow = 1n;
  for (const cj of commitments) {
    if (cj <= 0n || cj >= p || modPow(cj, q, p) !== 1n) {
      return false;
    }
    rhs = (rhs * modPow(cj, xPow, p)) % p;
    xPow = (xPow * shareX) % q;
  }

  return modPow(g, shareY, p) === rhs;
}
