def aead_collision_upper_bound(messages_sent: int, nonce_bits: int = 96) -> float:
    if messages_sent <= 1:
        return 0.0
    if nonce_bits < 64:
        raise ValueError("AEAD nonce width too small")
    return (messages_sent * (messages_sent - 1)) / float(1 << (nonce_bits + 1))

def needs_session_rekey(
    messages_sent: int,
    nonce_bits: int = 96,
    max_risk_neg_log2: int = 32,
) -> bool:
    if messages_sent < 0 or nonce_bits <= max_risk_neg_log2:
        raise ValueError("invalid message count or nonce/risk bit bounds")
    if messages_sent <= 1:
        return False
    # Equivalent to q*(q-1)/(2*2^nonce_bits) >= 2^(-max_risk_neg_log2)
    threshold_num = 1 << (nonce_bits + 1 - max_risk_neg_log2)
    return messages_sent * (messages_sent - 1) >= threshold_num
