package safexml

import (
	"bytes"
	"encoding/xml"
	"errors"
	"io"
	"strings"
)

func VerifyAndDecodeSafeXML(raw []byte, dst any) error {
	if len(raw) == 0 || len(raw) > 262144 {
		return errors.New("XML input outside [1, 262144] byte limit")
	}
	scan := xml.NewDecoder(bytes.NewReader(raw))
	scan.Strict = true
	scan.Entity = map[string]string{}
	depth, nodes := 0, 0
	for {
		tok, err := scan.RawToken()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return err
		}
		switch t := tok.(type) {
		case xml.Directive:
			return errors.New("XML DOCTYPE/ENTITY directives forbidden")
		case xml.ProcInst:
			if !strings.EqualFold(t.Target, "xml") {
				return errors.New("non-declaration XML processing instruction forbidden")
			}
		case xml.StartElement:
			depth++
			nodes++
			if depth > 24 || nodes > 2000 {
				return errors.New("XML depth or element count exceeded")
			}
		case xml.EndElement:
			depth--
		}
	}
	dec := xml.NewDecoder(bytes.NewReader(raw))
	dec.Strict = true
	dec.Entity = map[string]string{}
	return dec.Decode(dst)
}
