use roxmltree::{Document, NodeType, ParsingOptions};

const XINCLUDE_NS: &str = "http://www.w3.org/2001/XInclude";

pub fn validate_safe_xml_doc(xml_str: &str) -> Result<usize, &'static str> {
    if xml_str.is_empty() || xml_str.len() > 262_144 {
        return Err("XML payload outside [1, 262144] byte limit");
    }
    let opts = ParsingOptions {
        allow_dtd: false,
        nodes_limit: 2048,
    };
    let doc = Document::parse_with_options(xml_str, opts)
        .map_err(|_| "XML rejected (DTD forbidden, malformed, or nodes_limit exceeded)")?;
    let mut elem_count = 0usize;
    for node in doc.descendants() {
        match node.node_type() {
            NodeType::PI => return Err("XML processing instructions forbidden"),
            NodeType::Element => {
                elem_count += 1;
                if node.tag_name().namespace() == Some(XINCLUDE_NS) {
                    return Err("XInclude elements forbidden");
                }
            }
            _ => {}
        }
    }
    Ok(elem_count)
}
