  /<!\s*(?:DOCTYPE|ENTITY)\b|<\?\s*xml-stylesheet\b|<\s*(?:[a-z0-9_.-]+:)?include\b[^>]*XInclude/i;

export function assertSafeUtf8XmlProlog(raw: Uint8Array, maxBytes = 262_144): string {
  if (raw.byteLength === 0 || raw.byteLength > maxBytes) {
    throw new Error(`XML payload outside [1, ${maxBytes}] byte limit`);
  }
  if (
    (raw.byteLength >= 2 && ((raw[0] === 0xfe && raw[1] === 0xff) || (raw[0] === 0xff && raw[1] === 0xfe))) ||
    (raw.byteLength >= 4 && raw[0] === 0x2b && raw[1] === 0x2f && raw[2] === 0x76)
  ) {
    throw new Error("UTF-16 and UTF-7 XML encodings forbidden; require UTF-8");
