package jsonrpcguard

import (
	"bytes"
	"context"
	"encoding/json"
	"errors"
	"io"
	"net/http"
	"time"
)

type RPCRequest struct {
	JSONRPC string          `json:"jsonrpc"`
	Method  string          `json:"method"`
	Params  json.RawMessage `json:"params,omitempty"`
	ID      json.RawMessage `json:"id,omitempty"`
}

func ParseBoundedJSONRPC(
	w http.ResponseWriter,
	r *http.Request,
	maxBytes int64,
	maxBatch int,
	budget time.Duration,
) (context.Context, context.CancelFunc, []RPCRequest, error) {
	r.Body = http.MaxBytesReader(w, r.Body, maxBytes)
	raw, err := io.ReadAll(r.Body)
	if err != nil {
		var maxErr *http.MaxBytesError
		if errors.As(err, &maxErr) {
			http.Error(w, "payload too large", http.StatusRequestEntityTooLarge)
			return nil, nil, nil, err
		}
		http.Error(w, "bad request", http.StatusBadRequest)
		return nil, nil, nil, err
	}
	trimmed := bytes.TrimSpace(raw)
	if len(trimmed) == 0 {
		http.Error(w, "empty body", http.StatusBadRequest)
		return nil, nil, nil, errors.New("empty jsonrpc body")
	}
	var calls []RPCRequest
	if trimmed[0] == '[' {
		if err := json.Unmarshal(trimmed, &calls); err != nil || len(calls) == 0 || len(calls) > maxBatch {
			http.Error(w, "invalid or oversized jsonrpc batch", http.StatusBadRequest)
			return nil, nil, nil, errors.New("jsonrpc batch violation")
		}
	} else {
		var single RPCRequest
		if err := json.Unmarshal(trimmed, &single); err != nil {
			http.Error(w, "invalid jsonrpc object", http.StatusBadRequest)
			return nil, nil, nil, err
		}
		calls = []RPCRequest{single}
	}
	ctx, cancel := context.WithTimeout(r.Context(), budget)
	return ctx, cancel, calls, nil
}
