```typescript
export interface JsonRpcCall {
  jsonrpc: "2.0";
  method: string;
  params?: unknown;
  id?: string | number | null;
}

export function parseBoundedJsonRpc(
  rawUtf8: string,
  allowedMethods: ReadonlySet<string>,
  maxBytes = 65536,
  maxBatchSize = 10,
  budgetMs = 2000,
): { calls: JsonRpcCall[]; signal: AbortSignal } {
  if (Buffer.byteLength(rawUtf8, "utf8") > maxBytes) {
    throw new RangeError("JSON-RPC body exceeded maxBytes");
  }
  const parsed: unknown = JSON.parse(rawUtf8);
  const arr = Array.isArray(parsed) ? parsed : [parsed];
  if (arr.length === 0 || arr.length > maxBatchSize) {
    throw new RangeError(`Batch size outside 1..${maxBatchSize}`);
  }
  const calls: JsonRpcCall[] = arr.map((item) => {
    if (typeof item !== "object" || item === null) throw new Error("Invalid RPC item");
    const rec = item as Record<string, unknown>;
    if (rec.jsonrpc !== "2.0" || typeof rec.method !== "string" || !allowedMethods.has(rec.method)) {
      throw new Error("Unsupported or malformed JSON-RPC method");
    }
    return rec as unknown as JsonRpcCall;
  });
  return { calls, signal: AbortSignal.timeout(budgetMs) };
}
