const MAX_CBOR_BSTR: usize = 65_536;

pub fn parse_canonical_cbor_bstr(input: &[u8]) -> IResult<&[u8], &[u8]> {
    let (rest, initial) = verify(nom_u8, |&b| (b >> 5) == 2 && (b & 0x1f) != 31)(input)?;
    let ai = initial & 0x1f;
