        26 => {
            let (r, n) = verify(be_u32, |&v| v >= 65_536 && (v as usize) <= MAX_CBOR_BSTR)(rest)?;
            (r, n as usize)
        }
        _ => return Err(Err::Failure(Error::new(input, ErrorKind::TooLarge))),
    };
    if len > MAX_CBOR_BSTR {
        return Err(Err::Failure(Error::new(input, ErrorKind::TooLarge)));
    }
    take(len)(rest)
