```typescript
export interface RadiusAttr {
  type: number;
  value: Uint8Array;
}

export function parseRadiusPacket(buf: Uint8Array): { code: number; attrs: RadiusAttr[] } {
  if (buf.byteLength < 20 || buf.byteLength > 4096) {
    throw new RangeError("RADIUS packet length out of 20..4096 bounds");
  }
  const view = new DataView(buf.buffer, buf.byteOffset, buf.byteLength);
  const pktLen = view.getUint16(2, false);
  if (pktLen !== buf.byteLength) {
    throw new Error("RADIUS header length does not match datagram bytes");
  }
  const attrs: RadiusAttr[] = [];
  let pos = 20;
  while (pos < pktLen) {
    if (pktLen - pos < 2) {
      throw new RangeError("truncated RADIUS attribute header");
    }
    const aType = buf[pos];
    const aLen = buf[pos + 1];
    if (aLen < 2 || pos + aLen > pktLen) {
      throw new RangeError(`invalid RADIUS attribute length: ${aLen}`);
    }
    attrs.push({ type: aType, value: buf.subarray(pos + 2, pos + aLen) });
    pos += aLen;
  }
  return { code: buf[0], attrs };
}
