use serde_yaml::Value;
use std::collections::HashSet;

fn grants_actions_write(perms: Option<&Value>) -> bool {
    match perms {
        Some(Value::String(s)) => s == "write-all",
        Some(Value::Mapping(m)) => m
            .get(Value::String("actions".into()))
            .and_then(Value::as_str)
            == Some("write"),
        _ => false,
    }
}

pub fn audit_actions_write_scope(
    filename: &str,
    workflow_yaml: &str,
    allowed_files: &HashSet<String>,
) -> Result<Vec<String>, serde_yaml::Error> {
    if allowed_files.contains(filename) {
        return Ok(Vec::new());
    }
    let doc: Value = serde_yaml::from_str(workflow_yaml)?;
    let mut issues = Vec::new();

    if grants_actions_write(doc.get("permissions")) {
        issues.push(format!("{filename}: top-level permissions grant 'actions: write'"));
    }
    if let Some(jobs) = doc.get("jobs").and_then(Value::as_mapping) {
        for (k, job) in jobs {
            if grants_actions_write(job.get("permissions")) {
                let jid = k.as_str().unwrap_or("unknown");
                issues.push(format!("{filename} job '{jid}': grants dangerous 'actions: write' scope"));
            }
        }
    }
    Ok(issues)
}
