use hmac::{Hmac, Mac};
use sha2::Sha256;

type HmacSha256 = Hmac<Sha256>;

pub fn verify_tf_http_lock_mac(
    secret: &[u8],
    method: &str,
    workspace: &str,
    lock_id: &str,
    unix_ts: i64,
    now_unix: i64,
    sig_hex: &str,
) -> bool {
    if (now_unix - unix_ts).abs() > 120 {
        return false;
    }
    let Ok(sig_bytes) = hex::decode(sig_hex.trim()) else {
        return false;
    };
    let Ok(mut mac) = HmacSha256::new_from_slice(secret) else {
        return false;
    };
    let msg = format!("{method}\n{workspace}\n{lock_id}\n{unix_ts}");
    mac.update(msg.as_bytes());
    mac.verify_slice(&sig_bytes).is_ok()
}
