import hashlib
import hmac
import secrets
from dataclasses import dataclass
from typing import Dict, Set

@dataclass
class DPoPRefreshEntry:
    family_id: str
    user_id: str
    dpop_jkt: str
    used: bool = False

class SenderConstrainedRefreshStore:
    def __init__(self) -> None:
        self.entries: Dict[str, DPoPRefreshEntry] = {}
        self.revoked_families: Set[str] = set()

    def _h(self, raw: str) -> str:
        return hashlib.sha256(raw.encode("ascii")).hexdigest()

    def issue(self, user_id: str, dpop_jkt: str) -> str:
        if len(dpop_jkt) != 43:
            raise ValueError("invalid dpop_jkt")
        raw = secrets.token_urlsafe(32)
        fam = secrets.token_hex(16)
        self.entries[self._h(raw)] = DPoPRefreshEntry(fam, user_id, dpop_jkt)
        return raw

    def rotate(self, raw_rt: str, proof_jkt: str) -> str:
        rec = self.entries.get(self._h(raw_rt))
        if not rec or rec.family_id in self.revoked_families:
            raise PermissionError("invalid or revoked refresh token")
        if rec.used or not hmac.compare_digest(rec.dpop_jkt.encode("ascii"), proof_jkt.encode("ascii")):
            self.revoked_families.add(rec.family_id)
            raise PermissionError("sender-constraint mismatch or reuse; family revoked")
        rec.used = True
        nxt = secrets.token_urlsafe(32)
        self.entries[self._h(nxt)] = DPoPRefreshEntry(rec.family_id, rec.user_id, rec.dpop_jkt)
        return nxt
