		got := base64.RawURLEncoding.EncodeToString(sum[:])
		if subtle.ConstantTimeCompare([]byte(pinnedX5t), []byte(got)) != 1 {
			return errors.New("mTLS x5t#S256 mismatch on refresh grant")
