type noListNoDotFS struct{ inner fs.FS }

func (s noListNoDotFS) Open(name string) (fs.File, error) {
	for _, seg := range strings.Split(name, "/") {
		if len(seg) > 1 && strings.HasPrefix(seg, ".") {
			return nil, fs.ErrNotExist
		}
