use cap_std::fs::Dir;
use std::io::{self, Read};
use std::path::{Component, Path};

pub fn load_static_asset(root: &Dir, req_path: &str, max_bytes: u64) -> io::Result<Vec<u8>> {
    let trimmed = req_path.trim_start_matches('/');
    let rel = if trimmed.is_empty() { Path::new("index.html") } else { Path::new(trimmed) };

    for comp in rel.components() {
        match comp {
            Component::Normal(seg) => {
                let s = seg.to_str().ok_or_else(|| io::Error::new(io::ErrorKind::InvalidInput, "utf8"))?;
                if s.starts_with('.') {
                    return Err(io::Error::new(io::ErrorKind::NotFound, "dotfile blocked"));
                }
            }
            _ => return Err(io::Error::new(io::ErrorKind::PermissionDenied, "traversal blocked")),
        }
    }
    let meta = root.symlink_metadata(rel)?;
    if !meta.is_file() || meta.len() > max_bytes {
        return Err(io::Error::new(io::ErrorKind::NotFound, "not a bounded regular file"));
    }
    let mut buf = Vec::with_capacity(meta.len() as usize);
    root.open(rel)?.take(max_bytes).read_to_end(&mut buf)?;
    Ok(buf)
}
