func SignRSAPSSVerified(priv *rsa.PrivateKey, message []byte) ([]byte, error) {
	if priv == nil || priv.N.BitLen() < 3072 {
		return nil, errors.New("RSA key nil or below 3072 bits")
	}
	if err := priv.Validate(); err != nil {
		return nil, err
	}

	digest := sha256.Sum256(message)
	opts := &rsa.PSSOptions{
		SaltLength: rsa.PSSSaltLengthEqualsHash,
		Hash:       crypto.SHA256,
	}

	sig, err := rsa.SignPSS(rand.Reader, priv, crypto.SHA256, digest[:], opts)
	if err != nil {
		return nil, err
	}

	if err := rsa.VerifyPSS(&priv.PublicKey, crypto.SHA256, digest[:], sig, opts); err != nil {
		return nil, errors.New("post-sign RSA-PSS CRT fault check failed")
	}
	return sig, nil
}
