use sha2::{Digest, Sha256};
use std::collections::VecDeque;
use subtle::ConstantTimeEq;

pub fn verify_multiproof(
    tree_size: u64,
    leaf_indices: &[u64],
    leaf_payloads: &[&[u8]],
    aux_proof: &[[u8; 32]],
    expected_root: &[u8; 32],
) -> bool {
    if !tree_size.is_power_of_two() || leaf_indices.is_empty() || leaf_indices.len() != leaf_payloads.len() {
        return false;
    }

    let mut queue: VecDeque<(u64, [u8; 32])> = VecDeque::with_capacity(leaf_indices.len());
    for (i, &idx) in leaf_indices.iter().enumerate() {
        if idx >= tree_size || (i > 0 && idx <= leaf_indices[i - 1]) {
            return false;
        }
        let mut h = Sha256::new();
        h.update([0x00]);
        h.update(leaf_payloads[i]);
        queue.push_back((tree_size + idx, h.finalize().into()));
    }

    let mut aux_cur = 0usize;
    while let Some((pos, hash)) = queue.pop_front() {
        if pos == 1 {
            return queue.is_empty()
                && aux_cur == aux_proof.len()
                && bool::from(hash.ct_eq(expected_root));
        }

        let (left, right) = if (pos & 1) == 0 {
            let r = if queue.front().map(|&(p, _)| p == (pos ^ 1)).unwrap_or(false) {
                queue.pop_front().unwrap().1
            } else if aux_cur < aux_proof.len() {
                let s = aux_proof[aux_cur];
                aux_cur += 1;
                s
            } else {
                return false;
            };
            (hash, r)
        } else if aux_cur < aux_proof.len() {
            let l = aux_proof[aux_cur];
            aux_cur += 1;
            (l, hash)
        } else {
            return false;
        };

        let mut ph = Sha256::new();
        ph.update([0x01]);
        ph.update(left);
        ph.update(right);
        queue.push_back((pos >> 1, ph.finalize().into()));
    }
    false
}
