const SECP256K1_N = 0xfffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141n;

function hmacSha256(key: Buffer, ...parts: Buffer[]): Buffer {
  const mac = createHmac("sha256", key);
  for (const p of parts) mac.update(p);
  return mac.digest();
}

function to32BytesBE(val: bigint): Buffer {
  return Buffer.from(val.toString(16).padStart(64, "0"), "hex");
}

export function rfc6979Secp256k1Nonce(privScalar: bigint, msgDigest32: Buffer): bigint {
  if (privScalar <= 0n || privScalar >= SECP256K1_N || msgDigest32.length !== 32) {
    throw new RangeError("invalid secp256k1 private scalar or 32-byte digest");
  }

  const xOct = to32BytesBE(privScalar);
  const h1Mod = BigInt("0x" + msgDigest32.toString("hex")) % SECP256K1_N;
  const h1Oct = to32BytesBE(h1Mod);

  let k = Buffer.alloc(32, 0x00);
  let v = Buffer.alloc(32, 0x01);

  k = hmacSha256(k, v, Buffer.from([0x00]), xOct, h1Oct);
  v = hmacSha256(k, v);
  k = hmacSha256(k, v, Buffer.from([0x01]), xOct, h1Oct);
  v = hmacSha256(k, v);

  while (true) {
    v = hmacSha256(k, v);
    const cand = BigInt("0x" + v.toString("hex"));
    if (cand >= 1n && cand < SECP256K1_N) {
      return cand;
    }
    k = hmacSha256(k, v, Buffer.from([0x00]));
    v = hmacSha256(k, v);
  }
}
