func VerifyWGInitiationMAC1(pkt []byte, responderStaticPub [32]byte) bool {
	if len(pkt) != 148 || binary.LittleEndian.Uint32(pkt[0:4]) != 1 {
		return false
	}
	hKey, err := blake2s.New256(nil)
	if err != nil {
