	_, _ = hKey.Write([]byte("mac1----"))
	_, _ = hKey.Write(responderStaticPub[:])
	mac1Key := hKey.Sum(nil)

	mac, err := blake2s.New128(mac1Key)
	if err != nil {
		return false
	}
	_, _ = mac.Write(pkt[:116])
	expected := mac.Sum(nil)
	return subtle.ConstantTimeCompare(expected, pkt[116:132]) == 1
}
