```typescript
const LDH_HOST_RE = /^(?!-)[a-zA-Z0-9-]{1,63}(?<!-)(\.(?!-)[a-zA-Z0-9-]{1,63}(?<!-))*$/;

export function extractSniHostname(ext: Uint8Array): string {
  if (ext.byteLength < 6) {
    throw new RangeError("undersized TLS SNI extension");
  }
  const view = new DataView(ext.buffer, ext.byteOffset, ext.byteLength);
  const listLen = view.getUint16(0, false);
  const nameType = view.getUint8(2);
  const hostLen = view.getUint16(3, false);
  if (listLen + 2 !== ext.byteLength || nameType !== 0x00 || hostLen + 5 !== ext.byteLength) {
    throw new Error("malformed TLS SNI nested lengths or name_type");
  }
  if (hostLen === 0 || hostLen > 253) {
    throw new RangeError("TLS SNI hostname length out of 1..253 bounds");
  }
  const host = new TextDecoder("utf-8", { fatal: true }).decode(ext.subarray(5, 5 + hostLen));
  if (!LDH_HOST_RE.test(host)) {
    throw new Error("invalid characters or label structure in TLS SNI");
  }
  return host.toLowerCase();
}
