use std::collections::HashMap;

pub fn check_oci_provenance_labels(dockerfile: &str) -> Vec<String> {
    let mut labels = HashMap::new();
    for raw in dockerfile.lines() {
        let line = raw.trim();
        if !line.get(..6).map(|p| p.eq_ignore_ascii_case("LABEL ")).unwrap_or(false) {
            continue;
        }
        for tok in line[6..].split_whitespace() {
            if let Some((k, v)) = tok.split_once('=') {
                let clean_k = k.trim_matches('"');
                let clean_v = v.trim_matches('"').trim_matches('\'');
                labels.insert(clean_k.to_string(), clean_v.to_string());
            }
        }
    }

    let mut errs = Vec::new();
    match labels.get("org.opencontainers.image.source") {
        Some(u) if u.starts_with("https://") => {}
        Some(u) => errs.push(format!("org.opencontainers.image.source must use https:// ('{u}')")),
        None => errs.push("missing LABEL org.opencontainers.image.source".into()),
    }
    match labels.get("org.opencontainers.image.revision") {
        Some(rev) if !rev.is_empty() => {}
        _ => errs.push("missing or empty LABEL org.opencontainers.image.revision".into()),
    }
    errs
}
