var insecureCurlRe = regexp.MustCompile(`\bcurl\b[^\n;|]*(?:\s-k\b|\s--insecure\b)`)

func AuditInsecureCurlInRun(raw []byte) ([]string, error) {
	var root yaml.Node
	if err := yaml.Unmarshal(raw, &root); err != nil {
		return nil, err
	}
	var findings []string
	var visit func(n *yaml.Node)
	visit = func(n *yaml.Node) {
		if n == nil {
			return
		}
		if n.Kind == yaml.MappingNode {
			for i := 0; i+1 < len(n.Content); i += 2 {
				k, v := n.Content[i], n.Content[i+1]
				if k.Value == "run" && v.Kind == yaml.ScalarNode {
					if m := insecureCurlRe.FindString(v.Value); m != "" {
						findings = append(findings, fmt.Sprintf("%d:%d insecure TLS bypass in curl command (%q)", v.Line, v.Column, m))
					}
				} else {
					visit(v)
				}
			}
			return
		}
		for _, c := range n.Content {
			visit(c)
		}
	}
	visit(&root)
	return findings, nil
}
