UNSAFE_VAL_RE = re.compile(r"(?:javascript:|data:|vbscript:|expression\s*\(|@import|url\s*\(\s*['\"]?(?!#[A-Za-z_]))", re.I)

def _split_ns(tag: str) -> tuple[str, str]:
    if tag.startswith("{"):
        ns, local = tag[1:].split("}", 1)
        return ns, local
    return "", tag

def _clean_node(src: Element, depth: int) -> Element | None:
    if depth > 16:
        raise ValueError("SVG nesting depth exceeds 16")
    ns, local = _split_ns(src.tag)
    if ns not in (SVG_NS, "") or local not in ALLOWED_TAGS:
        return None
    clean_attrs: dict[str, str] = {}
    for raw_k, raw_v in src.attrib.items():
        k_ns, k_local = _split_ns(raw_k)
        val = raw_v.strip()
