            continue
        if k_local in ("href",) and SAFE_FRAGMENT_RE.fullmatch(val):
            clean_attrs["href"] = val
        elif k_ns == "" and k_local in ALLOWED_ATTRS:
            clean_attrs[k_local] = val
    dst = Element(f"{{{SVG_NS}}}{local}", clean_attrs)
    if local == "title" and src.text:
        dst.text = src.text[:120]
    for child in list(src):
        cleaned = _clean_node(child, depth + 1)
        if cleaned is not None:
            dst.append(cleaned)
    return dst

def sanitize_svg_bytes(raw_svg: bytes, max_bytes: int = 65536) -> bytes:
    if not raw_svg or len(raw_svg) > max_bytes:
        raise ValueError("SVG empty or exceeds 64 KiB")
    register_namespace("", SVG_NS)
    root = DefusedET.fromstring(raw_svg, forbid_dtd=True, forbid_entities=True, forbid_external=True)
    _, root_local = _split_ns(root.tag)
    if root_local != "svg":
        raise ValueError("root element must be <svg>")
    cleaned = _clean_node(root, 1)
    if cleaned is None:
        raise ValueError("SVG root rejected by allowlist")
