```go
package svgsafe

import (
	"bytes"
	"encoding/xml"
	"errors"
	"io"
	"strings"
)

var allowedTags = map[string]bool{
	"svg": true, "g": true, "path": true, "rect": true, "circle": true, "line": true, "polygon": true,
}

var allowedAttrs = map[string]bool{
	"xmlns": true, "viewbox": true, "width": true, "height": true, "d": true,
	"x": true, "y": true, "cx": true, "cy": true, "r": true, "points": true,
	"fill": true, "stroke": true, "stroke-width": true, "opacity": true,
}

func ValidateSafeStaticSVG(raw []byte) error {
	if len(raw) == 0 || len(raw) > 65536 {
		return errors.New("SVG size outside [1, 65536] bytes")
	}
	dec := xml.NewDecoder(bytes.NewReader(raw))
	dec.Strict = true
	dec.Entity = map[string]string{}
	sawRoot := false
	for {
		tok, err := dec.RawToken()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return err
		}
		switch t := tok.(type) {
		case xml.Directive, xml.ProcInst:
			return errors.New("SVG directives and processing instructions forbidden")
		case xml.StartElement:
			name := strings.ToLower(t.Name.Local)
			if !sawRoot && name != "svg" {
				return errors.New("root element must be <svg>")
			}
			sawRoot = true
			if t.Name.Space != "" || !allowedTags[name] {
				return errors.New("disallowed SVG element or namespace prefix")
			}
			for _, a := range t.Attr {
				ak := strings.ToLower(a.Name.Local)
				av := strings.ToLower(strings.TrimSpace(a.Value))
				if a.Name.Space != "" || strings.HasPrefix(ak, "on") || !allowedAttrs[ak] {
					return errors.New("disallowed SVG attribute")
				}
				if ak != "xmlns" && (strings.Contains(av, ":") || strings.Contains(av, "url(")) {
					return errors.New("URI or CSS url() forbidden in static SVG attribute")
				}
			}
		}
	}
	if !sawRoot {
		return errors.New("empty SVG document")
	}
	return nil
}
