```go
package multitenant

import (
	"errors"
	"sync"
	"time"
)

type IssuerBucket struct {
	mu        sync.Mutex
	keys      map[string][]byte
	lastFetch time.Time
}

type PartitionedJWKS struct {
	mu       sync.RWMutex
	buckets  map[string]*IssuerBucket
	cooldown time.Duration
}

func (p *PartitionedJWKS) LookupOrRefresh(issuer, kid string, fetch func(string) (map[string][]byte, error)) ([]byte, error) {
	p.mu.RLock()
	b, ok := p.buckets[issuer]
	p.mu.RUnlock()
	if !ok {
		return nil, errors.New("untrusted issuer")
	}
	b.mu.Lock()
	defer b.mu.Unlock()
	if k, hit := b.keys[kid]; hit {
		return k, nil
	}
	if time.Since(b.lastFetch) < p.cooldown {
		return nil, errors.New("tenant jwks refresh in cooldown")
	}
	fresh, err := fetch(issuer)
	if err != nil {
		return nil, err
	}
	b.keys = fresh
	b.lastFetch = time.Now()
	k, hit := b.keys[kid]
	if !hit {
		return nil, errors.New("unknown kid for issuer")
	}
	return k, nil
}
