package apiauth

import (
	"bytes"
	"crypto"
	"crypto/ed25519"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"net/http"
	"strconv"
	"time"
)

func VerifyAPIRequestEd25519ctx(w http.ResponseWriter, r *http.Request, pub ed25519.PublicKey, maxBody int64) ([]byte, error) {
	if len(pub) != ed25519.PublicKeySize {
		return nil, errors.New("invalid ed25519 pubkey size")
	}
	jti := r.Header.Get("X-Nonce-JTI")
	tsStr := r.Header.Get("X-Timestamp")
	sigHex := r.Header.Get("X-Sig-Ed25519ctx")
	if len(jti) < 16 || len(jti) > 64 {
		return nil, errors.New("invalid jti length")
	}
	ts, err := strconv.ParseInt(tsStr, 10, 64)
	if err != nil || abs64(time.Now().Unix()-ts) > 60 {
		return nil, errors.New("stale or invalid timestamp")
	}
	sig, err := hex.DecodeString(sigHex)
	if err != nil || len(sig) != ed25519.SignatureSize {
		return nil, errors.New("invalid signature encoding")
	}
	r.Body = http.MaxBytesReader(w, r.Body, maxBody)
	body, err := io.ReadAll(r.Body)
	if err != nil {
		return nil, err
	}
	bodyHash := sha256.Sum256(body)
	canonical := fmt.Sprintf("%s\n%s\n%s\n%s\n%x", r.Method, r.URL.RequestURI(), jti, tsStr, bodyHash)
	opts := &ed25519.Options{Hash: crypto.Hash(0), Context: "api-req-v1"}
	if err := ed25519.VerifyWithOptions(pub, []byte(canonical), sig, opts); err != nil {
		return nil, err
	}
	r.Body = io.NopCloser(bytes.NewReader(body))
	return body, nil
}

func abs64(x int64) int64 {
	if x < 0 {
		return -x
	}
	return x
}
