import hashlib
import time

class JtiReplayGuard:
    def __init__(self, ttl_s: int = 60, max_entries: int = 50_000) -> None:
        self.ttl_s = ttl_s
        self.max_entries = max_entries
        self._seen: dict[str, int] = {}

    def build_and_check(self, method: str, request_uri: str, jti: str, ts_str: str, body: bytes) -> bytes:
        now = int(time.time())
        ts = int(ts_str)
        if abs(now - ts) > self.ttl_s:
            raise PermissionError("timestamp outside 60s window")
        if len(self._seen) >= self.max_entries:
            cutoff = now - self.ttl_s
            self._seen = {k: v for k, v in self._seen.items() if v >= cutoff}
            if len(self._seen) >= self.max_entries:
                raise BufferError("replay cache saturated")
        exp = self._seen.get(jti)
        if exp is not None and exp >= (now - self.ttl_s):
            raise PermissionError("replayed jti rejected")
        self._seen[jti] = ts
        digest = hashlib.sha256(body).hexdigest()
        return f"{method.upper()}\n{request_uri}\n{jti}\n{ts_str}\n{digest}".encode("utf-8")
