import { ed25519ctx } from "@noble/curves/ed25519";
import { createHash, randomBytes } from "node:crypto";

export function signApiRequestEd25519ctx(
  privSeed32: Uint8Array,
  method: string,
  requestUri: string,
  body: Buffer,
): Record<string, string> {
