  const ts = Math.floor(Date.now() / 1000).toString();
  const bodyHex = createHash("sha256").update(body).digest("hex");
  const canonical = Buffer.from(`${method.toUpperCase()}\n${requestUri}\n${jti}\n${ts}\n${bodyHex}`, "utf8");
  const sig = ed25519ctx.sign(canonical, privSeed32, { context: Buffer.from("api-req-v1", "utf8") });
  return {
