import { z } from "zod";

const SessionClaimsSchema = z
  .object({
    jti: z.string().uuid(),
    sub: z.string().min(1).max(64),
    exp: z.number().int().positive(),
  })
  .strict();

const COOKIE_AAD = new TextEncoder().encode("cookie:__Host-sess");

export async function sealHostSessionCookie(
  key: CryptoKey,
  claims: z.infer<typeof SessionClaimsSchema>,
): Promise<string> {
  const valid = SessionClaimsSchema.parse(claims);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const pt = new TextEncoder().encode(JSON.stringify(valid));
  const ct = new Uint8Array(
    await crypto.subtle.encrypt({ name: "AES-GCM", iv, additionalData: COOKIE_AAD, tagLength: 128 }, key, pt),
  );
  const out = new Uint8Array(12 + ct.byteLength);
  out.set(iv, 0);
  out.set(ct, 12);
  return Buffer.from(out).toString("base64url");
}

export async function openHostSessionCookie(
  key: CryptoKey,
  cookieVal: string,
  nowSec = Math.floor(Date.now() / 1000),
) {
  const raw = Buffer.from(cookieVal, "base64url");
  if (raw.byteLength < 28) throw new Error("truncated __Host-sess cookie");
  const pt = await crypto.subtle.decrypt(
    { name: "AES-GCM", iv: raw.subarray(0, 12), additionalData: COOKIE_AAD, tagLength: 128 },
    key,
    raw.subarray(12),
  );
  const claims = SessionClaimsSchema.parse(JSON.parse(new TextDecoder().decode(pt)));
  if (claims.exp <= nowSec) throw new Error("expired __Host-sess cookie");
  return claims;
}
