import struct

def read_canonical_cbor_uint(buf: bytes, offset: int = 0) -> tuple[int, int]:
    mv = memoryview(buf)
    if offset >= len(mv):
        raise ValueError("empty CBOR slice")
    b0 = mv[offset]
    if (b0 >> 5) != 0:
        raise ValueError("expected CBOR major type 0 unsigned int")
    ai = b0 & 0x1F
    if ai < 24:
        return ai, offset + 1
    specs = {24: (">B", 1, 24), 25: (">H", 2, 256), 26: (">I", 4, 65_536), 27: (">Q", 8, 1 << 32)}
    if ai not in specs:
        raise ValueError(f"invalid or indefinite CBOR additional info: {ai}")
    fmt, width, min_val = specs[ai]
    if len(mv) - (offset + 1) < width:
        raise ValueError("truncated CBOR integer payload")
    (val,) = struct.unpack_from(fmt, mv, offset + 1)
    if val < min_val:
        raise ValueError("non-canonical overlong CBOR integer encoding")
    return val, offset + 1 + width
