pub struct RadiusPacket<'a> {
    pub code: u8,
    pub identifier: u8,
    pub authenticator: &'a [u8],
    pub attrs: Vec<(u8, &'a [u8])>,
}

fn parse_radius_attr(input: &[u8]) -> IResult<&[u8], (u8, &[u8])> {
