```typescript
import { KeyObject, verify } from "node:crypto";

export function verifyRpcEnvelopeEd25519(
  frame: Uint8Array,
  pubKey: KeyObject,
  nowSec = Math.floor(Date.now() / 1000),
): { nonce: Uint8Array; payload: Uint8Array } {
  if (frame.byteLength < 89 || frame[0] !== 1) {
    throw new Error("invalid or undersized v1 RPC envelope");
  }
  const view = new DataView(frame.buffer, frame.byteOffset, frame.byteLength);
  const tsSec = Number(view.getBigUint64(1, false));
  if (!Number.isSafeInteger(tsSec) || Math.abs(nowSec - tsSec) > 60) {
    throw new Error("RPC envelope timestamp outside 60s replay window");
  }
  const signedBytes = frame.subarray(0, frame.byteLength - 64);
  const sigBytes = frame.subarray(frame.byteLength - 64);
  if (!verify(null, signedBytes, pubKey, sigBytes)) {
    throw new Error("Ed25519 RPC envelope signature invalid");
  }
  return {
    nonce: frame.subarray(9, 25),
    payload: frame.subarray(25, frame.byteLength - 64),
  };
}
