import os
from typing import Callable, TypeVar

T = TypeVar("T")

def split_key_xor(secret: bytes) -> tuple[bytes, bytes]:
    if len(secret) < 16:
        raise ValueError("secret must be at least 16 bytes")
    share_a = os.urandom(len(secret))
    share_b = bytes(a ^ b for a, b in zip(share_a, secret))
    return share_a, share_b

def with_reconstructed_key(
    share_a: bytes,
    share_b: bytes,
    fn: Callable[[memoryview], T],
) -> T:
    if len(share_a) != len(share_b) or not share_a:
        raise ValueError("mismatched or empty XOR key shares")
    buf = bytearray(a ^ b for a, b in zip(share_a, share_b))
    try:
        return fn(memoryview(buf))
    finally:
        buf[:] = b"\x00" * len(buf)
