```typescript
import * as readline from "node:readline";
import { Readable } from "node:stream";

interface SecretFetchEvent {
  eventTime?: string;
  eventSource?: string;
  eventName?: string;
  userIdentity?: { arn?: string };
}

export async function secretSweepJitter(
  input: Readable,
  minFetches = 6
): Promise<Record<string, { count: number; pstdevSec: number }>> {
  const byArn = new Map<string, number[]>();
  const rl = readline.createInterface({ input, crlfDelay: Infinity });
  for await (const line of rl) {
    if (!line.trim()) continue;
    const ev = JSON.parse(line) as SecretFetchEvent;
    if (
      ev.eventSource !== "secretsmanager.amazonaws.com" ||
      ev.eventName !== "GetSecretValue" ||
      !ev.eventTime
    ) {
      continue;
    }
    const arn = ev.userIdentity?.arn ?? "unknown";
    const sec = Date.parse(ev.eventTime) / 1000;
    if (!Number.isNaN(sec)) {
      const arr = byArn.get(arn) ?? [];
      arr.push(sec);
      byArn.set(arn, arr);
    }
  }
  const out: Record<string, { count: number; pstdevSec: number }> = {};
  for (const [arn, ts] of byArn) {
    if (ts.length < minFetches) continue;
    ts.sort((a, b) => a - b);
    const deltas = ts.slice(1).map((t, i) => t - ts[i]);
    const mean = deltas.reduce((s, d) => s + d, 0) / deltas.length;
    const variance = deltas.reduce((s, d) => s + (d - mean) ** 2, 0) / deltas.length;
    out[arn] = { count: ts.length, pstdevSec: Number(Math.sqrt(variance).toFixed(4)) };
  }
  return out;
}
