func AssertXSWResistantSAML(raw []byte) error {
	if len(raw) == 0 || len(raw) > 131072 {
		return errors.New("SAML XML size out of bounds")
	}
	dec := xml.NewDecoder(bytes.NewReader(raw))
	dec.Strict = true
	dec.Entity = map[string]string{}
	seenIDs := make(map[string]struct{})
	assertions := 0
	for {
		tok, err := dec.RawToken()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return err
		}
		switch t := tok.(type) {
		case xml.Directive, xml.Comment:
			return errors.New("XML directives and comments forbidden in SAML")
		case xml.StartElement:
			if t.Name.Local == "Assertion" {
				assertions++
			}
			for _, a := range t.Attr {
				if strings.EqualFold(a.Name.Local, "id") {
					if _, dup := seenIDs[a.Value]; dup || a.Value == "" {
						return errors.New("empty or duplicate XML ID attribute (XSW risk)")
					}
					seenIDs[a.Value] = struct{}{}
				}
			}
		}
	}
	if assertions != 1 {
		return errors.New("SAML payload must contain exactly one Assertion")
	}
	return nil
