use roxmltree::{Document, NodeType, ParsingOptions};

pub fn verify_saml_reference_binding(xml_str: &str) -> Result<String, &'static str> {
    let doc = Document::parse_with_options(
        xml_str,
        ParsingOptions { allow_dtd: false, nodes_limit: 1024 },
    )
    .map_err(|_| "invalid SAML XML or DTD present")?;

    if doc.descendants().any(|n| n.node_type() == NodeType::Comment) {
        return Err("XML comments forbidden in SAML response");
    }
    let assertions: Vec<_> = doc
        .descendants()
        .filter(|n| n.is_element() && n.tag_name().name() == "Assertion")
        .collect();
    if assertions.len() != 1 {
        return Err("expected exactly one Assertion element");
    }
    let id = assertions[0].attribute("ID").ok_or("Assertion missing ID")?;
    if id.is_empty() {
        return Err("empty Assertion ID");
    }
    let refs: Vec<_> = doc
        .descendants()
        .filter(|n| n.is_element() && n.tag_name().name() == "Reference")
        .collect();
    if refs.len() != 1 {
        return Err("expected exactly one ds:Reference element");
    }
    let uri = refs[0].attribute("URI").ok_or("ds:Reference missing URI")?;
    let expected = format!("#{id}");
    if uri != expected {
        return Err("ds:Reference URI does not bind sole Assertion ID (XSW detected)");
    }
    Ok(id.to_string())
}
