import { X509Certificate, timingSafeEqual } from "node:crypto";

export function verifyPinnedSamlIdpCert(
  embeddedCertBase64: string,
  pinnedIdpPem: string,
  nowMs: number = Date.now(),
): X509Certificate {
  const cleanB64 = embeddedCertBase64.replace(/\s+/g, "");
  const der = Buffer.from(cleanB64, "base64");
  const presented = new X509Certificate(der);
  const pinned = new X509Certificate(pinnedIdpPem);

  const a = Buffer.from(presented.fingerprint256, "utf8");
  const b = Buffer.from(pinned.fingerprint256, "utf8");
  if (a.length !== b.length || !timingSafeEqual(a, b)) {
    throw new Error("Embedded SAML KeyInfo X509Certificate does not match pinned IdP certificate");
  }
  if (nowMs < Date.parse(pinned.validFrom) || nowMs > Date.parse(pinned.validTo)) {
    throw new Error("Pinned IdP X509Certificate is expired or not yet valid");
  }
  return pinned;
}
