use serde_json::Value;

pub fn audit_ecr_repositories(plan_json: &str) -> Result<Vec<String>, serde_json::Error> {
    let plan: Value = serde_json::from_str(plan_json)?;
    let mut errs = Vec::new();
    let Some(changes) = plan.get("resource_changes").and_then(Value::as_array) else {
        return Ok(errs);
    };

    for rc in changes {
        if rc.get("type").and_then(Value::as_str) != Some("aws_ecr_repository") {
            continue;
        }
        let is_del = rc
            .pointer("/change/actions")
            .and_then(Value::as_array)
            .map(|a| a.len() == 1 && a[0].as_str() == Some("delete"))
            .unwrap_or(false);
        if is_del {
            continue;
        }
        let addr = rc.get("address").and_then(Value::as_str).unwrap_or("unknown");
        let Some(after) = rc.pointer("/change/after") else {
            continue;
        };
        if after.get("image_tag_mutability").and_then(Value::as_str) != Some("IMMUTABLE") {
            errs.push(format!("{addr}: image_tag_mutability must be IMMUTABLE"));
        }
        let scan_ok = after
            .get("image_scanning_configuration")
            .and_then(Value::as_array)
            .map(|arr| arr.iter().any(|c| c.get("scan_on_push").and_then(Value::as_bool) == Some(true)))
            .unwrap_or(false);
        if !scan_ok {
            errs.push(format!("{addr}: image_scanning_configuration.scan_on_push must be true"));
        }
        let kms_ok = after
            .get("encryption_configuration")
            .and_then(Value::as_array)
            .map(|arr| {
