const PACKAGE_RE = /^\s*package\s+([a-zA-Z0-9_.]+)/m;
const TEST_RULE_RE = /^\s*test_[a-zA-Z0-9_]+\s+if\b|^\s*test_[a-zA-Z0-9_]+\s*\{/m;

export function verifyRegoTestSuite(files: Record<string, string>): string[] {
  const missing: string[] = [];
  for (const [path, src] of Object.entries(files)) {
    if (!path.endsWith(".rego") || path.endsWith("_test.rego")) continue;
    const pkgMatch = PACKAGE_RE.exec(src);
    const pkg = pkgMatch?.[1] ?? "";
    const testPath = path.replace(/\.rego$/, "_test.rego");
    const testSrc = files[testPath];

    if (!testSrc) {
      missing.push(`${path} (package ${pkg}): missing companion test file '${testPath}'`);
      continue;
    }
    const testPkg = PACKAGE_RE.exec(testSrc)?.[1] ?? "";
    if (testPkg !== pkg) {
      missing.push(`${testPath}: package '${testPkg}' does not match '${pkg}' in ${path}`);
    }
    if (!TEST_RULE_RE.test(testSrc)) {
      missing.push(`${testPath}: contains no 'test_*' Rego unit test rules`);
    }
  }
  return missing;
}
