import ast

class ActionEntrypointAuditor(ast.NodeVisitor):
    def __init__(self) -> None:
        self.tainted_vars: set[str] = set()
        self.findings: list[tuple[int, str]] = []

    def _is_input_env_lookup(self, node: ast.AST) -> bool:
        src = ast.unparse(node)
        return "os.environ" in src and "INPUT_" in src

    def visit_Assign(self, node: ast.Assign) -> None:
        if self._is_input_env_lookup(node.value):
            for t in node.targets:
                if isinstance(t, ast.Name):
                    self.tainted_vars.add(t.id)
        self.generic_visit(node)

    def visit_Call(self, node: ast.Call) -> None:
        if isinstance(node.func, ast.Name) and node.func.id in {"eval", "exec"}:
            self.findings.append((node.lineno, f"forbidden {node.func.id}() dynamic code execution in Action entrypoint"))
        elif isinstance(node.func, ast.Attribute) and isinstance(node.func.value, ast.Name):
            if node.func.value.id == "subprocess":
                for arg in node.args:
                    names = {n.id for n in ast.walk(arg) if isinstance(n, ast.Name)}
                    if (names & self.tainted_vars) or self._is_input_env_lookup(arg):
                        self.findings.append((node.lineno, f"tainted INPUT_* env passed to subprocess.{node.func.attr}()"))
        self.generic_visit(node)

def audit_action_entrypoint(source: str) -> list[tuple[int, str]]:
    auditor = ActionEntrypointAuditor()
    auditor.visit(ast.parse(source))
    return auditor.findings
