const SAFE_JTI_RE = /^[\x21-\x7E]{16,128}$/;

export class BoundedJtiReplayGuard {
  private store = new Map<string, number>();
  private readonly replayTtlMs: number;

  constructor(maxIatAgeSec = 60, maxFutureSkewSec = 5, private readonly maxSize = 25_000) {
    this.replayTtlMs = (maxIatAgeSec + maxFutureSkewSec + 5) * 1000;
  }

  consume(jkt: string, jti: string, nowMs = Date.now()): void {
    if (!SAFE_JTI_RE.test(jti)) {
      throw new Error("malformed or weak-length DPoP jti");
    }
    const composite = `${jkt}:${jti}`;
    const existingExp = this.store.get(composite);
    if (existingExp !== undefined && existingExp > nowMs) {
      throw new Error("DPoP jti replay detected");
    }
    if (this.store.size >= this.maxSize) {
      for (const [k, exp] of this.store) {
        if (exp <= nowMs) this.store.delete(k);
      }
      if (this.store.size >= this.maxSize) {
        throw new Error("DPoP replay cache full; failing closed");
      }
    }
    this.store.set(composite, nowMs + this.replayTtlMs);
  }
}
