package procguard

import (
	"bytes"
	"context"
	"os"
	"os/exec"
	"syscall"
	"time"
)

func RunConfinedJob(
	parent context.Context,
	workDir string,
	binPath string,
	args []string,
	input []byte,
	budget time.Duration,
) ([]byte, error) {
	ctx, cancel := context.WithTimeout(parent, budget)
	defer cancel()

	root, err := os.OpenRoot(workDir)
	if err != nil {
		return nil, err
	}
	defer root.Close()

	f, err := root.OpenFile("input.bin", os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o600)
	if err != nil {
		return nil, err
	}
	if _, err := f.Write(input); err != nil {
		_ = f.Close()
		return nil, err
	}
	_ = f.Close()
	stopScrub := context.AfterFunc(ctx, func() {
		_ = root.Remove("input.bin")
	})
	defer func() {
		stopScrub()
		_ = root.Remove("input.bin")
	}()

	cmd := exec.CommandContext(ctx, binPath, args...)
	cmd.Dir = workDir
	cmd.Env = []string{"LC_ALL=C"}
	cmd.SysProcAttr = &syscall.SysProcAttr{Setpgid: true}
	cmd.Cancel = func() error {
		return syscall.Kill(-cmd.Process.Pid, syscall.SIGKILL)
	}
	cmd.WaitDelay = 500 * time.Millisecond

	var stdout bytes.Buffer
	cmd.Stdout = &stdout
	if err := cmd.Run(); err != nil {
		return nil, err
	}
	return stdout.Bytes(), nil
}
