use std::path::Path;
use std::process::Stdio;
use std::time::Duration;
use tokio::io::AsyncReadExt;
use tokio::process::Command;
use tokio::time::timeout;

pub async fn run_bounded_command(
    bin: &Path,
    args: &[&str],
    work_dir: &Path,
    budget: Duration,
    max_out: usize,
) -> Result<Vec<u8>, &'static str> {
    let mut child = Command::new(bin)
        .args(args)
        .current_dir(work_dir)
        .env_clear()
        .stdin(Stdio::null())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .kill_on_drop(true)
        .spawn()
        .map_err(|_| "spawn failed")?;

    timeout(budget, async {
        let mut stdout = child.stdout.take().ok_or("missing stdout")?;
        let mut buf = Vec::new();
        stdout.take((max_out + 1) as u64).read_to_end(&mut buf).await.map_err(|_| "read err")?;
        let _ = child.wait().await;
        if buf.len() > max_out {
            return Err("stdout exceeded max_out");
        }
        Ok(buf)
    })
    .await
    .map_err(|_| "subprocess deadline exceeded")?
}
