import hashlib
import hmac
import struct

def mint_worker_lease_mac(secret: bytes, job_id: str, worker_id: str, work_dir: str, deadline_ms: int) -> str:
    dir_hash = hashlib.sha256(work_dir.encode("utf-8")).digest()
    j_b = job_id.encode("utf-8")
    w_b = worker_id.encode("utf-8")
    msg = struct.pack(">IIQ", len(j_b), len(w_b), deadline_ms) + j_b + w_b + dir_hash
    return hmac.new(secret, msg, hashlib.sha256).hexdigest()

def verify_worker_lease_mac(
    secret: bytes, job_id: str, worker_id: str, work_dir: str, deadline_ms: int, now_ms: int, mac_hex: str
) -> bool:
    if now_ms > deadline_ms:
        return False
    expected = mint_worker_lease_mac(secret, job_id, worker_id, work_dir, deadline_ms)
    return hmac.compare_digest(expected.encode("ascii"), mac_hex.encode("ascii"))
