import hashlib
import hmac
import struct


def verify_radix_merkle_proof(
    key: bytes,
    value: bytes,
    steps: list[tuple[str, bytes]],
    expected_root: bytes,
) -> bool:
    if len(expected_root) != 32 or len(steps) > 256:
        return False

    key_hash = hashlib.sha256(key).digest()
    val_hash = hashlib.sha256(value).digest()
    curr = hashlib.sha256(b"\x00" + key_hash + val_hash).digest()
    path_bits = int.from_bytes(key_hash, "big")
    bit_cursor = 0

    for kind, payload in steps:
        if kind == "branch":
            if len(payload) != 32 or bit_cursor >= 256:
                return False
            bit = (path_bits >> bit_cursor) & 1
            bit_cursor += 1
            if bit == 0:
                curr = hashlib.sha256(b"\x01" + curr + payload).digest()
            else:
                curr = hashlib.sha256(b"\x01" + payload + curr).digest()
        elif kind == "ext":
            if len(payload) != 33:
                return False
            run_len = payload[0]
            if run_len < 1 or bit_cursor + run_len > 256:
                return False
            mask = (1 << run_len) - 1
            expected_segment = (path_bits >> bit_cursor) & mask
            claimed_segment = int.from_bytes(payload[1:], "big") & mask
            if expected_segment != claimed_segment:
                return False
            bit_cursor += run_len
            curr = hashlib.sha256(b"\x02" + struct.pack(">B", run_len) + payload[1:] + curr).digest()
        else:
            return False

    return bit_cursor == 256 and hmac.compare_digest(curr, expected_root)
