import (
	"errors"
	"math/big"
)

func evalLagrangeModP(targetX *big.Int, basis []Share, prime *big.Int) (*big.Int, error) {
	acc := big.NewInt(0)
	for i := range basis {
		num := big.NewInt(1)
		den := big.NewInt(1)
		for j := range basis {
			if i == j {
				continue
			}
			tx := new(big.Int).Sub(targetX, basis[j].X)
			tx.Mod(tx, prime)
			num.Mul(num, tx)
			num.Mod(num, prime)

			dx := new(big.Int).Sub(basis[i].X, basis[j].X)
			dx.Mod(dx, prime)
			den.Mul(den, dx)
			den.Mod(den, prime)
		}
		inv := new(big.Int).ModInverse(den, prime)
		if inv == nil {
			return nil, errors.New("singular Lagrange denominator")
		}
		term := new(big.Int).Mul(basis[i].Y, num)
		term.Mod(term, prime)
		term.Mul(term, inv)
		term.Mod(term, prime)

		acc.Add(acc, term)
		acc.Mod(acc, prime)
	}
	return acc, nil
}

func ReconstructConsistentGFp(shares []Share, threshold int, prime *big.Int) (*big.Int, error) {
	if threshold < 2 || len(shares) < threshold {
		return nil, errors.New("insufficient shares")
	}
	seen := make(map[string]struct{}, len(shares))
	for _, s := range shares {
		if s.X == nil || s.Y == nil || s.X.Sign() <= 0 || s.X.Cmp(prime) >= 0 || s.Y.Sign() < 0 || s.Y.Cmp(prime) >= 0 {
			return nil, errors.New("coordinate out of GF(p) bounds")
		}
		k := s.X.Text(16)
		if _, exists := seen[k]; exists {
			return nil, errors.New("duplicate share X coordinate")
		}
		seen[k] = struct{}{}
	}

	basis := shares[:threshold]
	for _, extra := range shares[threshold:] {
		expectedY, err := evalLagrangeModP(extra.X, basis, prime)
		if err != nil {
			return nil, err
		}
		if expectedY.Cmp(extra.Y) != 0 {
			return nil, errors.New("inconsistent Shamir share set: polynomial degree exceeds t-1")
		}
	}
	return evalLagrangeModP(big.NewInt(0), basis, prime)
}
