use num_bigint::BigUint;
use num_integer::Integer;
use num_traits::{One, Zero};

#[derive(Debug, PartialEq, Eq)]
pub enum CrtAuditVerdict {
    ValidSignature,
    InvalidBenign,
    CriticalFactorExposed { factor_bits: u64 },
}

pub fn inspect_suspect_rsa_signature(
    msg_rep: &BigUint,
    suspect_sig: &BigUint,
    e: &BigUint,
    n: &BigUint,
) -> Result<CrtAuditVerdict, &'static str> {
    if msg_rep.is_zero() || msg_rep >= n || suspect_sig >= n || *e < BigUint::from(3u32) {
        return Err("inputs out of RSA modulus range");
    }

    let check = suspect_sig.modpow(e, n);
    if &check == msg_rep {
        return Ok(CrtAuditVerdict::ValidSignature);
    }

    let diff = if msg_rep >= &check {
        msg_rep - &check
    } else {
        n - ((&check - msg_rep) % n)
    };

    let g = diff.gcd(n);
    if g > BigUint::one() && &g < n {
        Ok(CrtAuditVerdict::CriticalFactorExposed {
            factor_bits: g.bits(),
        })
    } else {
        Ok(CrtAuditVerdict::InvalidBenign)
    }
}
