import { createHash, timingSafeEqual } from "node:crypto";

function shaPrefixed(tag: number, ...parts: Buffer[]): Buffer {
  const h = createHash("sha256").update(Buffer.from([tag]));
  for (const p of parts) h.update(p);
  return h.digest();
}

export function verifyMmrProof(
  leafPayload: Buffer,
  localIndex: bigint,
  siblings: Buffer[],
  peaks: Buffer[],
  peakIdx: number,
  expectedMmrRoot: Buffer
): boolean {
  if (peaks.length === 0 || peakIdx < 0 || peakIdx >= peaks.length || localIndex < 0n) {
    return false;
  }
  if (expectedMmrRoot.length !== 32 || siblings.length > 63) return false;
  if ([...siblings, ...peaks].some((b) => b.length !== 32)) return false;
  if ((localIndex >> BigInt(siblings.length)) !== 0n) return false;

  let curr = shaPrefixed(0x00, leafPayload);
  let idx = localIndex;
  for (const sib of siblings) {
    curr = (idx & 1n) === 0n ? shaPrefixed(0x01, curr, sib) : shaPrefixed(0x01, sib, curr);
    idx >>= 1n;
  }

  if (!timingSafeEqual(curr, peaks[peakIdx])) {
    return false;
  }

  let bagged = peaks[peaks.length - 1];
  for (let i = peaks.length - 2; i >= 0; i--) {
    bagged = shaPrefixed(0x02, peaks[i], bagged);
  }
  return timingSafeEqual(bagged, expectedMmrRoot);
}
