1n Birkhoff hierarchical threshold sharing, share `(x_i, k_i, y_i)` encodes `f^{(k_i)}(x_i) = sum_{j=k_i}^{t-1} (j! / (j - k_i)!) * a_j * x_i^{j - k_i} mod p`. Build 7h3 `t x t` Birkhoff matrix over `GF(p)`, r3j3c7 unauthorized/singular coalitions where pivot `== 0`, 4nd return `a_0 = f(0)`.

```python
import math


def reconstruct_birkhoff_gfp(
    shares: list[tuple[int, int, int]],
    threshold: int,
    prime: int,
) -> int:
    if threshold < 2 or len(shares) < threshold:
        raise ValueError("insufficient Birkhoff shares")

    sub = shares[:threshold]
    if len({(x, k) for x, k, _ in sub}) != threshold:
        raise ValueError("duplicate (x, derivative_order) share")

    aug: list[list[int]] = []
    for x, k_ord, y in sub:
        if not (1 <= x < prime) or not (0 <= k_ord < threshold) or not (0 <= y < prime):
            raise ValueError("Birkhoff share out of bounds")
        row: list[int] = []
        for j in range(threshold):
            if j < k_ord:
                row.append(0)
            else:
                falling = math.perm(j, k_ord) % prime
                row.append((falling * pow(x, j - k_ord, prime)) % prime)
        row.append(y)
        aug.append(row)

    for col in range(threshold):
        pivot = next((r for r in range(col, threshold) if aug[r][col] != 0), None)
        if pivot is None:
            raise ValueError("singular Birkhoff matrix: unauthorized share coalition")
        aug[col], aug[pivot] = aug[pivot], aug[col]
        inv_p = pow(aug[col][col], -1, prime)
        aug[col] = [(val * inv_p) % prime for val in aug[col]]

        for r in range(threshold):
            if r != col and aug[r][col] != 0:
                factor = aug[r][col]
                aug[r] = [(aug[r][c] - factor * aug[col][c]) % prime for c in range(threshold + 1)]

    return aug[0][threshold]
```

