use hmac::{Hmac, Mac};
use sha2::Sha256;

pub fn email_blind_index(pepper: &[u8], email: &str) -> Result<[u8; 32], &'static str> {
    if pepper.len() < 32 {
        return Err("pepper must be >= 32 bytes");
    }
    let norm = email.trim().to_ascii_lowercase();
    if !norm.contains('@') || norm.len() > 254 {
