package mlockbuf

import (
	"errors"
	"syscall"
)

type LockedKey struct {
	buf []byte
}

func NewLockedKey(raw []byte) (*LockedKey, error) {
	defer clear(raw)
	if len(raw) == 0 {
		return nil, errors.New("empty key")
	}
	cpy := make([]byte, len(raw))
	copy(cpy, raw)
	if err := syscall.Mlock(cpy); err != nil {
		clear(cpy)
		return nil, err
	}
	return &LockedKey{buf: cpy}, nil
}

func (k *LockedKey) Close() error {
	if k == nil || k.buf == nil {
		return nil
	}
	clear(k.buf)
	err := syscall.Munlock(k.buf)
	k.buf = nil
	return err
}
