```rust
use nom::{
    combinator::{all_consuming, verify},
    number::complete::{be_u32, u8 as nom_u8},
    sequence::pair,
    IResult,
};
use std::{io, time::Duration};
use tokio::io::{AsyncRead, AsyncReadExt};

const MAX_GRPC_MSG: u32 = 4 * 1024 * 1024;

pub fn parse_grpc_header(hdr: &[u8]) -> IResult<&[u8], (bool, usize)> {
    let (rest, (flag, len)) = all_consuming(pair(
        verify(nom_u8, |&f| f <= 1),
        verify(be_u32, |&n| n <= MAX_GRPC_MSG),
    ))(hdr)?;
    Ok((rest, (flag == 1, len as usize)))
}

pub async fn read_grpc_frame_timeout<R: AsyncRead + Unpin>(
    reader: &mut R,
    deadline: Duration,
) -> io::Result<(bool, Vec<u8>)> {
    tokio::time::timeout(deadline, async {
        let mut hdr = [0u8; 5];
        reader.read_exact(&mut hdr).await?;
        let (_, (compressed, len)) = parse_grpc_header(&hdr)
            .map_err(|_| io::Error::new(io::ErrorKind::InvalidData, "bad gRPC header"))?;
        let mut body = vec![0u8; len];
        reader.read_exact(&mut body).await?;
        Ok((compressed, body))
    })
    .await
    .map_err(|_| io::Error::new(io::ErrorKind::TimedOut, "gRPC frame read timed out"))?
}
