```typescript
import { createPrivateKey, KeyObject } from "node:crypto";

export function importPkcs8PemZeroize(pemText: string): KeyObject {
  const b64Body = pemText
    .replace(/-----BEGIN PRIVATE KEY-----/g, "")
    .replace(/-----END PRIVATE KEY-----/g, "")
    .replace(/\s+/g, "");
  if (!b64Body) {
    throw new Error("empty PKCS#8 PEM body");
  }
  const derBuf = Buffer.from(b64Body, "base64");
  try {
    return createPrivateKey({ key: derBuf, format: "der", type: "pkcs8" });
  } finally {
    derBuf.fill(0);
  }
}
