def long_lived_sa_token_cidrs(
    lines: Iterable[str], max_exp_sec: int = 86400
) -> list[str]:
    v4, v6 = [], []
    for raw in lines:
        ev = json.loads(raw)
        obj = ev.get("objectRef") or {}
        if obj.get("resource") != "serviceaccounts" or obj.get("subresource") != "token":
            continue
        if ev.get("verb") != "create":
            continue
        exp = (((ev.get("requestObject") or {}).get("spec")) or {}).get("expirationSeconds")
