```go
package ooxmlsafe

import (
	"archive/zip"
	"bytes"
	"encoding/xml"
	"errors"
	"io"
	"path"
	"strings"
)

func ScanOOXMLArchive(raw []byte) error {
	r, err := zip.NewReader(bytes.NewReader(raw), int64(len(raw)))
	if err != nil || len(r.File) > 128 {
		return errors.New("invalid OOXML zip or >128 entries")
	}
	var total int64
	for _, zf := range r.File {
		clean := path.Clean(zf.Name)
		if strings.HasPrefix(clean, "..") || strings.HasPrefix(clean, "/") || strings.Contains(zf.Name, "\\") {
			return errors.New("path traversal in OOXML zip entry")
		}
		if !strings.HasSuffix(clean, ".xml") && !strings.HasSuffix(clean, ".rels") {
			continue
		}
		rc, err := zf.Open()
		if err != nil {
			return err
		}
		buf, rerr := io.ReadAll(io.LimitReader(rc, 1<<20+1))
		rc.Close()
		if rerr != nil || len(buf) > 1<<20 {
			return errors.New("OOXML XML entry exceeded 1 MiB stream limit")
		}
		total += int64(len(buf))
		if total > 8<<20 {
			return errors.New("OOXML cumulative XML size exceeded 8 MiB")
		}
		dec := xml.NewDecoder(bytes.NewReader(buf))
		dec.Strict = true
		dec.Entity = map[string]string{}
		for {
			tok, terr := dec.RawToken()
			if errors.Is(terr, io.EOF) {
				break
			}
			if terr != nil {
				return terr
			}
			if _, isDir := tok.(xml.Directive); isDir {
				return errors.New("DOCTYPE/ENTITY directive in OOXML entry")
			}
		}
	}
	return nil
}
