import ast

XPATH_METHODS = {"find", "findall", "iterfind", "xpath"}

def _is_dynamic_str_expr(node: ast.AST) -> bool:
    if isinstance(node, ast.JoinedStr):
        return True
    if isinstance(node, ast.BinOp) and isinstance(node.op, (ast.Add, ast.Mod)):
        return True
    if isinstance(node, ast.Call) and isinstance(node.func, ast.Attribute) and node.func.attr == "format":
        return True
    return False

def find_xpath_injection_sinks(source: str) -> list[tuple[int, str]]:
    tree = ast.parse(source)
    hits: list[tuple[int, str]] = []
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call) or not isinstance(node.func, ast.Attribute):
            continue
        if node.func.attr in XPATH_METHODS and node.args:
            if _is_dynamic_str_expr(node.args[0]):
                hits.append((node.lineno, node.func.attr))
    return hits
