import re

VAR_REF_RE = re.compile(r"\$\{([a-zA-Z_][a-zA-Z0-9_]*)\}|\$([a-zA-Z_][a-zA-Z0-9_]*)")
SHA256_PIN_RE = re.compile(r"@sha256:[0-9a-fA-F]{64}$")

def lint_dockerfile_from_args(dockerfile_src: str) -> list[tuple[int, str]]:
    global_args: dict[str, str] = {}
    seen_from = False
    issues: list[tuple[int, str]] = []

    for lineno, raw in enumerate(dockerfile_src.splitlines(), 1):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split()
        instr = parts[0].upper()
        if instr == "ARG" and not seen_from and len(parts) >= 2:
            k, _, v = parts[1].partition("=")
            global_args[k] = v.strip("\"'")
        elif instr == "FROM" and len(parts) >= 2:
            seen_from = True
            img = next((p for p in parts[1:] if not p.startswith("--")), "")
            if "$" not in img:
                continue
            resolved = VAR_REF_RE.sub(lambda m: global_args.get(m.group(1) or m.group(2), ""), img)
            if not resolved or "$" in resolved:
                issues.append((lineno, f"FROM '{img}' uses unbound global ARG without pinned default"))
            elif resolved.lower() != "scratch" and not SHA256_PIN_RE.search(resolved):
                issues.append((lineno, f"FROM '{img}' resolves to unpinned ARG default '{resolved}'"))
    return issues
