```typescript
interface BucketStmt {
  Sid?: string;
  Effect: string;
  Principal?: "*" | { AWS?: string | string[] };
  Condition?: Record<string, Record<string, unknown>>;
}

function isWildcardPrincipal(p: BucketStmt["Principal"]): boolean {
  if (p === "*") return true;
  if (!p || typeof p !== "object") return false;
  const aws = Array.isArray(p.AWS) ? p.AWS : p.AWS ? [p.AWS] : [];
  return aws.includes("*");
}

export function auditSpoofableS3RefererPolicy(policyJson: string): string[] {
  const doc = JSON.parse(policyJson) as { Statement?: BucketStmt[] };
  const warnings: string[] = [];

  for (const [idx, stmt] of (doc.Statement ?? []).entries()) {
    if (stmt.Effect !== "Allow" || !isWildcardPrincipal(stmt.Principal)) continue;
    const condKeys = Object.values(stmt.Condition ?? {})
      .flatMap((m) => Object.keys(m))
      .map((k) => k.toLowerCase());

    if (condKeys.length === 0) {
      warnings.push(`Statement[${idx}]: public Allow Principal '*' with no Condition`);
    } else if (condKeys.every((k) => k === "aws:referer")) {
      warnings.push(`Statement[${idx}]: public Allow Principal '*' guarded only by spoofable aws:Referer`);
    }
  }
  return warnings;
}
