var ghTokenExprRe = regexp.MustCompile(`(?i)\$\{\{\s*(?:github\.token|secrets\.GITHUB_TOKEN)\s*\}\}`)

func nodeContainsGhToken(n *yaml.Node) *yaml.Node {
	if n == nil {
		return nil
	}
	if n.Kind == yaml.ScalarNode && ghTokenExprRe.MatchString(n.Value) {
		return n
	}
	for _, c := range n.Content {
		if hit := nodeContainsGhToken(c); hit != nil {
			return hit
		}
	}
	return nil
}

func AuditThirdPartyGithubTokenPass(raw []byte) ([]string, error) {
	var root yaml.Node
	if err := yaml.Unmarshal(raw, &root); err != nil {
		return nil, err
	}
	var out []string
	var walk func(n *yaml.Node)
	walk = func(n *yaml.Node) {
		if n == nil {
			return
		}
		if n.Kind == yaml.MappingNode {
			var usesVal string
			var tokenHit *yaml.Node
			for i := 0; i+1 < len(n.Content); i += 2 {
				k, v := n.Content[i], n.Content[i+1]
				if k.Value == "uses" && v.Kind == yaml.ScalarNode {
					usesVal = strings.TrimSpace(v.Value)
				}
				if k.Value == "with" || k.Value == "env" {
					if hit := nodeContainsGhToken(v); hit != nil {
						tokenHit = hit
					}
				}
				walk(v)
			}
			if usesVal != "" && !strings.HasPrefix(usesVal, "actions/") && !strings.HasPrefix(usesVal, "./") && tokenHit != nil {
				out = append(out, fmt.Sprintf("%d:%d GITHUB_TOKEN passed to third-party action %q", tokenHit.Line, tokenHit.Column, usesVal))
			}
			return
		}
		for _, c := range n.Content {
			walk(c)
		}
	}
	walk(&root)
	return out, nil
}
