func SealTenantHKDFGCM(masterKey []byte, tenantID string, plaintext, aad []byte) ([]byte, error) {
	if len(masterKey) != 32 || tenantID == "" {
		return nil, errors.New("invalid master key or empty tenantID")
	}
	salt := make([]byte, 16)
	if _, err := io.ReadFull(rand.Reader, salt); err != nil {
		return nil, err
	}
	info := "c12-tenant-gcm-v1\x00" + tenantID
	subkey, err := hkdf.Key(sha256.New, masterKey, salt, info, 32)
	if err != nil {
