	block, err := aes.NewCipher(subkey)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	var zeroNonce [12]byte
	boundAAD := append(append([]byte(nil), salt...), aad...)
	return gcm.Seal(salt, zeroNonce[:], plaintext, boundAAD), nil
}

func OpenTenantHKDFGCM(masterKey []byte, tenantID string, blob, aad []byte) ([]byte, error) {
