use aes_gcm::aead::{Aead, KeyInit, Payload};
use aes_gcm::{Aes256Gcm, Nonce};
use hkdf::Hkdf;
use sha2::Sha256;
use zeroize::Zeroizing;

pub fn open_hkdf_gcm(
    master_key: &[u8; 32],
    tenant_id: &str,
    blob: &[u8],
    aad: &[u8],
) -> Result<Vec<u8>, &'static str> {
    if tenant_id.is_empty() || blob.len() < 32 {
        return Err("invalid tenant_id or truncated blob");
    }
    let salt = &blob[..16];
    let hk = Hkdf::<Sha256>::new(Some(salt), master_key);
    let mut subkey = Zeroizing::new([0u8; 32]);
    let info = [b"c12-tenant-gcm-v1\x00", tenant_id.as_bytes()].concat();
    hk.expand(&info, &mut *subkey).map_err(|_| "hkdf expand failed")?;

    let mut bound_aad = Vec::with_capacity(16 + aad.len());
    bound_aad.extend_from_slice(salt);
    bound_aad.extend_from_slice(aad);

    let cipher = Aes256Gcm::new((&*subkey).into());
    cipher
        .decrypt(Nonce::from_slice(&[0u8; 12]), Payload { msg: &blob[16..], aad: &bound_aad })
        .map_err(|_| "hkdf-gcm auth failed")
}
