import { createCipheriv, hkdfSync, randomBytes } from "node:crypto";

export function sealTenantHkdfGcm(masterKey: Buffer, tenantId: string, plaintext: Buffer, aad: Buffer): Buffer {
  if (masterKey.byteLength !== 32 || !tenantId || tenantId.includes("\0")) {
    throw new Error("Invalid 32B masterKey or tenantId");
  }
  const salt = randomBytes(16);
  const info = Buffer.from(`c12-tenant-gcm-v1\0${tenantId}`, "utf8");
  const subkeyBuf = Buffer.from(hkdfSync("sha256", masterKey, salt, info, 32));
  try {
    const cipher = createCipheriv("aes-256-gcm", subkeyBuf, Buffer.alloc(12, 0), { authTagLength: 16 });
    cipher.setAAD(Buffer.concat([salt, aad]));
    return Buffer.concat([salt, cipher.update(plaintext), cipher.final(), cipher.getAuthTag()]);
  } finally {
    subkeyBuf.fill(0);
  }
