use subtle::ConstantTimeEq;

const APK_PREFIX: &str = "android:apk-key-hash:";

pub fn verify_origin_or_apk_hash(
    origin: &str,
    allowed_web_origins: &[&str],
    pinned_apk_hashes: &[&str],
) -> Result<(), &'static str> {
    if let Some(hash_b64u) = origin.strip_prefix(APK_PREFIX) {
        if hash_b64u.len() != 43 {
            return Err("invalid apk-key-hash length");
