            }
        }
        return if ok == 1 { Ok(()) } else { Err("untrusted android apk-key-hash") };
    }
    if allowed_web_origins.iter().any(|&w| w == origin) {
        Ok(())
    } else {
        Err("untrusted web origin")
    }
