```typescript
import * as readline from "node:readline";
import { Readable } from "node:stream";

interface ZeekFilesRow {
  ts?: number;
  sha256?: string;
  rx_hosts?: string[];
}

export async function rapidFilePropagation(
  input: Readable,
  minRecipients = 5
): Promise<Array<{ sha256: string; recipients: number; pstdevSec: number }>> {
  const rxByHash = new Map<string, Set<string>>();
  const tsByHash = new Map<string, number[]>();
  const rl = readline.createInterface({ input, crlfDelay: Infinity });
  for await (const line of rl) {
    if (!line.trim()) continue;
    const ev = JSON.parse(line) as ZeekFilesRow;
    if (!ev.sha256 || ev.ts === undefined) continue;
    const h = ev.sha256.toLowerCase();
    const set = rxByHash.get(h) ?? new Set<string>();
    for (const ip of ev.rx_hosts ?? []) set.add(ip);
    rxByHash.set(h, set);
    const arr = tsByHash.get(h) ?? [];
    arr.push(ev.ts);
    tsByHash.set(h, arr);
  }
  const out: Array<{ sha256: string; recipients: number; pstdevSec: number }> = [];
  for (const [sha256, hosts] of rxByHash) {
    const stamps = tsByHash.get(sha256) ?? [];
    if (hosts.size < minRecipients || stamps.length < 3) continue;
    stamps.sort((a, b) => a - b);
    const deltas = stamps.slice(1).map((t, i) => t - stamps[i]);
    const mean = deltas.reduce((s, d) => s + d, 0) / deltas.length;
    const variance = deltas.reduce((s, d) => s + (d - mean) ** 2, 0) / deltas.length;
    out.push({
      sha256,
      recipients: hosts.size,
      pstdevSec: Number(Math.sqrt(variance).toFixed(4)),
    });
  }
  return out;
}
