```go
package hardensrv

import (
	"context"
	"crypto/tls"
	"io"
	"net"
	"net/http"
	"os"
	"time"
)

func loadCertFromRoot(certRoot *os.Root) (*tls.Certificate, error) {
	crtFile, err := certRoot.Open("tls.crt")
	if err != nil {
		return nil, err
	}
	defer crtFile.Close()
	keyFile, err := certRoot.Open("tls.key")
	if err != nil {
		return nil, err
	}
	defer keyFile.Close()
	crtPEM, err := io.ReadAll(io.LimitReader(crtFile, 65536))
	if err != nil {
		return nil, err
	}
	keyPEM, err := io.ReadAll(io.LimitReader(keyFile, 65536))
	if err != nil {
		return nil, err
	}
	cert, err := tls.X509KeyPair(crtPEM, keyPEM)
	return &cert, err
}

func ServeGracefully(runCtx context.Context, addr, certDir string, maxBody int64, handler http.Handler) error {
	certRoot, err := os.OpenRoot(certDir)
	if err != nil {
		return err
	}
	defer certRoot.Close()

	srv := &http.Server{
		Addr:              addr,
		ReadHeaderTimeout: 3 * time.Second,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      15 * time.Second,
		IdleTimeout:       60 * time.Second,
		MaxHeaderBytes:    16 << 10,
		BaseContext:       func(_ net.Listener) context.Context { return runCtx },
		TLSConfig: &tls.Config{
			MinVersion: tls.VersionTLS13,
			GetCertificate: func(_ *tls.ClientHelloInfo) (*tls.Certificate, error) {
				return loadCertFromRoot(certRoot)
			},
		},
		Handler: http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			r.Body = http.MaxBytesReader(w, r.Body, maxBody)
			handler.ServeHTTP(w, r)
		}),
	}

	go func() {
		<-runCtx.Done()
		drainCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
		defer cancel()
		_ = srv.Shutdown(drainCtx)
	}()
	return srv.ListenAndServeTLS("", "")
}
