	var buf strings.Builder
	startLine := 1

	for idx, raw := range strings.Split(dockerfile, "\n") {
		trimmed := strings.TrimSpace(raw)
		if buf.Len() == 0 {
			startLine = idx + 1
		}
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}
		if strings.HasSuffix(trimmed, "\\") {
			buf.WriteString(strings.TrimSuffix(trimmed, "\\"))
			buf.WriteByte(' ')
			continue
		}
		buf.WriteString(trimmed)
		full := buf.String()
		buf.Reset()

		if strings.HasPrefix(strings.ToUpper(full), "RUN ") {
			if m := dangerousSetcapRe.FindStringSubmatch(full); len(m) >= 2 {
				findings = append(findings, fmt.Sprintf("line %d: RUN grants dangerous file capability %q via setcap", startLine, m[1]))
			}
		}
	}
	return findings
