use std::collections::HashSet;

pub fn audit_backup_vaults(plan_json: &str) -> Result<Vec<String>, serde_json::Error> {
    let plan: Value = serde_json::from_str(plan_json)?;
    let mut issues = Vec::new();
    let Some(changes) = plan.get("resource_changes").and_then(Value::as_array) else {
        return Ok(issues);
    };

    let mut locked_vaults = HashSet::new();
    for rc in changes {
        if rc.get("type").and_then(Value::as_str) == Some("aws_backup_vault_lock_configuration") {
            if let Some(vname) = rc.pointer("/change/after/backup_vault_name").and_then(Value::as_str) {
                locked_vaults.insert(vname.to_string());
            }
        }
    }

    for rc in changes {
        if rc.get("type").and_then(Value::as_str) != Some("aws_backup_vault") {
            continue;
        }
        let is_del = rc
            .pointer("/change/actions")
            .and_then(Value::as_array)
            .map(|a| a.len() == 1 && a[0].as_str() == Some("delete"))
            .unwrap_or(false);
        if is_del {
            continue;
        }
        let addr = rc.get("address").and_then(Value::as_str).unwrap_or("unknown");
        let Some(after) = rc.pointer("/change/after") else {
            continue;
        };
        let kms = after.get("kms_key_arn").and_then(Value::as_str).unwrap_or("").trim();
        if kms.is_empty() {
            issues.push(format!("{addr}: missing customer-managed kms_key_arn"));
        }
        let name = after.get("name").and_then(Value::as_str).unwrap_or("");
        if !locked_vaults.contains(name) {
            issues.push(format!("{addr}: backup vault '{name}' lacks aws_backup_vault_lock_configuration"));
        }
    }
    Ok(issues)
}
