const HEX_40_RE = /^[0-9a-f]{40}$/i;
const REMOTE_WF_RE = /^[^/]+\/[^/]+\/\.github\/workflows\/[^@]+@(.+)$/;

export function lintReusableWorkflowPins(
  jobs: Record<string, { uses?: string }>
): string[] {
  const errors: string[] = [];
  for (const [jobId, job] of Object.entries(jobs)) {
    const uses = job.uses?.trim();
    if (!uses || uses.startsWith("./")) continue;
    const m = REMOTE_WF_RE.exec(uses);
    if (!m) {
      errors.push(`job '${jobId}': malformed or unpinned reusable workflow '${uses}'`);
      continue;
    }
    if (!HEX_40_RE.test(m[1])) {
      errors.push(`job '${jobId}': reusable workflow '${uses}' uses mutable ref '${m[1]}'; pin to 40-hex SHA`);
    }
  }
  return errors;
}
