from pydantic import BaseModel, ConfigDict, Field, model_validator

class SvgViewportSpec(BaseModel):
    model_config = ConfigDict(strict=True, extra="forbid", allow_inf_nan=False)
    width: float = Field(gt=0.0, le=4096.0)
    height: float = Field(gt=0.0, le=4096.0)
    vb_w: float = Field(gt=0.0, le=8192.0)
    vb_h: float = Field(gt=0.0, le=8192.0)

