    def _check_pixel_area(self) -> "SvgViewportSpec":
        if self.width * self.height > 4096.0 * 4096.0:
            raise ValueError("SVG pixel area budget exceeded")
        return self

def _parse_px(val: str) -> float:
    clean = val.strip().removesuffix("px").strip()
    num = float(clean)
    if not math.isfinite(num):
        raise ValueError("non-finite SVG dimension")
    return num

def validate_svg_dimensions_and_refs(raw_svg: bytes) -> SvgViewportSpec:
    if not raw_svg or len(raw_svg) > 65536:
        raise ValueError("SVG exceeds 64 KiB")
    root = DefusedET.fromstring(raw_svg, forbid_dtd=True, forbid_entities=True, forbid_external=True)
    w = _parse_px(root.attrib.get("width", "0"))
    h = _parse_px(root.attrib.get("height", "0"))
    vb_parts = root.attrib.get("viewBox", "").replace(",", " ").split()
    if len(vb_parts) != 4:
        raise ValueError("SVG must specify canonical 4-number viewBox")
    _, _, vb_w, vb_h = (_parse_px(x) for x in vb_parts)
    for el in root.iter():
        local = el.tag.split("}")[-1]
        if local == "use":
            raise ValueError("<use> clone elements forbidden to prevent DAG expansion DoS")
    return SvgViewportSpec(width=w, height=h, vb_w=vb_w, vb_h=vb_h)
