```go
package svggraph

import (
	"errors"
)

func CheckBoundedDAGExpansion(edges map[string][]string, roots []string, maxExpanded int) error {
	state := make(map[string]uint8) // 0=unvisited, 1=visiting, 2=done
	memo := make(map[string]int)

	var countSubtree func(id string) (int, error)
	countSubtree = func(id string) (int, error) {
		if state[id] == 1 {
			return 0, errors.New("cyclic <use> reference detected in SVG")
		}
		if state[id] == 2 {
			return memo[id], nil
		}
		state[id] = 1
		total := 1
		for _, child := range edges[id] {
			c, err := countSubtree(child)
			if err != nil {
				return 0, err
			}
			total += c
			if total > maxExpanded {
				return 0, errors.New("SVG <use> clone expansion budget exceeded")
			}
		}
		state[id] = 2
		memo[id] = total
		return total, nil
	}

	sum := 0
	for _, r := range roots {
		c, err := countSubtree(r)
		if err != nil {
			return err
		}
		sum += c
		if sum > maxExpanded {
			return errors.New("total SVG <use> expansion exceeded cap")
		}
	}
	return nil
}
