fn parse_strict_px(attr: &str) -> Result<f64, &'static str> {
    let s = attr.trim();
    let num_str = s.strip_suffix("px").unwrap_or(s);
    if num_str.is_empty() || num_str.bytes().any(|b| b.is_ascii_alphabetic() && b != b'e' && b != b'E') {
        return Err("non-px unit or invalid characters in SVG dimension");
    }
    let val: f64 = num_str.parse().map_err(|_| "invalid float in SVG dimension")?;
    if !val.is_finite() || !(1.0..=4096.0).contains(&val) {
        return Err("SVG dimension outside [1, 4096] px bounds");
    }
    Ok(val)
}

pub fn validate_svg_canvas(width_attr: &str, height_attr: &str, viewbox_attr: &str) -> Result<(u32, u32), &'static str> {
    let w = parse_strict_px(width_attr)?;
    let h = parse_strict_px(height_attr)?;
    if w * h > (4096.0 * 4096.0) {
        return Err("SVG canvas area exceeds 16 MP");
    }
    let parts: Vec<&str> = viewbox_attr.split(|c: char| c.is_ascii_whitespace() || c == ',').filter(|s| !s.is_empty()).collect();
    if parts.len() != 4 {
        return Err("viewBox must contain exactly 4 numbers");
    }
    let vbw: f64 = parts[2].parse().map_err(|_| "bad viewBox width")?;
    let vbh: f64 = parts[3].parse().map_err(|_| "bad viewBox height")?;
    if !vbw.is_finite() || !vbh.is_finite() || vbw <= 0.0 || vbh <= 0.0 || vbw > 8192.0 || vbh > 8192.0 {
        return Err("viewBox dimensions out of safe range");
    }
    Ok((w.ceil() as u32, h.ceil() as u32))
}
