import base64
import hashlib
import hmac

def compute_stepup_challenge(server_nonce: bytes, family_id: str, dpop_jkt: str) -> str:
    if len(server_nonce) < 16 or len(dpop_jkt) != 43:
        raise ValueError("invalid step-up inputs")
    msg = server_nonce + b":" + family_id.encode("ascii") + b":" + dpop_jkt.encode("ascii")
    digest = hashlib.sha256(msg).digest()
    return base64.urlsafe_b64encode(digest).rstrip(b"=").decode("ascii")

def verify_stepup_assertion(client_challenge: str, auth_flags: int, server_nonce: bytes, family_id: str, dpop_jkt: str) -> None:
    expected = compute_stepup_challenge(server_nonce, family_id, dpop_jkt)
    if not hmac.compare_digest(client_challenge.encode("ascii"), expected.encode("ascii")):
        raise PermissionError("step-up challenge binding mismatch")
    if (auth_flags & 0x01) == 0 or (auth_flags & 0x04) == 0:
        raise PermissionError("WebAuthn UP and UV flags required for step-up")
