package shamir

import (
	"errors"
	"math/big"
)

func ShamirToAdditiveShareModP(
	myX, myY *big.Int,
	quorumXs []*big.Int,
	prime *big.Int,
) (*big.Int, error) {
	if len(quorumXs) < 2 || myX == nil || myY == nil || prime == nil {
		return nil, errors.New("invalid Shamir quorum inputs")
	}
	if myY.Sign() < 0 || myY.Cmp(prime) >= 0 {
		return nil, errors.New("myY out of GF(p) bounds")
	}

	seen := make(map[string]struct{}, len(quorumXs))
	foundSelf := false
	for _, xj := range quorumXs {
		if xj == nil || xj.Sign() <= 0 || xj.Cmp(prime) >= 0 {
			return nil, errors.New("quorum X out of GF(p) bounds")
		}
		k := xj.Text(16)
		if _, dup := seen[k]; dup {
			return nil, errors.New("duplicate X in quorumXs")
		}
		seen[k] = struct{}{}
		if xj.Cmp(myX) == 0 {
			foundSelf = true
		}
	}
	if !foundSelf {
		return nil, errors.New("myX not present in quorumXs")
	}

	num := big.NewInt(1)
	den := big.NewInt(1)
	for _, xj := range quorumXs {
		if xj.Cmp(myX) == 0 {
			continue
		}
		negX := new(big.Int).Neg(xj)
		negX.Mod(negX, prime)
		num.Mul(num, negX)
		num.Mod(num, prime)

		diff := new(big.Int).Sub(myX, xj)
		diff.Mod(diff, prime)
		den.Mul(den, diff)
		den.Mod(den, prime)
	}

	invDen := new(big.Int).ModInverse(den, prime)
	if invDen == nil {
		return nil, errors.New("singular Lagrange denominator")
	}
	w := new(big.Int).Mul(myY, num)
	w.Mod(w, prime)
	w.Mul(w, invDen)
	w.Mod(w, prime)
	return w, nil
}
