use sha2::{Digest, Sha256};
use subtle::ConstantTimeEq;

pub fn verify_indexed_exclusion(
    target_key: &[u8; 32],
    low_key: &[u8; 32],
    low_next_idx: u64,
    low_next_key: &[u8; 32],
    mut leaf_index: u64,
    siblings: &[[u8; 32]],
    expected_root: &[u8; 32],
) -> bool {
    if siblings.len() > 63 || (leaf_index >> siblings.len()) != 0 {
        return false;
    }
    if target_key == &[0u8; 32] || low_key >= target_key {
        return false;
    }
    if low_next_key == &[0u8; 32] {
        if low_next_idx != 0 {
            return false;
        }
    } else if target_key >= low_next_key {
        return false;
    }

    let mut curr: [u8; 32] = {
        let mut h = Sha256::new();
        h.update([0x00]);
        h.update(low_key);
        h.update(low_next_idx.to_be_bytes());
        h.update(low_next_key);
        h.finalize().into()
    };

    for sib in siblings {
        let mut h = Sha256::new();
        h.update([0x01]);
