```typescript
import { randomBytes } from "node:crypto";

export function sampleUniformGFp(prime: bigint): bigint {
  if (prime <= 2n) throw new RangeError("prime must exceed 2");
  const bitLen = prime.toString(2).length;
  const byteLen = Math.ceil(bitLen / 8);
  const topBits = bitLen % 8;
  const topMask = topBits === 0 ? 0xff : (1 << topBits) - 1;

  while (true) {
    const buf = randomBytes(byteLen);
    buf[0] &= topMask;
    const cand = BigInt("0x" + buf.toString("hex"));
    if (cand < prime) {
      return cand;
    }
  }
}

export function generateProactiveDeltasGFp(
  participantXs: bigint[],
  threshold: number,
  prime: bigint
): Map<bigint, bigint> {
  if (threshold < 2 || participantXs.length < threshold) {
    throw new Error("insufficient participants for threshold refresh");
  }
  const seen = new Set<bigint>();
  for (const x of participantXs) {
    if (x <= 0n || x >= prime || seen.has(x)) {
      throw new Error("invalid or duplicate participant x-coordinate");
    }
    seen.add(x);
  }

  const coeffs: bigint[] = [];
  for (let j = 0; j < threshold - 1; j++) {
    coeffs.push(sampleUniformGFp(prime));
  }

  const out = new Map<bigint, bigint>();
  for (const x of participantXs) {
    let acc = 0n;
    let xPow = x;
    for (const c of coeffs) {
      acc = (acc + c * xPow) % prime;
      xPow = (xPow * x) % prime;
    }
    out.set(x, acc);
  }
  return out;
}
