pub fn audit_buildkit_syntax_directive(dockerfile: &str) -> Option<String> {
    let first_line = dockerfile.lines().next()?.trim();
    let rest = first_line.strip_prefix('#')?.trim();
    let syntax_ref = rest.strip_prefix("syntax=")?.trim();

    if !syntax_ref.starts_with("docker/dockerfile:") && !syntax_ref.starts_with("docker.io/docker/dockerfile:") {
        return Some(format!("untrusted BuildKit syntax frontend image: '{syntax_ref}'"));
    }
    let valid_digest = syntax_ref
        .split_once("@sha256:")
        .map(|(_, hex_part)| hex_part.len() == 64 && hex_part.chars().all(|c| c.is_ascii_hexdigit()))
        .unwrap_or(false);

    if !valid_digest {
        return Some(format!(
            "BuildKit # syntax directive '{syntax_ref}' must be pinned with @sha256:<64-hex>"
        ));
    }
    None
}
