export function auditMultiRegionKmsReplication(plan: { resource_changes?: MultiRegionKmsChange[] }): string[] {
  const issues: string[] = [];
  for (const rc of plan.resource_changes ?? []) {
    if (rc.type !== "aws_kms_key" || !rc.change.after?.multi_region || !rc.change.after.policy) continue;
