func checkPermsNode(n *yaml.Node, allowedWrite map[string]bool, out *[]string) {
	if n == nil {
		return
	}
	if n.Kind == yaml.ScalarNode && n.Value == "write-all" {
		*out = append(*out, fmt.Sprintf("%d:%d permissions: write-all is prohibited", n.Line, n.Column))
		return
	}
	if n.Kind == yaml.MappingNode {
		for i := 0; i+1 < len(n.Content); i += 2 {
			scopeNode, levelNode := n.Content[i], n.Content[i+1]
			if levelNode.Value == "write" && !allowedWrite[scopeNode.Value] {
				*out = append(*out, fmt.Sprintf("%d:%d unauthorized write permission on scope %q", scopeNode.Line, scopeNode.Column, scopeNode.Value))
			}
		}
	}
}

func AuditAllowedWriteScopes(raw []byte, allowedWriteScopes []string) ([]string, error) {
	var root yaml.Node
	if err := yaml.Unmarshal(raw, &root); err != nil {
		return nil, err
	}
	allow := make(map[string]bool, len(allowedWriteScopes))
	for _, s := range allowedWriteScopes {
		allow[s] = true
	}
	var findings []string
	var walk func(n *yaml.Node)
	walk = func(n *yaml.Node) {
		if n == nil {
			return
		}
		if n.Kind == yaml.MappingNode {
			for i := 0; i+1 < len(n.Content); i += 2 {
				k, v := n.Content[i], n.Content[i+1]
				if k.Value == "permissions" {
					checkPermsNode(v, allow, &findings)
				} else {
					walk(v)
				}
			}
			return
		}
		for _, c := range n.Content {
			walk(c)
		}
	}
	walk(&root)
	return findings, nil
}
