import (
	"bytes"
	"encoding/xml"
	"errors"
	"io"
	"net/url"
	"strings"
)

func ExtractSafeAtomLinks(raw []byte) ([]string, error) {
	if len(raw) == 0 || len(raw) > 131072 {
		return nil, errors.New("Atom feed outside [1, 131072] byte limit")
	}
	dec := xml.NewDecoder(bytes.NewReader(raw))
	dec.Strict = true
	dec.Entity = map[string]string{}
	var links []string
	for {
		tok, err := dec.RawToken()
		if errors.Is(err, io.EOF) {
			break
		}
		if err != nil {
			return nil, err
		}
		switch t := tok.(type) {
		case xml.Directive, xml.ProcInst:
			return nil, errors.New("DTD directives and processing instructions forbidden in Atom")
		case xml.StartElement:
			if strings.EqualFold(t.Name.Local, "link") {
				for _, a := range t.Attr {
					if strings.EqualFold(a.Name.Local, "href") {
						u, uerr := url.Parse(strings.TrimSpace(a.Value))
						if uerr != nil || !strings.EqualFold(u.Scheme, "https") || u.Host == "" {
							return nil, errors.New("non-HTTPS or malformed Atom link href")
						}
						links = append(links, u.String())
						if len(links) > 50 {
							return nil, errors.New("Atom feed exceeded 50 links")
						}
					}
				}
			}
		}
	}
	return links, nil
}
