```rust
use roxmltree::{Document, Node, ParsingOptions};

fn max_depth(node: Node<'_, '_>) -> usize {
    node.children().map(max_depth).max().unwrap_or(0) + 1
}

pub fn validate_safe_xmlrpc_call<'a>(
    xml_str: &'a str,
    allowed_methods: &[&str],
) -> Result<String, &'static str> {
    if xml_str.is_empty() || xml_str.len() > 16_384 {
        return Err("XML-RPC body outside [1, 16384] byte limit");
    }
    let doc = Document::parse_with_options(
        xml_str,
        ParsingOptions { allow_dtd: false, nodes_limit: 256 },
    )
    .map_err(|_| "malformed XML-RPC or DTD forbidden")?;

    let root = doc.root_element();
    if root.tag_name().name() != "methodCall" || max_depth(root) > 8 {
        return Err("invalid methodCall root or excessive nesting depth");
    }
    let method = root
        .children()
        .find(|n| n.has_tag_name("methodName"))
        .and_then(|n| n.text())
        .map(str::trim)
        .ok_or("missing methodName")?;
    if method.starts_with("system.") || !allowed_methods.contains(&method) {
        return Err("XML-RPC method not allowlisted or system.* forbidden");
    }
    let param_count = root
        .descendants()
        .filter(|n| n.is_element() && n.has_tag_name("param"))
        .count();
    if param_count > 8 {
        return Err("XML-RPC param count exceeds limit of 8");
    }
    Ok(method.to_owned())
}
