from cryptography import x509
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey
from cryptography.x509.oid import SignatureAlgorithmOID

def verify_ed25519_cert_chain_link(leaf: x509.Certificate, issuer: x509.Certificate) -> None:
    if leaf.signature_algorithm_oid != SignatureAlgorithmOID.ED25519:
        raise ValueError(f"expected Ed25519 OID 1.3.101.112, got {leaf.signature_algorithm_oid.dotted_string}")
    if leaf.signature_hash_algorithm is not None:
        raise ValueError("RFC 8410 PureEdDSA must have signature_hash_algorithm=None")
    if leaf.issuer != issuer.subject:
        raise ValueError("leaf issuer DN does not match issuer subject DN")
    pub = issuer.public_key()
    if not isinstance(pub, Ed25519PublicKey):
        raise ValueError("issuer public key is not Ed25519PublicKey")
    if len(leaf.signature) != 64:
        raise ValueError("Ed25519 signature must be exactly 64 bytes")
    pub.verify(leaf.signature, leaf.tbs_certificate_bytes)
