```typescript
import { randomBytes } from "node:crypto";

function mod(a: bigint, m: bigint): bigint {
  const r = a % m;
  return r < 0n ? r + m : r;
}

function modInv(a: bigint, m: bigint): bigint {
  let [t, newT] = [0n, 1n];
  let [r, newR] = [m, mod(a, m)];
  while (newR !== 0n) {
    const q = r / newR;
    [t, newT] = [newT, t - q * newT];
    [r, newR] = [newR, r - q * newR];
  }
  if (r !== 1n) throw new Error("non-invertible denominator");
  return t < 0n ? t + m : t;
}

function uniformGFp(prime: bigint): bigint {
  const bits = prime.toString(2).length;
  const bytes = Math.ceil(bits / 8);
  const mask = bits % 8 === 0 ? 0xff : (1 << (bits % 8)) - 1;
  while (true) {
    const b = randomBytes(bytes);
    b[0] &= mask;
    const v = BigInt("0x" + b.toString("hex"));
    if (v < prime) return v;
  }
}

export function generateReshareSubsharesGFp(
  oldX: bigint,
  oldY: bigint,
  oldQuorumXs: bigint[],
  newCommitteeXs: bigint[],
  newThreshold: number,
  prime: bigint
): Map<bigint, bigint> {
  if (oldQuorumXs.length < 2 || new Set(oldQuorumXs).size !== oldQuorumXs.length) {
    throw new Error("invalid oldQuorumXs");
  }
  if (newThreshold < 2 || newCommitteeXs.length < newThreshold || new Set(newCommitteeXs).size !== newCommitteeXs.length) {
    throw new Error("invalid newCommitteeXs or newThreshold");
  }
  if (!oldQuorumXs.includes(oldX)) throw new Error("oldX missing from oldQuorumXs");

  let num = 1n;
  let den = 1n;
  for (const xj of oldQuorumXs) {
    if (xj === oldX) continue;
    num = mod(num * -xj, prime);
    den = mod(den * (oldX - xj), prime);
  }
  const weighted = mod(oldY * mod(num * modInv(den, prime), prime), prime);

  const coeffs: bigint[] = [weighted];
  for (let k = 1; k < newThreshold; k++) coeffs.push(uniformGFp(prime));

  const subshares = new Map<bigint, bigint>();
  for (const u of newCommitteeXs) {
    if (u <= 0n || u >= prime) throw new RangeError("newX out of GF(p) bounds");
    let acc = 0n;
    for (let j = coeffs.length - 1; j >= 0; j--) {
      acc = mod(acc * u + coeffs[j], prime);
    }
    subshares.set(u, acc);
  }
  return subshares;
}

export function combineReshareSubsharesGFp(newX: bigint, subshares: bigint[], prime: bigint): { x: bigint; y: bigint } {
  if (newX <= 0n || newX >= prime || subshares.length < 2) throw new Error("invalid newX or subshares");
  let sum = 0n;
  for (const s of subshares) sum = mod(sum + s, prime);
  return { x: newX, y: sum };
}
