        return Err("invalid quorum size or zero my_x");
    }
    let mut found_self = false;
    for (i, &xj) in quorum_xs.iter().enumerate() {
        if xj == 0 || quorum_xs[..i].contains(&xj) {
            return Err("zero or duplicate x-coordinate in quorum_xs");
        }
