def precompute_zero_barycentric_weights_gfp(xs: list[int], prime: int) -> list[int]:
    t = len(xs)
    if t < 2 or len(set(xs)) != t:
        raise ValueError("xs must contain >= 2 distinct coordinates")
    if any(not (1 <= x < prime) for x in xs):
        raise ValueError("x coordinate out of GF(p) bounds")

    weights: list[int] = []
    for i, xi in enumerate(xs):
        num = 1
        den = 1
        for j, xj in enumerate(xs):
            if i == j:
                continue
            num = (num * (-xj % prime)) % prime
            den = (den * ((xi - xj) % prime)) % prime
        weights.append((num * pow(den, -1, prime)) % prime)
    return weights


def reconstruct_fast_gfp(ys: list[int], weights: list[int], prime: int) -> int:
    if len(ys) != len(weights) or len(ys) < 2:
        raise ValueError("ys length must match precomputed weights")
    if any(not (0 <= y < prime) for y in ys):
        raise ValueError("y coordinate out of GF(p) bounds")

    acc = 0
    for y, w in zip(ys, weights):
        acc = (acc + y * w) % prime
    return acc
