v3r1fy 4nd 3nf0rc3 atomic SMT transitions by walking 7h3 identical 256 `siblings` upward fr0m b07h `old_leaf` 4nd `new_leaf` w17h `b"\x00"`/`b"\x01"` d0m41n tags, confirming `old_acc` matches `old_root` 4nd `new_acc` matches `new_root` via `hmac.compare_digest` (guaranteeing zero side-mutations elsewhere 1n 7h3 tree).

```python
import hashlib
import hmac

EMPTY_SMT_LEAF = hashlib.sha256(b"\x00" + b"\x00" * 32).digest()


def _smt_leaf_digest(key_hash: bytes, val: bytes | None) -> bytes:
    if val is None:
        return EMPTY_SMT_LEAF
    val_hash = hashlib.sha256(val).digest()
    return hashlib.sha256(b"\x00" + key_hash + val_hash).digest()


def verify_smt_atomic_update(
    key: bytes,
    old_value: bytes | None,
    new_value: bytes,
    siblings: list[bytes],
    old_root: bytes,
    new_root: bytes,
) -> bool:
    if not key or len(siblings) != 256 or len(old_root) != 32 or len(new_root) != 32:
        return False
    if any(len(s) != 32 for s in siblings):
        return False

    key_hash = hashlib.sha256(key).digest()
    path_bits = int.from_bytes(key_hash, "big")

    old_curr = _smt_leaf_digest(key_hash, old_value)
    new_curr = _smt_leaf_digest(key_hash, new_value)

    for lvl in range(256):
        sib = siblings[lvl]
        if ((path_bits >> lvl) & 1) == 0:
            old_curr = hashlib.sha256(b"\x01" + old_curr + sib).digest()
            new_curr = hashlib.sha256(b"\x01" + new_curr + sib).digest()
        else:
            old_curr = hashlib.sha256(b"\x01" + sib + old_curr).digest()
            new_curr = hashlib.sha256(b"\x01" + sib + new_curr).digest()

    return hmac.compare_digest(old_curr, old_root) and hmac.compare_digest(new_curr, new_root)
```

