```go
package shamir

import (
	"crypto/rand"
	"errors"
	"math/big"
)

func GenerateProactiveDeltasGFp(
	participantXs []*big.Int,
	threshold int,
	prime *big.Int,
) (map[string]*big.Int, error) {
	if threshold < 2 || len(participantXs) < threshold || prime == nil {
		return nil, errors.New("invalid proactive refresh parameters")
	}

	seen := make(map[string]struct{}, len(participantXs))
	for _, x := range participantXs {
		if x == nil || x.Sign() <= 0 || x.Cmp(prime) >= 0 {
			return nil, errors.New("participant X out of GF(p) bounds")
		}
		k := x.Text(16)
		if _, dup := seen[k]; dup {
			return nil, errors.New("duplicate participant X coordinate")
		}
		seen[k] = struct{}{}
	}

	coeffs := make([]*big.Int, threshold-1)
	for i := range coeffs {
		c, err := rand.Int(rand.Reader, prime)
		if err != nil {
			return nil, err
		}
		coeffs[i] = c
	}
	defer func() {
		for _, c := range coeffs {
			if c != nil {
				c.SetInt64(0)
			}
		}
	}()

	deltas := make(map[string]*big.Int, len(participantXs))
	for _, x := range participantXs {
		acc := big.NewInt(0)
		xPow := new(big.Int).Set(x)
		for _, c := range coeffs {
			term := new(big.Int).Mul(c, xPow)
			term.Mod(term, prime)
			acc.Add(acc, term)
			acc.Mod(acc, prime)
			xPow.Mul(xPow, x)
			xPow.Mod(xPow, prime)
		}
		deltas[x.Text(16)] = acc
	}
	return deltas, nil
}

func ApplyProactiveRefreshGFp(currY *big.Int, incomingDeltas []*big.Int, prime *big.Int) (*big.Int, error) {
	if currY == nil || currY.Sign() < 0 || currY.Cmp(prime) >= 0 {
		return nil, errors.New("invalid current share Y")
	}
	out := new(big.Int).Set(currY)
	for _, d := range incomingDeltas {
		if d == nil || d.Sign() < 0 || d.Cmp(prime) >= 0 {
			return nil, errors.New("delta out of GF(p) bounds")
		}
		out.Add(out, d)
		out.Mod(out, prime)
	}
	return out, nil
}
