```rust
use subtle::{Choice, ConstantTimeEq};

const P256_N: [u8; 32] = [
    0xff, 0xff, 0xff, 0xff, 0x00, 0x00, 0x00, 0x00,
    0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
    0xbc, 0xe6, 0xfa, 0xad, 0xa7, 0x17, 0x9e, 0x84,
    0xf3, 0xb9, 0xca, 0xc2, 0xfc, 0x63, 0x25, 0x51,
];

const P256_HALF_N_PLUS_1: [u8; 32] = [
    0x7f, 0xff, 0xff, 0xff, 0x80, 0x00, 0x00, 0x00,
    0x7f, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff, 0xff,
    0xde, 0x73, 0x7d, 0x56, 0xd3, 0x8b, 0xcf, 0x42,
    0x79, 0xdc, 0xe5, 0x61, 0x7e, 0x31, 0x92, 0xa9,
];

fn ct_lt_be32(a: &[u8; 32], b: &[u8; 32]) -> Choice {
    let mut borrow: u16 = 0;
    for i in (0..32).rev() {
        let diff = (a[i] as u16).wrapping_sub(b[i] as u16).wrapping_sub(borrow);
        borrow = (diff >> 15) & 1;
    }
    Choice::from(borrow as u8)
}

pub fn validate_canonical_p256_p1363(sig64: &[u8; 64]) -> bool {
    let r: &[u8; 32] = sig64[..32].try_into().unwrap();
    let s: &[u8; 32] = sig64[32..].try_into().unwrap();
    let zero = [0u8; 32];

    let r_valid = (!r.ct_eq(&zero)) & ct_lt_be32(r, &P256_N);
    let s_valid = (!s.ct_eq(&zero)) & ct_lt_be32(s, &P256_HALF_N_PLUS_1);
    (r_valid & s_valid).into()
}
