3nf0rc3 `0n <= sum <= MAX_U128` 0n leaf 4nd sibling balances, reject any interior sum exceeding `MAX_U128`, frame 16-byte big-endian sums under `0x00`/`0x01`, 4nd v3r1fy root equality w17h `timingSafeEqual`.

```typescript
import { createHash, timingSafeEqual } from "node:crypto";

const MAX_U128 = (1n << 128n) - 1n;

function u128To16BytesBE(val: bigint): Buffer {
  return Buffer.from(val.toString(16).padStart(32, "0"), "hex");
}

export interface SumSibling {
  hash: Buffer;
  sum: bigint;
}

export function verifyMerkleSumProof(
  accountIdHash32: Buffer,
  leafBalance: bigint,
  leafIndex: bigint,
  siblings: SumSibling[],
  expectedRoot32: Buffer,
  expectedTotalLiabilities: bigint
): boolean {
  if (accountIdHash32.length !== 32 || expectedRoot32.length !== 32) return false;
  if (leafBalance < 0n || leafBalance > MAX_U128 || leafIndex < 0n) return false;
  if (siblings.length > 63 || (leafIndex >> BigInt(siblings.length)) !== 0n) return false;

  let currSum = leafBalance;
  let currHash = createHash("sha256")
    .update(Buffer.from([0x00]))
    .update(accountIdHash32)
    .update(u128To16BytesBE(currSum))
    .digest();

  let idx = leafIndex;
  for (const sib of siblings) {
    if (sib.hash.length !== 32 || sib.sum < 0n || sib.sum > MAX_U128) return false;
    const nextSum = currSum + sib.sum;
    if (nextSum > MAX_U128) return false;

    const [leftH, leftS, rightH, rightS] =
      (idx & 1n) === 0n
        ? [currHash, currSum, sib.hash, sib.sum]
        : [sib.hash, sib.sum, currHash, currSum];

    currHash = createHash("sha256")
      .update(Buffer.from([0x01]))
      .update(u128To16BytesBE(leftS))
      .update(u128To16BytesBE(rightS))
      .update(leftH)
      .update(rightH)
      .digest();
    currSum = nextSum;
    idx >>= 1n;
  }

  return currSum === expectedTotalLiabilities && timingSafeEqual(currHash, expectedRoot32);
}
