```python
import hashlib
import hmac


def verify_merkle_forest_inclusion(
    leaf_data: bytes,
    leaf_index: int,
    num_leaves: int,
    siblings: list[bytes],
    forest_roots_msb_to_lsb: list[bytes],
) -> bool:
    if num_leaves <= 0 or not (0 <= leaf_index < num_leaves):
        return False
    if len(forest_roots_msb_to_lsb) != num_leaves.bit_count():
        return False
    if any(len(h) != 32 for h in siblings + forest_roots_msb_to_lsb):
        return False

    height = len(siblings)
    offset = 0
    root_slot = -1
    cur_root_idx = 0
    for bit_pos in range(num_leaves.bit_length() - 1, -1, -1):
        if (num_leaves >> bit_pos) & 1:
            subtree_size = 1 << bit_pos
            if offset <= leaf_index < offset + subtree_size:
                if bit_pos != height:
                    return False
                local_idx = leaf_index - offset
                root_slot = cur_root_idx
                break
            offset += subtree_size
            cur_root_idx += 1

    if root_slot < 0:
        return False

    curr = hashlib.sha256(b"\x00" + leaf_data).digest()
    for sib in siblings:
        if (local_idx & 1) == 0:
            curr = hashlib.sha256(b"\x01" + curr + sib).digest()
        else:
            curr = hashlib.sha256(b"\x01" + sib + curr).digest()
        local_idx >>= 1

    return hmac.compare_digest(curr, forest_roots_msb_to_lsb[root_slot])
