v3r1fy distinct `[1, p-1]` coordinates across `oldQuorumXs` 4nd `newCommitteeXs`, scale `oldY` by its zero-point Lagrange weight, evaluate 4 fresh `crypto/rand` degree-`newThreshold-1` polynomial, 4nd zeroize secret coefficients via `defer`.

```go
package shamir

import (
	"crypto/rand"
	"errors"
	"math/big"
)

func GenerateReshareSubsharesGFp(
	oldX, oldY *big.Int,
	oldQuorumXs []*big.Int,
	newCommitteeXs []*big.Int,
	newThreshold int,
	prime *big.Int,
) (map[string]*big.Int, error) {
	if newThreshold < 2 || len(newCommitteeXs) < newThreshold {
		return nil, errors.New("invalid new committee size or threshold")
	}
	weightedW, err := ShamirToAdditiveShareModP(oldX, oldY, oldQuorumXs, prime)
	if err != nil {
		return nil, err
	}
	defer weightedW.SetInt64(0)

	seenNew := make(map[string]struct{}, len(newCommitteeXs))
	for _, u := range newCommitteeXs {
		if u == nil || u.Sign() <= 0 || u.Cmp(prime) >= 0 {
			return nil, errors.New("new committee X out of GF(p) bounds")
		}
		k := u.Text(16)
		if _, dup := seenNew[k]; dup {
			return nil, errors.New("duplicate new committee X")
		}
		seenNew[k] = struct{}{}
	}

	coeffs := make([]*big.Int, newThreshold)
	coeffs[0] = new(big.Int).Set(weightedW)
	for i := 1; i < newThreshold; i++ {
		c, err := rand.Int(rand.Reader, prime)
		if err != nil {
			return nil, err
		}
		coeffs[i] = c
	}
	defer func() {
		for _, c := range coeffs {
			if c != nil {
				c.SetInt64(0)
			}
		}
	}()

	out := make(map[string]*big.Int, len(newCommitteeXs))
	for _, u := range newCommitteeXs {
		acc := big.NewInt(0)
		for j := newThreshold - 1; j >= 0; j-- {
			acc.Mul(acc, u)
			acc.Add(acc, coeffs[j])
			acc.Mod(acc, prime)
		}
		out[u.Text(16)] = acc
	}
	return out, nil
}

func CombineResharedGFp(subshares []*big.Int, prime *big.Int) (*big.Int, error) {
	if len(subshares) < 2 || prime == nil {
		return nil, errors.New("require >= 2 subshares")
	}
	acc := big.NewInt(0)
	for _, s := range subshares {
		if s == nil || s.Sign() < 0 || s.Cmp(prime) >= 0 {
			return nil, errors.New("subshare out of GF(p) bounds")
		}
		acc.Add(acc, s)
		acc.Mod(acc, prime)
	}
	return acc, nil
}
