use sha2::{Digest, Sha256};
use std::fs::OpenOptions;
use std::io::{BufRead, Read};
use std::os::unix::fs::OpenOptionsExt;
use std::path::{Component, Path};
use subtle::ConstantTimeEq;

pub fn verify_unambiguous_sha256sums<R: BufRead>(root: &Path, reader: R) -> Result<usize, &'static str> {
    let mut count = 0usize;
    for raw_res in reader.lines() {
        let line = raw_res.map_err(|_| "manifest read failure")?;
        if line.is_empty() {
            continue;
        }
        if line.starts_with('\\') || line.bytes().any(|b| b < 0x20 || b == 0x7f) {
            return Err("escaped or control-char manifest line rejected");
        }
        let (hex_digest, tail) = line.split_at_checked(64).ok_or("malformed line")?;
        let rel_str = tail.strip_prefix("  ").ok_or("expected two-space text separator")?;
        if rel_str.is_empty() || rel_str.starts_with('-') || rel_str.contains('\\') {
            return Err("unsafe filename");
        }
        let mut full = root.to_path_buf();
        for c in Path::new(rel_str).components() {
            match c {
                Component::Normal(p) => full.push(p),
                _ => return Err("traversal rejected"),
            }
        }
        let expected = hex::decode(hex_digest).map_err(|_| "invalid hex digest")?;
        let mut fh = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&full)
            .map_err(|_| "open failed")?;
        let mut hasher = Sha256::new();
        let mut buf = [0u8; 32768];
        loop {
            let n = fh.read(&mut buf).map_err(|_| "io error")?;
            if n == 0 {
                break;
            }
            hasher.update(&buf[..n]);
        }
        if hasher.finalize().as_slice().ct_eq(expected.as_slice()).unwrap_u8() != 1 {
            return Err("digest mismatch");
        }
        count += 1;
    }
    if count == 0 {
        return Err("manifest had zero entries");
    }
    Ok(count)
}
