import { createHash, timingSafeEqual } from "node:crypto";
import { constants as fsConst } from "node:fs";
import { open, realpath } from "node:fs/promises";
import path from "node:path";

export async function verifySriManifest(
  distRoot: string,
  sriMap: Record<string, string>
): Promise<void> {
  const rootReal = await realpath(distRoot);
  const entries = Object.entries(sriMap);
  if (entries.length === 0) {
    throw new Error("Empty SRI manifest");
  }
  for (const [assetPath, sri] of entries) {
    if (!sri.startsWith("sha256-")) {
      throw new Error(`Unsupported SRI algorithm for ${assetPath}`);
    }
    const expected = Buffer.from(sri.slice("sha256-".length), "base64");
    if (expected.length !== 32) {
      throw new Error(`Invalid base64 SHA-256 digest length for ${assetPath}`);
    }
    const resolved = path.resolve(rootReal, assetPath);
    const rel = path.relative(rootReal, resolved);
    if (rel.startsWith("..") || path.isAbsolute(rel)) {
      throw new Error(`Asset path escapes distRoot: ${assetPath}`);
    }
    const fh = await open(resolved, fsConst.O_RDONLY | (fsConst.O_NOFOLLOW ?? 0));
    try {
      const st = await fh.stat();
      if (!st.isFile()) {
        throw new Error(`Asset is not a regular file: ${assetPath}`);
      }
      const data = await fh.readFile();
      const actual = createHash("sha256").update(data).digest();
      if (!timingSafeEqual(actual, expected)) {
        throw new Error(`SRI mismatch for ${assetPath}`);
      }
    } finally {
      await fh.close();
    }
  }
}
