```go
package merklemanifest

import (
	"crypto/sha256"
	"crypto/subtle"
	"encoding/binary"
	"sort"
)

type LeafEntry struct {
	RelPath string
	FileSum [32]byte
}

func ComputeManifestRoot(entries []LeafEntry) [32]byte {
	sorted := append([]LeafEntry(nil), entries...)
	sort.Slice(sorted, func(i, j int) bool { return sorted[i].RelPath < sorted[j].RelPath })

	level := make([][32]byte, len(sorted))
	for i, e := range sorted {
		h := sha256.New()
		h.Write([]byte{0x00})
		h.Write([]byte(e.RelPath))
		h.Write([]byte{0x00})
		h.Write(e.FileSum[:])
		copy(level[i][:], h.Sum(nil))
	}
	for len(level) > 1 {
		next := make([][32]byte, 0, (len(level)+1)/2)
		for i := 0; i < len(level); i += 2 {
			if i+1 == len(level) {
				next = append(next, level[i])
				continue
			}
			h := sha256.New()
			h.Write([]byte{0x01})
			h.Write(level[i][:])
			h.Write(level[i+1][:])
			var p [32]byte
			copy(p[:], h.Sum(nil))
			next = append(next, p)
		}
		level = next
	}
	env := sha256.New()
	env.Write([]byte{0x02})
	var cnt [8]byte
	binary.BigEndian.PutUint64(cnt[:], uint64(len(sorted)))
	env.Write(cnt[:])
	if len(level) == 1 {
		env.Write(level[0][:])
	}
	var root [32]byte
	copy(root[:], env.Sum(nil))
	return root
}

func VerifyManifestRoot(entries []LeafEntry, expected [32]byte) bool {
	actual := ComputeManifestRoot(entries)
	return subtle.ConstantTimeCompare(actual[:], expected[:]) == 1
}
