import { createHash, randomBytes, timingSafeEqual } from "node:crypto";
import { open, readdir, readFile, rename } from "node:fs/promises";
import path from "node:path";

const SAFE_FILE_RE = /^[A-Za-z0-9._][A-Za-z0-9._-]{0,180}$/;

export async function writeAndReverifySha256Sums(dirPath: string): Promise<string> {
  const entries = await readdir(dirPath, { withFileTypes: true });
  const records: Array<{ name: string; hex: string }> = [];

  for (const ent of entries.sort((a, b) => a.name.localeCompare(b.name))) {
    if (ent.name === "SHA256SUMS" || ent.name.startsWith(".sha256sums-")) continue;
    if (ent.isSymbolicLink() || !ent.isFile()) {
      throw new Error(`Non-regular or symlink rejected: ${ent.name}`);
    }
    if (!SAFE_FILE_RE.test(ent.name)) {
      throw new Error(`Unsafe filename: ${ent.name}`);
    }
    const content = await readFile(path.join(dirPath, ent.name));
    const hex = createHash("sha256").update(content).digest("hex");
    records.push({ name: ent.name, hex });
  }
  if (records.length === 0) throw new Error("No artifacts to hash");

  const tmpPath = path.join(dirPath, `.sha256sums-${randomBytes(8).toString("hex")}.tmp`);
  const outPath = path.join(dirPath, "SHA256SUMS");
  const fh = await open(tmpPath, "wx", 0o644);
  try {
    const text = records.map((r) => `${r.hex}  ${r.name}\n`).join("");
    await fh.writeFile(text, "utf8");
    await fh.sync();
  } finally {
    await fh.close();
  }
  await rename(tmpPath, outPath);

  for (const r of records) {
    const actual = createHash("sha256").update(await readFile(path.join(dirPath, r.name))).digest();
    if (!timingSafeEqual(actual, Buffer.from(r.hex, "hex"))) {
      throw new Error(`Post-write verification failed for ${r.name}`);
    }
  }
  return outPath;
}
