package auditparser

import (
	"encoding/hex"
	"strconv"
	"strings"
)

type ProcTitleRecord struct {
	AuditID string
	UID     int
	Argv    []string
}

func sanitizeASCII(b []byte) string {
	out := make([]byte, len(b))
	for i, c := range b {
		if c >= 0x20 && c <= 0x7e {
			out[i] = c
		} else {
			out[i] = '?'
		}
	}
	return string(out)
}

func ParseAuditProcTitle(line string) (ProcTitleRecord, bool) {
	var rec ProcTitleRecord
	rec.UID = -1
	for _, tok := range strings.Fields(line) {
		if v, ok := strings.CutPrefix(tok, "msg=audit("); ok {
			rec.AuditID = strings.TrimSuffix(v, "):")
		} else if v, ok := strings.CutPrefix(tok, "uid="); ok {
			if u, err := strconv.Atoi(v); err == nil && u >= 0 {
				rec.UID = u
			}
		} else if v, ok := strings.CutPrefix(tok, "proctitle="); ok {
			if raw, err := hex.DecodeString(v); err == nil && len(raw) > 0 {
				for _, part := range strings.Split(strings.TrimRight(string(raw), "\x00"), "\x00") {
					rec.Argv = append(rec.Argv, sanitizeASCII([]byte(part)))
				}
			}
		}
	}
	return rec, rec.AuditID != "" && len(rec.Argv) > 0
}
