    let out_path = tmp.path().join("decompressed.bin");

    let mut child = Command::new("/bin/gzip")
        .args(["-d", "-c", "--"])
        .arg(gz_path)
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .map_err(|_| "failed spawning gzip")?;

    let stdout = child.stdout.take().ok_or("missing stdout")?;
    let mut limited = stdout.take(max_bytes + 1);
    let mut out_file = File::create(&out_path).map_err(|_| "create failed")?;
    let mut hasher = Sha256::new();
    let mut buf = [0u8; 32768];
    let mut total = 0u64;

    loop {
        let n = limited.read(&mut buf).map_err(|_| "read error")?;
        if n == 0 {
            break;
        }
        total += n as u64;
        if total > max_bytes {
            let _ = child.kill();
            return Err("decompressed payload exceeded max_bytes");
        }
        hasher.update(&buf[..n]);
        out_file.write_all(&buf[..n]).map_err(|_| "write error")?;
    }
    let status = child.wait().map_err(|_| "wait failed")?;
    if !status.success() {
        return Err("gzip exited non-zero");
    }
    if hasher.finalize().as_slice().ct_eq(expected_sha256).unwrap_u8() != 1 {
        return Err("uncompressed sha256 mismatch");
    }
    Ok((tmp, out_path))
}
