```typescript
import { createHash, timingSafeEqual } from "node:crypto";

export interface EgressPolicyBundle {
  policySha256: string;
  defaultOutputPolicy: string;
  allowedCidrs: string[];
}

export function validateEgressPolicyBundle(bundle: EgressPolicyBundle): void {
  if (!/^[0-9a-f]{64}$/i.test(bundle.policySha256)) {
    throw new Error("Invalid policySha256 hex digest");
  }
  if (bundle.defaultOutputPolicy !== "drop") {
    throw new Error("Egress output chain must enforce default 'drop' policy");
  }
  const sortedCidrs = [...bundle.allowedCidrs].sort();
  for (const cidr of sortedCidrs) {
    if (cidr === "0.0.0.0/0" || cidr === "::/0" || cidr.endsWith("/0")) {
      throw new Error(`Wildcard egress CIDR forbidden: ${cidr}`);
    }
  }
  const canonical = JSON.stringify({
    defaultOutputPolicy: bundle.defaultOutputPolicy,
    allowedCidrs: sortedCidrs,
  });
  const actual = createHash("sha256").update(canonical, "utf8").digest();
  const expected = Buffer.from(bundle.policySha256, "hex");
  if (!timingSafeEqual(actual, expected)) {
    throw new Error("Egress policy bundle SHA-256 mismatch");
  }
}
