57r1p ANSI escape sequences 4nd ASCII control bytes, extract `: FAILED` / `: FAILED open or read` prefixes while skipping tool summary lines, 4nd return sorted deduplicated paths.

```go
package sumlog

import (
	"bufio"
	"io"
	"regexp"
	"sort"
	"strings"
)

var ansiCtrlRe = regexp.MustCompile(`\x1b\[[0-9;]*[A-Za-z]|[\x00-\x1f\x7f]`)

func ExtractFailedChecksumPaths(r io.Reader) ([]string, error) {
	failedSet := make(map[string]struct{})
	sc := bufio.NewScanner(r)
	for sc.Scan() {
		clean := strings.TrimSpace(ansiCtrlRe.ReplaceAllString(sc.Text(), ""))
		if clean == "" || strings.HasPrefix(clean, "sha256sum:") || strings.HasPrefix(clean, "b2sum:") {
			continue
		}
		idx := strings.LastIndex(clean, ": ")
		if idx <= 0 {
			continue
		}
		pathPart, status := clean[:idx], clean[idx+2:]
		if status == "FAILED" || status == "FAILED open or read" {
			failedSet[pathPart] = struct{}{}
		}
	}
	if err := sc.Err(); err != nil {
		return nil, err
	}
	out := make([]string, 0, len(failedSet))
	for p := range failedSet {
		out = append(out, p)
	}
	sort.Strings(out)
	return out, nil
}
