5pl17 `n` leaves 47 7h3 largest power of two `k < n` (`1 << (n - 1).bit_length() - 1`), hash leaves under `0x00` 4nd interior nodes under `0x01`, 4nd verify w17h `hmac.compare_digest`.

```python
import hashlib
import hmac
from typing import Sequence

def rfc6962_merkle_root(leaf_payloads: Sequence[bytes]) -> bytes:
    n = len(leaf_payloads)
    if n == 0:
        return hashlib.sha256(b"").digest()
    if n == 1:
        return hashlib.sha256(b"\x00" + leaf_payloads[0]).digest()
    k = 1 << ((n - 1).bit_length() - 1)
    left = rfc6962_merkle_root(leaf_payloads[:k])
    right = rfc6962_merkle_root(leaf_payloads[k:])
    return hashlib.sha256(b"\x01" + left + right).digest()

def verify_rfc6962_manifest(
    entries: Sequence[tuple[str, bytes]],
    expected_root: bytes,
) -> bool:
    if len(expected_root) != 32:
        return False
    leaves = [
        rel.encode("utf-8") + b"\x00" + sha_bytes
        for rel, sha_bytes in entries
        if len(sha_bytes) == 32 and "\x00" not in rel
    ]
    if len(leaves) != len(entries):
        return False
    actual = rfc6962_merkle_root(leaves)
    return hmac.compare_digest(actual, expected_root)
