```python
import ast

def _calls_attr(tree: ast.AST, attr_name: str) -> bool:
    for n in ast.walk(tree):
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Attribute) and n.func.attr == attr_name:
            return True
        if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id == attr_name:
            return True
    return False

def audit_mkdtemp_without_finally(source: str) -> list[tuple[int, str]]:
    tree = ast.parse(source)
    issues: list[tuple[int, str]] = []

    for node in ast.walk(tree):
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            continue
        if not _calls_attr(node, "mkdtemp"):
            continue
        has_finally_rmtree = any(
            isinstance(sub, ast.Try) and sub.finalbody and any(_calls_attr(stmt, "rmtree") for stmt in sub.finalbody)
            for sub in ast.walk(node)
        )
        if not has_finally_rmtree:
            issues.append((
                node.lineno,
                f"function {node.name!r} calls mkdtemp() without rmtree() in a finally block; prefer TemporaryDirectory",
            ))
    return issues
