```go
package sysverify

import (
	"context"
	"encoding/hex"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

func RunSystemSha256Check(ctx context.Context, artifactDir string, sums map[string]string) error {
	if len(sums) == 0 {
		return errors.New("empty checksum map")
	}
	tmpDir, err := os.MkdirTemp("", "shachk-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir)

	var b strings.Builder
	for name, hexDig := range sums {
		if name == "" || strings.HasPrefix(name, "-") || strings.ContainsAny(name, "/\\\r\n\x00") {
			return errors.New("unsafe artifact name: " + name)
		}
		raw, err := hex.DecodeString(hexDig)
		if err != nil || len(raw) != 32 {
			return errors.New("invalid sha256 hex for " + name)
		}
		fmt.Fprintf(&b, "%x  %s\n", raw, name)
	}
	sumsPath := filepath.Join(tmpDir, "SHA256SUMS")
	if err := os.WriteFile(sumsPath, []byte(b.String()), 0o600); err != nil {
		return err
	}
	cmd := exec.CommandContext(ctx, "/usr/bin/sha256sum", "--strict", "--quiet", "-c", "--", sumsPath)
	cmd.Dir = artifactDir
	cmd.Env = []string{"PATH=/usr/bin:/bin", "LC_ALL=C"}
	return cmd.Run()
}
