use serde_json::Value;
use sha2::{Digest, Sha256};
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::{Component, Path};
use subtle::ConstantTimeEq;

pub fn verify_json_file_map(root: &Path, json_text: &str) -> Result<usize, &'static str> {
    let root_val: Value = serde_json::from_str(json_text).map_err(|_| "invalid json")?;
    let files = root_val.get("files").and_then(Value::as_object).ok_or("missing files map")?;
    if files.is_empty() {
        return Err("empty files map");
    }
    for (rel, meta_val) in files {
        let size = meta_val.get("size").and_then(Value::as_u64).ok_or("missing u64 size")?;
        let hex_str = meta_val.get("sha256").and_then(Value::as_str).ok_or("missing sha256")?;
        let expected = hex::decode(hex_str).map_err(|_| "invalid sha256 hex")?;
        if expected.len() != 32 {
            return Err("sha256 must be 32 bytes");
        }
        let mut full = root.to_path_buf();
        for c in Path::new(rel).components() {
            match c {
                Component::Normal(s) => full.push(s),
                _ => return Err("unsafe path component"),
            }
        }
        let mut fh = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&full)
            .map_err(|_| "open failed")?;
        let md = fh.metadata().map_err(|_| "stat failed")?;
        if !md.is_file() || md.len() != size {
            return Err("file type or size mismatch");
        }
        let mut hasher = Sha256::new();
        let mut buf = [0u8; 32768];
        loop {
            let n = fh.read(&mut buf).map_err(|_| "read error")?;
            if n == 0 {
                break;
            }
            hasher.update(&buf[..n]);
        }
        if hasher.finalize().as_slice().ct_eq(expected.as_slice()).unwrap_u8() != 1 {
            return Err("sha256 mismatch");
        }
    }
    Ok(files.len())
}
