```typescript
import { createHash, timingSafeEqual } from "node:crypto";
import { execFile } from "node:child_process";
import { lstat, mkdtemp, readFile, rename, rm } from "node:fs/promises";
import path from "node:path";
import { promisify } from "node:util";

const execFileAsync = promisify(execFile);

export async function promoteVerifiedArtifact(
  srcFile: string,
  releaseDir: string,
  artifactName: string,
  expectedSha256Hex: string
): Promise<void> {
  if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/.test(artifactName)) {
    throw new Error(`Unsafe artifact name: ${artifactName}`);
  }
  if (!/^[0-9a-f]{64}$/i.test(expectedSha256Hex)) {
    throw new Error("Invalid expected SHA-256 hex");
  }
  const workDir = await mkdtemp(path.join(releaseDir, ".promote-"));
  const staged = path.join(workDir, artifactName);
  try {
    await execFileAsync("/bin/cp", ["--no-dereference", "--", srcFile, staged]);
    const st = await lstat(staged);
    if (!st.isFile() || st.isSymbolicLink()) {
      throw new Error("Staged file is a symlink or non-regular file");
    }
    const actual = createHash("sha256").update(await readFile(staged)).digest();
    if (!timingSafeEqual(actual, Buffer.from(expectedSha256Hex, "hex"))) {
      throw new Error("Artifact SHA-256 mismatch during promotion");
    }
    await rename(staged, path.join(releaseDir, artifactName));
  } finally {
    await rm(workDir, { recursive: true, force: true });
  }
}
