use serde_json::Value;
use std::collections::HashMap;

pub fn aggregate_ulogd_drops(jsonl: &str) -> HashMap<(u8, u8, u16), u64> {
    let mut counts: HashMap<(u8, u8, u16), u64> = HashMap::new();
    for line in jsonl.lines() {
        let Ok(val) = serde_json::from_str::<Value>(line) else { continue };
        let Some(prefix) = val.get("oob.prefix").and_then(Value::as_str) else { continue };
        if !prefix.contains("EGRESS_DROP") {
            continue;
        }
        let Some(fam) = val.get("oob.family").and_then(Value::as_u64) else { continue };
        let Some(proto) = val.get("ip.protocol").and_then(Value::as_u64) else { continue };
        let dport = val
            .get("tcp.dport")
            .or_else(|| val.get("udp.dport"))
            .and_then(Value::as_u64)
            .unwrap_or(0);
        if fam <= u8::MAX as u64 && proto <= u8::MAX as u64 && dport <= u16::MAX as u64 {
            *counts.entry((fam as u8, proto as u8, dport as u16)).or_insert(0) += 1;
        }
    }
    counts
}
