use hmac::{Hmac, Mac};
use sha2::Sha256;

type HmacSha256 = Hmac<Sha256>;

#[derive(Clone)]
pub struct ManifestItem<'a> {
    pub rel_path: &'a str,
    pub byte_len: u64,
    pub sha256: [u8; 32],
}

pub fn verify_canonical_hmac(
    key: &[u8],
    items: &[ManifestItem<'_>],
    expected_tag: &[u8],
) -> Result<(), &'static str> {
    if key.len() < 32 {
        return Err("hmac key must be >= 32 bytes");
    }
    let mut sorted = items.to_vec();
    sorted.sort_by(|a, b| a.rel_path.as_bytes().cmp(b.rel_path.as_bytes()));

    let mut mac = HmacSha256::new_from_slice(key).map_err(|_| "invalid key")?;
    mac.update(b"rust-manifest-hmac-v1\0");
    mac.update(&(sorted.len() as u32).to_be_bytes());
    for item in &sorted {
        let pb = item.rel_path.as_bytes();
        mac.update(&(pb.len() as u32).to_be_bytes());
        mac.update(pb);
        mac.update(&item.byte_len.to_be_bytes());
        mac.update(&item.sha256);
    }
    mac.verify_slice(expected_tag).map_err(|_| "hmac verification failed")
}
