```go
package hexaudit

import (
	"go/ast"
	"go/parser"
	"go/token"
)

func isHexEncodeCall(expr ast.Expr) bool {
	call, ok := expr.(*ast.CallExpr)
	if !ok {
		return false
	}
	sel, ok := call.Fun.(*ast.SelectorExpr)
	if !ok {
		return false
	}
	pkg, ok := sel.X.(*ast.Ident)
	return ok && pkg.Name == "hex" && sel.Sel.Name == "EncodeToString"
}

func FindNonConstantHexComparisons(src string) ([]int, error) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "audit.go", src, 0)
	if err != nil {
		return nil, err
	}
	var lines []int
	ast.Inspect(f, func(n ast.Node) bool {
		bin, ok := n.(*ast.BinaryExpr)
		if !ok || (bin.Op != token.EQL && bin.Op != token.NEQ) {
			return true
		}
		if isHexEncodeCall(bin.X) || isHexEncodeCall(bin.Y) {
			lines = append(lines, fset.Position(bin.Pos()).Line)
		}
		return true
	})
	return lines, nil
}
