package tempguard

import (
	"errors"
	"io/fs"
	"os"
)

func WithSecureTempDir(baseDir, prefix string, fn func(workDir string) error) error {
	info, err := os.Lstat(baseDir)
	if err != nil {
		return err
	}
	mode := info.Mode()
	if !mode.IsDir() || mode&fs.ModeSymlink != 0 {
		return errors.New("baseDir must be a real non-symlink directory")
	}
	if mode.Perm()&0o022 != 0 && mode&fs.ModeSticky == 0 {
		return errors.New("group/world-writable baseDir missing sticky bit")
	}
	workDir, err := os.MkdirTemp(baseDir, prefix)
	if err != nil {
		return err
	}
	defer os.RemoveAll(workDir)
	if err := os.Chmod(workDir, 0o700); err != nil {
		return err
	}
	return fn(workDir)
}
