use sha2::{Digest, Sha256};
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::{Component, Path};
use subtle::ConstantTimeEq;

pub fn verify_capped_manifest<R: Read>(
    root: &Path,
    reader: R,
    max_manifest_bytes: usize,
) -> Result<usize, &'static str> {
    let mut raw = Vec::new();
    reader
        .take((max_manifest_bytes + 1) as u64)
        .read_to_end(&mut raw)
        .map_err(|_| "manifest read error")?;
    if raw.len() > max_manifest_bytes {
        return Err("manifest exceeds max_manifest_bytes cap");
    }
    let text = core::str::from_utf8(&raw).map_err(|_| "manifest not utf8")?;
    let mut count = 0usize;
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        let (hex_dig, rest) = line.split_at_checked(64).ok_or("malformed line")?;
        let rel = rest.strip_prefix("  ").ok_or("missing two-space delimiter")?;
        let expected = hex::decode(hex_dig).map_err(|_| "invalid hex")?;
        let mut target = root.to_path_buf();
        for c in Path::new(rel).components() {
            match c {
                Component::Normal(seg) => target.push(seg),
                _ => return Err("unsafe path component"),
            }
        }
        let mut fh = OpenOptions::new()
            .read(true)
            .custom_flags(libc::O_NOFOLLOW)
            .open(&target)
            .map_err(|_| "open failed")?;
        let mut hasher = Sha256::new();
        let mut buf = [0u8; 16384];
        loop {
            let n = fh.read(&mut buf).map_err(|_| "file read error")?;
            if n == 0 {
                break;
            }
            hasher.update(&buf[..n]);
        }
        if hasher.finalize().as_slice().ct_eq(expected.as_slice()).unwrap_u8() != 1 {
            return Err("sha256 mismatch");
        }
        count += 1;
    }
    if count == 0 {
        return Err("empty manifest");
    }
    Ok(count)
}
