```typescript
import { createHash, createHmac, timingSafeEqual } from "node:crypto";
import { constants as fsConst } from "node:fs";
import { open, realpath } from "node:fs/promises";
import path from "node:path";

export async function verifyHmacProtectedSums(
  hmacKey: Buffer,
  manifestBytes: Buffer,
  expectedMacHex: string,
  rootDir: string
): Promise<number> {
  if (hmacKey.length < 32) throw new Error("HMAC key must be >= 32 bytes");
  const actualMac = createHmac("sha256", hmacKey).update(manifestBytes).digest();
  const wantMac = Buffer.from(expectedMacHex, "hex");
  if (wantMac.length !== 32 || !timingSafeEqual(actualMac, wantMac)) {
    throw new Error("Manifest HMAC verification failed");
  }

  const rootReal = await realpath(rootDir);
  const lines = manifestBytes.toString("utf8").split("\n").filter((l) => l.trim().length > 0);
  if (lines.length === 0) throw new Error("Authenticated manifest is empty");

  for (const line of lines) {
    const m = /^([0-9a-f]{64})  ([^\0\r\n]+)$/i.exec(line);
    if (!m) throw new Error("Invalid manifest line");
    const [, hexDig, relName] = m;
    const full = path.resolve(rootReal, relName);
    const rel = path.relative(rootReal, full);
    if (rel.startsWith("..") || path.isAbsolute(rel)) {
      throw new Error(`Path traversal rejected: ${relName}`);
    }
    const fh = await open(full, fsConst.O_RDONLY | (fsConst.O_NOFOLLOW ?? 0));
    try {
      const st = await fh.stat();
      if (!st.isFile()) throw new Error(`Non-regular file: ${relName}`);
      const digest = createHash("sha256").update(await fh.readFile()).digest();
      if (!timingSafeEqual(digest, Buffer.from(hexDig, "hex"))) {
