import re

TMP_PATH_RE = re.compile(r"(?:/var)?/tmp\b")

def lint_systemd_unit_tmp_isolation(unit_text: str) -> list[str]:
    in_service = False
    private_tmp = False
    exec_tmp_lines: list[str] = []

