        if key == "PrivateTmp" and val.lower() in {"yes", "true", "1"}:
            private_tmp = True
        elif key.startswith("ExecStart") and TMP_PATH_RE.search(val):
            exec_tmp_lines.append(f"{key}={val}")

    if exec_tmp_lines and not private_tmp:
        return [
            f"shared temp path in {cmd!r} without PrivateTmp=yes in [Service]"
            for cmd in exec_tmp_lines
        ]
