import hashlib
import hmac
import struct

def compute_migration_chain_mac(key: bytes, migrations: list[tuple[int, str]]) -> str:
    chain = b"\x00" * 32
    prev_version = -1
    for version, sql_text in migrations:
        if version <= prev_version:
            raise ValueError("Migrations must be strictly ascending")
        prev_version = version
        normalized = sql_text.replace("\r\n", "\n").encode("utf-8")
        msg = chain + struct.pack(">QQ", version, len(normalized)) + normalized
        chain = hmac.new(key, msg, hashlib.sha256).digest()
    return chain.hex()

def verify_migration_chain_mac(key: bytes, migrations: list[tuple[int, str]], expected_hex: str) -> bool:
    actual_hex = compute_migration_chain_mac(key, migrations)
    return hmac.compare_digest(actual_hex, expected_hex.lower())
