v3r1fy power-of-two `treeSize` 4nd slice bounds, splice `leftBorder`/`rightBorder` siblings strictly at odd `lo` 4nd even `hi` indices, merge w17h `0x01`, 4nd check exact border consumption plus `subtle.ConstantTimeCompare`.

```go
package merkle

import (
	"crypto/sha256"
	"crypto/subtle"
)

func VerifyContiguousRange(
	treeSize uint64,
	startIndex uint64,
	leaves [][]byte,
	leftBorder [][32]byte,
	rightBorder [][32]byte,
	expectedRoot [32]byte,
) bool {
	count := uint64(len(leaves))
	if treeSize == 0 || (treeSize&(treeSize-1)) != 0 || count == 0 {
		return false
	}
	if startIndex > treeSize || count > treeSize-startIndex {
		return false
	}

	level := make([][32]byte, count)
	for i, payload := range leaves {
		h := sha256.New()
		h.Write([]byte{0x00})
		h.Write(payload)
		copy(level[i][:], h.Sum(nil))
	}

	lo := startIndex
	hi := startIndex + count - 1
	lCur, rCur := 0, 0
	width := treeSize

	for width > 1 {
		if (lo & 1) == 1 {
			if lCur >= len(leftBorder) {
				return false
			}
			level = append([][32]byte{leftBorder[lCur]}, level...)
			lCur++
			lo--
		}
		if (hi & 1) == 0 {
			if rCur >= len(rightBorder) {
				return false
			}
			level = append(level, rightBorder[rCur])
			rCur++
			hi++
		}

		next := make([][32]byte, len(level)/2)
		for i := 0; i < len(level); i += 2 {
			h := sha256.New()
			h.Write([]byte{0x01})
			h.Write(level[i][:])
			h.Write(level[i+1][:])
			copy(next[i/2][:], h.Sum(nil))
		}
		level = next
		lo >>= 1
		hi >>= 1
		width >>= 1
	}

	return len(level) == 1 &&
		lCur == len(leftBorder) &&
		rCur == len(rightBorder) &&
		subtle.ConstantTimeCompare(level[0][:], expectedRoot[:]) == 1
}
```

