```rust
const M61: u64 = (1u64 << 61) - 1;

fn m61_add(a: u64, b: u64) -> u64 {
    ((a as u128 + b as u128) % (M61 as u128)) as u64
}

fn m61_sub(a: u64, b: u64) -> u64 {
    ((a as u128 + M61 as u128 - (b % M61) as u128) % (M61 as u128)) as u64
}

fn m61_mul(a: u64, b: u64) -> u64 {
    ((a as u128 * b as u128) % (M61 as u128)) as u64
}

fn m61_pow(mut base: u64, mut exp: u64) -> u64 {
    let mut acc = 1u64;
    base %= M61;
    while exp > 0 {
        if (exp & 1) == 1 {
            acc = m61_mul(acc, base);
        }
        base = m61_mul(base, base);
        exp >>= 1;
    }
    acc
}

fn eval_lagrange_m61(target_x: u64, basis: &[(u64, u64)]) -> u64 {
    let mut acc = 0u64;
    for (i, &(xi, yi)) in basis.iter().enumerate() {
        let mut num = 1u64;
        let mut den = 1u64;
        for (j, &(xj, _)) in basis.iter().enumerate() {
            if i == j {
                continue;
            }
            num = m61_mul(num, m61_sub(target_x, xj));
            den = m61_mul(den, m61_sub(xi, xj));
        }
        let term = m61_mul(yi, m61_mul(num, m61_pow(den, M61 - 2)));
        acc = m61_add(acc, term);
    }
    acc
}

pub fn reconstruct_consistent_m61(shares: &[(u64, u64)], threshold: usize) -> Result<u64, &'static str> {
    if threshold < 2 || shares.len() < threshold {
        return Err("insufficient shares");
    }
    for (i, &(x, y)) in shares.iter().enumerate() {
        if x == 0 || x >= M61 || y >= M61 {
            return Err("coordinate out of GF(2^61 - 1) range");
        }
        if shares[..i].iter().any(|&(px, _)| px == x) {
            return Err("duplicate share x-coordinate");
        }
    }

    let basis = &shares[..threshold];
    for &(ex, ey) in &shares[threshold..] {
        if eval_lagrange_m61(ex, basis) != ey {
            return Err("inconsistent share set: cheating or corrupted share detected");
        }
    }
    Ok(eval_lagrange_m61(0, basis))
}
