```typescript
import { createHash, timingSafeEqual } from "node:crypto";

const EMPTY_LEAF = createHash("sha256").update(Buffer.alloc(33, 0x00)).digest();

function smtLeafHash(keyHash32: Buffer, val: Buffer | null): Buffer {
  if (val === null) return EMPTY_LEAF;
  const valHash = createHash("sha256").update(val).digest();
  return createHash("sha256").update(Buffer.from([0x00])).update(keyHash32).update(valHash).digest();
}

export function verifySmtAtomicUpdate(
  key: Buffer,
  oldValue: Buffer | null,
  newValue: Buffer,
  siblings: Buffer[],
  oldRoot32: Buffer,
  newRoot32: Buffer
): boolean {
  if (key.length === 0 || siblings.length !== 256 || oldRoot32.length !== 32 || newRoot32.length !== 32) {
    return false;
  }
  if (siblings.some((s) => s.length !== 32)) return false;

  const keyHash = createHash("sha256").update(key).digest();
  let oldCurr = smtLeafHash(keyHash, oldValue);
  let newCurr = smtLeafHash(keyHash, newValue);

  for (let lvl = 0; lvl < 256; lvl++) {
    const byteIdx = 31 - Math.floor(lvl / 8);
    const bit = (keyHash[byteIdx] >> (lvl % 8)) & 1;
    const sib = siblings[lvl];

    if (bit === 0) {
      oldCurr = createHash("sha256").update(Buffer.from([0x01])).update(oldCurr).update(sib).digest();
      newCurr = createHash("sha256").update(Buffer.from([0x01])).update(newCurr).update(sib).digest();
    } else {
      oldCurr = createHash("sha256").update(Buffer.from([0x01])).update(sib).update(oldCurr).digest();
      newCurr = createHash("sha256").update(Buffer.from([0x01])).update(sib).update(newCurr).digest();
    }
  }

  return timingSafeEqual(oldCurr, oldRoot32) && timingSafeEqual(newCurr, newRoot32);
}
