impl SqlitePoolGuard {
    pub async fn acquire(&self, wait: Duration) -> Result<(Connection, OwnedSemaphorePermit), String> {
        let permit = timeout(wait, self.sem.clone().acquire_owned())
            .await
            .map_err(|_| "pool checkout timed out".to_string())?
            .map_err(|_| "pool closed".to_string())?;
