import hashlib
import hmac

def merkle_migration_root(migrations: list[tuple[int, bytes]]) -> str:
    if not migrations:
        return hashlib.sha256(b"\x00").hexdigest()
    ordered = sorted(migrations, key=lambda item: item[0])
    level = [
        hashlib.sha256(b"\x00" + ver.to_bytes(8, "big") + hashlib.sha256(sql).digest()).digest()
        for ver, sql in ordered
    ]
    while len(level) > 1:
        nxt: list[bytes] = []
        for idx in range(0, len(level), 2):
            left = level[idx]
            right = level[idx + 1] if idx + 1 < len(level) else left
            nxt.append(hashlib.sha256(b"\x01" + left + right).digest())
        level = nxt
    return level[0].hex()

def verify_merkle_root(migrations: list[tuple[int, bytes]], pinned_hex: str) -> bool:
