func PackageWithSha256Sidecar(ctx context.Context, srcDir, outDir, archiveBase string) error {
	if archiveBase == "" || strings.ContainsAny(archiveBase, "/\\") || strings.HasPrefix(archiveBase, "-") {
		return errors.New("unsafe archive base name")
	}
	tmpDir, err := os.MkdirTemp(outDir, ".pkgstage-*")
	if err != nil {
		return err
	}
