	tarName := archiveBase + ".tar.gz"
	stagedTar := filepath.Join(tmpDir, tarName)
	cmd := exec.CommandContext(ctx, "tar", "--owner=0", "--group=0", "-C", srcDir, "-czf", stagedTar, "--", ".")
	if err := cmd.Run(); err != nil {
		return err
	}

	f, err := os.Open(stagedTar)
	if err != nil {
		return err
	}
	h := sha256.New()
	_, copyErr := io.Copy(h, f)
	f.Close()
	if copyErr != nil {
		return copyErr
	}
	sumLine := fmt.Sprintf("%s  %s\n", hex.EncodeToString(h.Sum(nil)), tarName)
	stagedSum := filepath.Join(tmpDir, tarName+".sha256")
	if err := os.WriteFile(stagedSum, []byte(sumLine), 0o644); err != nil {
		return err
	}
	if err := os.Rename(stagedTar, filepath.Join(outDir, tarName)); err != nil {
		return err
	}
	return os.Rename(stagedSum, filepath.Join(outDir, tarName+".sha256"))
}
