```typescript
import { timingSafeEqual } from "node:crypto";
import { spawn } from "node:child_process";
import { lstat } from "node:fs/promises";
import path from "node:path";

export async function spawnAndVerifySha256(
  workDir: string,
  expected: Record<string, string>
): Promise<void> {
  const names = Object.keys(expected);
  if (names.length === 0) throw new Error("Empty expected map");
  for (const n of names) {
    if (!/^[A-Za-z0-9._][A-Za-z0-9._-]{0,120}$/.test(n)) {
      throw new Error(`Unsafe filename: ${n}`);
    }
    const st = await lstat(path.join(workDir, n));
    if (!st.isFile() || st.isSymbolicLink()) {
      throw new Error(`Not a regular file: ${n}`);
    }
  }

  const stdout = await new Promise<string>((resolve, reject) => {
    const child = spawn("/usr/bin/sha256sum", ["--", ...names], {
      cwd: workDir,
      shell: false,
      env: { PATH: "/usr/bin:/bin", LC_ALL: "C" },
      stdio: ["ignore", "pipe", "pipe"],
    });
    let out = "";
    child.stdout.setEncoding("utf8");
    child.stdout.on("data", (chunk: string) => { out += chunk; });
    child.on("error", reject);
    child.on("close", (code) => (code === 0 ? resolve(out) : reject(new Error(`sha256sum exited ${code}`))));
  });

  const lines = stdout.trim().split("\n");
  if (lines.length !== names.length) throw new Error("Output count mismatch");
  for (const ln of lines) {
    const [hex, file] = [ln.slice(0, 64), ln.slice(66)];
    const want = Buffer.from(expected[file] ?? "", "hex");
    const got = Buffer.from(hex, "hex");
    if (want.length !== 32 || got.length !== 32 || !timingSafeEqual(got, want)) {
      throw new Error(`Digest mismatch for ${file}`);
    }
  }
}
