        ip_hdr = pkt.get("ip") or pkt.get("ip6") or {}
        l4_hdr = pkt.get("tcp") or pkt.get("udp") or {}
        try:
            daddr = str(ipaddress.ip_address(str(ip_hdr.get("daddr", ""))))
            dport = int(l4_hdr.get("dport", 0))
