package archmanifest

import (
	"crypto/hmac"
	"crypto/sha256"
	"errors"
)

func derivePlatformKey(ikm, salt []byte, goos, goarch string) ([]byte, error) {
	if len(ikm) < 32 {
		return nil, errors.New("ikm too short")
	}
	extract := hmac.New(sha256.New, salt)
	extract.Write(ikm)
	prk := extract.Sum(nil)

	expand := hmac.New(sha256.New, prk)
	expand.Write([]byte("platform-manifest-v1\x00" + goos + "/" + goarch))
	expand.Write([]byte{0x01})
	return expand.Sum(nil), nil
}

func VerifyPlatformManifest(ikm, salt []byte, goos, goarch string, manifest, expectedMAC []byte) (bool, error) {
	subkey, err := derivePlatformKey(ikm, salt, goos, goarch)
	if err != nil {
		return false, err
	}
	mac := hmac.New(sha256.New, subkey)
	mac.Write(manifest)
	return hmac.Equal(mac.Sum(nil), expectedMAC), nil
}
