pub fn lint_shell_missing_double_dash(script: &str) -> Vec<(usize, String)> {
    let guarded = ["cp", "mv", "rm", "chmod", "chown", "ln"];
    let mut findings = Vec::new();

    for (idx, raw_line) in script.lines().enumerate() {
        let code_part = raw_line.split('#').next().unwrap_or("").trim();
        if code_part.is_empty() {
            continue;
        }
        for segment in code_part.split([';', '|', '&']) {
            let tokens: Vec<&str> = segment.split_whitespace().collect();
            let Some(&first) = tokens.first() else { continue };
            let bin = first.rsplit('/').next().unwrap_or(first);
            if !guarded.contains(&bin) {
                continue;
            }
            let mut saw_ddash = false;
            for &tok in &tokens[1..] {
                if tok == "--" {
                    saw_ddash = true;
                    break;
                }
                if tok.starts_with('-') && !tok.contains('$') {
                    continue;
                }
                if tok.contains('$') && !saw_ddash {
                    findings.push((idx + 1, format!("{} expands {} before '--'", bin, tok)));
                    break;
                }
            }
        }
    }
    findings
}
