func safeFindArg(dir string) string {
	if strings.HasPrefix(dir, "-") {
		return "./" + dir
	}
	return dir
}

func FindAndVerifyRegularFiles(ctx context.Context, scanDir string, expected map[string][32]byte) error {
	tmpDir, err := os.MkdirTemp("", "findstage-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir)

	argDir := safeFindArg(scanDir)
	cmd := exec.CommandContext(ctx, "/usr/bin/find", argDir, "-maxdepth", "1", "-type", "f", "-print0")
	out, err := cmd.Output()
	if err != nil {
		return err
	}
	entries := bytes.Split(bytes.TrimRight(out, "\x00"), []byte{0})
	verified := 0
	for _, raw := range entries {
		if len(raw) == 0 {
			continue
		}
		p := string(raw)
		base := filepath.Base(p)
		want, ok := expected[base]
		if !ok {
			return errors.New("unexpected file found: " + base)
		}
		f, err := os.OpenFile(p, os.O_RDONLY|syscall.O_NOFOLLOW, 0)
		if err != nil {
			return err
		}
		staged, err := os.OpenFile(filepath.Join(tmpDir, base), os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o600)
		if err != nil {
			f.Close()
			return err
		}
		h := sha256.New()
		_, copyErr := io.Copy(staged, io.TeeReader(f, h))
		f.Close()
		staged.Close()
		if copyErr != nil || subtle.ConstantTimeCompare(h.Sum(nil), want[:]) != 1 {
			return errors.New("digest mismatch: " + base)
		}
		verified++
	}
	if verified != len(expected) {
		return errors.New("missing expected files")
	}
	return nil
}
