```typescript
import { createHash, timingSafeEqual } from "node:crypto";
import { createReadStream, createWriteStream } from "node:fs";
import { mkdtemp, rename, rm } from "node:fs/promises";
import { pipeline } from "node:stream/promises";
import { Transform } from "node:stream";
import { createGunzip } from "node:zlib";
import path from "node:path";

export async function unpackVerifiedGzip(
  gzFile: string,
  destFile: string,
  expectedGzHex: string,
  expectedRawHex: string,
  maxOutputLength = 64 * 1024 * 1024
): Promise<void> {
  const workDir = await mkdtemp(path.join(path.dirname(destFile), ".gunzip-"));
  const staged = path.join(workDir, "unpacked.bin");
  try {
    const gzHash = createHash("sha256");
    const rawHash = createHash("sha256");
    const tapGz = new Transform({
      transform(chunk, _enc, cb) {
        gzHash.update(chunk as Buffer);
        cb(null, chunk);
      },
    });
    const tapRaw = new Transform({
      transform(chunk, _enc, cb) {
        rawHash.update(chunk as Buffer);
        cb(null, chunk);
      },
    });

    await pipeline(
      createReadStream(gzFile),
      tapGz,
      createGunzip({ maxOutputLength }),
      tapRaw,
      createWriteStream(staged, { mode: 0o600, flags: "wx" })
    );

    const gzOk = timingSafeEqual(gzHash.digest(), Buffer.from(expectedGzHex, "hex"));
    const rawOk = timingSafeEqual(rawHash.digest(), Buffer.from(expectedRawHex, "hex"));
    if (!gzOk || !rawOk) {
      throw new Error("Compressed or uncompressed SHA-256 verification failed");
    }
    await rename(staged, destFile);
  } finally {
    await rm(workDir, { recursive: true, force: true });
  }
}
