func VerifyDualCustodyManifest(buildKey, secopsKey, manifest, buildTag, secopsTag []byte) (bool, error) {
	if len(buildKey) < 32 || len(secopsKey) < 32 {
		return false, errors.New("keys must be at least 32 bytes")
	}
	if subtle.ConstantTimeCompare(buildKey, secopsKey) == 1 {
		return false, errors.New("buildKey and secopsKey must be distinct")
