package manifestgen

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"os"
	"sort"
	"strings"
)

func BuildDeterministicManifest(baseDir string) ([]byte, error) {
	root, err := os.OpenRoot(baseDir)
	if err != nil {
		return nil, err
	}
	defer root.Close()

	var relPaths []string
	err = fs.WalkDir(root.FS(), ".", func(p string, d fs.DirEntry, walkErr error) error {
		if walkErr != nil {
			return walkErr
		}
		if p == "." || d.IsDir() {
			return nil
		}
		if !d.Type().IsRegular() {
			return errors.New("symlink or non-regular file rejected: " + p)
		}
		if strings.HasPrefix(p, "-") || strings.ContainsAny(p, "\\\r\n\x00") {
			return errors.New("unsafe filename: " + p)
		}
		relPaths = append(relPaths, p)
		return nil
	})
	if err != nil {
		return nil, err
	}
	if len(relPaths) == 0 {
		return nil, errors.New("no regular files found")
	}
	sort.Strings(relPaths)
	var out bytes.Buffer
	for _, rel := range relPaths {
		f, err := root.Open(rel)
		if err != nil {
			return nil, err
		}
		h := sha256.New()
		_, copyErr := io.Copy(h, f)
		f.Close()
		if copyErr != nil {
			return nil, copyErr
		}
		fmt.Fprintf(&out, "%s  %s\n", hex.EncodeToString(h.Sum(nil)), rel)
	}
	return out.Bytes(), nil
}
