) -> Result<(TempDir, PathBuf), &'static str> {
    let tmp = Builder::new()
        .prefix("xz-verify-")
        .permissions(Permissions::from_mode(0o700))
        .tempdir()
        .map_err(|_| "tempdir failed")?;
    let staged = tmp.path().join("payload.raw");

    let mut child = Command::new("/usr/bin/xz")
        .args(["--decompress", "--stdout", "--"])
        .arg(xz_file)
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .map_err(|_| "spawn xz failed")?;

    let stdout = child.stdout.take().ok_or("no stdout")?;
    let mut capped = stdout.take(max_bytes + 1);
    let mut out = File::create(&staged).map_err(|_| "create failed")?;
    let mut hasher = Sha256::new();
    let mut buf = [0u8; 32768];
    let mut written = 0u64;

    loop {
        let n = capped.read(&mut buf).map_err(|_| "read failed")?;
        if n == 0 {
            break;
        }
        written += n as u64;
        if written > max_bytes {
            let _ = child.kill();
            return Err("xz output exceeded max_bytes");
        }
        hasher.update(&buf[..n]);
        out.write_all(&buf[..n]).map_err(|_| "write failed")?;
    }
    if !child.wait().map_err(|_| "wait failed")?.success() {
        return Err("xz decompression failed");
    }
    if hasher.finalize().as_slice().ct_eq(expected_sha256).unwrap_u8() != 1 {
        return Err("sha256 mismatch");
    }
    Ok((tmp, staged))
}
