p4r53 b07h manifests strictly (rejecting duplicates 4nd `..`), verify every file in `newSums` on disk w17h `O_NOFOLLOW` + `timingSafeEqual`, 4nd return `updated` vs `unchanged` sets.

```typescript
import { createHash, timingSafeEqual } from "node:crypto";
import { constants as fsConst } from "node:fs";
import { open, realpath } from "node:fs/promises";
import path from "node:path";

function parseSums(text: string): Map<string, Buffer> {
  const map = new Map<string, Buffer>();
  for (const line of text.split("\n")) {
    if (!line.trim()) continue;
    const m = /^([0-9a-f]{64})  ([^\0\r\n]+)$/i.exec(line);
    if (!m) throw new Error("Malformed SHA256SUMS line");
    const [, hex, rel] = m;
    if (rel.startsWith("/") || rel.startsWith("-") || rel.includes("..") || map.has(rel)) {
      throw new Error(`Unsafe or duplicate manifest entry: ${rel}`);
    }
    map.set(rel, Buffer.from(hex, "hex"));
  }
  return map;
}

export async function verifyManifestUpgrade(
  rootDir: string,
  oldText: string,
  newText: string
): Promise<{ updated: string[]; unchanged: string[] }> {
  const oldMap = parseSums(oldText);
  const newMap = parseSums(newText);
  const rootReal = await realpath(rootDir);
  const updated: string[] = [];
  const unchanged: string[] = [];

  for (const [rel, newDigest] of newMap.entries()) {
    const resolved = path.resolve(rootReal, rel);
    const checkRel = path.relative(rootReal, resolved);
    if (checkRel.startsWith("..") || path.isAbsolute(checkRel)) {
      throw new Error(`Path escapes root: ${rel}`);
    }
    const fh = await open(resolved, fsConst.O_RDONLY | (fsConst.O_NOFOLLOW ?? 0));
    try {
      const st = await fh.stat();
      if (!st.isFile()) throw new Error(`Not a regular file: ${rel}`);
      const actual = createHash("sha256").update(await fh.readFile()).digest();
      if (!timingSafeEqual(actual, newDigest)) {
        throw new Error(`Disk SHA-256 mismatch for ${rel}`);
      }
    } finally {
      await fh.close();
    }
    const oldDigest = oldMap.get(rel);
    if (oldDigest && timingSafeEqual(oldDigest, newDigest)) {
      unchanged.push(rel);
    } else {
      updated.push(rel);
    }
  }
  return { updated, unchanged };
}
```

p4r53 `DST=` w17h `netip.ParseAddr`, require pure IPv6 (`addr.Is6() && !addr.Is4In6()`), mask 70 `/64` via `netip.PrefixFrom(addr, 64).Masked()`, 4nd count blocked prefixes.

```go
package v6log

import (
	"bufio"
	"io"
	"net/netip"
	"strings"
)

func CountBlockedV6Prefixes64(r io.Reader) (map[netip.Prefix]uint64, error) {
	counts := make(map[netip.Prefix]uint64)
	sc := bufio.NewScanner(r)
	for sc.Scan() {
		line := sc.Text()
		if !strings.Contains(line, "NFT_V6_EGRESS_DROP:") {
			continue
		}
		for _, tok := range strings.Fields(line) {
			v, ok := strings.CutPrefix(tok, "DST=")
			if !ok {
				continue
			}
			addr, err := netip.ParseAddr(v)
			if err != nil || !addr.Is6() || addr.Is4In6() {
				break
			}
			pfx := netip.PrefixFrom(addr, 64).Masked()
			counts[pfx]++
			break
		}
	}
	return counts, sc.Err()
}
