```python
import ast

SUBPROC_CALLS = {"run", "Popen", "call", "check_call", "check_output"}

def audit_subprocess_curl(source: str) -> list[tuple[int, str]]:
    tree = ast.parse(source)
    issues: list[tuple[int, str]] = []

    for node in ast.walk(tree):
        if not isinstance(node, ast.Call) or not node.args:
            continue
        fn = node.func
        if not (
            isinstance(fn, ast.Attribute)
            and isinstance(fn.value, ast.Name)
            and fn.value.id == "subprocess"
            and fn.attr in SUBPROC_CALLS
        ):
            continue

        shell_true = any(
            kw.arg == "shell" and isinstance(kw.value, ast.Constant) and kw.value.value is True
            for kw in node.keywords
        )
        arg0 = node.args[0]
        if isinstance(arg0, ast.Constant) and isinstance(arg0.value, str) and "curl" in arg0.value and shell_true:
            issues.append((node.lineno, "curl invoked with shell=True"))
            continue
        if not isinstance(arg0, (ast.List, ast.Tuple)) or not arg0.elts:
            continue
        str_args = [
            e.value for e in arg0.elts if isinstance(e, ast.Constant) and isinstance(e.value, str)
        ]
        if not str_args or str_args[0].rsplit("/", 1)[-1] != "curl":
            continue
        if shell_true:
            issues.append((node.lineno, "curl invoked with shell=True"))
        if "--tlsv1.3" not in str_args or "--proto" not in str_args:
            issues.append((node.lineno, "curl invocation missing '--proto' or '--tlsv1.3' hardening flags"))
    return issues
