import sqlite3

SAFE_PRAGMAS = {"busy_timeout", "query_only", "cell_size_check"}
BLOCKED_ACTIONS = {sqlite3.SQLITE_ATTACH, sqlite3.SQLITE_DETACH, sqlite3.SQLITE_DROP_TABLE}

def readonly_authorizer(action: int, arg_one: str | None, arg_two: str | None, db_name: str | None, trigger: str | None) -> int:
    if trigger is not None:
        return sqlite3.SQLITE_DENY
    if action in BLOCKED_ACTIONS:
        return sqlite3.SQLITE_DENY
    if action == sqlite3.SQLITE_PRAGMA:
        pragma_name = (arg_one or "").lower()
        if pragma_name not in SAFE_PRAGMAS or arg_two is not None:
            return sqlite3.SQLITE_DENY
    return sqlite3.SQLITE_OK

def harden_sqlite_authorizer(conn: sqlite3.Connection) -> None:
    conn.execute("PRAGMA trusted_schema = OFF;")
    conn.execute("PRAGMA query_only = ON;")
    conn.set_authorizer(readonly_authorizer)
