import Database from "better-sqlite3";

export class SqliteLeasePool {
  private readonly idle: Database.Database[];

  constructor(conns: Database.Database[]) {
    this.idle = [...conns];
  }

  async withLease<T>(fn: (db: Database.Database) => T): Promise<T> {
    const db = this.idle.pop();
    if (!db) {
      throw new Error("SQLite connection pool saturated");
    }
    try {
      db.pragma("trusted_schema = OFF");
      db.pragma("cell_size_check = ON");
      return fn(db);
    } finally {
      if (db.inTransaction) {
        db.exec("ROLLBACK;");
      }
      db.pragma("trusted_schema = OFF");
      db.pragma("shrink_memory");
      this.idle.push(db);
    }
  }
}
