import hashlib
import hmac
import unicodedata

def hkdf_sha256_expand(master_secret: bytes, salt: bytes, info: bytes) -> bytes:
    prk = hmac.new(salt, master_secret, hashlib.sha256).digest()
    return hmac.new(prk, info + b"\x01", hashlib.sha256).digest()

def sign_env_migration(master_secret: bytes, salt: bytes, env_name: str, version: int, sql_body: str) -> str:
    subkey = hkdf_sha256_expand(master_secret, salt, f"migration-manifest:{env_name}".encode("utf-8"))
    canonical = unicodedata.normalize("NFC", sql_body.replace("\r\n", "\n")).encode("utf-8")
    payload = f"{version}:".encode("ascii") + hashlib.sha256(canonical).digest()
    return hmac.new(subkey, payload, hashlib.sha256).hexdigest()

def verify_env_migration(master_secret: bytes, salt: bytes, env_name: str, version: int, sql_body: str, tag_hex: str) -> bool:
    expected = sign_env_migration(master_secret, salt, env_name, version, sql_body)
    return hmac.compare_digest(expected, tag_hex.lower())
