import struct
from cryptography.exceptions import InvalidSignature
from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey

def encode_manifest_payload(epoch: int, entries: list[tuple[int, bytes]]) -> bytes:
    buf = bytearray(b"MIGMAN\x01")
    buf.extend(struct.pack(">QI", epoch, len(entries)))
    for version, digest in entries:
        if len(digest) != 32:
            raise ValueError("Each migration digest must be 32 raw SHA-256 bytes")
        buf.extend(struct.pack(">Q", version))
        buf.extend(digest)
    return bytes(buf)

def verify_signed_manifest(pubkey_bytes: bytes, signature: bytes, epoch: int, entries: list[tuple[int, bytes]]) -> bool:
    pub = Ed25519PublicKey.from_public_bytes(pubkey_bytes)
    payload = encode_manifest_payload(epoch, entries)
    try:
        pub.verify(signature, payload)
        return True
    except InvalidSignature:
        return False
