package migrator

import (
	"context"
	"crypto/sha256"
	"crypto/subtle"
	"database/sql"
	"encoding/hex"
	"errors"
)

func ApplyMigrationTx(ctx context.Context, conn *sql.Conn, version int, ddl string, expectedHex string) error {
	digest := sha256.Sum256([]byte(ddl))
	actualHex := hex.EncodeToString(digest[:])
	if subtle.ConstantTimeCompare([]byte(actualHex), []byte(expectedHex)) != 1 {
		return errors.New("migration sha256 mismatch")
	}
	if _, err := conn.ExecContext(ctx, "PRAGMA trusted_schema = OFF; PRAGMA foreign_keys = ON;"); err != nil {
		return err
	}
	tx, err := conn.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback()
	if _, err := tx.ExecContext(ctx, ddl); err != nil {
		return err
	}
	rows, err := tx.QueryContext(ctx, "PRAGMA foreign_key_check;")
	if err != nil {
		return err
	}
	defer rows.Close()
	if rows.Next() {
		return errors.New("foreign_key_check failed after migration")
	}
	_, err = tx.ExecContext(ctx, "INSERT INTO schema_migration_ledger (version_num, checksum_hex) VALUES (?, ?)", version, actualHex)
	if err != nil {
		return err
	}
	return tx.Commit()
}
