import { Connection } from "duckdb-async";

export class DuckDBPoolGuard {
  constructor(private readonly available: Connection[]) {}

  async executeReadOnly<T>(sql: string, params: unknown[]): Promise<T[]> {
    const conn = this.available.pop();
    if (!conn) {
      throw new Error("DuckDB sandbox pool exhausted");
    }
    try {
      const check = await conn.all("SELECT current_setting('lock_configuration') AS locked;");
      if (!check[0] || Boolean(check[0].locked) !== true) {
        throw new Error("Sandbox violation: lock_configuration is not enabled");
      }
      const stmt = await conn.prepare(sql);
      try {
        return (await stmt.all(...params)) as T[];
      } finally {
        await stmt.finalize();
      }
    } finally {
      this.available.push(conn);
    }
  }
}
