import hashlib
import hmac
import struct

def seal_schema_state(secret_key: bytes, schema_cookie: int, digests: list[bytes]) -> str:
    mac = hashlib.blake2b(key=secret_key, digest_size=32, person=b"sqlite-mig-seal")
    mac.update(struct.pack(">QI", schema_cookie, len(digests)))
    for digest in digests:
