```go
package poolguard

import (
	"context"
	"database/sql"
	"errors"
	"sync"
)

type TenantPoolQuota struct {
	mu        sync.Mutex
	active    map[string]int
	maxPerTen int
	db        *sql.DB
}

func NewTenantPoolQuota(db *sql.DB, maxPerTenant int) *TenantPoolQuota {
	return &TenantPoolQuota{active: make(map[string]int), maxPerTen: maxPerTenant, db: db}
}

func (q *TenantPoolQuota) Checkout(ctx context.Context, tenantID string) (*sql.Conn, func(), error) {
	q.mu.Lock()
	if q.active[tenantID] >= q.maxPerTen {
		q.mu.Unlock()
		return nil, nil, errors.New("tenant connection quota exceeded")
	}
	q.active[tenantID]++
	q.mu.Unlock()
	conn, err := q.db.Conn(ctx)
	if err != nil {
		q.mu.Lock()
		q.active[tenantID]--
		q.mu.Unlock()
		return nil, nil, err
	}
	release := func() {
		_ = conn.Close()
		q.mu.Lock()
		q.active[tenantID]--
		q.mu.Unlock()
	}
	return conn, release, nil
}
