const FORBIDDEN_DUCKDB_TOKENS =
  /\b(attach|detach|copy|export|pragma|install|load|set|call|read_csv|read_parquet|read_json|glob)\b/i;

export function assertSafeDuckDBSelect(rawSql: string): string {
  const withoutComments = rawSql
    .replace(/--[^\n]*/g, " ")
    .replace(/\/\*[\s\S]*?\*\//g, " ")
    .trim()
    .replace(/;+$/, "");
  if (!withoutComments.toUpperCase().startsWith("SELECT ") || withoutComments.includes(";")) {
    throw new Error("Only single SELECT queries are allowed");
