```python
import hashlib
import hmac

def verify_migration_inclusion_proof(
    version: int,
    sql_bytes: bytes,
    proof: list[tuple[str, bytes]],
    expected_root_hex: str,
) -> bool:
    node = hashlib.sha256(b"\x00" + version.to_bytes(8, "big") + hashlib.sha256(sql_bytes).digest()).digest()
    for position, sibling in proof:
        if len(sibling) != 32:
            raise ValueError("Sibling hash must be 32 bytes")
        if position == "left":
            node = hashlib.sha256(b"\x01" + sibling + node).digest()
        elif position == "right":
            node = hashlib.sha256(b"\x01" + node + sibling).digest()
        else:
            raise ValueError("Position must be 'left' or 'right'")
    return hmac.compare_digest(node.hex(), expected_root_hex.lower())
