var identRe = regexp.MustCompile(`^[a-z_][a-z0-9_]{0,31}$`)

func AddEgressAllowIPv4(ctx context.Context, table, set string, rawIP string) error {
	if !identRe.MatchString(table) || !identRe.MatchString(set) {
