						"name":   set,
						"elem":   []string{addr.String()},
					},
				},
			},
		},
	}
	body, err := json.Marshal(payload)
	if err != nil {
		return err
	}
	cmd := exec.CommandContext(ctx, "/usr/sbin/nft", "--json", "-f", "-")
	cmd.Stdin = bytes.NewReader(body)
	cmd.Env = []string{"PATH=/usr/sbin:/sbin:/usr/bin:/bin", "LC_ALL=C"}
