use sha2::{Digest, Sha256};
use std::collections::BTreeMap;
use std::fs::OpenOptions;
use std::io::Read;
use std::os::unix::fs::OpenOptionsExt;
use std::path::{Component, Path};
use subtle::ConstantTimeEq;

fn parse_manifest_map(text: &str) -> Result<BTreeMap<&str, [u8; 32]>, &'static str> {
    let mut map = BTreeMap::new();
    for line in text.lines().filter(|l| !l.trim().is_empty()) {
        let (h, rest) = line.split_at_checked(64).ok_or("bad line")?;
        let rel = rest.strip_prefix("  ").ok_or("bad delimiter")?;
        let raw = hex::decode(h).map_err(|_| "bad hex")?;
        let arr: [u8; 32] = raw.try_into().map_err(|_| "bad hash len")?;
        if map.insert(rel, arr).is_some() {
            return Err("duplicate entry");
        }
    }
    if map.is_empty() {
        return Err("empty manifest");
    }
    Ok(map)
}

pub fn verify_reproducible_manifests(root: &Path, sums_a: &str, sums_b: &str) -> Result<usize, &'static str> {
    let map_a = parse_manifest_map(sums_a)?;
    let map_b = parse_manifest_map(sums_b)?;
    if map_a.len() != map_b.len() {
        return Err("builder manifest entry counts differ");
    }
    for (rel, dig_a) in &map_a {
        let dig_b = map_b.get(rel).ok_or("builder manifest path mismatch")?;
        if dig_a.ct_eq(dig_b).unwrap_u8() != 1 {
            return Err("reproducible build mismatch between builder A and B");
        }
        let mut target = root.to_path_buf();
        for c in Path::new(rel).components() {
            match c {
                Component::Normal(s) => target.push(s),
                _ => return Err("unsafe path"),
            }
        }
        let mut fh = OpenOptions::new().read(true).custom_flags(libc::O_NOFOLLOW).open(&target).map_err(|_| "open failed")?;
        let mut hasher = Sha256::new();
        let mut buf = [0u8; 32768];
        loop {
            let n = fh.read(&mut buf).map_err(|_| "read error")?;
            if n == 0 { break; }
            hasher.update(&buf[..n]);
        }
        if hasher.finalize().as_slice().ct_eq(dig_a).unwrap_u8() != 1 {
            return Err("disk artifact mismatch");
        }
    }
    Ok(map_a.len())
}
