import { createHash, timingSafeEqual } from "node:crypto";
import { execFile } from "node:child_process";
import { mkdtemp, rename, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { promisify } from "node:util";

const execFileAsync = promisify(execFile);

export async function extractSingleZipEntryVerified(
  zipPath: string,
  entryName: string,
  expectedSha256Hex: string,
  destPath: string,
  maxBytes = 16 * 1024 * 1024
): Promise<void> {
  if (!/^[A-Za-z0-9._/-]{1,200}$/.test(entryName) || entryName.startsWith("/") || entryName.startsWith("-") || entryName.includes("..")) {
    throw new Error(`Unsafe zip entry name: ${entryName}`);
  }
  const workDir = await mkdtemp(path.join(path.dirname(destPath), ".zipext-"));
  const staged = path.join(workDir, "entry.bin");
  try {
    const { stdout } = await execFileAsync(
      "unzip",
      ["-p", "--", zipPath, entryName],
      { encoding: "buffer", maxBuffer: maxBytes }
    );
    const actual = createHash("sha256").update(stdout).digest();
    const want = Buffer.from(expectedSha256Hex, "hex");
    if (want.length !== 32 || !timingSafeEqual(actual, want)) {
      throw new Error("Extracted zip entry SHA-256 mismatch");
    }
    await writeFile(staged, stdout, { mode: 0o600, flag: "wx" });
    await rename(staged, destPath);
  } finally {
    await rm(workDir, { recursive: true, force: true });
  }
}
