use serde_json::Value;

fn valid_sha256_ref(s: &str) -> bool {
    let Some(hex_part) = s.strip_prefix("sha256:") else { return false };
    hex_part.len() == 64 && hex_part.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f'))
