pub fn collect_mismatched_layers(jsonl: &str) -> Vec<String> {
    let mut bad = Vec::new();
    for line in jsonl.lines() {
        let Ok(v) = serde_json::from_str::<Value>(line) else { continue };
        let Some(layer) = v.get("layer").and_then(Value::as_str) else { continue };
        let exp = v.get("expected").and_then(Value::as_str).unwrap_or("");
        let act = v.get("actual").and_then(Value::as_str).unwrap_or("");
        if !valid_sha256_ref(exp) || !valid_sha256_ref(act) || exp != act {
            let clean_layer: String = layer.chars().filter(|c| !c.is_control()).take(128).collect();
            if !clean_layer.is_empty() {
                bad.push(clean_layer);
            }
        }
    }
    bad
