use sha2::{Digest, Sha256};
use subtle::ConstantTimeEq;

pub fn verify_indexed_merkle_proof(
    leaf_bytes: &[u8],
    leaf_index: u64,
    total_leaves: u64,
    siblings: &[[u8; 32]],
    expected_root: &[u8; 32],
) -> bool {
    if leaf_index >= total_leaves || siblings.len() > 63 {
        return false;
    }
    if (leaf_index >> siblings.len()) != 0 {
        return false;
    }
    let mut node: [u8; 32] = {
        let mut h = Sha256::new();
        h.update([0x00]);
        h.update(leaf_bytes);
        h.finalize().into()
    };

    for (height, sib) in siblings.iter().enumerate() {
        let mut h = Sha256::new();
        h.update([0x01]);
        if ((leaf_index >> height) & 1) == 1 {
            h.update(sib);
            h.update(node);
        } else {
            h.update(node);
            h.update(sib);
        }
        node = h.finalize().into();
    }
    node.ct_eq(expected_root).unwrap_u8() == 1
