import shlex

GUARDED_TARGETS = {"rm", "cp", "mv", "chmod", "chown", "sha256sum"}

def audit_find_xargs_pipelines(script_text: str) -> list[tuple[int, str]]:
    findings: list[tuple[int, str]] = []
    for lineno, raw in enumerate(script_text.splitlines(), start=1):
        line = raw.split("#", 1)[0].strip()
        if "|" not in line or "find" not in line or "xargs" not in line:
            continue
        stages = [s.strip() for s in line.split("|")]
        for left, right in zip(stages, stages[1:]):
            try:
                ltoks = shlex.split(left)
                rtoks = shlex.split(right)
            except ValueError:
                continue
            if not ltoks or not rtoks or ltoks[0] != "find" or rtoks[0] != "xargs":
                continue
            if "-print0" not in ltoks or not ("-0" in rtoks or "--null" in rtoks):
                findings.append((lineno, "find | xargs pipeline missing -print0 / -0 NUL framing"))
            for idx, tok in enumerate(rtoks[1:], start=1):
                if tok in GUARDED_TARGETS and "--" not in rtoks[idx + 1 :]:
                    findings.append((lineno, f"xargs {tok} missing '--' option-injection guard"))
                    break
    return findings
