```go
package dettar

import (
	"archive/tar"
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"time"
)

func BuildManifestFirstTar(srcDir, outTarPath string, files []string) error {
	root, err := os.OpenRoot(srcDir)
	if err != nil {
		return err
	}
	defer root.Close()

	sorted := append([]string(nil), files...)
	sort.Strings(sorted)
	var sumsBuf bytes.Buffer
	sizes := make(map[string]int64, len(sorted))
	for _, rel := range sorted {
		f, err := root.Open(rel)
		if err != nil {
			return err
		}
		h := sha256.New()
		n, copyErr := io.Copy(h, f)
		f.Close()
		if copyErr != nil {
			return copyErr
		}
		sizes[rel] = n
		fmt.Fprintf(&sumsBuf, "%s  %s\n", hex.EncodeToString(h.Sum(nil)), rel)
	}

	tmpDir, err := os.MkdirTemp(filepath.Dir(outTarPath), ".dettar-*")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmpDir)
	staged := filepath.Join(tmpDir, "bundle.tar")
	out, err := os.OpenFile(staged, os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o644)
	if err != nil {
		return err
	}
	tw := tar.NewWriter(out)
	epoch := time.Unix(0, 0).UTC()
	if err := tw.WriteHeader(&tar.Header{Name: "SHA256SUMS", Mode: 0o644, Size: int64(sumsBuf.Len()), ModTime: epoch}); err != nil {
		out.Close()
		return err
	}
	if _, err := tw.Write(sumsBuf.Bytes()); err != nil {
		out.Close()
		return err
	}
	for _, rel := range sorted {
		if err := tw.WriteHeader(&tar.Header{Name: rel, Mode: 0o644, Size: sizes[rel], ModTime: epoch}); err != nil {
			out.Close()
			return err
		}
		f, err := root.Open(rel)
		if err != nil {
			out.Close()
			return err
		}
		_, cErr := io.CopyN(tw, f, sizes[rel])
		f.Close()
		if cErr != nil {
			out.Close()
			return cErr
		}
	}
	if err := tw.Close(); err != nil {
		out.Close()
		return err
	}
	if err := out.Sync(); err != nil {
		out.Close()
		return err
	}
	if err := out.Close(); err != nil {
		return err
	}
	return os.Rename(staged, outTarPath)
}
