```typescript
import { createHash, timingSafeEqual } from "node:crypto";
import { constants as fsConst } from "node:fs";
import { open, realpath } from "node:fs/promises";
import path from "node:path";

export async function verifyStrictLfSha256Sums(rootDir: string, manifestText: string): Promise<number> {
  if (manifestText.includes("\r") || manifestText.includes("\0") || manifestText.includes("\\")) {
    throw new Error("CRLF, NUL, or backslash escapes forbidden in strict SHA256SUMS");
  }
  const lines = manifestText.split("\n").filter((l) => l.length > 0);
  if (lines.length === 0) throw new Error("Empty SHA256SUMS manifest");

  const rootReal = await realpath(rootDir);
  const seen = new Set<string>();
  for (const line of lines) {
    const m = /^([0-9a-f]{64})  ([A-Za-z0-9._][A-Za-z0-9._/-]{0,240})$/.exec(line);
    if (!m) throw new Error(`Invalid strict manifest line: ${line}`);
    const [, hexDig, relName] = m;
    if (relName.includes("..") || seen.has(relName)) {
      throw new Error(`Duplicate or traversal path: ${relName}`);
    }
    const full = path.resolve(rootReal, relName);
    const rel = path.relative(rootReal, full);
    if (rel.startsWith("..") || path.isAbsolute(rel)) {
      throw new Error(`Escaped rootDir: ${relName}`);
    }
    const fh = await open(full, fsConst.O_RDONLY | (fsConst.O_NOFOLLOW ?? 0));
    try {
      const st = await fh.stat();
      if (!st.isFile()) throw new Error(`Not a regular file: ${relName}`);
      const actual = createHash("sha256").update(await fh.readFile()).digest();
      if (!timingSafeEqual(actual, Buffer.from(hexDig, "hex"))) {
        throw new Error(`SHA-256 mismatch: ${relName}`);
      }
    } finally {
      await fh.close();
    }
    seen.add(relName);
  }
  return seen.size;
}
