```go
package fulldigest

import (
	"crypto/sha256"
	"crypto/subtle"
	"encoding/hex"
	"errors"
)

func VerifyFull256BitDigest(payload []byte, expectedHex string) error {
	if len(expectedHex) != sha256.Size*2 {
		return errors.New("truncated digest rejected: full 64-char SHA-256 hex required")
	}
	for i := 0; i < len(expectedHex); i++ {
		c := expectedHex[i]
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			return errors.New("expected lowercase hexadecimal SHA-256 string")
		}
	}
	expected, err := hex.DecodeString(expectedHex)
	if err != nil || len(expected) != sha256.Size {
		return errors.New("hex decode error")
	}
	actual := sha256.Sum256(payload)
	if subtle.ConstantTimeCompare(actual[:], expected) != 1 {
		return errors.New("sha256 digest mismatch")
	}
	return nil
}
