```go
package zipverify

import (
	"archive/zip"
	"crypto/sha256"
	"crypto/subtle"
	"errors"
	"io"
	"os"
	"path"
	"strings"
)

func VerifyZipManifest(zr *zip.Reader, manifest map[string][32]byte, maxTotalBytes int64) error {
	var total int64
	seen := make(map[string]bool, len(manifest))
	for _, zf := range zr.File {
		if zf.FileInfo().IsDir() {
			continue
		}
		if zf.Mode()&os.ModeSymlink != 0 || !zf.Mode().IsRegular() {
			return errors.New("symlink or non-regular zip entry rejected")
		}
		clean := path.Clean(zf.Name)
		if strings.HasPrefix(clean, "/") || strings.HasPrefix(clean, "..") || strings.HasPrefix(clean, "-") || seen[clean] {
			return errors.New("unsafe or duplicate zip entry: " + zf.Name)
		}
		want, ok := manifest[clean]
		if !ok {
			return errors.New("unmanifested zip entry: " + clean)
		}
		rc, err := zf.Open()
		if err != nil {
			return err
		}
		h := sha256.New()
		n, copyErr := io.Copy(h, io.LimitReader(rc, (maxTotalBytes-total)+1))
		rc.Close()
		if copyErr != nil {
			return copyErr
		}
		total += n
		if total > maxTotalBytes {
			return errors.New("zip uncompressed size cap exceeded")
		}
		if subtle.ConstantTimeCompare(h.Sum(nil), want[:]) != 1 {
			return errors.New("zip entry sha256 mismatch: " + clean)
		}
		seen[clean] = true
	}
	if len(seen) != len(manifest) {
		return errors.New("missing manifested entries in zip")
	}
	return nil
}
