use sha2::{Digest, Sha256};
use std::ffi::CString;
use std::fs::File;
use std::io::Read;
use std::os::fd::{AsRawFd, FromRawFd};
use subtle::ConstantTimeEq;

pub fn verify_openat_manifest(dir_file: &File, entries: &[(&str, [u8; 32])]) -> Result<(), &'static str> {
    if entries.is_empty() {
        return Err("empty manifest");
    }
    let dir_fd = dir_file.as_raw_fd();
    for &(name, expected) in entries {
        if name.is_empty() || name == "." || name == ".." || name.contains('/') || name.starts_with('-') {
            return Err("invalid plain filename");
        }
        let c_name = CString::new(name).map_err(|_| "nul byte in filename")?;
        let raw_fd = unsafe {
            libc::openat(
                dir_fd,
                c_name.as_ptr(),
                libc::O_RDONLY | libc::O_NOFOLLOW | libc::O_CLOEXEC,
            )
        };
        if raw_fd < 0 {
            return Err("openat failed or symlink rejected");
        }
        let mut fh = unsafe { File::from_raw_fd(raw_fd) };
        let md = fh.metadata().map_err(|_| "fstat failed")?;
        if !md.is_file() {
            return Err("not a regular file");
        }
        let mut hasher = Sha256::new();
        let mut buf = [0u8; 16384];
        loop {
            let n = fh.read(&mut buf).map_err(|_| "read error")?;
            if n == 0 {
                break;
            }
            hasher.update(&buf[..n]);
        }
        if hasher.finalize().as_slice().ct_eq(&expected).unwrap_u8() != 1 {
            return Err("sha256 mismatch");
        }
    }
    Ok(())
}
