export async function writeNftConcatSetAtomic(
  destFile: string,
  setName: string,
  endpoints: EndpointTuple[]
): Promise<void> {
  if (!/^[a-z_][a-z0-9_]{1,31}$/.test(setName) || endpoints.length === 0) {
    throw new Error("Invalid set name or empty endpoint list");
  }
  const uniq = new Set<string>();
  for (const ep of endpoints) {
    if (!net.isIPv4(ep.ipv4) || ep.ipv4.startsWith("127.") || ep.ipv4.startsWith("0.")) {
      throw new Error(`Disallowed IPv4 endpoint: ${ep.ipv4}`);
    }
    if (!Number.isInteger(ep.port) || ep.port < 1 || ep.port > 65535) {
      throw new Error(`Invalid port: ${ep.port}`);
    }
    uniq.add(`${ep.ipv4} . ${ep.port}`);
  }
  const body = [
    `set ${setName} {`,
    `    type ipv4_addr . inet_service`,
    `    elements = { ${[...uniq].sort().join(", ")} }`,
    `}`,
    "",
  ].join("\n");

  const tmpFile = path.join(path.dirname(destFile), `.nft-${randomBytes(6).toString("hex")}.tmp`);
  const fh = await open(tmpFile, "wx", 0o640);
  try {
    await fh.writeFile(body, "utf8");
    await fh.sync();
  } finally {
    await fh.close();
  }
  await rename(tmpFile, destFile);
}
