```python
import hashlib
import hmac
import struct
from typing import Iterable

def order_independent_manifest_hash(
    entries: Iterable[tuple[str, int, bytes]],
) -> bytes:
    seen_paths: set[str] = set()
    leaf_hashes: list[bytes] = []
    for rel_path, size_bytes, file_sha in entries:
        if rel_path in seen_paths or len(file_sha) != 32 or size_bytes < 0:
            raise ValueError(f"duplicate or invalid entry: {rel_path!r}")
        seen_paths.add(rel_path)
        pb = rel_path.encode("utf-8")
        lh = hashlib.sha256(
            b"\x00" + struct.pack(">IQ", len(pb), size_bytes) + pb + file_sha
        ).digest()
        leaf_hashes.append(lh)

    leaf_hashes.sort()
    root = hashlib.sha256(b"\x01" + struct.pack(">I", len(leaf_hashes)))
    for lh in leaf_hashes:
        root.update(lh)
    return root.digest()

def verify_manifest_set_hash(
    entries: Iterable[tuple[str, int, bytes]],
    expected_root: bytes,
) -> bool:
    if len(expected_root) != 32:
        return False
    actual = order_independent_manifest_hash(entries)
    return hmac.compare_digest(actual, expected_root)
