export interface ExecGuardFinding {
  index: number;
  tool: string;
  detail: string;
}

const CALL_RE = /\b(?:execFile|execFileSync|spawn|spawnSync)\s*\(\s*["'](?:\/usr\/bin\/|\/bin\/)?(rm|cp|mv|tar|sha256sum)["']\s*,\s*\[([^\]]*)\]/g;

export function auditNodeExecDoubleDash(tsSource: string): ExecGuardFinding[] {
  const findings: ExecGuardFinding[] = [];
  for (const match of tsSource.matchAll(CALL_RE)) {
    const tool = match[1];
    const rawArgs = match[2]
      .split(",")
      .map((s) => s.trim())
      .filter((s) => s.length > 0);

    let sawDash = false;
    for (const arg of rawArgs) {
      if (arg === `'--'` || arg === `"--"`) {
        sawDash = true;
        break;
      }
      const isStringLiteral = (arg.startsWith("'") && arg.endsWith("'")) || (arg.startsWith('"') && arg.endsWith('"'));
      if (!isStringLiteral && !sawDash) {
        findings.push({
          index: match.index ?? 0,
          tool,
          detail: `${tool} passes non-literal argument '${arg}' before '--' option guard`,
        });
        break;
      }
    }
  }
  return findings;
}
