func VerifyFooterSignedManifest(hmacKey, rawManifest []byte, baseDir string) error {
	if len(hmacKey) < 32 {
		return errors.New("hmac key must be >= 32 bytes")
	}
	trimmed := bytes.TrimRight(rawManifest, "\r\n")
	lastNL := bytes.LastIndexByte(trimmed, '\n')
