```rust
use std::fs;
use std::os::unix::fs::PermissionsExt;
use std::path::Path;
use std::process::Command;

pub fn remove_verified_stage_dir(stage_dir: &Path) -> Result<(), &'static str> {
    if !stage_dir.is_absolute() || stage_dir.components().count() < 4 {
        return Err("refusing shallow or relative path");
    }
    let name = stage_dir
        .file_name()
        .and_then(|s| s.to_str())
        .ok_or("invalid directory basename")?;
    if !name.starts_with(".stage-") {
        return Err("basename missing required '.stage-' prefix");
    }
    let meta = fs::symlink_metadata(stage_dir).map_err(|_| "symlink_metadata failed")?;
    if !meta.file_type().is_dir() {
        return Err("target is a symlink or not a directory");
    }
    if (meta.permissions().mode() & 0o777) != 0o700 {
        return Err("staging directory permissions must be 0700");
    }
    let status = Command::new("/bin/rm")
        .args(["-rf", "--"])
        .arg(stage_dir)
        .status()
        .map_err(|_| "failed spawning rm")?;
    if status.success() {
        Ok(())
    } else {
        Err("rm exited non-zero")
    }
}
