import { createHash, KeyObject, timingSafeEqual, verify } from "node:crypto";
import { constants as fsConst } from "node:fs";
import { open, realpath } from "node:fs/promises";
import path from "node:path";

const DOMAIN = Buffer.from("ts-ed25519-sha256sums-v1\0", "utf8");

export async function verifyEd25519ReleaseSums(
  publicKey: KeyObject,
  manifestBytes: Buffer,
  signatureBytes: Buffer,
  rootDir: string
): Promise<number> {
  const signedPayload = Buffer.concat([DOMAIN, manifestBytes]);
  if (!verify(null, signedPayload, publicKey, signatureBytes)) {
    throw new Error("Ed25519 manifest signature verification failed");
  }
  const rootReal = await realpath(rootDir);
  const lines = manifestBytes.toString("utf8").split("\n").filter((l) => l.trim().length > 0);
  if (lines.length === 0) throw new Error("Signed manifest is empty");

  for (const line of lines) {
    const m = /^([0-9a-f]{64})  ([^\0\r\n]+)$/i.exec(line);
    if (!m) throw new Error("Invalid SHA256SUMS line");
    const [, hexDig, relName] = m;
    const full = path.resolve(rootReal, relName);
    const rel = path.relative(rootReal, full);
    if (rel.startsWith("..") || path.isAbsolute(rel)) {
      throw new Error(`Path traversal rejected: ${relName}`);
    }
    const fh = await open(full, fsConst.O_RDONLY | (fsConst.O_NOFOLLOW ?? 0));
    try {
      const st = await fh.stat();
      if (!st.isFile()) throw new Error(`Not a regular file: ${relName}`);
      const actual = createHash("sha256").update(await fh.readFile()).digest();
      if (!timingSafeEqual(actual, Buffer.from(hexDig, "hex"))) {
        throw new Error(`Digest mismatch: ${relName}`);
      }
    } finally {
      await fh.close();
    }
  }
  return lines.length;
}
