#[derive(Debug, PartialEq, Eq)]
pub struct VerifyAlert {
    pub file: String,
    pub expected: String,
    pub actual: String,
}

fn is_hex64(s: &str) -> bool {
    s.len() == 64 && s.bytes().all(|b| matches!(b, b'0'..=b'9' | b'a'..=b'f'))
}

fn extract_attr<'a>(block: &'a str, key: &str) -> Option<&'a str> {
    let pat = format!("{}=\"", key);
    let start = block.find(&pat)? + pat.len();
    let rest = &block[start..];
    let end = rest.find('"')?;
    Some(&rest[..end])
}

pub fn parse_rfc5424_verify_alerts(log: &str) -> Vec<VerifyAlert> {
    let mut out = Vec::new();
    for line in log.lines() {
        let Some(s_idx) = line.find("[verify@1337 ") else { continue };
        let tail = &line[s_idx..];
        let Some(e_idx) = tail.find(']') else { continue };
        let sd = &tail[..e_idx];

        let (Some(f), Some(exp), Some(act)) = (
            extract_attr(sd, "file"),
            extract_attr(sd, "expected"),
            extract_attr(sd, "actual"),
        ) else { continue };

        if is_hex64(exp) && is_hex64(act) && exp != act {
            let clean_file: String = f.chars().filter(|c| !c.is_control()).take(200).collect();
            if !clean_file.is_empty() {
                out.push(VerifyAlert {
                    file: clean_file,
                    expected: exp.to_string(),
                    actual: act.to_string(),
                });
            }
        }
    }
    out
}
