package keyedmanifest

import (
	"crypto/hmac"
	"crypto/sha256"
	"errors"
)

const domainSep = "hmac-sha256sums-v1\x00"

func AuthenticateManifest(secret, manifest []byte) ([]byte, error) {
	if len(secret) < 32 {
		return nil, errors.New("secret key must be at least 32 bytes")
	}
	mac := hmac.New(sha256.New, secret)
	mac.Write([]byte(domainSep))
	mac.Write(manifest)
	return mac.Sum(nil), nil
}

func VerifyAuthenticatedManifest(secret, manifest, expectedTag []byte) (bool, error) {
	tag, err := AuthenticateManifest(secret, manifest)
	if err != nil {
		return false, err
	}
	return hmac.Equal(tag, expectedTag), nil
}
