import ast

SUBPROC_NAMES = {"run", "Popen", "call", "check_call", "check_output"}

def audit_shell_invocation(source: str) -> list[tuple[int, str]]:
    tree = ast.parse(source)
    findings: list[tuple[int, str]] = []

    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        fn = node.func
        if (
            isinstance(fn, ast.Attribute)
            and isinstance(fn.value, ast.Name)
            and fn.value.id == "os"
            and fn.attr in {"system", "popen"}
        ):
            findings.append((node.lineno, f"os.{fn.attr}() invokes a shell; use subprocess list argv with '--'"))
            continue

        if (
            isinstance(fn, ast.Attribute)
            and isinstance(fn.value, ast.Name)
            and fn.value.id == "subprocess"
            and fn.attr in SUBPROC_NAMES
        ):
            for kw in node.keywords:
                if kw.arg == "shell":
                    if not (isinstance(kw.value, ast.Constant) and kw.value.value is False):
                        findings.append((node.lineno, f"subprocess.{fn.attr}() enables or dynamically sets shell="))
    return findings
