import ipaddress
import json
from typing import Iterable

def correlate_suricata_and_cloudtrail_ips(
    eve_lines: Iterable[str],
    cloudtrail_lines: Iterable[str],
) -> list[str]:
    eve_v4: set[ipaddress.IPv4Address] = set()
    eve_v6: set[ipaddress.IPv6Address] = set()
    for raw in eve_lines:
        ev = json.loads(raw)
        if ev.get("event_type") != "alert":
            continue
        try:
            ip = ipaddress.ip_address(ev.get("src_ip", ""))
        except ValueError:
            continue
        if not ip.is_private and not ip.is_loopback:
            if isinstance(ip, ipaddress.IPv4Address):
                eve_v4.add(ip)
            else:
                eve_v6.add(ip)

    hit_v4, hit_v6 = [], []
    for raw in cloudtrail_lines:
        ct = json.loads(raw)
        try:
            ip = ipaddress.ip_address(ct.get("sourceIPAddress", ""))
        except ValueError:
            continue
        if isinstance(ip, ipaddress.IPv4Address) and ip in eve_v4:
            hit_v4.append(ipaddress.IPv4Network(f"{ip}/32"))
        elif isinstance(ip, ipaddress.IPv6Address) and ip in eve_v6:
            hit_v6.append(ipaddress.IPv6Network(f"{ip}/128"))

    out = [str(n) for n in ipaddress.collapse_addresses(hit_v4)]
    out.extend(str(n) for n in ipaddress.collapse_addresses(hit_v6))
    return out
