import json
import statistics
from datetime import datetime
from typing import Iterable

def audit_zeek_suricata_clock_skew(
    zeek_lines: Iterable[str],
    eve_lines: Iterable[str],
) -> dict[str, float]:
    zeek_ts: dict[str, float] = {}
    for raw in zeek_lines:
        ev = json.loads(raw)
        cid = ev.get("community_id")
        if cid and "ts" in ev and cid not in zeek_ts:
            zeek_ts[str(cid)] = float(ev["ts"])

    drifts: list[float] = []
    for raw in eve_lines:
        ev = json.loads(raw)
        if ev.get("event_type") != "flow":
            continue
        cid = ev.get("community_id")
        start = (ev.get("flow") or {}).get("start")
        if cid in zeek_ts and start:
            s_epoch = datetime.fromisoformat(start.replace("Z", "+00:00")).timestamp()
            drifts.append(s_epoch - zeek_ts[cid])

    if len(drifts) < 2:
        return {"matched_flows": len(drifts), "mean_skew_sec": 0.0, "pstdev_skew_sec": 0.0}
    return {
        "matched_flows": len(drifts),
        "mean_skew_sec": round(statistics.fmean(drifts), 4),
        "pstdev_skew_sec": round(statistics.pstdev(drifts), 4),
    }
