```rust
use serde_json::Value;
use std::io::BufRead;

pub fn sanitize_jsonl_objects<R: BufRead>(reader: R, max_bytes: usize) -> (usize, usize) {
    let mut accepted = 0usize;
    let mut rejected = 0usize;
    for line_res in reader.lines() {
        let Ok(line) = line_res else {
            rejected += 1;
            continue;
        };
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        if trimmed.len() > max_bytes {
            rejected += 1;
            continue;
        }
        match serde_json::from_str::<Value>(trimmed) {
            Ok(Value::Object(_)) => accepted += 1,
            _ => rejected += 1,
        }
    }
    (accepted, rejected)
}
