```typescript
import * as readline from "node:readline";
import { Readable } from "node:stream";

export interface UnifiedTelemetryEvent {
  tsEpochMs: number;
  sourceIp: string;
  vendor: "cloudtrail" | "k8s_audit" | "suricata";
}

export async function normalizeMultiTelemetry(
  input: Readable
): Promise<UnifiedTelemetryEvent[]> {
  const out: UnifiedTelemetryEvent[] = [];
  const rl = readline.createInterface({ input, crlfDelay: Infinity });
  for await (const line of rl) {
    if (!line.trim()) continue;
    const raw = JSON.parse(line) as Record<string, unknown>;
    if (typeof raw.eventTime === "string" && typeof raw.sourceIPAddress === "string") {
      const ms = Date.parse(raw.eventTime);
      if (!Number.isNaN(ms)) {
        out.push({ tsEpochMs: ms, sourceIp: raw.sourceIPAddress, vendor: "cloudtrail" });
      }
    } else if (typeof raw.requestReceivedTimestamp === "string" && Array.isArray(raw.sourceIPs)) {
      const ms = Date.parse(raw.requestReceivedTimestamp);
      const ip = raw.sourceIPs[0];
      if (!Number.isNaN(ms) && typeof ip === "string") {
        out.push({ tsEpochMs: ms, sourceIp: ip, vendor: "k8s_audit" });
      }
    } else if (typeof raw.timestamp === "string" && typeof raw.src_ip === "string") {
      const ms = Date.parse(raw.timestamp);
      if (!Number.isNaN(ms)) {
        out.push({ tsEpochMs: ms, sourceIp: raw.src_ip, vendor: "suricata" });
      }
    }
  }
  return out;
}
